// Function to manage dynamic list of NFAPI_RX_FRAME_PDU_T structures
void manage_frame_list(int num_frames) {
    // Initialize the frame list with specified number of frames
    NFAPI_RX_FRAME_PDU_T **frame_list = (NFAPI_RX_FRAME_PDU_T **)malloc(num_frames * sizeof(NFAPI_RX_FRAME_PDU_T *));

    // Track most recent frame for each RNTI
    int *latest_frame_index = (int *)calloc(256, sizeof(int)); // Assuming 8-bit RNTI

    // Initialize the latest frame index for each RNTI to -1 (indicating no frame)
    for (int i = 0; i < 256; i++) {
        latest_frame_index[i] = -1;
    }

    // Function to insert a new frame into the list based on RNTI
    void insert_frame(int rnti, NFAPI_RX_FRAME_PDU_T *new_frame) {
        // Find an empty slot in the frame list for the new frame
        int i;
        for (i = 0; i < num_frames; i++) {
            if (!frame_list[i]) {
                break;
            }
        }

        // Insert the new frame into the list at the found index
        frame_list[i] = new_frame;

        // Update the latest frame index for the given RNTI
        latest_frame_index[rnti] = i;
    }

    // Function to delete a frame from the list based on RNTI
    void delete_frame(int rnti) {
        int i = latest_frame_index[rnti];

        // If a frame exists for the given RNTI, remove it and update the latest frame index
        if (i != -1 && frame_list[i]) {
            free(frame_list[i]);
            frame_list[i] = NULL;
            latest_frame_index[rnti] = -1;
        }
    }

    // Function to retrieve the most recent frame for a given RNTI
    NFAPI_RX_FRAME_PDU_T *get_latest_frame(int rnti) {
        int i = latest_frame_index[rnti];

        // Return the most recent frame for the given RNTI, or NULL if no frame exists
        return i == -1 ? NULL : frame_list[i];
    }
}
