typedef struct {
    int value;
    char* str;
} record;

record* initializeRecords(int numRecords, int maxRecordSize, int minVal, int maxVal, const char** strings) {
    // Initialize random number generator
    srand(time(NULL));

    // Validate the number of records against the maximum size
    if (numRecords > maxRecordSize) {
        printf("Error: Number of records exceeds maximum size. Exiting...\n");
        return NULL;
    }

    record* records = malloc(numRecords * sizeof(record));
    if (!records) {
        printf("Error: Unable to allocate memory for records.\n");
        return NULL;
    }

    // Initialize each record's 'int' value to a unique random number
    for (int i = 0; i < numRecords; i++) {
        int val = rand() % (maxVal - minVal + 1) + minVal;
        records[i].value = val;

        // Populate the 'char*' pointer with a unique substring from the provided list
        int strIndex = rand() % (strlen(strings[0]) + 1);
        char* tempStr = malloc((strIndex > 0 ? strIndex : 1) * sizeof(char));
        if (!tempStr) {
            printf("Error: Unable to allocate memory for string.\n");
            return NULL;
        }
        memcpy(tempStr, strings[rand() % (sizeof(strings) / sizeof(*strings))], strIndex);
        tempStr[strIndex > 0 ? strIndex - 1 : 0] = '\0'; // Null-terminate the substring
        records[i].str = tempStr;
    }

    // Optional: Log initialization process to a file (configure via command-line flag)
    // ...

    return records;
}

void periodicMemoryOptimization(record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (!records[i].str) {
            free(records[i].str);
        }
    }

    // Optional: Periodically release unused memory
    // ...
}

void cleanup(record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i].str) {
            free(records[i].str);
        }
    }

    free(records);
}
