```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define MAX_LINE_LENGTH 1024

// Helper function to calculate word length
size_t getWordLength(const char *line) {
    size_t len = 0;
    while (*line != '\0' && !strchr(" \t\r\n", *line)) {
        line++;
        len++;
    }
    return len;
}

int main(int argc, char *argv[]) {
    int outputFileFlag = 0;
    int manPageFlag = 0;
    int quietFlag = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-o") == 0) {
            outputFileFlag = 1;
        } else if (strcmp(argv[i], "--manpage") == 0) {
            manPageFlag = 1;
        } else if (strcmp(argv[i], "-cs") == 0) {
            quietFlag = 1;
        }
    }

    if (argc <= 1 || (manPageFlag && !outputFileFlag)) {
        printf("Usage: %s [-o output_file] [--manpage] [-cs]\n", argv[0]);
        return 0;
    }

    FILE *file, *output = NULL;
    int totalLines = 0, totalWords = 0;
    char longestWord[MAX_LINE_LENGTH];
    size_t maxLength = 0;

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-o") && !quietFlag) {
            printf("Processing file: %s\n", argv[i]);
        }

        file = fopen(argv[i], "r");
        if (!file) {
            perror("File error");
            continue;
        }

        char line[MAX_LINE_LENGTH];
        int lines = 0, words = 0;

        while (fgets(line, MAX_LINE_LENGTH, file)) {
            totalLines++;
            lines++;

            size_t wordLength = 0;
            char *word = strtok(line, " \t\r\n");
            while (word) {
                wordLength += getWordLength(word);
                words++;
                if (!quietFlag && !strcmp(word, longestWord)) {
                    maxLength = wordLength;
                }
                word = strtok(NULL, " \t\r\n");
            }

            printf("File: %s, Lines: %d, Average Word Length: %.2f, Longest Word: %s (%zu)\n", argv[i], lines, (double)wordLength / words, longestWord, maxLength);
        }
        fclose(file);

        if (outputFileFlag) {
            output = fopen("output.txt", "a");
            fprintf(output, "File: %s, Lines: %d, Average Word Length: %.2f, Longest Word: %s (%zu)\n", argv[i], lines, (double)wordLength / words, longestWord, maxLength);
            fclose(output);
        }

        totalLines += lines;
    }

    if (!quietFlag && outputFileFlag) {
        printf("Total Lines: %d\n", totalLines);
    }
}
