#include <unistd.h>
#include <pthread.h>

// DNS cache structure
typedef struct {
    char hostname[256];
    uint32_t ip;
} DnsCache;

// DNS cache size
#define DNS_CACHE_SIZE 1024

// DNS cache
DnsCache dns_cache[DNS_CACHE_SIZE];
int dns_cache_index = 0;

// Function to perform DNS resolution
uint8_t* resolve_dns(const char* hostname) {
    // Check if hostname is already cached
    for (int i = 0; i < dns_cache_index; i++) {
        if (!strcmp(dns_cache[i].hostname, hostname)) {
            return (uint8_t*)&dns_cache[i].ip;
        }
    }

    // Perform DNS resolution using standard library functions
    struct sockaddr_in* addr = malloc(sizeof(struct sockaddr_in));
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    inet_pton(AF_INET, "1.1.1.1", (void*) &addr->sin_addr); // Use a reliable DNS server for this example

    if (connect(sock, (struct sockaddr*) addr, sizeof(struct sockaddr_in)) == 0) {
        // Get IP address from DNS response
        uint8_t* ip = malloc(4);
        read(sock, ip, 4);
        close(sock);

        // Add hostname and IP to cache
        strcpy(dns_cache[dns_cache_index].hostname, hostname);
        dns_cache[dns_cache_index++].ip = *(uint32_t*)ip;
        free(ip);
    } else {
        return NULL; // Error during DNS resolution
    }

    return (uint8_t*)&dns_cache[dns_cache_index - 1].ip;
}

// Function to process CSV file records
void process_csv_file(char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Split record into fields
        char* field = strtok(line, ",");
        int num_fields = 0;
        while (field) {
            num_fields++;
            field = strtok(NULL, ",");
        }

        // Allocate memory for each record and append average of measurements
        double* measurements = malloc((num_fields - 2) * sizeof(double));
        char** fields = malloc(num_fields * sizeof(char*));
        int i = 0;
        field = strtok(line, ",");
        while (field) {
            fields[i] = strdup(field);
            field = strtok(NULL, ",");
            i++;
        }
        double avg = 0.0;
        for (int j = num_fields - 2; j < num_fields; j++) {
            measurements[j - num_fields + 2] = atof(fields[j]);
            avg += measurements[j - num_fields + 2];
        }
        avg /= (num_fields - 2);

        // Print processed record
        printf("%s,", fields[0]);
        for (int i = 1; i < num_fields - 2; i++) {
            printf("%s,", fields[i]);
        }
        printf("%lf\n", avg);

        // Free memory and process next line
        for (int i = 0; i < num_fields; i++) {
            free(fields[i]);
        }
        free(fields);
        free(measurements);
    }

    fclose(file);
}

// Main program
int main() {
    // Perform DNS resolution concurrently using threads
    pthread_t thread;
    pthread_create(&thread, NULL, (void*) resolve_dns, "example.com");
    uint8_t* ip = malloc(4);
    pthread_join(thread, NULL);

    // Read CSV file records line by line and process them
    process_csv_file("metrics.csv");

    return 0;
}
