#include <string.h>

typedef struct {
    int* data;
    size_t size;
    size_t capacity;
} IntArray;

IntArray* int_array_create(size_t initial_capacity) {
    IntArray* array = (IntArray*)malloc(sizeof(IntArray));
    array->data = (int*)calloc(initial_capacity, sizeof(int));
    array->size = 0;
    array->capacity = initial_capacity;
    return array;
}

void int_array_free(IntArray* array) {
    free(array->data);
    free(array);
}

void process_integerIntArray(IntArray** array, int integer) {
    if (*array == NULL || integer < 1 || integer > 1000) {
        // Log error and reject invalid input
        printf("Invalid input: %d\n", integer);
        return;
    }

    if ((*array)->size >= (*array)->capacity) {
        // Dynamically allocate more space for the array
        *array = (IntArray*)realloc(*array, sizeof(IntArray));
        (*array)->data = (int*)realloc((*array)->data, (*array)->capacity * 2);
        (*array)->capacity *= 2;
    }

    // Store the integer in the array
    if (!binary_search((*array)->data, 0, (*array)->size, &integer)) {
        (*array)->data[(*array)->size] = integer;
        (*array)->size++;
    }
}

int binary_search(int* array, size_t left, size_t right, int* target) {
    if (left <= right) {
        size_t mid = left + (right - left) / 2;

        if (array[mid] == *target)
            return mid;
        else if (array[mid] < *target)
            return binary_search(array, mid + 1, right, target);
        else
            return binary_search(array, left, mid - 1, target);
    }

    return -1; // Not found
}

void print_largest_unique(IntArray* array) {
    if (array->size == 0) {
        printf("No unique values found.\n");
        return;
    }

    int max = array->data[0];
    for (int i = 1; i < array->size; i++) {
        if (array->data[i] > max)
            max = array->data[i];
    }
    printf("Largest unique value: %d\n", max);
}

void process_stream(IntArray** array, FILE* stream) {
    int integer;
    while (fscanf(stream, "%d", &integer) == 1) {
        process_integerIntArray(array, integer);
    }
}
