typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} log_level_t;

typedef struct {
    int rate_limit;
    int interval;
} rate_limit_config_t;

typedef struct {
    void (*sink_func)(const char*);
    void* sink_arg;
} sink_t;

void debug_log(const char* message, void* arg);
void info_log(const char* message, void* arg);
void warning_log(const char* message, void* arg);
void error_log(const char* message, void* arg);

int log_level_config = DEBUG; // default level
rate_limit_config_t rate_limit = {RATE_LIMIT_DEFAULT, RATE_LIMIT_INTERVAL};
sink_t sinks[] = {{debug_log, NULL}, {info_log, NULL}, {warning_log, NULL}, {error_log, NULL}};

void log_message(log_level_t level, const char* message) {
    if (level > log_level_config)
        return;

    pthread_mutex_lock(&log_mutex);

    // rate limiting
    static int log_count = 0;
    static time_t last_log_time = 0;
    time_t now = time(NULL);
    if ((now - last_log_time) >= rate_limit.interval / 1000.0) {
        log_count = 0;
    }
    if (log_count < rate_limit.rate_limit) {
        sinks[level]->sink_func(message, rate_limit_config.sink_arg);
        log_count++;
    } else {
        printf("Rate limit exceeded: %s\n", message);
    }

    pthread_mutex_unlock(&log_mutex);
}

void* log_thread(void* arg) {
