        with open(f"{os.path.dirname(__file__)}/json_configs/{self.server_name}.json") as f:
            self.json_config = json.load(f)

    def update_config(self, runtime_values):
        config_file_content = ""
        for line in open(self.config_file_path):
            if "{server_name}" in line and not "{{" in line:
                line = line.replace("{server_name}", runtime_values["server_name"])
            elif "{db_username}" in line and not "{{" in line:
                line = line.replace("{db_username}", runtime_values["db_username"])
            elif "{api_key}" in line and not "{{" in line:
                line = line.replace("{api_key}", runtime_values["api_key"])
            config_file_content += line
        with open(self.config_file_path, "w") as f:
            f.write(config_file_content)

    def configure_logging(self):
        logging_level = self.json_config.get("logging_level", "INFO")
        # implement logging configuration based on the json config

@wraps(update_config)
def update_config_and_log(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            print(f"Error updating {server_name} config: {e}")
    return wrapper

class ServerManager:
    def __init__(self):
        self.servers = {}

    def load_servers(self):
        for server_name in os.listdir("servers"):
            if os.path.isdir(f"servers/{server_name}"):
                self.servers[server_name] = ServerConfig(server_name)
                self.servers[server_name].load_json_config()

    def update_configs(self, runtime_values):
        for server_name, server_config in self.servers.items():
            try:
                server_config.update_config(runtime_values.get(server_name))
                print(f"Updated {server_name} config")
            except Exception as e:
                print(f"Error updating {server_name} config: {e}")

