use reqwest;
use serde_json::json;

pub fn generate_js_code(url: &str) -> String {
    let client = reqwest::blocking::Client::new();
    let response = match client.get(&url).send() {
        Ok(r) => r,
        Err(_) => return format!("Error fetching API data at {}", url),
    };

    if !response.status().is_success() {
        return format!("API request failed with status code {}", response.status());
    }

    let json_response = match response.json::<serde_json::Value>() {
        Ok(j) => j,
        Err(_) => return "Invalid JSON response from API".to_string(),
    };

    let js_code = format!(
        r#"fetch("{}")
            .then(response => response.json())
            .then(data => {})
            .catch(error => console.error("Error:", error));
"#,
        url
    );

    if json_response.is_object() {
        for (key, value) in json_response.as_object().unwrap().iter() {
            let js_var_name = key.to_string();
            let js_var_value = match &value {
                serde_json::Value::String(s) => s.replace('"', "\\\"").to_string(),
                _ => format!("({})", serde_json::to_string_pretty(value, true).unwrap()),
            };
            js_code.push_str(&format!("{} = {};\n", js_var_name, js_var_value));
        }
    }

    js_code
}
