bool insertElement(std::vector<int>& vec, int relativeIndex, int valueToInsert) {
    if (relativeIndex < 0 || relativeIndex >= vec.size()) {
        return false; // first index out of bounds
    }

    int targetIndex = std::min(relativeIndex, static_cast<int>(vec.size()));
    vec.insert(vec.begin() + targetIndex, valueToInsert);

    return true;
