int calculateConcurrencyLevel(boost::asio::io_service& io, int initialConcurrencyLevel) {
    // Monitor CPU and memory usage, and adjust concurrency level accordingly
    double cpuUsage = getCPUUsage();
    double memoryUsage = getMemoryUsage();

    if (cpuUsage > 0.5 && memoryUsage < 0.8) {
