    void setDistributionType(std::string type);
    void setLoggingLevel(int level);
    int generateRandomNumber();

private:
    std::mutex mtx;
    std::condition_variable cv;
    bool running = true;

    // Map to store distribution types and their corresponding implementations
    std::map<std::string, std::function<int()>> distributions;

    // Atomic variable for synchronization and thread-safe access
    std::atomic<uint64_t> seedValue;

    // Logging level
    int loggingLevel;
};

void RandomNumberGeneratorService::start() {
    running = true;
}

void RandomNumberGeneratorService::stop() {
    running = false;
    cv.notify_all();
}

void RandomNumberGeneratorService::setSeed(uint64_t seed) {
    seedValue.store(seed);
}

void RandomNumberGeneratorService::setDistributionType(std::string type) {
    // Implement distribution types here
    if (type == "uniform") {
        distributions[type] = []() { return rand(); };
    } else if (type == "normal") {
        // ...
    } else if (type == "exponential") {
        // ...
    }
}

void RandomNumberGeneratorService::setLoggingLevel(int level) {
    loggingLevel = level;
}

int RandomNumberGeneratorService::generateRandomNumber() {
    uint64_t localSeed = seedValue.load();
    int randomNumber;

    while (running) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return !running; });

        // Generate random number using the chosen distribution
        if (!distributions.empty()) {
            randomNumber = distributions.begin()->second();
        } else {
            // Default to uniform distribution if no specific type is set
            randomNumber = rand();
        }

        lock.unlock();

        // Log the generated random number (if logging level is set)
        if (loggingLevel > 0) {
            std::cout << "Generated random number: " << randomNumber << std::endl;
        }
    }

    return randomNumber;
}

