using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace GameConfigLoader
{
    public class GameConfigManager
    {
        private readonly Dictionary<string, Configuration> _configCache = new Dictionary<string, Configuration>();
        private readonly object _syncLock = new object();
        private readonly ILogger _logger;

        public GameConfigManager(ILogger logger)
        {
            _logger = logger;
        }

        public void LoadConfigs(string[] configFiles)
        {
            foreach (string file in configFiles)
            {
                if (!File.Exists(file))
                    throw new FileNotFoundException($"File '{file}' not found");

                try
                {
                    string json = File.ReadAllText(file);
                    Configuration config = JsonConvert.DeserializeObject<Configuration>(json);

                    lock (_syncLock)
                    {
                        _configCache.Add(config.FileName, config);
                    }

                    _logger.LogInformation($"Loaded configuration from file '{file}'");
                }
                catch (Exception ex)
                {
                    _logger.LogError($"Error loading configuration from file '{file}': {ex.Message}");
                }
            }
        }

        public Configuration GetConfig(string fileName)
        {
            lock (_syncLock)
            {
                return _configCache.ContainsKey(fileName) ? _configCache[fileName] : null;
            }
        }

        public void UpdateConfig(string fileName, string json)
        {
            try
            {
                Configuration config = JsonConvert.DeserializeObject<Configuration>(json);

                lock (_syncLock)
                {
                    if (!_configCache.ContainsKey(fileName))
                        _configCache.Add(fileName, config);
                    else
                    {
                        _configCache[fileName] = config;
                    }

                    _logger.LogInformation($"Updated configuration for file '{fileName}'");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Error updating configuration for file '{fileName}': {ex.Message}");
            }
        }
    }

    [Serializable]
    public class Configuration
    {
        public string FileName { get; set; }
        public int MapWidth { get; set; }
        public int MapHeight { get; set; }
        public List<EntityConfig> Entities { get; set; }
    }

    [Serializable]
    public class EntityConfig
    {
        public string TypeName { get; set; }
        public int X { get; set; }
        public int Y { get; set; }
        public int Size { get; set; }
    }
}

public interface ILogger
{
    void LogInformation(string message);
    void LogError(string message);
}
