using System;
using System.IO;
using System.Linq;
using System.Xml.XPath;

public class ConfigParser
{
    private const string TEMP_DIR_PREFIX = "TempDir-";
    private readonly string _tempDirPath;

    public ConfigParser()
    {
        // Initialize a unique temporary directory path
        int processId = Environment.ProcessorCount.GetHashCode();
        _tempDirPath = Path.Combine(Path.GetTempPath(), $"{TEMP_DIR_PREFIX}{processId}");
        Directory.CreateDirectory(_tempDirPath);

        // Set up error logging
        AppDomain.CurrentDomain.UnhandledException += (sender, e) => HandleError(e);
    }

    ~ConfigParser()
    {
        // Ensure temporary directory is cleaned up when the app exits
        GC.SuppressFinalize(this);
        DeleteTempFiles();
    }

    public string ParseConfig(string configFilePath, string elementName)
    {
        try
        {
            if (!Directory.Exists(configFilePath))
                throw new DirectoryNotFoundException("Invalid configuration file path");

            XPathDocument xmlDoc = new XPathDocument(configFilePath);
            XPathNavigator navigator = xmlDoc.CreateNavigator();

            // Check for multiple elements with the same name and log an error if found
            var matchingElements = navigator.Select("//" + elementName).Cast<XPathNode>().ToList();
            if (matchingElements.Count > 1)
                Log.Error($"Multiple '{elementName}' elements found in configuration file. Using default value instead.");

            // Retrieve the value of the specified element and initialize the configuration setting
            XPathNavigator targetElement = matchingElements.FirstOrDefault();
            if (targetElement != null)
                return targetElement.Value;
            else
                return "Default Configuration Value";
        }
        catch (XmlException ex) { Log.Error($"Invalid XML document: {ex.Message}"); }
        catch (UnauthorizedAccessException ex) { Log.Error($"Access denied: {ex.Message}"); }
        catch (PathTooLongException ex) { Log.Error($"Path too long: {ex.Message}"); }
        catch (IOException ex) { Log.Error($"I/O error: {ex.Message}"); }

        return "Fallback Configuration Value";
    }

    private void HandleError(UnhandledExceptionEventArgs e)
    {
        // Log unhandled exceptions
        Log.Error("Uncaught exception:", e.ExceptionObject);
    }

    private void DeleteTempFiles()
    {
        try
        {
            Directory.Delete(_tempDirPath, true);
        }
        catch (UnauthorizedAccessException ex) { Log.Error($"Access denied: {ex.Message}"); }
        catch (IOException ex) { Log.Error($"I/O error: {ex.Message}"); }
    }
}
