import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class StreamProcessor {

    private final Lock lock = new ReentrantLock();

    public String processStream(UnboundedStringStream stream) throws IOException {
        StringBuilder messageBuilder = new StringBuilder();
        MessageDigest md5 = getMessageDigest();

        try (stream.forEach((string) -> {
            lock.lock();
            try {
                messageBuilder.append(string);
                String hash = bytesToHex(md5.digest(messageBuilder.toString().getBytes()));
                messageBuilder.setLength(0); // Reset the builder for next string
            } finally {
                lock.unlock();
            }
        }));
        return messageBuilder.toString() + " - " + bytesToHex(md5.digest(messageBuilder.toString().getBytes()));
    }

    private MessageDigest getMessageDigest() {
        try {
            return MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte aByte : bytes) {
            Integer hexadecimal = Integer.toHexString(aByte);
            result.append((hexadecimal.length() == 1) ? "0" + hexadecimal : hexadecimal);
        }
        return result.toString();
    }
}
