function manage_user_account() {
    $request = $_REQUEST;
    if (empty($request['sub_action'])) {
        $request['sub_action'] = 'create';
    }

    switch ($request['sub_action']) {
        case 'create':
            return create_user_account($request);
        case 'update':
            return update_user_account($request);
        case 'delete':
            return delete_user_account($request);
        default:
            return array('status' => 'error', 'message' => 'Invalid sub-action');
    }
}

function create_user_account(array $request) {
    if (!Validate::name($request['name']) || !Validate::email($request['email'])) {
        return array('status' => 'error', 'message' => 'Invalid user information');
    }

    if (!Validate::password($request['password'])) {
        return array('status' => 'error', 'message' => 'Password must be at least 8 characters with at least one digit');
    }

    $user_data = array(
        'name' => $request['name'],
        'email' => $request['email'],
        'password' => hash('sha256', $request['password'])
    );

    Save::create_user($user_data);
    return array('status' => 'success', 'message' => 'User account created successfully');
}

function update_user_account(array $request) {
    if (!isset($request['id'])) {
        return array('status' => 'error', 'message' => 'Invalid request - missing ID');
    }

    if (!Validate::name($request['name']) || !Validate::email($request['email'])) {
        return array('status' => 'error', 'message' => 'Invalid user information');
    }

    if (!Validate::password($request['password'])) {
        return array('status' => 'error', 'message' => 'Password must be at least 8 characters with at least one digit');
    }

    $user_data = Get::get_user($request['id']);
    if (!$user_data) {
        return array('status' => 'error', 'message' => 'User not found');
    }

    Save::update_user($request['id'], array(
