        'email' => $request['email'],
        'password' => hash('sha256', $request['password'])
    ));
    return array('status' => 'success', 'message' => 'User account updated successfully');
}

function delete_user_account(array $request) {
    if (!isset($request['id'])) {
        return array('status' => 'error', 'message' => 'Invalid request - missing ID');
