    public static class ThemeCacheManager {
        private static Map<String, Bitmap> themeBitmaps = new HashMap<>();
        private static String defaultThemeDir;

        public ThemeCacheManager(String themeDir) {
            if (themeDir == null || themeDir.isEmpty()) {
                defaultThemeDir = "/sdcard/most/default";
            } else {
                defaultThemeDir = themeDir;
            }
        }

        public Bitmap getThemeBitmap(String themeName) {
            if (!themeBitmaps.containsKey(themeName)) {
                // Check if the theme bitmap is already in use and recycle it
                Bitmap themeBitmap = BitmapFactory.decodeStream(new FileInputStream(defaultThemeDir + "/" + themeName + ".png"));
                if (themeBitmap == null) {
                    // Handle parsing error or default theme
                }
                themeBitmaps.put(themeName, themeBitmap);
            }
            return themeBitmaps.get(themeName);
        }

        public void recycleBitmap(String themeName) {
            Bitmap bitmap = themeBitmaps.remove(themeName);
            if (bitmap != null) {
                bitmap.recycle();
            }
        }
    }
}
