const { promises: fs } = require('fs');
const { promisify } = require('util');

class FileProcessor {
  constructor({ concurrencyLimit, fileSizeThreshold }) {
    this.concurrencyLimit = concurrencyLimit;
    this.fileSizeThreshold = fileSizeThreshold;
    this.activeReads = 0;
    this.loggers = [];
  }

  async processDirectory(dirPath, filterExtension) {
    const files = await fs.readdir(dirPath);
    for (const file of files) {
      if (!file.endsWith(filterExtension)) continue;

      await this.processFile(`${dirPath}/${file}`);
    }
  }

  async processFile(filePath) {
    try {
      const fileSize = await promisify(fs.stat)(filePath).size;
      if (fileSize > this.fileSizeThreshold) {
        // handle large files
        console.log(`Large file detected: ${filePath}`);
      } else {
        for (let i = 0; i < this.concurrencyLimit; i++) {
          const readFile = promisify(fs.readFile)(filePath, 'utf8');
          this.activeReads++;
          await readExternalMetadata(filePath)
            .then((metadata) => {
              console.log(`Processing file: ${filePath} with metadata: ${JSON.stringify(metadata)}`);
            })
            .catch((error) => {
              console.error(`Error processing file: ${filePath}, reason: ${error.message}`);
            })
            .finally(() => {
              this.activeReads--;
              if (this.activeReads === 0 && i === this.concurrencyLimit - 1) {
                console.log('All files processed');
              }
            });
        }
      }
    } catch (error) {
      console.error(`Error processing file: ${filePath}, reason: ${error.message}`);
    }
  }

  async readExternalMetadata(filePath) {
    // implement your external metadata service call here
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        resolve({ /* mock metadata */ });
      }, 1000); // simulate network latency
    });
  }

  addLogger(logger) {
    this.loggers.push(logger);
  }

  removeLogger(logger) {
    this.loggers = this.loggers.filter((l) => l !== logger);
  }
}

