function renderScripts(env) {
  const scriptService = new DynamicConfigService();
  const scripts = scriptService.fetchScripts();

  if (!scripts || scripts.length === 0) return 'No scripts to render.';

  const logLevel = env === 'development' ? console.log : () => {};

  for (const script of scripts) {
    if (!validateScript(script)) return 'Invalid script detected.';
    try {
      if (script.src) {
        // Handle network failures and script loading errors
        fetch(script.src)
          .then(response => response.text())
          .catch(error => logLevel(`Error loading script: ${error}`));
      }
    } catch (error) {
      logLevel(`Error processing script: ${error}`);
    }
  }

  return scripts.reduce((acc, script) => `${acc}<script>${script.src ? `src="${script.src}"` : ''}${script.defer ? ' defer' : ''}</script>`, '');
}

function validateScript(script) {
  if (!script.type || !script.src && !script.code) return false;
  if (script.src && /https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-z]{1,6}/.test(script.src)) return false; // Block external URLs
  return true;
}
