function refreshDialogFields(resourceId, url) {
  // Configurable list of field names to check
  const fieldNames = ['field1', 'field2', 'field3'];

  // Iterate over dialog fields
  for (const fieldName in $scope.dialogFields) {
    if ($.inArray(fieldName, fieldNames) !== -1) {
      // Asynchronously send message to parent window with field name
      $.ajax({
        type: 'POST',
        url: url,
        data: {field: fieldName, resourceId: resourceId},
        async: true,
        success: function(response) {
          if (response.status === 'success') {
            $scope.dialogFields[fieldName] = response.data;
          } else {
            // Retry operation up to a predefined number of times with exponential backoff
            const maxRetries = 3;
            let retryCount = 0;
            const retryDelay = 1000; // in milliseconds

            function retry() {
              if (retryCount < maxRetries) {
                setTimeout(function() {
                  $.ajax({
                    type: 'POST',
                    url: url,
                    data: {field: fieldName, resourceId: resourceId},
                    async: true,
                    success: function(response) {
                      if (response.status === 'success') {
                        $scope.dialogFields[fieldName] = response.data;
                      } else {
                        retry();
                      }
                    },
                    error: function() {
                      retry();
                    }
                  });
                }, retryDelay);
                retryCount++;
                retryDelay *= 2;
              } else {
                // Log failure and do not update the field
                console.error('Failed to refresh field:', fieldName);
              }
            }
            retry();
          }
        },
        error: function() {
          console.error('Error refreshing fields:', resourceId, url);
        }
      });
    }
  }
}
