#include <forward_list>
#include <string>

void insertAfter(const std::forward_list<std::string>& list,
                  const std::string& searchFor,
                  const std::string& insert) {
  auto it = list.begin();
  bool found = false;

  for (; it != list.end(); ++it) {
    if (*it == searchFor) {
      found = true;
      break;
    }
  }

  if (found) {
    list.insert_after(it, insert);
  } else {
    list.push_back(insert);
  }
}
```

