        this.delay = delay;
    }

    private int delay;

    public void start() {
        executor = Executors.newFixedThreadPool(PROCESSING_THREADS);
        completionService = new ExecutorCompletionService(executor);

        // Initialize processing tasks
        for (int i = 0; i < PROCESSING_THREADS; i++) {
            processingTasks.add(new ProcessingTask(this));
        }

        // Start threads
        for (ProcessingTask task : processingTasks) {
            executor.submit(task);
        }
    }

    public void stop() throws InterruptedException {
        running = false;

        // Stop and shutdown threads
        for (ProcessingTask task : processingTasks) {
            completionService.take().get();
