const crypto = require('crypto');
const buffer = require('buffer');

function aggregateDataStreams(dataStreams, bufferLength) {
  const bufferArray = [];
  let currentBuffer;

  for (const stream of dataStreams) {
    if (!stream) continue;

    while (stream.length > 0) {
      const chunk = stream.splice(0, Math.min(stream.length, bufferLength));

      if (currentBuffer) {
        bufferArray.push(currentBuffer);
        currentBuffer = Buffer.allocUnsafe(bufferLength);
      } else {
        currentBuffer = Buffer.allocUnsafe(bufferLength);
      }

      for (const part of chunk) {
        currentBuffer.write(part.toString(), 0, part.length);
        const checksum = crypto.createHash('sha256').update(part).digest();
        currentBuffer.write(checksum.toString('hex'), part.length, part.length + 32);
      }
    }

    if (currentBuffer) bufferArray.push(currentBuffer), currentBuffer = null;
  }

  return Buffer.concat(bufferArray);
}

module.exports = aggregateDataStreams;
