["```javascript
function traverseDOM(selector, maxRecursionDepth = 1000) {
    const cache = {};
    let result = [];

    function traverse(node, selector, currentPath = []) {
        if (!node) return;

        const key = `${selector}:${currentPath.join(' ')}`;
        if (cache[key]) return cache[key];

        if (node.matches(selector)) {
            result.push(...Array.from(node.querySelectorAll(selector)));
        }

        let children = node.children;
        if (children.length > 0 && maxRecursionDepth > 0) {
            for (let i = 0; i < children.length; i++) {
                traverse(children[i], selector, [...currentPath, children[i].localName]);
            }
        }

        cache[key] = result.slice();
    }

    function handleContentLoaded() {
        const document = document.documentElement;
        const content = document.getElementById('content');
        traverse(content, selector);
    }

    document.addEventListener('DOMContentLoaded', handleContentLoaded);

    return result;
}
