const fs = require('fs');
const path = require('path');

async function loadModule(moduleName) {
  const config = await fetchConfig();
  if (!config) return;

  const moduleId = appendId(moduleName);
  const filePath = getFilePath(moduleId, config);

  try {
    const moduleCode = await fs.readFileSync(filePath, 'utf8');
    // Execute the loaded module
    eval(`(${moduleCode})`);
  } catch (err) {
    console.error(`Error loading module ${moduleName}: ${err.message}`);
  }
}

function appendId(filename) {
  const idLength = determineIdLength(filename);
  return `${filename}_${getRandomId(idLength)}.js`;
}

function getFilePath(moduleId, config) {
  let baseDir = config.baseDir;
  for (const rule of config.moduleRules) {
    if (rule.pattern.test(moduleId)) {
      baseDir = rule.dir;
      break;
    }
  }
  return path.join(baseDir, moduleId);
}

async function fetchConfig() {
  try {
    const response = await fetch('https://api.example.com/config');
    const data = await response.json();
    return data.config;
  } catch (err) {
    console.error(`Error fetching config: ${err.message}`);
    return null;
  }
}

function determineIdLength(filename) {
  let idLength = 0;
  for (let i = filename.length - 1; i >= 0; i--) {
    if (!isNaN(filename[i])) {
      idLength++;
    } else {
      break;
    }
  }
  return idLength;
}

function getRandomId(length) {
  const chars = '0123456789';
  let id = '';
  for (let i = 0; i < length; i++) {
    id += chars[Math.floor(Math.random() * chars.length)];
  }
  return id;
}
