public class TransactionProcessor {

    private static final int MAX_THREADS = 5; // adjust according to your system's capabilities

    public Map<String, TransactionSummary> processTransactions(String[] fileNames) {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
        List<TransactionProcessorTask> tasks = new ArrayList<>();

        for (String fileName : fileNames) {
            Path filePath = Paths.get(fileName);
            if (!Files.exists(filePath)) {
                System.out.println("File not found: " + fileName);
                continue;
            }

            try (BufferedReader reader = Files.newBufferedReader(filePath)) {
                String line;
                while ((line = reader.readLine()) != null) {
                    Transaction transaction = parseTransaction(line);
                    if (transaction == null) {
                        System.out.println("Invalid transaction format: " + line);
                        continue;
                    }

                    // Add tasks to the executor
                    tasks.add(new TransactionProcessorTask(transaction));
                }
            } catch (IOException e) {
                System.err.println("Error reading file: " + fileName);
                return null; // or handle error as per your requirements
            }
        }

        // Execute tasks and process results
        Map<String, TransactionSummary> summaries = new HashMap<>();
        executor.invokeAll(tasks).forEach(r -> r.get().forEach((userId, summary) -> {
            if (!summaries.containsKey(userId)) {
                summaries.put(userId, new TransactionSummary());
            }
            summaries.get(userId).addTransaction(summary);
        }));

        // Calculate total transaction amounts and Z-scores
        for (Map.Entry<String, TransactionSummary> entry : summaries.entrySet()) {
            entry.getValue().calculateStats();
        }

        // Log processing times and errors
        long startTime = System.currentTimeMillis();
        try {
            processTransactionsParallel(summaries);
        } catch (Exception e) {
            System.err.println("Error during parallel processing: " + e.getMessage());
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Processing time: " + (endTime - startTime));

        return summaries;
    }

