    private ServerSocketChannel serverSocketChannel;
    private List<Connection> connectionList = new ArrayList<>();
    private ExecutorService executorService;
    private int initialConnections = 10; // Initial connections in the pool
    private int maxConnections = 50; // Maximum connections in the pool
    private int minIdleConnections = 5; // Minimum idle connections in the pool
    private long connectionTimeout = 30000; // Connection timeout in milliseconds
    private long heartBeatInterval = 1000; // Heartbeat interval in milliseconds

    public ConnectionPool(int port) throws IOException {
        serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress(port));
        executorService = Executors.newCachedThreadPool();
        startServer();
    }

    private void startServer() {
        Thread heartBeatThread = new Thread(() -> {
            while (true) {
                checkConnections();
                try {
                    Thread.sleep(heartBeatInterval);
                } catch (InterruptedException e) {
                    // Handle interrupt
                }
            }
        });
        heartBeatThread.start();

        serverSocketChannel.configureBlocking(false);
        SelectionKey key = serverSocketChannel.keyFor(null);
        if (!key.isValid()) {
            key.interestOps(SelectionKey.OP_ACCEPT);
        }

        while (true) {
            try {
                serverSocketChannel.accept();
            } catch (IOException e) {
                // Handle exception
            }
        }
    }

    public Connection createConnection() throws IOException {
        Connection connection = new Connection(serverSocketChannel.socket());
        executorService.submit(connection::start);
        return connection;
    }

    public void closeConnection(Connection connection) {
        connection.close();
    }

    private void checkConnections() {
