        imageProcessor = new ExternalImageProcessor();
    }

    public void setDefaultThemeDir(String dir) {
        if (!defaultThemeDir.equals(dir)) {
            themeBitmaps.clear();
            defaultThemeDir = dir;
        }
    }

    public Bitmap getThemeBitmap(String themeId) {
        Bitmap bitmap = themeBitmaps.get(themeId);
        if (bitmap != null && !bitmap.isRecycled()) {
            bitmap.recycle();
            bitmap = null;
        } else if (bitmap == null) {
            bitmap = imageProcessor.resizeImage(themeId + ".png", 100, 100);
            themeBitmaps.put(themeId, bitmap);
        }
        return bitmap;
    }

    public void evictLRU() {
        while (themeBitmaps.size() > maxCacheSize) {
            String lruKey = getLRUKey();
            Bitmap lruBitmap = themeBitmaps.remove(lruKey);
            if (lruBitmap != null) {
                lruBitmap.recycle();
                lruBitmap = null;
            }
        }
    }

