public class BackgroundService {
    private static final Random RAND = new Random();
    private static final int MIN_START_STOP_INTERVAL = 5 * 60 * 1000; // 5 minutes in milliseconds
    private static final int MAX_START_STOP_INTERVAL = 10 * 60 * 1000; // 10 minutes in milliseconds

    private static class ServiceState {
        boolean isRunning;
        long lastStartTimestamp;

        public ServiceState() {
            this.isRunning = false;
            this.lastStartTimestamp = System.currentTimeMillis();
        }
    }

    private static final List<ServiceState> SERVICE_STATES = new ArrayList<>();
    private static final Object STATE_ACCESS_LOCK = new Object();

    public static void main(String[] args) throws IOException, InterruptedException {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            for (ServiceState state : SERVICE_STATES) {
                if (state.isRunning) {
                    stopService();
                }
            }
        }));

        startServiceMonitoringThread();
        startConfigurationUpdateThread();

        while (true) {
            Thread.sleep(1000);
        }
    }

    private static void startService() {
        ServiceState state;
        synchronized (STATE_ACCESS_LOCK) {
            state = SERVICE_STATES.stream()
                    .filter(s -> !s.isRunning)
                    .findFirst()
                    .orElseThrow();
        }

        state.isRunning = true;
        state.lastStartTimestamp = System.currentTimeMillis();

        try {
            Thread.sleep(RAND.nextInt(5000)); // Simulate a random delay
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }

    private static void stopService() {
        ServiceState state;
        synchronized (STATE_ACCESS_LOCK) {
            state = SERVICE_STATES.stream()
                    .filter(s -> s.isRunning)
                    .findFirst()
                    .orElseThrow();
        }

        state.isRunning = false;

        // Simulate sending a message to an external monitoring system
        System.out.println("Service stopped. Duration since last start: " + (System.currentTimeMillis() - state.lastStartTimestamp));
    }

    private static void startServiceMonitoringThread() {
        new Thread(() -> {
            while (true) {
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
                long cpuUsage = getSystemCpuUsage();
                if (cpuUsage > 80) {
                    // Simulate adjusting the scheduling strategy based on real-time data feeds
                    System.out.println("CPU usage high. Postponing next scheduled start or stop operation by 1 minute.");
                    Thread.sleep(60 * 1000); // 1 minute in milliseconds
                }
            }
        }).start();
    }

    private static long getSystemCpuUsage() {
        // Simulate retrieving CPU utilization
        return 50;
    }

    private static void startConfigurationUpdateThread() {
        new Thread(() -> {
            while (true) {
                try {
                    Thread.sleep(RAND.nextInt((MAX_START_STOP_INTERVAL - MIN_START_STOP_INTERVAL) + 1) + MIN_START_STOP_INTERVAL);
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
                int newInterval = adjustStartStopInterval();
                System.out.println("New start-stop interval: " + newInterval);

                // Simulate updating the scheduling strategy based on current load conditions
                Thread.sleep(newInterval); // Simulate adjusting the next scheduled start or stop operation
            }
        }).start();
    }

    private static int adjustStartStopInterval() {
        // Simulate retrieving current system load metrics and adjusting the interval dynamically
        return 5 * 60 * 1000; // 5 minutes in milliseconds
    }

    public static void healthCheck() throws IOException {
        for (ServiceState state : SERVICE_STATES) {
            if (state.isRunning) {
                System.out.println("Service is running since: " + state.lastStartTimestamp);
            } else {
                System.out.println("Service is stopped.");
            }
        }
    }
}
