use tokio::{net::TcpStream, io};
use std::collections::HashMap;
use serde_json::json;

pub struct HttpClient {
    user_agent: String,
    timeout: u64,
    headers: HashMap<String, String>,
}

impl HttpClient {
    pub async fn new() -> Self {
        Self {
            user_agent: "MyHttpClient/1.0".to_string(),
            timeout: 10000,
            headers: HashMap::new(),
        }
    }

    pub async fn get(&self, url: &str) -> io::Result<tokio::sync::mpsc::Receiver<String>> {
        let mut client = reqwest::blocking::get(url).await?;
        client.header("User-Agent", self.user_agent.clone());
        for (k, v) in &self.headers {
            client.header(k.to_string(), v.clone());
        }
        client.timeout(self.timeout as f64).send().await?
    }

    pub async fn post(&self, url: &str, body: serde_json::Value) -> io::Result<tokio::sync::mpsc::Receiver<String>> {
        let mut client = reqwest::blocking::post(url).json(&body).await?;
        client.header("User-Agent", self.user_agent.clone());
        for (k, v) in &self.headers {
            client.header(k.to_string(), v.clone());
        }
        client.timeout(self.timeout as f64).send().await?
    }
}

#[tokio::main]
async fn main() {
    let client = HttpClient::new().await;
    let response = client.get("https://example.com").await.unwrap();
    println!("{}", response.recv().await);
}
