            array_push($results, ['success' => true]);
        } catch (Exception $e) {
            // Handle transient failures by retrying with exponential backoff
            if ($e instanceof TransientFailureException) {
                array_push($results, ['failure' => true, 'error' => $e->getMessage()]);
                continue; // Retry on next iteration
            }

            // Log the failure and return an error result
