<?php
function generateRandomString($configFilePath, $length, $charset) {
    $config = json_decode(file_get_contents($configFilePath), true);
    if ($config === null || !isset($config['characters']) || !isset($config['special_characters'])) {
        return 'Invalid configuration file';
    }
    $characters = array_merge(range('a', 'z'), range('A', 'Z'), range(0, 9));
    foreach ($config['characters'] as $char) {
        if (in_array($char, $characters)) {
            unset($characters[array_search($char, $characters)]);
        }
    }
    foreach ($config['special_characters'] as $char) {
        array_push($characters, $char);
    }
    shuffle($characters);
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        if (isset($config['no_repeating'])) {
            while (strpos($randomString, $characters[$i]) !== false) {
                $i--;
                break;
            }
        }
        $randomString .= $characters[$i];
    }
    return $randomString;
}
