#include <stdlib.h>
#include <pthread.h>

struct state {
    int id;
    pthread_mutex_t lock;
    struct state* next;
};

struct subset {
    int size;
    struct state** states;
    pthread_mutex_t lock;
};

struct fsa {
    int num_states;
    int last_state;
    struct state* states[];
};

struct subset* construct_subset(int* states, int num_states, struct fsa* fsa, int last_state, bool (*callback)(int)) {
    struct state** subset_states = NULL;
    int subset_size = 0;

    // Dynamically allocate memory for the subset
    pthread_mutex_init(&subset_states[0]->lock, NULL);

    // Iterate over each state in the FSA to filter and construct the subset
    for (int i = 0; i <= last_state; i++) {
        if (callback(states[i])) {
            struct state* new_state = realloc(subset_states[subset_size], sizeof(struct state));
            new_state->id = states[i];
            pthread_mutex_init(&new_state->lock, NULL);
            subset_states[subset_size] = new_state;
            subset_size++;
        }
    }

    // Update the 'next' pointer of the last state in the list
    for (int i = 0; i < num_states; i++) {
        if (states[i] == last_state) {
            fsa->states[i]->next = subset_states[subset_size - 1];
        }
    }

    return subset_states;
}
