#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <math.h>

#define MAX_DEVICES 100
#define MAX_SENSORS_PER_DEVICE 50
#define WINDOW_SIZE 100

typedef struct {
    double avg;
    double var;
    double max_deviation;
    pthread_mutex_t mutex;
} DeviceMetrics;

DeviceMetrics device_metrics[MAX_DEVICES];

void* process_data(void* arg) {
    int device_id = *(int*)arg;
    int sensor_id, timestamp, value;
    FILE* file = fopen("data.txt", "r");

    while(fscanf(file, "%d %d %d\n", &timestamp, &sensor_id, &value) == 3) {
        pthread_mutex_lock(&device_metrics[device_id].mutex);

        // Filter entries based on timestamp and frequency of recent readings
        if(timestamp > device_metrics[device_id].avg + WINDOW_SIZE) {
            device_metrics[device_id].avg = (double)value / (sensor_id % WINDOW_SIZE + 1);
            device_metrics[device_id].var = (double)(value - device_metrics[device_id].avg) * (value - device_metrics[device_id].avg);
            if(device_metrics[device_id].max_deviation < abs(value - device_metrics[device_id].avg))
                device_metrics[device_id].max_deviation = abs(value - device_metrics[device_id].avg);
        }

        pthread_mutex_unlock(&device_metrics[device_id].mutex);
    }

    fclose(file);
    return NULL;
}

int main() {
    pthread_t threads[MAX_DEVICES];
    int i, j;

    for(i = 0; i < MAX_DEVICES; i++) {
        device_metrics[i].avg = 0.0;
        device_metrics[i].var = 0.0;
        device_metrics[i].max_deviation = 0.0;
        pthread_mutex_init(&device_metrics[i].mutex, NULL);
    }

    for(i = 0; i < MAX_DEVICES; i++) {
        threads[i] = pthread_create(&threads[i], NULL, process_data, &i);
    }

    for(i = 0; i < MAX_DEVICES; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print the latest average and the corresponding sensor ID
    // for the reading that deviates the most from the mean for each device
    printf("Latest Average and Maximum Deviation:\n");
    for(i = 0; i < MAX_DEVICES; i++) {
        printf("Device %d: %.2f, Sensor %d\n", i, device_metrics[i].avg, i * (device_metrics[i].max_deviation > 0 ? (device_metrics[i].max_deviation / abs(device_metrics[i].max_deviation)) : 1));
    }

    return 0;
}
