class GameCharacter {
public:
    GameCharacter(int cooldown) : cooldown_(cooldown), is_attacking_(false), cooldown_timer_(cooldown) {}

    void selectAttack() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (is_attacking_ || cooldown_timer_.load(std::memory_order_relaxed) > 0) {
            // Wait until the current attack or cooldown completes
            cond_var_.wait(lock);
        }

        is_attacking_ = true;
        cooldown_timer_ = 0;

        // Notify any waiting threads that a new attack has started
        cond_var_.notify_all();
    }

private:
    std::atomic<int> cooldown_timer_;
    std::mutex mutex_;
    std::condition_variable cond_var_;
    bool is_attacking_;
};

