using System;
using System.Collections.Concurrent;
using System.Linq;

public class DynamicRangeManager
{
    private readonly ConcurrentDictionary<string, Range> _ranges = new();
    private readonly ILogger _logger;

    public DynamicRangeManager(ILogger logger)
    {
        _logger = logger;
    }

    public void AddRange(string key, float min, float max, bool inclusiveBoundary)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot exceed maximum value", nameof(min));

        _ranges.AddOrUpdate(key, new Range(min, max, inclusiveBoundary), (k, v) => v);
        _logger.LogInformation($"Added range '{key}' with min={min}, max={max} and boundary {inclusiveBoundary ? "inclusive" : "exclusive"}");
    }

    public void UpdateRange(string key, float? newMin = null, float? newMax = null, bool? newInclusiveBoundary = null)
    {
        if (!TryGetRange(key, out Range range))
            throw new ArgumentException("Range not found", nameof(key));

        if (newMin.HasValue && range.Min != newMin.Value || newMax.HasValue && range.Max != newMax.Value || newInclusiveBoundary.HasValue && range.InclusiveBoundary != newInclusiveBoundary.Value)
        {
            range = new Range(newMin ?? range.Min, newMax ?? range.Max, newInclusiveBoundary ?? range.InclusiveBoundary);
            _ranges.AddOrUpdate(key, range, (k, v) => range);
            _logger.LogInformation($"Updated range '{key}' with min={range.Min}, max={range.Max} and boundary {range.InclusiveBoundary ? "inclusive" : "exclusive"}");
        }
    }

    public void RemoveRange(string key)
    {
        if (!TryGetRange(key, out Range range))
            throw new ArgumentException("Range not found", nameof(key));

        _ranges.TryRemove(key, out range);
        _logger.LogInformation($"Removed range '{key}'");
    }

    public float GetRandomFloatValue(string key)
    {
        if (!TryGetRange(key, out Range range))
            throw new ArgumentException("Range not found", nameof(key));

        return (float)Generator.Random.NextDouble() * (range.Max - range.Min) + range.Min;
    }

    public int GetRandomIntegerValue(string key)
    {
        if (!TryGetRange(key, out Range range))
            throw new ArgumentException("Range not found", nameof(key));

        return Generator.Random.Next((int)range.Min, (int)range.Max);
    }

    public void ResetRange(string key)
    {
        if (!TryGetRange(key, out Range range))
            throw new ArgumentException("Range not found", nameof(key));

        _ranges.AddOrUpdate(key, new Range(range.DefaultMin, range.DefaultMax, range.InclusiveBoundary), (k, v) => new Range(v.DefaultMin, v.DefaultMax, v.InclusiveBoundary));
        _logger.LogInformation($"Reset range '{key}' to default settings");
    }

    public void ResetAllRanges()
    {
        foreach (var pair in _ranges)
        {
            var range = pair.Value;
            range.Min = range.DefaultMin;
            range.Max = range.DefaultMax;
            range.InclusiveBoundary = range.DefaultInclusiveBoundary;
        }
        _logger.LogInformation("Reset all ranges to default settings");
    }

    public bool TryGetRange(string key, out Range value)
    {
        return _ranges.TryGetValue(key, out value);
    }
}

public class Logger
{
    public void LogInformation(string message) { }
}

public static class Generator
{
    public static Random Random { get; } = new();
}
