["```javascript
class ReductionFunction {
  constructor(logLevel = 'debug') {
    this.logLevel = logLevel;
    this.progressTracker = new ProgressTracker();
  }

  async synchronousReduce(array, callback) {
    let result = null;
    for (let i = 0; i < array.length; i++) {
      const element = array[i];
      if (!result) {
        result = await callback(element);
      } else {
        result = await callback(result, element);
      }
      this.log(`Processed ${i + 1} of ${array.length}`);
    }
    return result;
  }

  async asynchronousReduce(array, callback) {
    const promises = array.map((element, i) => {
      return callback(element).then((result) => {
        if (!this.result) {
          this.result = result;
        } else {
          this.result = await callback(this.result, element);
        }
      });
    });
    const results = await Promise.all(promises);
    this.log(`Processed all ${array.length} elements`);
    return results[results.length - 1];
  }

  log(message) {
    if (this.logLevel === 'debug') {
      console.debug(message);
    } else if (this.logLevel === 'info') {
      console.info(message);
    }
  }
}

class ProgressTracker {
  constructor() {
    this.start = Date.now();
    this.totalElements = 0;
    this.processedElements = 0;
  }

  update(elements) {
    this.totalElements += elements;
    this.processedElements += elements;
  }

  getEstimatedCompletionTime() {
    return Date.now() + (this.totalElements - this.processedElements) * 100; // assume 10ms processing time per element
  }

  getProgress() {
    return (this.processedElements / this.totalElements) * 100;
  }
}

// Example usage:
const array = [1, 2, 3, 4, 5];
const callback = async (acc, current) => acc + current;

const reducer = new ReductionFunction('info');
const result = await reducer.asynchronousReduce(array, callback);
console.log(`Result: ${result}`);
```"]

