```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

typedef struct {
    char* key;
    char* value;
} ConfigPair;

void loadConfig(char* filePath, ConfigPair** configPairs, int* numPairs) {
    int fd = open(filePath, O_RDONLY);
    if (fd == -1) {
        printf("Error opening file: %s\n", strerror(errno));
        return;
    }

    off_t fileSize = lseek(fd, 0, SEEK_END);
    lseek(fd, 0, SEEK_SET);

    char* buffer = malloc(fileSize + 1);
    if (buffer == NULL) {
        printf("Error allocating memory: %s\n", strerror(errno));
        close(fd);
        return;
    }

    read(fd, buffer, fileSize);
    buffer[fileSize] = '\0';
    close(fd);

    // Parse configuration file contents
    char* token = strtok(buffer, "\n");
    int i = 0;
    while (token != NULL) {
        char* keyEnd = strchr(token, '=');
        if (keyEnd == NULL) {
            printf("Error parsing config file: malformed line '%s'\n", token);
            break;
        }

        *keyEnd++ = '\0';
        ConfigPair* pair = malloc(sizeof(ConfigPair));
        if (pair == NULL) {
            printf("Error allocating memory for config pair: %s\n", strerror(errno));
            break;
        }
        pair->key = strdup(token);
        pair->value = strdup(keyEnd);
        configPairs[i++] = pair;

        token = strtok(NULL, "\n");
    }

    *numPairs = i;
}

void printConfig(ConfigPair** configPairs, int numPairs) {
    for (int i = 0; i < numPairs; i++) {
        printf("Key: %s\nValue: %s\n", configPairs[i]->key, configPairs[i]->value);
    }
}

void freeConfig(ConfigPair** configPairs, int numPairs) {
    for (int i = 0; i < numPairs; i++) {
        free(configPairs[i]->key);
        free(configPairs[i]->value);
        free(configPairs[i]);
    }
}
