#include <tiffio.h>
#include <md5.h>

typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    uint16_t extra_samples;
    char md5_hash[33];
    int error_code;
    char* error_message;
} tiff_info;

tiff_info parse_tiff_file(const char* file_path) {
    TIFF* tif = TIFFOpen(file_path, "r");
    if (!tif) {
        tiff_info info;
        info.bits_per_sample = 0;
        info.samples_per_pixel = 0;
        info.extra_samples = 0;
        strcpy(info.md5_hash, "");
        info.error_code = 1;
        info.error_message = "Failed to open TIFF file";
        return info;
    }

    tiff_info info;

    // Get the bits per sample
    uint16_t bits_per_sample = TIFFGetField(tif, TIFF_FIELD_IMAGE_BITSPERSAMPLE);

    // Get the samples per pixel
    uint16_t samples_per_pixel = TIFFGetField(tif, TIFF_FIELD_IMAGE_SAMPLESPERPIXEL);

    // Get the extra samples
    uint16_t extra_samples = TIFFGetField(tif, TIFF_FIELD_IMAGE_EXTRASAMPLES);

    // Calculate the MD5 hash of the image file's metadata
    unsigned char md5_hash[17];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    unsigned char* buffer = (unsigned char*)malloc(TIFFTell(tif));
    TIFFReadBufferSetup(tif, buffer, 0);
    MD5_Update(&ctx, buffer, TIFFTell(tif) - 1);
    MD5_Final(&ctx, md5_hash);

    // Set the error code and message to 0
    info.error_code = 0;
    info.error_message = "";

    // Free the memory allocated for the buffer
    free(buffer);

    info.bits_per_sample = bits_per_sample;
    info.samples_per_pixel = samples_per_pixel;
    info.extra_samples = extra_samples;
    sprintf(info.md5_hash, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x",
        md5_hash[0], md5_hash[1], md5_hash[2], md5_hash[3],
        md5_hash[4], md5_hash[5], md5_hash[6], md5_hash[7],
        md5_hash[8], md5_hash[9], md5_hash[10], md5_hash[11],
        md5_hash[12], md5_hash[13], md5_hash[14], md5_hash[15], md5_hash[16]);

    TIFFClose(tif);

    return info;
}

