#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>

#define BUFFER_SIZE 128
#define MAX_FILENAME_LENGTH 60
#define MODIFIED_FILENAME_MAX_LENGTH 100
#define LOG_FILE_TYPE "log"
#define DIRECTORY_PERMISSIONS S_IRWXU | S_IRWXG | S_IROTH

void process_filenames(int network_stream, const char* directory) {
    int file_descriptor;
    struct stat sb;

    // Establish a connection to the network stream
    if (network_stream != -1) {
        // Read from the network stream in chunks of BUFFER_SIZE bytes
        char buffer[BUFFER_SIZE];
        while (read(network_stream, buffer, BUFFER_SIZE) > 0) {
            for (int i = 0; i < BUFFER_SIZE; i++) {
                if (buffer[i] == '\0' || buffer[i] == '\n') {
                    // Handle potential delays and packet loss
                    int bytes_read = i;
                    char* filename = malloc(bytes_read + 1);
                    memcpy(filename, buffer, bytes_read);
                    filename[bytes_read] = '\0';

                    // Trim the filename to MAX_FILENAME_LENGTH if necessary
                    int length = strlen(filename);
                    if (length > MAX_FILENAME_LENGTH) {
                        filename[MAX_FILENAME_LENGTH] = '\0';
                    }

                    // Validate the filename using printable ASCII characters only
                    int valid = 1;
                    for (int j = 0; j < length && valid; j++) {
                        if (!isprint(filename[j])) {
                            valid = 0;
                        }
                    }
                    if (!valid) {
                        // Reject invalid filenames
                        free(filename);
                        continue;
                    }

                    // Determine the number of digits in the original filename
                    int digit_count = 0;
                    while (length-- && isdigit(filename[length])) {
                        digit_count++;
                    }

                    // Modify the filename extension
                    char* modified_filename = malloc(MODIFIED_FILENAME_MAX_LENGTH + 1);
                    sprintf(modified_filename, "%s-%s", filename, LOG_FILE_TYPE);

                    // Store the modified filename in the specified directory
                    if ((file_descriptor = open(directory, O_RDWR | O_CREAT | O_TRUNC, DIRECTORY_PERMISSIONS)) != -1) {
                        write(file_descriptor, modified_filename, strlen(modified_filename));
                        close(file_descriptor);
                    } else {
                        // Handle errors during file creation or writing
                        perror("Error opening or writing the file");
                    }
                    free(filename);
                    free(modified_filename);
                }
            }
        }

        // Close the network stream
        close(network_stream);
    }
}
