AES_CTX* aes256_cbc_init(const char* password) {
    // Initialize AES context and derive encryption key from SHA-256 hashed password
    AES_CTX* ctx = (AES_CTX*)OPENSSL_malloc(sizeof(AES_CTX));
    if (!ctx) return NULL;

    unsigned char password_hash[SHA256_DIGEST_LENGTH];
    SHA256(password, strlen(password), password_hash);

    // Derive the 32-byte encryption key from the SHA-256 hashed password
    unsigned char* key = OPENSSL_malloc(32);
    if (key) {
        EVP_BytesToKey(NULL, NULL, password_hash, password_hash, 28, 32, key, NULL);
        ctx->key = key;
    }

    // Initialize the AES-256-CBC cipher context
    ctx->cipher = EVP_DecryptInit_ex(EVP_aes_256_cbc(), NULL, NULL);
    if (!ctx->cipher) {
        OPENSSL_free(key);
        return NULL;
    }

    // Initialize a 16-byte IV for the encryption context
    unsigned char iv[AES_BLOCK_SIZE];
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        iv[i] = (unsigned char)i;
    }
    ctx->iv = iv;

    return ctx;
}

