int convertImageToPDF(char *inputFileName, char *outputPdfFile, char *conversionToolPath, int timeout) {
    char command[1024];
    sprintf(command, "%s %s %s", conversionToolPath, inputFileName, outputPdfFile);

    pid_t pid = fork();
    if (pid == 0) { // Child process
        setpgid(pid, pid);
        dup2(STDOUT_FILENO, STDERR_FILENO);
        system(command);
        exit(0);
    } else {
        int status;
        waitpid(pid, &status, timeout * 1000); // Wait for up to timeout seconds

        if (WEXITSTATUS(status) != 0)
            return 1;

        return 0;
    }
}
