#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_COMMANDS 15
#define TIMEOUT 300 // in seconds

typedef struct {
    pid_t pid;
    time_t start_time;
} Command;

Command commands[MAX_COMMANDS];
int command_count = 0;

void handle_SIGCHLD(int signum) {
    while(waitpid(-1, NULL, WNOHANG) > 0);
}

void execute_command(int sock, char* command) {
    pid_t pid = fork();
    if(pid == 0) {
        // Child process
        execlp("/bin/sh", "sh", "-c", command, (char*)NULL);
        perror("execlp");
        exit(1);
    } else if(pid > 0) {
        // Parent process
        commands[command_count].pid = pid;
        time(commands[command_count].start_time) = time(NULL);
        command_count++;
    }
}

void check_commands() {
    for(int i = 0; i < MAX_COMMANDS; i++) {
        if(commands[i].pid > 0) {
            if(time(NULL) - commands[i].start_time > TIMEOUT) {
                kill(commands[i].pid, SIGKILL);
                waitpid(commands[i].pid, NULL, 0);
            }
        }
    }
}

int main() {
    int sock;
    struct sockaddr_in addr;

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if(sock < 0) {
        perror("socket");
        return -1;
    }

    // Set up server address
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

    // Bind socket to address and port
    if(bind(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind");
        return -1;
    }

    // Listen for incoming connections
    if(listen(sock, 3) < 0) {
        perror("listen");
        return -1;
    }

    signal(SIGCHLD, handle_SIGCHLD);

    while(1) {
        int conn_sock = accept(sock, NULL, NULL);
        if(conn_sock < 0) {
            perror("accept");
            continue;
        }

        // Read command from client
        char buffer[1024];
        read(conn_sock, buffer, sizeof(buffer));

        // Execute command and handle timeout
        execute_command(conn_sock, buffer);

        close(conn_sock);
    }

    return 0;
}
