using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class WebsiteManager
{
    private const string ConfigFile = "web.config";
    private const string ExecutablePathEnvVarName = "EXECUTABLE_PATH";
    private const string MaxDirectoryLengthEnvVarName = "MAX_DIRECTORY_LENGTH";
    private const string LoggingLevelEnvVarName = "LOGGING_LEVEL";

    public async Task ManageWebsite(string directoryPath, string siteName)
    {
        // Verify the directory path
        if (!IsAbsolutePath(directoryPath) || directoryPath.Length > GetMaxDirectoryLength())
        {
            throw new ArgumentException("Invalid directory path", nameof(directoryPath));
        }

        // Check for web.config file and configure default settings
        var configFileExists = File.Exists(Path.Combine(directoryPath, ConfigFile));
        if (!configFileExists)
        {
            Console.WriteLine($"Warning: No {ConfigFile} found in directory '{directoryPath}'. Using default settings.");
        }

        // Ensure the directory structure supports concurrent operations
        try
        {
            using (var fs = new FileStream(Path.Combine(directoryPath, ".lock"), FileMode.OpenOrCreate, FileAccess.Write))
            {
                fs.Close();
            }
        }
        catch
        {
            throw new Exception("Failed to create file lock for concurrent operations.");
        }

        // Start or stop the website process
        try
        {
            if (File.Exists(Path.Combine(directoryPath, siteName + ".exe")))
            {
                using var proc = Process.Start(new ProcessStartInfo
                {
                    FileName = GetExecutablePath(),
                    Arguments = siteName,
                    CreateNoWindow = true,
                    UseShellExecute = false,
                    RedirectStandardError = true,
                    RedirectStandardInput = true,
                    RedirectStandardOutput = true,
                    ErrorDialog = SystemServices.Minimize
                });

                // Monitor and manage the website process
                await Task.Run(() =>
                {
                    while (proc.HasExited)
                    {
                        Console.WriteLine($"Website '{siteName}' has stopped. Trying to restart...");
                        proc.Start();
                    }
                });
            }
            else
            {
                throw new Exception($"No executable file found for site '{siteName}'.");
            }
        }
        catch (Exception ex)
        {
            LogError(ex, $"Failed to start/stop website '{siteName}' in directory '{directoryPath}'.");
        }
    }

    private string GetExecutablePath()
    {
        return Environment.GetEnvironmentVariable(ExecutablePathEnvVarName);
    }

    private int GetMaxDirectoryLength()
    {
        return Convert.ToInt32(Environment.GetEnvironmentVariable(MaxDirectoryLengthEnvVarName));
    }

    private void LogError(Exception ex, string message)
    {
        var logger = new Logger();
        logger.LogError(message + Environment.NewLine + ex.Message + Environment.NewLine + ex.StackTrace);
    }
}

public class Logger
{
    public void LogError(string message)
    {
        // Implement structured logging with an existing service
    }
}
