        for (int i = 0; i < encryptedMessages.Split(new[] { '\n' }, StringSplitOptions.None).Length; i++)
        {
            try
            {
                byte[] encodedMessage = Convert.FromBase64String(encryptedMessages.Split(new[] { '\n' }, StringSplitOptions.None)[i]);
