                    cryptoServiceProvider.IV = ASCIIEncoding.ASCII.GetBytes(iv);

                    ICryptoTransform decryptor = cryptoServiceProvider.CreateDecryptor();
                    using (MemoryStream memoryStream = new MemoryStream(encodedMessage))
                    {
                        using (CryptoStream cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                        {
                            byte[] decryptedBytes;
                            using (StreamReader reader = new StreamReader(cryptoStream))
                            {
                                string message = reader.ReadToEnd();
                                decryptedMessages += message;
                                if (!IsValidMessage(message))
                                {
                                    Console.WriteLine($"Warning: Invalid message at index {i} with length {message.Length}");
                                }
                            }
                        }
                    }
                }
            }
            catch (FormatException)
            {
                Console.WriteLine($"Error decoding message at index {i}:");
                continue;
            }
        }

        return decryptedMessages;
    }

