using System.Threading;

public class AESCBCDecryptor
{
    private readonly ILogger _logger;

    public AESCBCDecryptor(ILogger logger)
    {
        _logger = logger;
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, int paddingSize)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;

            using (var decryptor = aes.CreateDecryptor())
            {
                using (var ms = new MemoryStream(ciphertext))
                {
                    using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        byte[] buffer = new byte[paddingSize];
                        int bytesRead;
                        while ((bytesRead = cs.Read(buffer, 0, buffer.Length)) > 0)
                        {
                            if (_logger.IsDebugEnabled())
                            {
                                _logger.Debug($"Decrypted {bytesRead} bytes");
                            }
                        }
                    }
                }
            }
        }
    }
}

public interface ILogger
{
    bool IsDebugEnabled();
    void Debug(string message);
}
