        {
            using (var stream = File.OpenRead(filePath))
            {
                var compressedStream = new CompressedReadStream(stream);
                var reader = GetCompressorReader(compressedStream);

                if (!reader.Read())
                {
                    _logger.LogError($"Failed to read from file {filePath}");
                    return;
                }

                dataStructure = DeserializeData(reader);
            }
        }

        private IReadArchive GetCompressorReader(Stream stream)
        {
            using (var reader = ReaderFactory.OpenReader(stream))
            {
                if (reader.CompressionType == CompressionType.GZip)
                {
                    return new GZipStream();
                }
                else if (reader.CompressionType == CompressionType.Deflate)
                {
                    return new DeflateStream();
                }
                else
                {
                    _logger.LogError("Unsupported compression format");
                    throw new InvalidOperationException();
                }
            }
        }

        private CustomDataStructure DeserializeData(IReadArchive archive)
        {
            // Implement deserialization logic for your custom data structure
