    @abstractmethod
    def log(self, level: int, message: str) -> None:
        pass

class ConsoleLogger(LoggingHandler):
    def log(self, level: int, message: str) -> None:
        print(f"{level}: {message}")

@lru_cache(maxsize=None)
def get_logger() -> object:
    return ConsoleLogger()

class ConfigurationManager(ConfigManager):
    def __init__(self):
        super().__init__()
        self.logger = get_logger()

    def get_config(self, name: str) -> dict:
        config = self.configs.get(name)
        if not config:
            provider = get_provider(name)
            try:
                config = provider.load_config()
                self.validate_config(config)
                self.configs[name] = config
                self.logger.log(logging.INFO, f"Loaded configuration {name}")
            except Exception as e:
                self.logger.log(logging.ERROR, f"Failed to load configuration {name}: {str(e)}")
        return config

    def save_config(self, config: dict) -> None:
        for name, provider in self.providers.items():
            try:
                provider.save_config(config)
                self.logger.log(logging.INFO, f"Saved configuration {name}")
            except Exception as e:
                self.logger.log(logging.ERROR, f"Failed to save configuration {name}: {str(e)}")

    def validate_config(self, config: dict) -> None:
        validator = get_validator()
        try:
            validator.validate(config)
        except Exception as e:
            self.logger.log(logging.ERROR, f"Invalid configuration: {str(e)}")
