#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure for NFAPI_RX_FRAME_PDU_T
typedef struct {
    // Structure fields...
} NFAPI_RX_FRAME_PDU_T;

// Define a linked list node structure
typedef struct {
    NFAPI_RX_FRAME_PDU_T* frame;
    struct node* next;
} Node;

// Define the dynamic list structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int size;
} DynamicList;

// Initialize a new dynamic list with a specified number of frames
DynamicList* initDynamicList(int numFrames) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    // Initialize frames
    for (int i = 0; i < numFrames; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        node->frame = ...; // initialize frame structure
        node->next = NULL;
        if (!list->head) {
            list->head = node;
            list->tail = node;
        } else {
            list->tail->next = node;
            list->tail = node;
        }
    }
    return list;
}

// Insert a new frame into the dynamic list based on RNTI
void insertFrame(DynamicList* list, NFAPI_RX_FRAME_PDU_T* frame, int rnti) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->frame = frame;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    // Insert at the beginning if RNTI is not found
    Node* current = list->head;
    while (current && current->frame.rnti != rnti) {
        current = current->next;
    }
    if (!current) {
        newNode->next = list->head;
        list->head = newNode;
    } else {
        // Insert after the found RNTI
        Node* prev = NULL;
        while (current && current->frame.rnti == rnti) {
            prev = current;
            current = current->next;
        }
        if (prev) {
            newNode->next = current;
            prev->next = newNode;
        } else {
            list->head = newNode;
        }
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Delete a frame from the dynamic list based on RNTI
void deleteFrame(DynamicList* list, int rnti) {
    Node** nodePtr = &list->head;
    Node* prev = NULL;

    pthread_mutex_lock(&list->lock);

    while (*nodePtr) {
        if ((*nodePtr)->frame.rnti == rnti) {
            Node* temp = *nodePtr;
            *nodePtr = (*nodePtr)->next;
            if (prev) {
                prev->next = *nodePtr;
            } else {
                list->head = *nodePtr;
            }
            free(temp);
            list->size--;
        } else {
            prev = *nodePtr;
            nodePtr = &((*nodePtr)->next);
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Get the most recent frame for a given RNTI
NFAPI_RX_FRAME_PDU_T* getRecentFrame(DynamicList* list, int rnti) {
    Node* current = list->head;
    NFAPI_RX_FRAME_PDU_T* recentFrame = NULL;

    pthread_mutex_lock(&list->lock);

    while (current) {
        if (current->frame.rnti == rnti) {
            recentFrame = current->frame;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return recentFrame;
}

// Filter frames based on RX_UE_INFORMATION_TAG and NFAPI_RRC_SIB1_TAG
void filterFrames(DynamicList* list, int rnti, int tag) {
    Node** nodePtr = &list->head;

    pthread_mutex_lock(&list->lock);

    while (*nodePtr) {
        if ((*nodePtr)->frame.rnti == rnti && (*nodePtr)->frame.tag == tag) {
            // Process the frame
        } else {
            Node* temp = *nodePtr;
            *nodePtr = (*nodePtr)->next;
            free(temp);
            list->size--;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Release resources and deallocate memory
void destroyDynamicList(DynamicList* list) {
    Node* current = list->head;
    Node* next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

