typedef struct {
    int RNTI;
    NFAPI_RX_FRAME_PDU_T *frame;
} frame_entry;

typedef struct {
    int count;
    frame_entry **frames;
    // hash table to track the most recent frame for each RNTI
    int rnti_to_index[256]; // assume 256 possible RNTIs
} dynamic_frame_list;

dynamic_frame_list* init_dynamic_frame_list(int num_frames) {
    dynamic_frame_list *list = malloc(sizeof(dynamic_frame_list));
    list->count = 0;
    list->frames = (frame_entry**)malloc(num_frames * sizeof(frame_entry*));
    for (int i = 0; i < num_frames; i++) {
        list->frames[i] = NULL;
    }
    memset(list->rnti_to_index, -1, sizeof(list->rnti_to_index));
    return list;
}

void add_frame(dynamic_frame_list *list, NFAPI_RX_FRAME_PDU_T *frame) {
    frame_entry *new_entry = malloc(sizeof(frame_entry));
    new_entry->RNTI = frame->RNTI;
    new_entry->frame = frame;

    // find the correct position to insert the new frame
    for (int i = 0; i < list->count; i++) {
        if (list->frames[i]->RNTI > new_entry->RNTI) {
            break;
        }
    }

    // shift frames to make room for the new one
    for (int j = list->count; j > i; j--) {
        list->frames[j] = list->frames[j-1];
    }

    // insert the new frame at the correct position
    list->frames[i] = new_entry;
    list->rnti_to_index[new_entry->RNTI] = i;

    // update the count
    list->count++;
}

void remove_frame(dynamic_frame_list *list, int RNTI) {
    int index = list->rnti_to_index[RNTI];
    if (index >= 0 && index < list->count) {
        free(list->frames[index]);
        for (int i = index; i < list->count - 1; i++) {
            list->frames[i] = list->frames[i+1];
        }
        list->count--;
        list->rnti_to_index[RNTI] = -1;
    }
}

