    public XElement ProcessXmlFile(string filePath, Func<XElement, bool> filterCriteria)
    {
        try
        {
            XDocument xmlDoc = XDocument.Load(filePath);
            foreach (XElement node in xmlDoc.Descendants())
            {
                if (filterCriteria(node))
                    return node;
            }
            return null; // No matching nodes found
        }
