use reqwest;
use std::fs::OpenOptions;
use std::io::{self, BufReader};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::mpsc;

const MAX_REQUESTS: usize = 5; // max concurrent requests

struct NetworkRequest {
    url: String,
    headers: Vec<(String, String)>,
}

fn handle_input_and_network() -> Result<(), io::Error> {
    let mut input_stream = BufReader::new(io::stdin());
    let mut numbers = Vec::new();
    let mut max_value = AtomicUsize::new(0);
    let (tx, rx) = mpsc::channel();

    for line in input_stream.lines() {
        match line {
            Ok(n) => {
                let num: u32 = n.parse().unwrap_or_else(|_| panic!("Invalid number: {}", n));
                numbers.push(num);
                max_value.fetch_max(AtomicUsize::new(num as usize), Ordering::Relaxed);
            }
            Err(_) => break,
        }
    }

    let mut headers = Vec::new();
    if let Ok(req_headers) = std::env::var("REQ_HEADERS") {
        for header in req_headers.split(',') {
            let (key, value) = header.trim().split_once(':').unwrap_or_default();
            headers.push((String::from(key), String::from(value)));
        }
    }

    let mut client = reqwest::blocking::ClientBuilder::new()
        .timeout(reqwest::Time::from_secs(5)) // adjust timeout as needed
        .dangerously_allow_url_connections(true) // allow non-HTTPS connections for testing, etc.
        .set_certificate_bundle_dir("/path/to/cert/bundle") // customize certificate validation
        .build()?;

    let mut request_queue = Vec::new();

    for &num in numbers.iter().filter(|&&n| n > 0) {
        if num % 100 == 0 {
            send_request(&mut client, &headers, tx.clone(), "https://example.com/handler".to_string());
        }
    }

    for _ in 0..MAX_REQUESTS {
        match rx.recv() {
            Ok(_) => println!("Request completed"),
            Err(_err) => break,
        }
    }

    println!("Max value: {}", max_value.load(Ordering::Relaxed));

    Ok(())
}

fn send_request(client: &reqwest::blocking::Client, headers: Vec<(String, String)>, tx: mpsc::Sender<String>, url: String) {
    for _ in 0..MAX_REQUESTS {
        match client.post(&url).headervec(headers.clone()).send() {
            Ok(res) => {
                tx.send(res.text().unwrap_or_default()).unwrap();
                return;
            }
            Err(err) => {
                if err.is_timeout() || err.is_status_code(502) {
                    // retry or handle error as needed
                    std::thread::sleep(std::time::Duration::from_millis(500));
                    continue;
                } else {
                    println!("Error: {}", err);
                    return;
                }
            }
        }
    }

    tx.send("Timeout".to_string()).unwrap();
}
