using System;

public class RandomRangeGenerator
{
    private readonly Random _random = new Random();
    private int _minValue;
    private int _maxValue;

    public RandomRangeGenerator(int minValue, int maxValue)
    {
        ValidateRange(minValue, maxValue);
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public double GenerateRandomFloat()
    {
        return (double)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GenerateRandomInt()
    {
        return _random.Next(_minValue, _maxValue + 1);
    }

    private void ValidateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value must be less than or equal to max value.");
    }

    public override string ToString()
    {
        return $"Random values in range [{_minValue}, {_maxValue}]";
    }
}
