import java.util.*;

public class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            makeSet(i);
        }
    }

    private void makeSet(int x) {
        parent[x] = x;
        rank[x] = 0;
    }

    public int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    public boolean union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY)
            return false;

        if (rank[rootX] > rank[rootY])
            parent[rootY] = rootX;
        else if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
        return true;
    }

    public int countDisjointPairs(int[] arr) {
        UnionFind uf = new UnionFind(arr.length);
        int disjointCount = 0;

        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (!uf.union(i, j)) {
                    disjointCount++;
                    System.out.println("Disjoint pair: (" + i + ", " + j + ") in " + (System.currentTimeMillis() - 100) + " ms");
                }
            }
        }

        return disjointCount;
    }
}
