#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>

// Function prototypes
double calculate_mean(float* numbers, int size);
double calculate_stddev(float* numbers, int size, double mean);
void create_udp_packet(int seq_num, float payload[], char* buffer, int buffer_size);

int main() {
    // Read input data
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return 1;
    }

    // Allocate memory for the list of numbers
    float* numbers = (float*)malloc(sizeof(float));
    int size = 0;

    while (!feof(file)) {
        fscanf(file, "%f", &numbers[size]);
        size++;
        numbers = realloc(numbers, sizeof(float) * (size + 1));
    }

    fclose(file);

    // Calculate mean and standard deviation
    double mean = calculate_mean(numbers, size);
    double stddev = calculate_stddev(numbers, size, mean);

    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", stddev);

    // Create UDP packets
    int packet_count = 0;
    for (int i = 0; i < size; i++) {
        float payload[4];
        memcpy(payload, &numbers[i], sizeof(float));
        char buffer[1024];

        create_udp_packet(packet_count, payload, buffer, 1024);
        packet_count++;
    }

    // Free memory
    free(numbers);

    return 0;
}

double calculate_mean(float* numbers, int size) {
    double sum = 0.0;

    for (int i = 0; i < size; i++) {
        sum += numbers[i];
    }

    return sum / size;
}

double calculate_stddev(float* numbers, int size, double mean) {
    double variance = 0.0;

    for (int i = 0; i < size; i++) {
        variance += pow(numbers[i] - mean, 2);
    }

    return sqrt(variance / size);
}

void create_udp_packet(int seq_num, float payload[], char* buffer, int buffer_size) {
    // Create UDP packet
    struct sockaddr_in dest;
    dest.sin_family = AF_INET;
    dest.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &dest.sin_addr);

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        printf("Error creating UDP socket.\n");
        return;
    }

    sendto(sock, buffer, sizeof(char), 0, (struct sockaddr*)&dest, sizeof(dest));

    // Handle errors
    if (sendto(sock, buffer, sizeof(char), 0, (struct sockaddr*)&dest, sizeof(dest)) < 0) {
        printf("Error sending UDP packet.\n");
    }

    close(sock);
}
