import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class HashProcessor {
    private static final int BUFFER_SIZE = 1024 * 1024; // 1MB
    private static final ExecutorService executor = Executors.newCachedThreadPool();

    public static byte[] concatenateHashValues(List<String> inputStrings, String algorithm) throws IOException, InterruptedException {
        List<Future<byte[]>> futures = new ArrayList<>();
        for (String s : inputStrings) {
            Path path = Paths.get(s);
            try (BufferedReader reader = Files.newReader(path)) {
                StringBuilder buffer = new StringBuilder();
                char[] chars = new char[BUFFER_SIZE];
                int read;
                while ((read = reader.read(chars)) != -1) {
                    buffer.append(new String(chars, 0, read));
                }
                byte[] inputBytes = buffer.toString().getBytes("UTF-8");
                MessageDigest md = MessageDigest.getInstance(algorithm);
                ByteBuffer buffer2 = ByteBuffer.allocate(BUFFER_SIZE);
                for (int i = 0; i < inputBytes.length; i += BUFFER_SIZE) {
                    int chunkSize = Math.min(inputBytes.length - i, BUFFER_SIZE);
                    buffer2.put(inputBytes, i, chunkSize);
                    byte[] hashBytes = md.digest(buffer2.array());
                    futures.add(executor.submit(() -> hashBytes));
                }
            }
        }

        List<byte[]> results = new ArrayList<>();
        for (Future<byte[]> future : futures) {
            try {
                results.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
        }

        byte[] concatenatedHashValue = new byte[0];
        for (byte[] result : results) {
            concatenatedHashValue = concatenateBytes(concatenatedHashValue, result);
        }
        return concatenatedHashValue;
    }

    private static byte[] concatenateBytes(byte[] bytes1, byte[] bytes2) {
        byte[] result = new byte[bytes1.length + bytes2.length];
        System.arraycopy(bytes1, 0, result, 0, bytes1.length);
        System.arraycopy(bytes2, 0, result, bytes1.length, bytes2.length);
        return result;
    }
}
