int read_integers(int *arr, int size);
void print_largest_integer(int *arr, int size);

void* init_aes_cbc(const char *password) {
    unsigned char password_hash[SHA_DIGEST_SIZE];
    SHA1(password, strlen(password), password_hash);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX_set_padding(ctx, 0);
    AES_KEY *aes_key = (AES_KEY *)OPENSSL_malloc(AES_KEY_SIZE);
    AES_IV *aes_iv = (AES_IV *)OPENSSL_malloc(AES_IV_SIZE);
    memcpy(aes_key->r, password_hash, SHA_DIGEST_SIZE);
    EVP_SealInit(ctx, &aes_key, aes_iv, NULL, NULL);

    void *cipher_ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX_set_cipher(ctx, EVP_aes_256_cbc());
    EVP_CIPHER_CTX_set_key_length(ctx, AES_KEY_SIZE);
    EVP_CIPHER_CTX_set_iv_length(ctx, AES_IV_SIZE);

    return cipher_ctx;
}

void cleanup(void *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    const char *password = "your_password";
    void *cipher_ctx = init_aes_cbc(password);
    int arr[INTEGER_ARRAY_SIZE];
    int size = read_integers(arr, INTEGER_ARRAY_SIZE);
    print_largest_integer(arr, size);
    cleanup(cipher_ctx);
    return 0;
}

int read_integers(int *arr, int size) {
    int i = 0;
    while (i < size && scanf("%d", &arr[i]) == 1)
        i++;
    return i;
}

void print_largest_integer(int *arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++)
        if (arr[i] > max)
            max = arr[i];
    printf("Largest integer: %d\n", max);
}
