#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <json-c/json.h>

#define MAX_CONNECTIONS 1000
#define MAX_CLIENT_ID 64
#define MAX_SOCKET_DESC 256

typedef struct {
    int client_id;
    int socket_desc;
    int timeout;
} Connection;

Connection *connection_pool = NULL;
int num_connections = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_connection_pool(int max_connections) {
    connection_pool = (Connection *)malloc(max_connections * sizeof(Connection));
    num_connections = 0;
}

void free_connection_pool() {
    for (int i = 0; i < num_connections; i++) {
        close(connection_pool[i].socket_desc);
    }
    free(connection_pool);
}

int create_connection(int client_id, int socket_desc) {
    pthread_mutex_lock(&mutex);
    if (num_connections >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    connection_pool[num_connections].client_id = client_id;
    connection_pool[num_connections].socket_desc = socket_desc;
    connection_pool[num_connections].timeout = 30; // default timeout

    num_connections++;
    pthread_mutex_unlock(&mutex);

    return 0;
}

void close_connection(int client_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_connections; i++) {
        if (connection_pool[i].client_id == client_id) {
            close(connection_pool[i].socket_desc);
            connection_pool[i] = connection_pool[--num_connections];
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void update_timeout(int client_id, int new_timeout) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_connections; i++) {
        if (connection_pool[i].client_id == client_id) {
            connection_pool[i].timeout = new_timeout;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void process_json_response(char *json_data) {
    json_object *json_obj = json_tokener_parse(json_data);

    if (!json_obj) {
        // handle error
    }

    int client_id = json_object_get_int_value(json_obj, "client_id");
    int new_timeout = json_object_get_int_value(json_obj, "timeout");

    update_timeout(client_id, new_timeout);
}

void shutdown_connection_pool() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_connections; i++) {
        close(connection_pool[i].socket_desc);
    }

    free_connection_pool();

    pthread_mutex_unlock(&mutex);
}
