#include <pthread.h>

#define DNS_QUERY_TIMEOUT 10000 // 10 seconds in milliseconds
#define MAX_CONCURRENT_QUERIES 50
#define LOG_BUF_SIZE 256

typedef struct {
    char* hostname;
    u_char* ip;
    int status; // 0: pending, 1: resolved, 2: error
} dns_query_t;

pthread_mutex_t query_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t query_ready = PTHREAD_COND_INITIALIZER;
int current_queries = 0;
int max_queries = MAX_CONCURRENT_QUERIES;
u_char* ip_cache[256]; // Initialize with size of 256 for simplicity

void* query_thread(void* arg) {
    dns_query_t* query = (dns_query_t*)arg;
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        query->status = 2; // Error: unable to create socket
        return NULL;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(53);

    inet_pton(AF_INET, "8.8.8.8", &server_addr.sin_addr); // Replace with actual DNS server IP

    int query_id = 0;
    while (1) {
        pthread_mutex_lock(&query_lock);
        if (current_queries >= max_queries) {
            pthread_cond_wait(&query_ready, &query_lock);
        }

        if (query->status == 2) {
            // Query already failed or cancelled
            break;
        }

        struct sockaddr_in query_addr;
        query_addr.sin_family = AF_INET;
        inet_pton(AF_INET, query->hostname, &query_addr.sin_addr);

        int send_len = sizeof(struct iphdr);
        sendto(sock, &query_addr, send_len, 0, (struct sockaddr*)&server_addr, sizeof(server_addr));
        usleep(DNS_QUERY_TIMEOUT); // Wait for DNS query response

        char buffer[1024];
        recvfrom(sock, buffer, 1024, 0, NULL, NULL);
        u_char* ip = inet_ntoa((struct in_addr*)buffer);
        if (ip) {
            query->status = 1; // Query resolved
            query->ip = ip;
        } else {
            query->status = 2; // Error: unable to resolve IP
        }

        pthread_mutex_unlock(&query_lock);

        if (query->status == 1) {
            // Log successful query resolution
            printf("[%s] %s -> %s\n", strftime("%Y-%m-%d %H:%M:%S", &now, LOG_BUF_SIZE), query->hostname, ip);
        } else {
            // Log failed or cancelled query
            printf("[%s] %s -> error\n", strftime("%Y-%m-%d %H:%M:%S", &now, LOG_BUF_SIZE), query->hostname);
        }
    }

    close(sock);
    return NULL;
}

int perform_dns_resolution(char* hostname) {
    dns_query_t query = { .hostname = hostname, .ip = NULL, .status = 0 };
    pthread_t thread;

    pthread_create(&thread, NULL, query_thread, &query);

    pthread_mutex_lock(&query_lock);
    current_queries++;
    pthread_cond_signal(&query_ready);

    while (1) {
        if (query.status == 2) {
            // Query failed or cancelled
            break;
        }

        pthread_cond_wait(&query_ready, &query_lock);

        if (query.status == 1) {
            // Query resolved successfully
            return 0; // Success
        }
    }

    // Error: unable to resolve IP or query timed out
    return -1;
}

int main() {
    char* hostname = "example.com";
    int status = perform_dns_resolution(hostname);
    if (status == 0) {
        printf("Resolved %s to %s\n", hostname, inet_ntoa((struct in_addr*)query.ip));
    } else {
        printf("Error: unable to resolve %s\n", hostname);
    }
}
