    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

UserSession** init_user_sessions(int num_sessions) {
    srand(time(NULL));
    UserSession** sessions = malloc_or_die(num_sessions * sizeof(UserSession*));
    for (int i = 0; i < num_sessions; i++) {
        UserSession* session = malloc_or_die(sizeof(UserSession));
        session->session_id = rand() % 1000000;
        while (sessions[i]) {
            if (session->session_id == sessions[i]->session_id) {
                // Duplicate ID detected
                FILE* log_file = fopen("log.txt", "a");
                fprintf(log_file, "Duplicate ID detected at %s.\n"
                                 "Conflicting session details: ID=%d, Login Timestamp=%ld, "
                                 "Last Activity Timestamp=%ld, IP Address=%s, Browser Type=%s, User Agent String=%s\n",
                                  ctime(&time(NULL)), session->session_id,
                                  session->login_timestamp, session->last_activity_timestamp,
                                  session->ip_address, session->browser_type, session->user_agent_string);
                fclose(log_file);
                // Reassign a new ID
                session->session_id = rand() % 1000000;
                i--;
            }
        }
        sessions[i] = session;
    }
    return sessions;
}

void free_user_sessions(UserSession** sessions, int num_sessions) {
    for (int i = 0; i < num_sessions; i++) {
        free(sessions[i]);
    }
    free(sessions);
}
