// Define a structure for network packet headers and graph vertices
typedef struct {
    int packet_id;
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int protocol_type;
    // Vertex properties
} PacketVertex;

// Initialize the list with n entries, populating each entry with random valid values
PacketVertex* initialize_packet_list(int n) {
    PacketVertex* packet_list = (PacketVertex*)malloc(n * sizeof(PacketVertex));

    // Preload whitelist of allowed IP addresses and vertex properties
    char* allowed_ips[] = {"192.168.1.1", "10.0.0.1"};
    int allowed_vertex_properties[] = {1, 2, 3};

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < n; i++) {
        PacketVertex* packet = &packet_list[i];

        // Ensure no duplicate IDs
        while (true) {
            packet->packet_id = rand() % 10000;
            int found_duplicate = 0;

            for (int j = 0; j < i; j++) {
                if (packet->packet_id == packet_list[j].packet_id) {
                    found_duplicate = 1;
                    break;
                }
            }

            if (!found_duplicate) {
                break;
            }
        }

        // Validate and populate IP addresses
        for (int j = 0; j < sizeof(allowed_ips) / sizeof(*allowed_ips); j++) {
            if (strcmp(packet->source_ip, allowed_ips[j]) == 0 || strcmp(packet->destination_ip, allowed_ips[j]) == 0) {
                // Replace invalid IP with default value and log warning
                sprintf(packet->source_ip, "192.168.%d.%d", rand() % 255, rand() % 255);
                sprintf(packet->destination_ip, "10.%d.%d.%d", rand() % 255, rand() % 255, rand() % 255);
            }
        }

        // Validate and populate vertex properties
        for (int j = 0; j < sizeof(allowed_vertex_properties) / sizeof(*allowed_vertex_properties); j++) {
            if (packet->protocol_type == allowed_vertex_properties[j]) {
                // Replace invalid property with default value and log warning
                packet->protocol_type = rand() % 3;
            }
        }
    }

    return packet_list;
}

int main() {
    PacketVertex* packet_list = initialize_packet_list(100);
    for (int i = 0; i < 100; i++) {
        printf("Packet ID: %d\n", packet_list[i].packet_id);
        printf("Timestamp: %ld\n", packet_list[i].timestamp);
        printf("Source IP: %s\n", packet_list[i].source_ip);
        printf("Destination IP: %s\n", packet_list[i].destination_ip);
        printf("Protocol Type: %d\n", packet_list[i].protocol_type);
    }

    return 0;
}
