    } sessions[MAX_SESSIONS_PER_CONTEXT];
} UE_Context;

UE_Context* contexts = NULL;
int num_contexts = 0;

void* add_context(void* arg) {
    pthread_mutex_lock(&mutex);
    // Add new context and update the array
    UE_Context* new_context = (UE_Context*)malloc(sizeof(UE_Context));
    // Initialize the new context
    new_context->ue_id = rand();
    new_context->serving_plmns = 2;
    for (int i = 0; i < MAX_SESSIONS_PER_CONTEXT; i++) {
        new_context->sessions[i].qos_level = 1;
        new_context->sessions[i].qos_params = NULL;
    }
    // Add the new context to the array
    contexts = realloc(contexts, (num_contexts + 1) * sizeof(UE_Context));
    contexts[num_contexts] = new_context;
    num_contexts++;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* remove_context(void* arg) {
    pthread_mutex_lock(&mutex);
    // Find the context to be removed
    for (int i = 0; i < num_contexts; i++) {
        if (arg == &contexts[i]) {
            free(contexts[i].sessions[0].qos_params);
            free(contexts[i]);
            memmove(&contexts[i], &contexts[i + 1], (num_contexts - i - 1) * sizeof(UE_Context));
            num_contexts--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void update_qos(int context_id, int qos_level) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_contexts; i++) {
        if (contexts[i].ue_id == context_id) {
            for (int j = 0; j < MAX_SESSIONS_PER_CONTEXT; j++) {
                contexts[i].sessions[j].qos_level = qos_level;
            }
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    // Initialize the array of UE context information structures
    contexts = (UE_Context*)malloc(sizeof(UE_Context) * MAX_CONTEXTS);

    // Create a thread to periodically update UE context information from an external database
    pthread_t update_thread;
    pthread_create(&update_thread, NULL, &add_context, NULL);

    return 0;
}
