    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *create_and_populate_nfa_pdu(int n, int *error_code) {
    int i;
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        *error_code = 1; // Memory allocation failed
        return NULL;
    }

    for (i = 0; i < n && i < MAX_STRUCTURES; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        pdu_array[i].RNTI = rand() % (MAX_RNTI - MIN_RNTI) + MIN_RNTI;
        sprintf(pdu_array[i].CRC_INDICATION_REL8_TAG, "CRCFLAG_%d", i);
        pdu_array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        if (pdu_array[i].RNTI < MIN_RNTI || pdu_array[i].RNTI > MAX_RNTI) {
            *error_code = 2; // RNTI out of range
            return NULL;
        }
    }

    int success_count = i;
    free(pdu_array);
    return &pdu_array[0];
}
