#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 1024
#define MAX_EVENTS 10000
#define RETENTION_POLICY 3600 // seconds (1 hour)

typedef struct {
    time_t timestamp;
    char event_type;
    char source_id[10];
    char payload[MAX_PAYLOAD_SIZE + 1];
} Event;

Event* events = NULL;
int num_events = 0;

void log_event(Event* new_event) {
    if (num_events >= MAX_EVENTS) {
        // Handle overflow
        printf("Event log full. Consider increasing the buffer size.\n");
        return;
    }

    events[num_events] = *new_event;
    num_events++;
}

void clear_stale_events() {
    time_t current_time = time(NULL);
    int stale_events = 0;

    for (int i = 0; i < num_events; i++) {
        if ((current_time - events[i].timestamp) > RETENTION_POLICY) {
            // Clear stale event
            memmove(&events[i], &events[i + 1], (num_events - i - 1) * sizeof(Event));
            num_events--;
            i--; // Decrement loop counter to re-process the current index
        } else {
            stale_events++;
        }
    }

    if (!stale_events)
        printf("No stale events found.\n");
}

void* allocate_payload(size_t size) {
    void* payload = malloc(size);
    if (payload == NULL || size > MAX_PAYLOAD_SIZE) {
        // Handle allocation error
        free(payload);
        return NULL;
    }
    return payload;
}

int main() {
    Event new_event;
    new_event.timestamp = time(NULL);
    strcpy(new_event.source_id, "source");
    new_event.event_type = 'E';

    // Allocate and initialize the first event's payload
    char* payload = (char*) allocate_payload(strlen("This is a sample event") + 1);
    strcpy(payload, "This is a sample event");
    strcpy(new_event.payload, payload);

    log_event(&new_event);

    while (num_events > 0) {
        clear_stale_events();
        sleep(1); // Simulate periodic clearing of stale events
    }

    return 0;
}
