#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CONNECTIONS 1000
#define AVG_HISTORY 5

typedef struct {
    int id;
    char peer_address[17]; // IPv4 address
    int packet_sizes[AVG_HISTORY];
} connection_state;

connection_state* connections = NULL;
int num_connections = 0;
int avg_packet_size_sum = 0;

void add_connection(int id, const char* peer_address) {
    if (num_connections >= MAX_CONNECTIONS) {
        printf("Maximum number of connections reached.\n");
        return;
    }

    connection_state* new_conn = (connection_state*)malloc(sizeof(connection_state));
    strcpy(new_conn->peer_address, peer_address);
    new_conn->id = id;

    // Initialize packet size history
    for (int i = 0; i < AVG_HISTORY; i++) {
        new_conn->packet_sizes[i] = 0;
    }

    if (connections == NULL) {
        connections = new_conn;
    } else {
        connection_state* temp = connections;
        connections = new_conn;
        new_conn->next = temp;
    }

    num_connections++;
}

void update_connection(int id, int packet_size) {
    for (connection_state* curr = connections; curr != NULL; curr = curr->next) {
        if (curr->id == id) {
            // Update last observed packet size
            curr->packet_sizes[AVG_HISTORY - 1] = packet_size;

            // Calculate rolling average packet size
            int sum = 0;
            for (int i = 0; i < AVG_HISTORY; i++) {
                sum += curr->packet_sizes[i];
            }
            avg_packet_size_sum -= sum / AVG_HISTORY;
            avg_packet_size_sum += packet_size;
        }
    }
}

double get_average_packet_size() {
    return (double)avg_packet_size_sum / num_connections;
}

int main() {
    srand(time(NULL));

    add_connection(1, "192.168.1.100");
    add_connection(2, "10.0.0.1");

    for (int i = 0; i < 50; i++) {
        int id = rand() % num_connections + 1;
        int packet_size = rand() % 1500;
        update_connection(id, packet_size);
    }

    printf("Average packet size: %.2f\n", get_average_packet_size());

    return 0;
}
