    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

void init_node(struct node** node, NFAPI_CRC_INDICATION_PDU_T data) {
    *node = (struct node*)malloc(sizeof(struct node));
    if (*node == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }
    (*node)->data = data;
    (*node)->next = NULL;
}

void delete_node(struct node** node) {
    if (*node != NULL) {
        free(*node);
        *node = NULL;
    }
}

struct node* insert_node(struct node* head, NFAPI_CRC_INDICATION_PDU_T data) {
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    if (new_node == NULL) {
        printf("Memory allocation failed!\n");
        return head;
    }
    new_node->data = data;
    new_node->next = head;
    return new_node;
}

void delete_node_at_pos(struct node** head, int pos) {
    struct node* temp = *head;
    if (pos == 0) {
        *head = (*head)->next;
        delete_node(&temp);
        return;
    }
    for (int i = 0; i < pos - 1 && temp != NULL; i++) {
        temp = temp->next;
    }
    if (temp == NULL || temp->next == NULL) {
        printf("Position out of bounds!\n");
        return;
    }
    delete_node(&temp->next);
}

void clear_list(struct node** head) {
    struct node* temp = *head;
    while (temp != NULL) {
        struct node* next = temp->next;
        delete_node(&temp);
        temp = next;
    }
    *head = NULL;
}

int main() {
    // Example usage:
    NFAPI_CRC_INDICATION_PDU_T data1 = {"Tag1", 123, "Rel8TAG1", 0x1234};
    init_node(&node1, data1);
    NFAPI_CRC_INDICATION_PDU_T data2 = {"Tag2", 456, "Rel8TAG2", 0x5678};
    insert_node(&head, data2);

    // ...

    clear_list(&head);

    return 0;
}
