pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* nfa_list = NULL;
int nfa_list_size = 0;

void init_nfa_list() {
    if (!nfa_list) {
        nfa_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ELEMS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfa_list) {
            LOG_ERROR("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
    }
}

void add_nfa_element(RX_UE_INFORMATION_TAG tag, RNTI rnti, CRC_INDICATION_REL8_TAG crcflag) {
    pthread_mutex_lock(&list_mutex);
    init_nfa_list();

    if (nfa_list_size >= MAX_ELEMS) {
        LOG_ERROR("List is full");
    } else {
        NFAPI_CRC_INDICATION_PDU_T* elem = &nfa_list[nfa_list_size++];
        elem->tag = tag;
        elem->rnti = rnti;
        elem->crcflag = crcflag;
    }

    pthread_mutex_unlock(&list_mutex);
}

int get_nfa_list_size() {
    int size;
    pthread_mutex_lock(&list_mutex);
    size = nfa_list_size;
    pthread_mutex_unlock(&list_mutex);
    return size;
}

void* handle_crc_flags(void* arg) {
    // Generate unique random CRCFLAG value for each element
    for (int i = 0; i < MAX_CRCFLAGS; i++) {
        add_nfa_element(/*generate random tag*/, /*generate random RNTI*/, (CRC_INDICATION_REL8_TAG)(i & 0xFF));
    }

    return NULL;
}

void monitor_resources() {
    // Monitor resource usage and detect potential memory leaks
    // ...
}

int main() {
    pthread_t threads[MAX_CRCFLAGS];
    for (int i = 0; i < MAX_CRCFLAGS; i++) {
        pthread_create(&threads[i], NULL, handle_crc_flags, NULL);
    }

    for (int i = 0; i < MAX_CRCFLAGS; i++) {
        pthread_join(threads[i], NULL);
    }

    monitor_resources();

    return 0;
}
