class NFARangeManager {
public:
    struct RangeConfig {
        int min;
        int max;
        bool inclusive;
    };

    struct NFAPI_CRC_INDICATION_PDU_T {
        std::uint16_t RX_UE_INFORMATION_TAG;
        std::uint8_t RNTI;
        struct CRC_INDICATION_REL8_TAG {
            bool CRCFLAG;
        } CRC_INDICATION_REL8_TAG;
    };

    NFARangeManager() : ranges(), rangeConfigurations(), dataSrcAvailable(false) {}

    void addRange(const std::string& key, int min, int max, bool inclusive) {
        RangeConfig config = {min, max, inclusive};
        if (config.min > config.max || (!inclusive && config.min == config.max)) {
            throw std::invalid_argument("Invalid range configuration");
        }
        ranges[key] = config;
        rangeConfigurations[key] = config;
    }

    void removeRange(const std::string& key) {
        ranges.erase(key);
        rangeConfigurations.erase(key);
    }

    void updateRange(const std::string& key, int min, int max, bool inclusive) {
        if (min > max || (!inclusive && min == max)) {
            throw std::invalid_argument("Invalid range configuration");
        }
        ranges[key] = {min, max, inclusive};
        rangeConfigurations[key] = {min, max, inclusive};
    }

    int generateRandomValue(const std::string& key) {
        auto config = ranges.at(key);
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<int> dis(config.min, config.max);
        return dis(gen);
    }

    void resetRange(const std::string& key) {
        ranges[key] = rangeConfigurations[key];
    }

    void resetAllRanges() {
        for (auto& range : ranges) {
            ranges[range.first] = range.second;
        }
    }

    std::list<NFAPI_CRC_INDICATION_PDU_T> generateNFAPI_CRC_INDICATION_PDUs(int count) {
        std::list<NFAPI_CRC_INDICATION_PDU_T> pdus;
        std::random_device rd;
        std::mt19937 gen(rd());
        for (int i = 0; i < count; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = gen() % 0xFFFF;
            pdu.RNTI = static_cast<std::uint8_t>(gen() % 256);
            pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (gen() % 2) ? true : false;
            pdus.push_back(pdu);
        }
        return pdus;
    }

private:
    std::map<std::string, RangeConfig> ranges;
    std::map<std::string, RangeConfig> rangeConfigurations;
    bool dataSrcAvailable;

    // logging and fallback mechanisms will be implemented here
};

