#define MAX_STRUCTURES 1000
#define RNTI_MIN 0x0001
#define RNTI_MAX 0xFFFFF

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_indication_pdu(char* config_file_path, int num_structures, NFAPI_CRC_INDICATION_PDU_T** structures) {
    *structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*structures == NULL) return -1;

    FILE* config_file = fopen(config_file_path, "r");
    if (config_file == NULL) return -2;

    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = &(*structures)[i];
        structure->RX_UE_INFORMATION_TAG = rand() % 256;
        while (structure->RNTI < RNTI_MIN || structure->RNTI > RNTI_MAX) {
            structure->RNTI = rand() % ((RNTI_MAX - RNTI_MIN) + 1) + RNTI_MIN;
        }
        structure->CRC_INDICATION_REL8_TAG = rand() % 256;
        int crcflag = rand() % 2;
        structure->CRCFLAG = crcflag;

        if (fread(&structure, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, config_file) != 1) {
            fclose(config_file);
            free(*structures);
            *structures = NULL;
            return -3;
        }
    }

    fclose(config_file);

    int count = 0;
