class NFARangeManager {
public:
    NFARangeManager() : ranges_(), cache_(std::make_shared<std::mutex>()), source_fetchers_(), update_queue_() {}

    void addRange(const std::string& key, int min, int max, bool inclusive) {
        // implement range validation and configuration
        if (min > max || !inclusive && (min == max)) {
            throw std::runtime_error("Invalid range configuration");
        }
        ranges_[key] = Range(min, max, inclusive);
    }

    void removeRange(const std::string& key) {
        // implement range removal logic
        ranges_.erase(key);
    }

    void updateRange(const std::string& key, int min, int max, bool inclusive) {
        // implement range update logic
        if (min > max || !inclusive && (min == max)) {
            throw std::runtime_error("Invalid range configuration");
        }
        auto it = ranges_.find(key);
        if (it != ranges_.end()) {
            it->second.min = min;
            it->second.max = max;
            it->second.inclusive = inclusive;
        } else {
            addRange(key, min, max, inclusive);
        }
    }

    std::vector<int> generateRandomValues(const std::string& key, int count) {
        // implement random value generation logic
        auto range = ranges_[key];
        std::vector<int> values;
        for (int i = 0; i < count; i++) {
            values.push_back(rand() % (range.max - range.min + 1) + range.min);
        }
        return values;
    }

    void resetRange(const std::string& key) {
        // implement range resetting logic
        if (ranges_.find(key) != ranges_.end()) {
            ranges_[key].min = ranges_[key].max = 0;
        }
    }

    void resetAllRanges() {
        // implement all-range resetting logic
        for (auto& pair : ranges_) {
            pair.second.min = pair.second.max = 0;
        }
    }

private:
    struct Range {
        int min, max;
        bool inclusive;
    };

    std::map<std::string, Range> ranges_;
    std::shared_ptr<std::mutex> cache_;
    std::vector<std::function<void()>> source_fetchers_;
    std::queue<std::function<void()>> update_queue_;

    // implement logging and notification mechanisms
};

