#include <iostream>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>

class NFARangeManager {
private:
    std::unordered_map<std::string, struct Range> ranges;
    std::mutex mtx;

public:
    struct Range {
        double min, max;
        bool inclusive;
    };

    void addRange(const std::string& key, double minValue, double maxValue, bool isInclusive) {
        if (minValue > maxValue)
            throw std::runtime_error("Invalid range: minimum value must not exceed maximum value.");

        ranges[key] = {minValue, maxValue, isInclusive};
    }

    void removeRange(const std::string& key) {
        ranges.erase(key);
    }

    void updateRange(const std::string& key, double minValue, double maxValue, bool isInclusive) {
        if (key.empty())
            throw std::runtime_error("Invalid range: key cannot be empty.");

        if (minValue > maxValue)
            throw std::runtime_error("Invalid range: minimum value must not exceed maximum value.");

        ranges[key] = {minValue, maxValue, isInclusive};
    }

    double getRandomValue(const std::string& key) {
        auto it = ranges.find(key);
        if (it == ranges.end())
            throw std::runtime_error("Range not found: " + key);

        if (it->second.inclusive)
            return static_cast<double>(rand()) / RAND_MAX * (it->second.max - it->second.min) + it->second.min;
        else
            return static_cast<double>(rand()) / RAND_MAX * (it->second.max - it->second.min) + it->second.min + (it->second.max - it->second.min);
    }

    void resetRange(const std::string& key, double minValue = 0.0, double maxValue = 1.0, bool isInclusive = true) {
        if (key.empty())
            throw std::runtime_error("Invalid range: key cannot be empty.");

        ranges[key] = {minValue, maxValue, isInclusive};
    }

    void resetAllRanges(double minValue = 0.0, double maxValue = 1.0, bool isInclusive = true) {
        for (auto& it : ranges)
            it.second = {minValue, maxValue, isInclusive};
    }

    void partialReset(const std::vector<std::string>& keysToReset, double minValue = 0.0, double maxValue = 1.0, bool isInclusive = true) {
        for (const auto& key : keysToReset)
            resetRange(key, minValue, maxValue, isInclusive);
    }

    void logChanges(const std::string& message) {
        // implement logging mechanism here
    }
};

// example usage
int main() {
    NFARangeManager manager;

    manager.addRange("range1", 0.0, 10.0, true);
    manager.addRange("range2", -5.0, 5.0, false);

    for (int i = 0; i < 10; ++i) {
        std::cout << "Random value: " << manager.getRandomValue("range1") << "\n";
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    return 0;
}
