// Initialize a thread-safe counter for total structures created
int total_structures_created = 0;
pthread_mutex_t total_structures_created_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to manage and process an array of network statistics structures
NetworkStats** manage_network_stats(int num_stats) {
    // Allocate memory for the array of structures
    NetworkStats** stats_array = (NetworkStats**)malloc(num_stats * sizeof(NetworkStats*));
    if (!stats_array) {
        return NULL;  // Handle allocation failure
    }

    // Initialize thread-safe counters for each structure creation
    pthread_mutex_t* struct_creation_counters = (pthread_mutex_t*)malloc(num_stats * sizeof(pthread_mutex_t));
    for (int i = 0; i < num_stats; i++) {
        pthread_mutex_init(&struct_creation_counters[i], NULL);
    }

    // Process and integrate with the existing network monitoring system
    for (int i = 0; i < num_stats; i++) {
        NetworkStats* stats = (NetworkStats*)malloc(sizeof(NetworkStats));
        if (!stats) {
            return NULL;  // Handle allocation failure
        }

        pthread_mutex_lock(&struct_creation_counters[i]);
        total_structures_created++;
        pthread_mutex_unlock(&struct_creation_counters[i]);

        // Validate and process the structure here...

        stats_array[i] = stats;
    }

    // Clean up thread-safe counters
    for (int i = 0; i < num_stats; i++) {
        pthread_mutex_destroy(&struct_creation_counters[i]);
    }
    free(struct_creation_counters);

    return stats_array;
}

// Function to validate and free the array of network statistics structures
void free_network_stats(NetworkStats** stats_array, int num_stats) {
    for (int i = 0; i < num_stats; i++) {
        if (stats_array[i]) {
            free(stats_array[i]);
            stats_array[i] = NULL;
        }
    }
    free(stats_array);
}

