    NetworkStats** stats_array = manage_network_stats(num_stats);

    // Process and integrate with the existing system...
    for (int i = 0; i < num_stats; i++) {
        printf("Processing statistics: %d\n", i);
    }

    free_network_stats(stats_array, num_stats);

    return 0;
}
