NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_array(int N) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = i;
        pdu_array[i].RNTI = i * 2;

        // Randomly set CRCFLAG
        srand(time(NULL));
        int random_value = rand() % 2;
        if (random_value) {
            pdu_array[i].CRCFLAG = CRCFLAG_SET;
        } else {
            pdu_array[i].CRCFLAG = CRCFLAG_CLEAR;
        }
    }

    return pdu_array;
}

int validate_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int N) {
    for (int i = 0; i < N; ++i) {
        if (pdu_array[i].RX_UE_INFORMATION_TAG < 0 || pdu_array[i].RNTI < 0) {
            printf("Invalid RX_UE_INFORMATION_TAG or RNTI value in PDU %d.\n", i);
            return -1;
        }

        // Validate CRCFLAG integrity
        if (pdu_array[i].CRCFLAG == CRCFLAG_SET && pdu_array[i].RX_UE_INFORMATION_TAG % 2) {
            printf("PDU %d has invalid CRC flag value. RX_UE_INFORMATION_TAG must be even.\n", i);
            return -1;
        }
    }

    return 0;
}
