#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define structure for thread-safe counter
typedef struct {
    int value;
    pthread_mutex_t lock;
} ThreadSafeCounter;

// Define structure for NFAPI_CRC_INDICATION_PDU_T array management
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NFAPIArrayManager;

// Function to create and initialize an NFAPIArrayManager instance
NFAPIArrayManager* nfaPiArrayManagerCreate(size_t initialCapacity) {
    NFAPIArrayManager* manager = (NFAPIArrayManager*)malloc(sizeof(NFAPIArrayManager));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Function to add an NFAPI_CRC_INDICATION_PDU_T structure to the array
int nfaPiArrayManagerAdd(NFAPIArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pthread_mutex_lock(&manager->lock)) return -1; // Lock failed

    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        manager->array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager->array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failed
        }

        manager->capacity = newCapacity;
    }

    manager->array[manager->count] = pdu;
    manager->count++;

    pthread_mutex_unlock(&manager->lock); // Unlock

    return 0; // Success
}

// Function to get the total count of NFAPI_CRC_INDICATION_PDU_T structures in the array
int nfaPiArrayManagerGetCount(NFAPIArrayManager* manager) {
    if (pthread_mutex_lock(&manager->lock)) return -1; // Lock failed

    int count = manager->count;

    pthread_mutex_unlock(&manager->lock); // Unlock

    return count;
}

// Function to free the NFAPIArrayManager instance
void nfaPiArrayManagerDestroy(NFAPIArrayManager* manager) {
    if (!manager) return;

    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
