    for (int i = 0; i < num_connections; i++) {
        if (connections[i].id == id) {
            connections[i].packet_sizes = realloc(connections[i].packet_sizes, sizeof(int) * ++connections[i].history_size);
            connections[i]->packet_sizes[connections[i]->history_size-1] = packet_size;
            break;
