}

void resize_MAC_PDU_array(MAC_PDU* pdu, int new_capacity) {
    MACSDU* temp_elements = (MACSDU*)realloc(pdu->elements, new_capacity * sizeof(MACSDU));
    if (!temp_elements) {
        free(pdu->elements);
        return;  // Memory allocation failed
    }
    pdu->elements = temp_elements;
    pdu->capacity = new_capacity;
}

int add_MACSDU_to_pdu(MAC_PDU* pdu, int max_length) {
    if (pdu->size >= pdu->capacity) {  // Check if the array needs resizing
        int new_capacity = pdu->size + pdu->size / 2;  // Calculate new capacity
        if (new_capacity > max_length) {
            return -1;  // Max length exceeded
        }
        resize_MAC_PDU_array(pdu, new_capacity);
    }

    MACSDU* new_element = &pdu->elements[pdu->size++];
    new_element->length = rand() % (max_length + 1);  // Randomly generate length

    return 0;  // Success
}

void free_MAC_PDU_array(MAC_PDU* pdu) {
    free(pdu->elements);
    free(pdu);
}
