using System;
using System.Xml;
using System.Xml.XPath;

public class XmlProcessor
{
    public List<XElement> ProcessXml(string xml, string xpathQuery)
    {
        XmlDocument doc = new XmlDocument();
        doc.LoadXml(xml);

        XPathDocument xdoc = new XPathDocument(doc);
        XPathNavigator nav = xdoc.CreateNavigator();

        try
        {
            XPathExpression expression = nav.Compile(xpathQuery);
            XPathNodeIterator iterator = nav.Select(expression);

            List<XElement> result = new List<XElement>();

            while (iterator.MoveNext())
            {
                result.Add((XElement)iterator.Current);
            }

            return result;
        }
        catch (XPathException ex)
        {
            throw new Exception($"Error evaluating XPath expression '{xpathQuery}' at position {ex.LineNumber}: {ex.Message}", ex);
        }
    }
}
