#include <iostream>
#include <chrono>
#include <thread>
#include <random>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>
#include <string>
#include <vector>

class InterfaceTable {
public:
    virtual ~InterfaceTable() {}
    virtual std::string lookup(const std::string& key) = 0;
};

class MockInterface : public InterfaceTable {
public:
    std::string lookup(const std::string& key) override {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_real_distribution<double> dist(0.01, 0.05);

        if (gen() < dist(gen)) {
            return "Mocked failure";
        }
        return "Mocked success";
    }
};

class HTTPClient {
public:
    HTTPClient(InterfaceTable* table, int retries, double rateLimit) 
        : table_(table), retries_(retries), rateLimit_(rateLimit), sessionStats_({0, 0}), requestQueue_() {}

    void sendRequests(int numRequests) {
        for (int i = 0; i < numRequests; ++i) {
            sendRequest();
        }
    }

private:
    void sendRequest() {
        std::random_device rd;
        std::mt19937 gen(rd());
        auto requestId = std::to_string(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count()) + std::to_string(gen());

        while (true) {
            try {
                // Send request and check response
                if (table_->lookup(requestId) == "Mocked failure") {
                    // Retry if failed
                    if (--retries_ > 0) {
                        std::this_thread::sleep_for(std::chrono::milliseconds(500)); // Simulate delay
                        continue;
                    }
                    sessionStats_.failed++;
                } else {
                    // Success, update statistics and rate-limit
                    sessionStats_.successful++;
                    rateLimit_(sessionStats_.successful / 60);
                    break;
                }
            } catch (...) {
                // Handle exception, mark as failed and retry if allowed
                sessionStats_.failed++;
                if (--retries_ > 0) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(500)); // Simulate delay
                    continue;
                }
            }
        }

        requestQueue_.push(requestId);
    }

public:
    void monitor() {
        while (!requestQueue_.empty()) {
            std::cout << "Request ID: " << requestQueue_.front() << " | Status: FAILED" << std::endl;
            requestQueue_.pop();
        }
    }

private:
    InterfaceTable* table_;
    int retries_;
    double rateLimit_;
    struct SessionStats { int successful = 0, failed = 0; };
    std::queue<std::string> requestQueue_;
    SessionStats sessionStats_;
};

int main() {
    MockInterface mock;
    HTTPClient client(&mock, 3, 100);
    client.sendRequests(10);
    client.monitor();
    return 0;
}

