public class XmlConfigParser
{
    private const string DefaultConfigValue = "default_value";
    private const string FallbackValue = "fallback_value";

    public void ParseXmlConfig(string xmlFilePath, out string configSetting)
    {
        try
        {
            XPathDocument doc = new XPathDocument(xmlFilePath);
            XPathNavigator navigator = doc.CreateNavigator();
            XPathExpression expression = navigator.Compile("//configuration[@name='specific_config']");
            XPathNodeIterator iterator = expression.Evaluate();

            if (iterator.MoveNext())
            {
                XPathNavigator element = iterator.Current;
                configSetting = element.Value;

                Environment.SetEnvironmentVariable("CONFIG_DIR", Path.GetTempPath());
            }
            else
            {
                configSetting = FallbackValue;
            }
        }
        catch (XPathException ex)
        {
            configSetting = DefaultConfigValue;
        }
    }

    public void CleanUp()
    {
        try
        {
            string configDir = Environment.GetEnvironmentVariable("CONFIG_DIR");
            if (!string.IsNullOrEmpty(configDir))
            {
                Directory.Delete(configDir, true);
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions
        }
    }
}

