```java
import java.util.*;

public class ResourcePoolManager {
    private Map<Integer, Resource> resources;
    private List<TaskAssignmentRequest> taskAssignments;

    public ResourcePoolManager(int initialCapacity) {
        this.resources = new ConcurrentHashMap<>(initialCapacity);
        this.taskAssignments = new ArrayList<>();
    }

    public void addResource(int id, Resource resource) {
        if (!isValidResource(resource)) {
            throw new InvalidResourceException();
        }
        resources.put(id, resource);
    }

    public boolean allocateResource(int id) {
        Resource resource = resources.get(id);
        if (resource != null && !resource.isAvailable()) {
            throw new ResourceUnavailableException();
        }
        if (!resource.allocate()) {
            return false;
        }
