using System;
using System.Xml;
using System.IO;
using System.Threading;

public class ConfigurationParser
{
    public static string ParseXmlConfig(string xmlFilePath)
    {
        try
        {
            XmlDocument doc = new XmlDocument();
            doc.Load(xmlFilePath);
            XmlElement root = doc.DocumentElement;
            if (root != null)
            {
                XmlNode node = root.SelectSingleNode("/configuration/setting[@name='mySetting']");
                if (node != null)
                {
                    return node.InnerText;
                }
                else
                {
                    // Default configuration value
                    return "default";
                }
            }
            else
            {
                // Fallback value
                return "fallback";
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error parsing XML config: " + ex.Message);
            return "error";
        }
    }

    public static void CreateConfigDir()
    {
        string dirPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
        Directory.CreateDirectory(dirPath);
    }

    ~ConfigurationParser()
    {
        // Delete temporary files
        Directory.Delete(Path.Combine(Path.GetTempPath(), "config"));
    }
}

public class RuntimeConfigDir : IDisposable
{
    public void Dispose()
    {
        ConfigurationParser.DeleteTemporaryFiles();
    }
}
