import java.util.Random;

public class ServiceManager {
    private Random random = new Random();
    private int minStartupDelay;
    private int maxStartupDelay;
    private int currentDelay;
    private boolean serviceRunning = false;

    public ServiceManager(int minStartupDelay, int maxStartupDelay) {
        this.minStartupDelay = minStartupDelay;
        this.maxStartupDelay = maxStartupDelay;
        setCurrentDelay();
    }

    public void startService() {
        if (!serviceRunning) {
            try {
                Thread.sleep(getCurrentDelay());
                // Start the service logic here
                System.out.println("Service started");
                serviceRunning = true;
            } catch (InterruptedException e) {
                // Handle interruption
            }
        }
    }

    public void stopService() {
        if (serviceRunning) {
            try {
                // Stop the service logic here
                System.out.println("Service stopped");
                serviceRunning = false;

                sendStatusUpdateToMonitoringSystem();
            } catch (Exception e) {
                // Handle exceptions
            }
        }
    }

    public int getRandomInt(int min, int max) {
        return random.nextInt((max - min) + 1) + min;
    }

    public float getRandomFloat(int min, int max) {
        return min + (float) (random.nextGaussian() * (max - min));
    }

    private void setCurrentDelay() {
        currentDelay = getRandomInt(minStartupDelay, maxStartupDelay);
    }

    public int getCurrentDelay() {
        return currentDelay;
    }

    @Override
    public String toString() {
        return "Current delay: " + getCurrentDelay();
    }

