typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

NFAPI_CRC_INDICATION_PDU_T* generateNfarxIndications(int N, unsigned int seed) {
    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (node == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        node->RX_UE_INFORMATION_TAG = rand() % 256;
        node->RNTI = rand() % 65536;
        node->CRC_INDICATION_REL8_TAG = rand() % 256;
        node->CRCFLAG = rand() % 2;
        node->next = NULL;

        if (head == NULL) {
            head = node;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* temp = head;
            while (temp->next != NULL)
                temp = temp->next;
            temp->next = node;
        }
    }

    // Validate the list
    if (head == NULL) return head;

    NFAPI_CRC_INDICATION_PDU_T* temp = head;
    for (; temp; temp = temp->next) {
        if (temp->RX_UE_INFORMATION_TAG < 0 || temp->RNTI > 65535 ||
            temp->CRC_INDICATION_REL8_TAG < 0 || temp->CRCFLAG < 0 || temp->CRCFLAG > 1) {
            printf("Invalid node detected.\n");
            return NULL;
        }
    }

    return head;
}

int main() {
    int N = 10;
    unsigned int seed = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T* list = generateNfarxIndications(N, seed);

    if (list == NULL) {
        printf("Error generating the list.\n");
        return -1;
    }

    // Print the generated list
    NFAPI_CRC_INDICATION_PDU_T* temp = list;
    while (temp) {
        printf("%d %hu %d %d\n", temp->RX_UE_INFORMATION_TAG, temp->RNTI, temp->CRC_INDICATION_REL8_TAG, temp->CRCFLAG);
        temp = temp->next;
    }

    // Free the memory
    while (list) {
        NFAPI_CRC_INDICATION_PDU_T* next = list->next;
        free(list);
        list = next;
    }

    return 0;
}
