// Function to initialize dynamic array of LTEPHY_RRC_INTERFACE_MESSAGE structures
void init_dynamic_array(int size, LTEPHY_RRC_INTERFACE_MESSAGE** arr) {
    *arr = (LTEPHY_RRC_INTERFACE_MESSAGE*)malloc(size * sizeof(LTEPHY_RRC_INTERFACE_MESSAGE));
}

// Function to add a new LTEPHY_RRC_INTERFACE_MESSAGE structure to the dynamic array
void add_to_dynamic_array(LTEPHY_RRC_INTERFACE_MESSAGE* new_message, int* size, LTEPHY_RRC_INTERFACE_MESSAGE** arr) {
    if (*size == 0) {
        *arr = (LTEPHY_RRC_INTERFACE_MESSAGE*)malloc(1 * sizeof(LTEPHY_RRC_INTERFACE_MESSAGE));
        (*arr)[0] = *new_message;
        (*size)++;
    } else {
        *arr = (LTEPHY_RRC_INTERFACE_MESSAGE*)realloc(*arr, (*size + 1) * sizeof(LTEPHY_RRC_INTERFACE_MESSAGE));
        (*arr)[*size - 1] = *new_message;
        (*size)++;
    }
}

// Function to remove the LTEPHY_RRC_INTERFACE_MESSAGE structure at a specific index from the dynamic array
void remove_from_dynamic_array(int index, int* size, LTEPHY_RRC_INTERFACE_MESSAGE** arr) {
    if (index >= *size || index < 0) {
        printf("Invalid index. Cannot remove.\n");
        return;
    }

    for (int i = index; i < *size - 1; i++) {
        (*arr)[i] = (*arr)[i + 1];
    }
    free((*arr)[*size - 1]);
    (*size)--;
}

// Function to get the LTEPHY_RRC_INTERFACE_MESSAGE structure at a specific index from the dynamic array
LTEPHY_RRC_INTERFACE_MESSAGE* get_from_dynamic_array(int index, int size, LTEPHY_RRC_INTERFACE_MESSAGE* arr) {
    if (index >= size || index < 0) {
        printf("Invalid index. Cannot retrieve.\n");
        return NULL;
    }
    return &arr[index];
}

