int structures_allocated = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_structure(int rnti) {
    pthread_mutex_lock(&lock);

    if (structures_allocated >= MAX_STRUCTURES) {
        // Handle structure pool exhaustion
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structure) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    structure->CRCFLAG = (rnti & 1) ? 1 : 0;  // Set CRCFLAG based on RNTI parity

    structures_allocated++;
    pthread_mutex_unlock(&lock);

    // Log structured log event for new structure creation
    // This should be done in a way that does not introduce significant performance overhead

    return structure;
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    pthread_mutex_lock(&lock);

    if (structures_allocated <= 0) {
        // Handle invalid or freed structure
        pthread_mutex_unlock(&lock);
        return;
    }

    structures_allocated--;
    free(structure);

    pthread_mutex_unlock(&lock);
}
