    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)my_malloc((n + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Initialize the list and RNTI values
    for (int i = 0; i < n; i++) {
