typedef struct {
    LTEPHY_RRC_INTERFACE_MESSAGE **messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RRC_MESSAGE_ARRAY;

// Function to create a new RRC message array
RRC_MESSAGE_ARRAY *rrc_message_array_create(size_t initial_capacity) {
    RRC_MESSAGE_ARRAY *array = (RRC_MESSAGE_ARRAY *)malloc(sizeof(RRC_MESSAGE_ARRAY));
    array->messages = (LTEPHY_RRC_INTERFACE_MESSAGE **)calloc(initial_capacity, sizeof(LTEPHY_RRC_INTERFACE_MESSAGE *));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Function to insert a message into the dynamic array
void rrc_message_array_insert(RRC_MESSAGE_ARRAY *array, LTEPHY_RRC_INTERFACE_MESSAGE *message) {
    if (array->size >= array->capacity) {
        array->messages = (LTEPHY_RRC_INTERFACE_MESSAGE **)realloc(array->messages, (array->capacity *= 2) * sizeof(LTEPHY_RRC_INTERFACE_MESSAGE *));
    }
    array->messages[array->size++] = message;
}

// Function to delete a message from the dynamic array
void rrc_message_array_delete(RRC_MESSAGE_ARRAY *array, int conn_id) {
    for (int i = 0; i < array->size; i++) {
        if (array->messages[i]->conn_id == conn_id) {
            free(array->messages[i]);
            memmove(&array->messages[i], &array->messages[i + 1], (array->size - i - 1) * sizeof(LTEPHY_RRC_INTERFACE_MESSAGE *));
            array->size--;
            break;
        }
    }
}

// Function to lookup a message from the dynamic array
LTEPHY_RRC_INTERFACE_MESSAGE *rrc_message_array_lookup(RRC_MESSAGE_ARRAY *array, int conn_id) {
    for (int i = 0; i < array->size; i++) {
        if (array->messages[i]->conn_id == conn_id) {
            return array->messages[i];
        }
    }
    return NULL;
}

// Function to integrate with the external data source
void rrc_message_array_update(RRC_MESSAGE_ARRAY *array, int conn_id, LTEPHY_RRC_INTERFACE_MESSAGE *message) {
    // Implement strategy for handling delays or failures in data retrieval
    if (message != NULL) {
        rrc_message_array_insert(array, message);
    } else {
        // Handle delayed or failed updates
    }
}

// Function to test the RRC message array module
void test_rrc_message_array() {
    RRC_MESSAGE_ARRAY *array = rrc_message_array_create(10);

    // Insert and delete messages
    LTEPHY_RRC_INTERFACE_MESSAGE *message1 = (LTEPHY_RRC_INTERFACE_MESSAGE *)malloc(sizeof(LTEPHY_RRC_INTERFACE_MESSAGE));
    message1->conn_id = 1;
    message1->num_cells = 2;
    rrc_message_array_insert(array, message1);

    LTEPHY_RRC_INTERFACE_MESSAGE *message2 = (LTEPHY_RRC_INTERFACE_MESSAGE *)malloc(sizeof(LTEPHY_RRC_INTERFACE_MESSAGE));
    message2->conn_id = 2;
    message2->num_cells = 3;
    rrc_message_array_insert(array, message2);

    rrc_message_array_delete(array, 1);

    // Lookup messages
