    if (message3 != NULL) {
        printf("Message found: conn_id = %d\n", message3->conn_id);
    } else {
        printf("Message not found\n");
    }

    // Clean up
    for (int i = 0; i < array->size; i++) {
        free(array->messages[i]);
    }
    free(array->messages);
    free(array);
}

int main() {
