typedef struct {
    DL_FRAME_HEADER header;
    PHY_LAYER_DATA* data;
    int size;
} LTE_DL_FRAME_MSG;

// Global memory pool for dynamic array management
void** global_memory_pool = NULL;
int global_memory_pool_size = 0;
int global_memory_pool_current_index = 0;

// Mutex lock for concurrent access control
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Allocate a new LTE_DL_FRAME_MSG structure with specified size and BWP
LTE_DL_FRAME_MSG* lte_dl_frame_msg_alloc(int size, int bwp) {
    void* memory_block = NULL;
    while (1) {
        pthread_mutex_lock(&mutex);
        if (global_memory_pool_size == 0 || global_memory_pool[global_memory_pool_current_index] == NULL) {
            // Global pool exhausted; allocate a new block
            global_memory_pool_size++;
            global_memory_pool = realloc(global_memory_pool, sizeof(void*) * global_memory_pool_size);
            for (int i = global_memory_pool_current_index; i < global_memory_pool_size; i++) {
                global_memory_pool[i] = NULL;
            }
        }
        memory_block = global_memory_pool[global_memory_pool_current_index];
        global_memory_pool_current_index++;
        pthread_mutex_unlock(&mutex);

        if (memory_block == NULL) {
            // Allocation failed; retry with exponential backoff
            sleep(1);
            continue;
        }

        LTE_DL_FRAME_MSG* frame_msg = (LTE_DL_FRAME_MSG*)memory_block;
        frame_msg->data = (PHY_LAYER_DATA*)calloc(bwp * size, sizeof(int));
        if (frame_msg->data == NULL) {
            // Allocation failed; free existing memory and retry
            free(frame_msg);
            continue;
        }

        return frame_msg;
    }
}

// Deallocate an LTE_DL_FRAME_MSG structure
void lte_dl_frame_msg_free(LTE_DL_FRAME_MSG* frame_msg) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < global_memory_pool_current_index - 1; i++) {
        if (global_memory_pool[i] == (void*)frame_msg) {
            global_memory_pool[i] = global_memory_pool[global_memory_pool_current_index - 1];
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    free(frame_msg->data);
    free(frame_msg);
}

// Periodic cleanup to prevent memory leaks
