int numEntries = 0;
NFAPI_CRC_INDICATION_PDU_T *entries = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* allocateEntry(void) {
    return malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void freeAllEntries() {
    for (int i = 0; i < numEntries; i++) {
        free(entries + i);
    }
    free(entries);
}

void initializeAndManageNFAPI_CRC_INDICATION_PDU_T(int N) {
    pthread_t threads[N];
    entries = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*)allocateEntry();
        entry->RX_UE_INFORMATION_TAG = rand() % 100;
        while (1) {
            entry->RNTI = rand() % 500;
            pthread_mutex_lock(&mutex);
            int found = 0;
            for (int j = 0; j < numEntries; j++) {
                if (entries[j].RNTI == entry->RNTI) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                pthread_mutex_unlock(&mutex);
                break;
            } else {
                pthread_mutex_unlock(&mutex);
            }
        }
        entry->CRC_INDICATION_REL8_TAG = rand() % 1000;
        entry->CRCFLAG = (rand() % 2) ? 1 : 0;

        if (entry->RNTI < 128 || entry->RNTI > 511) {
            printf("Invalid RNTI value: %d\n", entry->RNTI);
        } else {
            pthread_mutex_lock(&mutex);
            entries[numEntries++] = *entry;
            pthread_mutex_unlock(&mutex);
            pthread_cond_signal(&cond);
        }
    }

    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, &threadProcessEntry, &entries[i]);
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }
}

void threadProcessEntry(void* entry) {
    printf("Processing entry: %d, RNTI: %d, CRCFLAG: %d\n", ((NFAPI_CRC_INDICATION_PDU_T*)entry)->RX_UE_INFORMATION_TAG, ((NFAPI_CRC_INDICATION_PDU_T*)entry)->RNTI, ((NFAPI_CRC_INDICATION_PDU_T*)entry)->CRCFLAG);
}

int main() {
    srand(time(NULL));
    initializeAndManageNFAPI_CRC_INDICATION_PDU_T(10);
    freeAllEntries();
    return 0;
}
