    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_LIST_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_element_to_list(NFAPI_CRC_INDICATION_PDU_LIST* list, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= MAX_LIST_SIZE) {
        // Discard the oldest entry
        free(list->data[0]);
        memmove(list->data, &list->data[1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - 1));
        list->size--;
    }
    memcpy(&list->data[list->size++], &new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_latest_entries(NFAPI_CRC_INDICATION_PDU_LIST* list, int n) {
    NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < n && i < list->size; i++) {
        memcpy(&result[i], &list->data[list->size - 1 - i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pthread_mutex_unlock(&list->lock);
    return result;
}

void free_list(NFAPI_CRC_INDICATION_PDU_LIST* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->data[i]);
    }
