['```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <pthread.h>

#define MAX_CONNECTIONS 10
#define CONN_POOL_SIZE 5

typedef struct Connection {
    int socket;
} Connection;

typedef struct ConnectionPool {
    Connection* connections;
    uint32_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ConnectionPool;

ConnectionPool* initializeConnectionPool(uint32_t poolSize) {
    ConnectionPool* pool = (ConnectionPool*)malloc(sizeof(ConnectionPool));
    if (!pool) return NULL;
    pool->size = 0;
    pool->connections = (Connection*)calloc(poolSize, sizeof(Connection));
    if (!pool->connections) {
        free(pool);
        return NULL;
    }
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

int openConnection(ConnectionPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    for (uint32_t i = 0; i < pool->size; ++i) {
        if (!pool->connections[i].socket) {
            int sock = socket(AF_INET, SOCK_STREAM, 0);
            if (sock != -1) {
                pool->connections[i].socket = sock;
                return sock;
            }
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return -1;
}

void closeConnections(ConnectionPool* pool, uint32_t start) {
    for (uint32_t i = 0; i < pool->size; ++i) {
        if (i >= start) {
            int sock = pool->connections[i].socket;
            pthread_mutex_lock(&pool->mutex);
            pool->connections[i].socket = -1;
            pthread_cond_signal(&pool->cond);
            pthread_mutex_unlock(&pool->mutex);
            close(sock);
        }
    }
}

void* connectionPoolThread(void* arg) {
    ConnectionPool* pool = (ConnectionPool*)arg;
    while (1) {
        pthread_mutex_lock(&pool->mutex);
        while (pool->size == CONN_POOL_SIZE) {
            pthread_cond_wait(&pool->cond, &pool->mutex);
        }
        int sock = openConnection(pool);
        if (sock != -1) {
            ++pool->size;
        } else {
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        pthread_mutex_unlock(&pool->mutex);
    }
}

int main() {
    ConnectionPool* pool = initializeConnectionPool(CONN_POOL_SIZE);
    pthread_t threads[CONN_POOL_SIZE];
    for (uint32_t i = 0; i < CONN_POOL_SIZE; ++i) {
        pthread_create(&threads[i], NULL, connectionPoolThread, pool);
    }
    return 0;
}
```']

