typedef struct {
    char src_addr[20];
    char dst_addr[20];
    int payload_size;
    void* payload;
    time_t timestamp;
} Message;

Message* initialize_message_queue(size_t capacity) {
    pthread_mutex_init(&mutex, NULL);
    message_queue = (Message*)malloc(capacity * sizeof(Message));
    return &message_queue;
}

void enqueue_message(Message* msg) {
    pthread_mutex_lock(&mutex);
    // Enqueue the message
    for (size_t i = 0; i < capacity; i++) {
        if (!message_queue[i].payload) {
            memcpy(message_queue + i, msg, sizeof(Message));
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

Message* dequeue_message() {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < capacity; i++) {
        if (!message_queue[i].payload) {
            Message* temp = &message_queue[i];
            message_queue[i].payload = NULL;
            pthread_mutex_unlock(&mutex);
            return temp;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void free_message_queue() {
    for (size_t i = 0; i < capacity; i++) {
        if (message_queue[i].payload) {
            free(message_queue[i].payload);
        }
    }
    free(message_queue);
    pthread_mutex_destroy(&mutex);
}
