// Function to dynamically manage memory for multiple batches
void* allocate_batch(int batch_id, int num_structures) {
    // Allocate memory for the batch
    void* batch_ptr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);

    if (!batch_ptr) {
