int count_crcflag(void* batch_ptr, int num_structures, unsigned int crcflag) {
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)batch_ptr;

    int count = 0;
    for (int i = 0; i < num_structures; i++) {
        if (structures[i].CRCFLAG == crcflag) {
            count++;
        }
    }

    return count;
}

// Asynchronous processing function
void* process_batch(void* batch_ptr, int num_structures, pthread_mutex_t* lock) {
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)batch_ptr;

    // Process each structure in the batch
    for (int i = 0; i < num_structures; i++) {
        // Access and modify structures under the lock
        pthread_mutex_lock(lock);
        // Your processing logic here
        pthread_mutex_unlock(lock);
    }

    return NULL;
}

// Thread-safe main function
int main() {
    int batches = 5; // Number of batches to allocate
    int num_structures_per_batch = 500; // Number of structures per batch

    pthread_mutex_t lock;

    // Initialize memory allocation and deallocation
    for (int i = 0; i < batches; i++) {
        void* batch_ptr = allocate_batch(i, num_structures_per_batch);
        if (!batch_ptr) {
            break;
        }

        // Monitor memory usage
        size_t allocated_memory = malloc_usable_size(batch_ptr);

        if (allocated_memory > MEMORY_THRESHOLD) {
            printf("Memory threshold exceeded for batch %d\n", i);
            deallocate_batch(batch_ptr, i);
            return 1; // Exit with error
        }
    }

    // Process each batch asynchronously
    pthread_t threads[batches];
    for (int i = 0; i < batches; i++) {
        void* batch_ptr = allocate_batch(i, num_structures_per_batch);

        if (!batch_ptr) {
            break;
        }

        int rc = pthread_create(&threads[i], NULL, process_batch, batch_ptr);
        if (rc) {
            printf("Thread creation failed for batch %d\n", i);
            deallocate_batch(batch_ptr, i);
            return 1; // Exit with error
        }
    }

    // Wait for threads to finish
    for (int i = 0; i < batches; i++) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate memory for each batch
    for (int i = 0; i < batches; i++) {
        deallocate_batch(allocate_batch(i, num_structures_per_batch), i);
    }

    return 0;
}
