// Custom hash function for efficient lookup of RNTI values
uint64_t custom_hash(int RNTI) {
    return (uint64_t)RNTI * 265 % (1llu << 48);
}

// Hash table implementation using a separate array and indexing
void* nfapi_crc_indication_pdu_array[1024];
int nfapi_crc_indication_pdu_index[1024];

// Bloom filter implementation for minimal collisions and optimal memory access patterns
uint32_t bloom_filter[128];

// Mechanism to track and limit the total number of active batches
int max_active_batches = 10;
int current_active_batches = 0;

// Function to dynamically allocate memory for multiple independent arrays
NFAPI_CRC_INDICATION_PDU_T** nfapi_crc_indication_pdu_batches(int* N, int batch_size) {
    if (*N < 1 || *batch_size <= 0) {
        printf("Invalid input parameters.\n");
        return NULL;
    }

    // Initialize memory allocation
    NFAPI_CRC_INDICATION_PDU_T** batches = (NFAPI_CRC_INDICATION_PDU_T**)malloc(*N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < *N; ++i) {
        if (current_active_batches >= max_active_batches) {
            printf("Memory limit exceeded. Cannot create more batches.\n");
            return NULL;
        }

        // Dynamically allocate memory for each batch
        NFAPI_CRC_INDICATION_PDU_T* batch = (NFAPI_CRC_INDICATION_PDU_T*)malloc(batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        batches[i] = batch;

        // Initialize hash table and bloom filter for the current batch
        int* hash_table = (int*)malloc(1024 * sizeof(int));
        memcpy(nfapi_crc_indication_pdu_index, hash_table, 1024 * sizeof(int));

        for (int j = 0; j < batch_size; ++j) {
