            pdu.RNTI = j;
            sprintf(pdu.CRC_INDICATION_REL8_TAG, "Batch_%d_Element_%d", i, j);
            pdu.CRCFLAG = CRCFLAG;

            // Insert the structure into the hash table and bloom filter
            int index = custom_hash(pdu.RNTI) % 1024;
            nfapi_crc_indication_pdu_array[index] = &pdu;
            nfapi_crc_indication_pdu_index[index]++;
        }

        current_active_batches++;
    }

    return batches;
}

// Function to deallocate memory for multiple independent arrays
void nfapi_crc_indication_pdu_deallocate(NFAPI_CRC_INDICATION_PDU_T** batches, int N) {
    for (int i = 0; i < N; ++i) {
        if (batches[i] != NULL) {
