// Function to dynamically allocate and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_ue_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** tail = &head;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Initialize and populate the node
        node->RX_UE_INFORMATION_TAG = rand() % 100; // Randomly set CRCFLAG
        node->RNTI = i;
        node->CRC_INDICATION_REL8_TAG.CRCFLAG = (i & 1);

        if (*tail) {
            (*tail)->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *tail = (*tail)->next;
        } else {
            *tail = node;
        }
    }

    // Check for duplicate RNTI values
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        if (current->RNTI != -1 && find_duplicate(head, current->RNTI)) {
            printf("Error: Duplicate RNTI value %d found in the list.\n", current->RNTI);
        }
        current = current->next;
    }

    return head;
}

// Function to check for duplicate RNTI values
int find_duplicate(NFAPI_CRC_INDICATION_PDU_T* list, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = list;
    while (current) {
        if (current->RNTI == rnti) {
            return 1; // Duplicate RNTI found
        }
        current = current->next;
    }
    return 0; // No duplicate RNTI found
}

// Function to free the linked list and its nodes
void free_ue_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    NFAPI_CRC_INDICATION_PDU_T* next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
}
