    char CRC_INDICATION_REL8_TAG[256];
    unsigned short CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define dynamic list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
} DynamicList;

// Function to create a new dynamic list
DynamicList* dynamic_list_create() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->size = 0;
    list->capacity = 1;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    return list;
}

// Function to add an element to the dynamic list
int dynamic_list_add(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (list->size == list->capacity) {
        // Resize the array when it's full
        list->capacity *= 2;
        void* new_data = realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -1; // Memory allocation failed
        list->data = new_data;
    }
    list->data[list->size] = *element;
    list->size++;
    return 0;
}

// Function to free the dynamic list and its elements
void dynamic_list_free(DynamicList* list) {
    for (int i = 0; i < list->size; i++) {
        free((void*)list->data[i].RX_UE_INFORMATION_TAG);
        free((void*)list->data[i].CRC_INDICATION_REL8_TAG);
    }
    free(list->data);
    free(list);
}

// Example usage
int main() {
    DynamicList* list = dynamic_list_create();

    // Add some elements to the dynamic list
    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T element;
        // Initialize CRCFLAG with a random value
        element.CRCFLAG = rand() % 256;
        dynamic_list_add(list, &element);
    }

    // Print the elements in the dynamic list
    for (int i = 0; i < list->size; i++) {
        printf("RX_UE_INFORMATION_TAG: %s\n", list->data[i].RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", list->data[i].RNTI);
        printf("CRC_INDICATION_REL8_TAG: %s\n", list->data[i].CRC_INDICATION_REL8_TAG);
        printf("CRCFLAG: %hu\n", list->data[i].CRCFLAG);
    }

    // Free the dynamic list and its elements
    dynamic_list_free(list);

    return 0;
}
