void Save(Account* account) {
    if (account == NULL) return;

    if (accounts == NULL || account_count >= MAX_ACCOUNTS) {
        accounts = realloc(accounts, sizeof(Account) * (MAX_ACCOUNTS + 1));
        account_count++;
    }

    memcpy(&accounts[account_count - 1], account, sizeof(Account));
}

Account* Get(int id) {
    for (int i = 0; i < account_count; i++) {
        if (accounts[i].id == id) return &accounts[i];
    }
    return NULL;
}

void manageUserAccounts($_REQUEST) {
