        account = Get(atoi($_REQUEST['id']));
        if (account != NULL) {
            // implement deletion logic here
        }
    } else if (Validate(account)) {
        if ($_REQUEST['id']) {
            account->id = atoi($_REQUEST['id']);
            Save(account);
        } else {
            account_count++;
            strcpy(account->name, $_REQUEST['name']);
            strcpy(account->email, $_REQUEST['email']);
            strcpy(account->password, $_REQUEST['password']);
            Save(account);
        }
