typedef struct {
    int timestamp;
    char source[20];
    char destination[20];
    int packetSize;
} TrafficEvent;

void initializeTrafficLog(TrafficEvent** log, int* maxEvents) {
    // Initialize the network monitoring service
    printf("Initializing network monitoring service...\n");

    // Allocate space for up to 10,000 events
    *maxEvents = 10000;
    *log = (TrafficEvent*)malloc((*maxEvents) * sizeof(TrafficEvent));

    if (*log == NULL) {
        printf("Error allocating memory. Exiting.\n");
        return;
    }

    // Initialize the first event with some realistic data
    clock_t start = clock();
    for (int i = 0; i < 10; i++) {
        TrafficEvent* event = &(*log)[i];

        // Timestamp: monotonically increasing
        event->timestamp = start + i * 100;

        // Source and destination: valid IP addresses
        strcpy(event->source, "192.168.1.");
        strcat(event->source, (i < 9) ? "0" : "1");

        strcpy(event->destination, "10.10.10.");
        strcat(event->destination, (i % 2 == 0) ? "1" : "2");

        // Packet size: random number
        event->packetSize = rand() % 1500 + 64;
    }

    printf("Initialization complete.\n");
}

void queryTrafficLog(TrafficEvent** log, int maxEvents, int timestamp, char* source, char* destination) {
    for (int i = 0; i < maxEvents; i++) {
        TrafficEvent* event = &(*log)[i];

        if ((event->timestamp == timestamp && 
             strcmp(event->source, source) == 0 && 
             strcmp(event->destination, destination) == 0)) {
            printf("Found event at timestamp %d with source '%s' and destination '%s'.\n", 
                   event->timestamp, event->source, event->destination);
            return;
        }
    }

    printf("No matching events found.\n");
}

int main() {
    TrafficEvent* log = NULL;
    int maxEvents = 0;

    initializeTrafficLog(&log, &maxEvents);

    // Query the log for some specific events
    queryTrafficLog(&log, maxEvents, 12345, "192.168.1.0", "10.10.10.1");

    free(log);
    return 0;
}
