    // Allocate an array of pointers to TrafficEvent structures
    TrafficEvent** trafficLog = (TrafficEvent**)malloc(10000 * sizeof(TrafficEvent*));

    if (!trafficLog) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize the traffic log with realistic network traffic
    for (int i = 0; i < 10000; i++) {
        TrafficEvent* event = (TrafficEvent*)malloc(sizeof(TrafficEvent));

        if (!event) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        // Set timestamps to monotonically increasing values
        event->Timestamp = i;

        // Validate IP addresses and avoid reserved or invalid IPs
        static char ipAddresses[][16] = {"192.168.1.1", "192.168.1.2", ...};
        event->Source = strcpy(event->Source, ipAddresses[i % 10]);
        event->Destination = strcpy(event->Destination, ipAddresses[(i + 5) % 10]);

        // Set packet size
        event->PacketSize = i;

        trafficLog[i] = event;
    }

    *count = 10000;
    return trafficLog;
}
