#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[5];
} NFAPI_CRC_INDICATION_PDU_T;

void manage_crc_indications(int max_size) {
    int i, j;
    NFAPI_CRC_INDICATION_PDU_T* crc_pdu_array = NULL;
    size_t current_size = 0;
    unsigned long long seed = time(NULL);

    // Dynamically allocate memory for the array
    while (1) {
        if ((crc_pdu_array = realloc(crc_pdu_array, (current_size + max_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL)
            break;
        current_size += max_size;

        // Initialize pseudo-random value generator
        unsigned long long prev_seed = seed;
        for (i = 0; i < max_size; i++) {
            srand(prev_seed);
            int crcflag = rand() % 2;
            NFAPI_CRC_INDICATION_PDU_T* pdu = &crc_pdu_array[current_size + i];
            pdu->RX_UE_INFORMATION_TAG = prev_seed++;
            pdu->RNTI = rand();
            pdu->CRC_INDICATION_REL8_TAG[0] = crcflag;
            pdu->CRC_INDICATION_REL8_TAG[1] = crcflag << 1;
            pdu->CRC_INDICATION_REL8_TAG[2] = crcflag << 2;
            pdu->CRC_INDICATION_REL8_TAG[3] = crcflag << 3;
            pdu->CRC_INDICATION_REL8_TAG[4] = crcflag << 4;
        }
    }

    // Iterate over the array to validate integrity and RNTI uniqueness
    for (i = 0; i < current_size; i++) {
        int is_duplicate = 0;
        NFAPI_CRC_INDICATION_PDU_T* pdu = &crc_pdu_array[i];
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);

        // Check for duplicate RNTI assignments
        for (j = i + 1; j < current_size; j++) {
            NFAPI_CRC_INDICATION_PDU_T* next_pdu = &crc_pdu_array[j];
            if (pdu->RNTI == next_pdu->RNTI) {
                printf("Duplicate RNTI detected: %d\n", pdu->RNTI);
                is_duplicate = 1;
                break;
            }
        }

        // Clean up partially allocated resources on failure
        if (is_duplicate) {
            free(crc_pdu_array);
            crc_pdu_array = NULL;
            current_size = 0;
            seed = time(NULL); // Reset pseudo-random value generator
            continue;
        }
    }

    printf("Validation complete. No duplicate RNTI assignments detected.\n");

    // Free allocated memory
    free(crc_pdu_array);
}

int main() {
    manage_crc_indications(10);

    return 0;
}
