#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_NFAPI_PDUS 1024
#define MEMORY_POOL_SIZE 128

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int num_pudus = 0;
NFAPI_CRC_INDICATION_PDU_T* pudus[MEMORY_POOL_SIZE];

void* allocate_pdu() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        if (!pudus[i]) {
            pudus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (pudus[i]) {
                return pudus[i];
            }
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void free_pdu(void* pdu) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        if (pudus[i] == pdu) {
            free(pdu);
            pudus[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu();
    if (pdu) {
        srand(time(NULL));
        pdu->rx_ue_info.tag = rand() % 256;
        pdu->rnti = rand() % 65536;
        pdu->crc_indication_rel8.crcflag = rand() % 2;
        return pdu;
    }
    return NULL;
}

void destroy_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    free_pdu(pdu);
}

int get_num_pudus() {
    return num_pudus;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&mutex);
    if (num_pudus < MAX_NFAPI_PDUS) {
        pudus[num_pudus++] = pdu;
    } else {
        printf("Warning: Exceeded maximum number of NFAPI PDUs.\n");
    }
    pthread_mutex_unlock(&mutex);
}

void validate_structures() {
    for (int i = 0; i < num_pudus; i++) {
        if (pudus[i]->rnti == pudus[i+1]->rnti) {
            printf("Error: Two structures share the same RNTI.\n");
            // Clean up partially allocated resources
            for (int j = 0; j < num_pudus - i; j++) {
                destroy_pdu(pudus[i + j]);
            }
            return;
        }
    }
}

void* thread_func(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu();
    add_pdu(pdu);
    validate_structures();
    // Perform other operations on the PDU
    destroy_pdu(pdu);
    return NULL;
}

int main() {
    pthread_t threads[MAX_NFAPI_PDUS];
    for (int i = 0; i < MAX_NFAPI_PDUS; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }
    for (int i = 0; i < MAX_NFAPI_PDUS; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
