#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* imsi;
    int rnti;
} ue_context;

typedef struct {
    ue_context** contexts;
    int count;
    pthread_mutex_t mutex;
} lte_ue_context_manager;

void lte_ue_context_manager_init(lte_ue_context_manager* manager) {
    manager->contexts = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

void lte_ue_context_manager_add(lte_ue_context_manager* manager, ue_context* context) {
    pthread_mutex_lock(&manager->mutex);

    manager->contexts = (ue_context**) realloc(manager->contexts, (manager->count + 1) * sizeof(ue_context*));
    manager->contexts[manager->count] = context;
    manager->count++;

    pthread_mutex_unlock(&manager->mutex);
}

void lte_ue_context_manager_remove(lte_ue_context_manager* manager, int index) {
    pthread_mutex_lock(&manager->mutex);

    if (index < 0 || index >= manager->count) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    for (int i = index; i < manager->count - 1; i++) {
        manager->contexts[i] = manager->contexts[i + 1];
    }
    free(manager->contexts[manager->count - 1]);
    manager->count--;

    pthread_mutex_unlock(&manager->mutex);
}

void lte_ue_context_manager_update(lte_ue_context_manager* manager, int index, ue_context* newContext) {
    pthread_mutex_lock(&manager->mutex);

    if (index < 0 || index >= manager->count) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    free(manager->contexts[index]->imsi);
    free(manager->contexts[index]);
    manager->contexts[index] = newContext;

    pthread_mutex_unlock(&manager->mutex);
}

void lte_ue_context_manager_free(lte_ue_context_manager* manager) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->count; i++) {
        free(manager->contexts[i]->imsi);
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    manager->count = 0;
    pthread_mutex_unlock(&manager->mutex);
}

