// Function to manage a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** create_crc_indication_list(int capacity) {
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc((capacity + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory for CRC indication list.\n");
        return NULL;
    }

    for (int i = 0; i <= capacity; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!list[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for CRC indication structure.\n");
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(list[j]);
            }
            free(list);
            return NULL;
        }

        list[i]->tag = -1; // Initialize RX_UE_INFORMATION_TAG
        list[i]->rnti = -1; // Initialize RNTI
        list[i]->crcflag = rand() % 2; // Randomly set CRCFLAG for each element

        printf("Allocated CRC indication structure at index %d.\n", i);
    }

    return list;
}

void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T** list, int capacity) {
    if (!list || capacity < 1) {
        return;
    }

    for (int i = 0; i <= capacity; i++) {
        free(list[i]);
    }
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T** dynamic_crc_indication_list(int initial_capacity, int max_elements) {
    NFAPI_CRC_INDICATION_PDU_T** list = create_crc_indication_list(initial_capacity);

    if (!list) {
        return NULL;
    }

    // Dynamic resizing of the list
    for (int capacity = initial_capacity; capacity < max_elements; capacity *= 2) {
        NFAPI_CRC_INDICATION_PDU_T** new_list = realloc(list, (capacity + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

        if (!new_list) {
            fprintf(stderr, "Error: Failed to reallocate memory for CRC indication list.\n");
            // Free previously allocated memory
            free_crc_indication_list(list, capacity);
            return NULL;
        }

        list = new_list;
    }

    return list;
}
