#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define WEIGHTS 3

int main() {
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return -1;
    }

    char *line = NULL;
    size_t length = 0;
    ssize_t read;

    while ((read = getline(&line, &length, file)) != -1) {
        int measurements[read];
        int non_zero_count = 0;
        double total = 0.0;
        int last_non_zero_index = -1;

        for (int i = 0; i < read; i++) {
            if (sscanf(line + i, "%d,", &measurements[i]) == 1) {
                non_zero_count++;
                total += measurements[i];
                last_non_zero_index = i;
            }
        }

        if (non_zero_count >= WEIGHTS) {
            double average = (double)(total / non_zero_count);
            printf("%s", line);

            for (int i = last_non_zero_index - 2; i >= 0 && i <= last_non_zero_index; i--) {
                total -= measurements[i];
                non_zero_count--;
            }

            if (non_zero_count > 0) {
                double weighted_average = ((double)(measurements[last_non_zero_index]) * 1 +
                                           (double)(measurements[last_non_zero_index - 1]) * 2 +
                                           (double)(measurements[last_non_zero_index - 2]) * 1) / WEIGHTS;
                printf(", %.2f", weighted_average);
            }

            printf("\n");
        } else {
            printf("%s\n", line);
        }

        free(line);
        line = NULL;
        length = 0;
    }

    fclose(file);

    return 0;
}
