    if (!structures) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock();
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = structures + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);

        structure->RX_UE_INFORMATION_TAG = rand();
        structure->RNTI = rand();
        sprintf(structure->CRC_INDICATION_REL8_TAG, "%x", rand());
        structure->CRCFLAG = rand() & 1;
    }

    pthread_mutex_unlock();

    return structures;
}

void deallocate_structures(void* structures) {
    free(structures);
}

int main(int argc, char** argv) {
    int num_structures = 100; // Default number of structures
    int max_memory = MAX_MEMORY; // Default maximum memory

    pthread_mutex_init();

    while (1) {
        void* structures = allocate_structures(num_structures);

        if (!structures) {
            break;
        }

        // Process the allocated structures...

        deallocate_structures(structures);
    }

