#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the maximum capacity for the dynamic list
#define MAX_CAPACITY 10000

// Structure to hold NFAPI_CRC_INDICATION_PDU_T and its fields
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void* nfapi_crc_indication_pdu_list_manager(void* args) {
    // Initialize the dynamic list with a default capacity and mutex for thread safety
    int capacity = MAX_CAPACITY;
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Initialize the logger
    FILE* log_file = fopen("nfaпи_crc_indication_pdu_list_manager.log", "w");

    while (1) {
        // Handle concurrent access and thread safety
        pthread_mutex_lock(&lock);
        int i;
        for (i = 0; i < capacity; i++) {
            if (!list[i]) {
                break;
            }
        }
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            // Handle memory allocation failure
            perror("Memory allocation failed");
            pthread_mutex_unlock(&lock);
            fclose(log_file);
            return NULL;
        }
        new_pdu->CRCFLAG = rand() % 2; // Set CRCFLAG randomly
        list[i] = new_pdu;

        // Log the successful allocation
        fprintf(log_file, "Successful allocation: PDU at index %d\n", i);
        pthread_mutex_unlock(&lock);

        // Handle reaching the maximum capacity and exceeding it
        if (i == capacity) {
            // Dynamically increase the list's capacity
            capacity *= 2;
            NFAPI_CRC_INDICATION_PDU_T** new_list = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            if (!new_list) {
                // Handle memory reallocation failure
                perror("Memory reallocation failed");
                pthread_mutex_unlock(&lock);
                fclose(log_file);
                return NULL;
            }
            list = new_list;
        }

        // Handle unexpected interruptions and edge cases
        if (pthread_kill(pthread_self(), 0)) {
            // Handle unexpected interruption or thread termination
            perror("Thread interrupted");
            pthread_mutex_unlock(&lock);
            fclose(log_file);
            return NULL;
        }
    }

    // Free allocated memory upon completion
    for (i = 0; i < capacity; i++) {
        if (list[i]) {
            free(list[i]);
        }
    }
    free(list);

    // Close the logger
    fclose(log_file);
    pthread_mutex_destroy(&lock);

    return NULL;
}
