#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 50000
#define MAX_THREADS 10

typedef struct {
    int cell_id;
    int measurement_type;
    long timestamp;
    float cell_rx_power;
} NFAPI_CELL_MEASUREMENT_PDU_T;

NFAPI_CELL_MEASUREMENT_PDU_T* cell_measurements[MAX_ELEMENTS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int num_elements = 0;

void init_cell_measurements() {
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        cell_measurements[i] = NULL;
    }
}

int add_cell_measurement(int cell_id, int measurement_type, long timestamp, float cell_rx_power) {
    if (num_elements >= MAX_ELEMENTS) {
        return -1; // list is full
    }

    NFAPI_CELL_MEASUREMENT_PDU_T* new_element = malloc(sizeof(NFAPI_CELL_MEASUREMENT_PDU_T));
    if (new_element == NULL) {
        return -2; // memory allocation failed
    }

    new_element->cell_id = cell_id;
    new_element->measurement_type = measurement_type;
    new_element->timestamp = timestamp;
    new_element->cell_rx_power = cell_rx_power;

    pthread_mutex_lock(&lock);
    cell_measurements[num_elements++] = new_element;
    pthread_mutex_unlock(&lock);

    return 0; // successful addition
}

int remove_cell_measurement(int cell_id) {
    for (int i = 0; i < num_elements; i++) {
        if (cell_measurements[i]->cell_id == cell_id) {
            free(cell_measurements[i]);
            for (int j = i + 1; j < num_elements; j++) {
                cell_measurements[j - 1] = cell_measurements[j];
            }
            num_elements--;
            return 0; // successful removal
        }
    }

    return -3; // cell_id not found
}

void print_cell_measurements() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_elements; i++) {
        printf("Cell ID: %d, Measurement Type: %d, Timestamp: %ld, Cell RX Power: %.2f\n", 
               cell_measurements[i]->cell_id, cell_measurements[i]->measurement_type, 
               cell_measurements[i]->timestamp, cell_measurements[i]->cell_rx_power);
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    init_cell_measurements();

    // Example usage:
    int result = add_cell_measurement(1, 2, 3, 4.5);
    if (result != 0) {
        printf("Error adding cell measurement: %d\n", result);
    }

    result = remove_cell_measurement(1);
    if (result != 0) {
        printf("Error removing cell measurement: %d\n", result);
    }

    print_cell_measurements();

    return 0;
}
