#define MAX_STRUCTURES 1000
#define LOG_LEVEL 1 // 0: Error only, 1: Info and error

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void *malloc_or_die(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int create_nfa_api_crc_indication_pdu_array(int n, int max_structures, int seed) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;
    int allocated = 0;

    if (n > max_structures) {
        fprintf(stderr, "Error: Requested %d structures, but maximum limit is %d.\n", n, max_structures);
        return -1;
    }

    if (!allocated && n <= max_structures) {
        pdu_array = malloc_or_die(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        allocated = 1;
    } else if (allocated) {
        // Reuse previously allocated memory
        pdu_array = realloc(pdu_array, (n + allocated) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_array) {
            fprintf(stderr, "Memory reallocation failed.\n");
            return -1;
        }
    }

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i;
        pdu.RNTI = rand_r(seed) % 100; // Initialize RNTI
        pdu.CRC_INDICATION_REL8_TAG = (rand_r(seed) & 1) << 31; // Random CRCFLAG
        pdu_array[i] = pdu;
    }

    if (!LOG_LEVEL)
        return allocated;

    printf("Allocated: %d structures.\n", n);
    return allocated;
}

int main() {
    int max_structures = MAX_STRUCTURES;
    int seed = time(NULL);

    // Initialize random number generator
    srand(seed);

    int n = 10; // Number of structures to create

    int status = create_nfa_api_crc_indication_pdu_array(n, max_structures, seed);
    if (status < 0) {
        return EXIT_FAILURE;
    }

    printf("NFAPI CRC indication PDU array created successfully.\n");

    return status;
}
