#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000
#define RNTI_MAX 65535
#define CRCFLAG_MAX 1

typedef struct {
    char RX_UE_INFORMATION_TAG[10];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfaPiArray = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initArray() {
    if (nfaPiArray != NULL) return;
    nfaPiArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_STRUCTURES);
}

int findFreeSlot() {
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (nfaPiArray[i].RNTI == 0) return i;
    }
    return -1;
}

void removeUnsetCrc(int index) {
    if (nfaPiArray[index].CRCFLAG == 0) {
        for (int i = index; i < MAX_STRUCTURES - 1; i++) {
            nfaPiArray[i] = nfaPiArray[i + 1];
        }
        free(&nfaPiArray[MAX_STRUCTURES - 1]);
    }
}

void* checkCrc(void* arg) {
    int iterations = 0;
    while (iterations < 5) {
        for (int i = 0; i < MAX_STRUCTURES; i++) {
            if (nfaPiArray[i].CRCFLAG == 0) {
                removeUnsetCrc(i);
                break;
            }
        }
        sleep(1);
        iterations++;
    }
}

void updateStructure(int index, int rnti, char* crcIndicationTag) {
    pthread_mutex_lock(&lock);
    if (nfaPiArray[index].RNTI != 0) {
        printf("Error: Duplicate RNTI detected. Terminating process.\n");
        exit(1);
    }
    nfaPiArray[index].RX_UE_INFORMATION_TAG[0] = crcIndicationTag[0];
    nfaPiArray[index].RNTI = rnti;
    nfaPiArray[index].CRC_INDICATION_REL8_TAG[0] = crcIndicationTag[1];
    if (rand() % CRCFLAG_MAX == 0) {
        nfaPiArray[index].CRCFLAG = 1;
    } else {
        nfaPiArray[index].CRCFLAG = 0;
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    initArray();
    pthread_t thread;
    pthread_create(&thread, NULL, checkCrc, NULL);

    // Example usage
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        int rnti = rand() % RNTI_MAX;
        char crcIndicationTag[] = "CRI";
        updateStructure(findFreeSlot(), rnti, crcIndicationTag);

        // Simulate concurrent read and write operations
        for (int j = 0; j < 10000; j++) {
            // Read operation
            printf("Reading from index %d: RNTI %d, CRCFLAG %d\n", i, nfaPiArray[i].RNTI, nfaPiArray[i].CRCFLAG);

            // Write operation
            updateStructure((i + 1) % MAX_STRUCTURES, rnti, crcIndicationTag);
        }
    }

    pthread_join(thread, NULL);
    return 0;
}
