void add_network_interface(NetworkingConfigModule* config, int buffer_size, int timeout) {
    // Check for available memory and allocate as needed
    NetworkInterfaceConfig* new_interface = (NetworkInterfaceConfig*)realloc(config->interfaces, (config->num_interfaces + 1) * sizeof(NetworkInterfaceConfig));
    if (!new_interface) {
        fprintf(stderr, "Failed to allocate memory for new interface\n");
        return; // Handle error
    }

    config->interfaces[config->num_interfaces].buffer_size = buffer_size;
    config->interfaces[config->num_interfaces].timeout = timeout;
    config->num_interfaces++;
}

// Function to set the dynamic protocol selection at runtime
