    // For example:
    if (strcmp(protocol, "TCP") == 0) {
        // Set TCP as the selected protocol for this interface
    } else if (strcmp(protocol, "UDP") == 0) {
        // Set UDP as the selected protocol for this interface
    } else if (strcmp(protocol, "ICMP") == 0) {
        // Set ICMP as the selected protocol for this interface
    } else {
        fprintf(stderr, "Invalid protocol: %s\n", protocol);
        return; // Handle error
    }
}

// Function to handle errors and log them for monitoring and debugging purposes
void handle_error(NetworkingConfigModule* config, char* message) {
    // Log the error message using a logging library or function
    fprintf(stderr, "Error: %s\n", message);

    // Implement any additional error handling logic as needed
}

// Function to free the flexible networking configuration module and its resources
void free_networking_config(NetworkingConfigModule* config) {
    // Free each network interface configuration structure
    for (int i = 0; i < config->num_interfaces; i++) {
        free(&config->interfaces[i]);
