NFAPI_CRC_INDICATION_PDU_T* generateNfarxIndications(int n) {
    srand(time(NULL)); // seed for random number generation
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_node) {
            // handle memory allocation failure
            free_list(head);
            return NULL;
        }

        current->rx_ue_info = /* initialize from external data source */;
        current->rnti = (RNTI)(rand() % 256); // assign random RNTI
        current->crc_ind_rel8.CRCFLAG = (CRCFLAG)(rand() % 2);

        if (!head) {
            head = new_node;
            current = head;
        } else {
            current->next = new_node;
            current = current->next;
        }
    }

    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
