int nfa_crc_indication_pdu_arr_mgmt(int num_structures) {
    NFAPI_CRC_INDICATION_PDU_T** arr = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * num_structures);
    if (!arr) return -1;

    for (int i = 0; i < num_structures; i++) {
        arr[i] = (NFAPI_CRC_INDICATION_PDU_T*)nfa_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!arr[i]) break;
        arr[i]->RX_UE_INFORMATION_TAG = rand() % 256;
        arr[i]->RNTI = rand();
        arr[i]->CRC_INDICATION_REL8_TAG = rand();
        arr[i]->CRCFLAG = rand() % 2;

        // check for duplicate RNTI
        int found_duplicate = 0;
        for (int j = i - 1; j >= 0 && !found_duplicate; j--) {
            if (arr[j]->RNTI == arr[i]->RNTI) {
                printf("Error: Duplicate RNTI detected. Terminating.\n");
                nfa_free(arr);
                exit(1);
                found_duplicate = 1;
            }
        }
    }

    // Perform DNS resolution
    for (int i = 0; i < num_structures; i++) {
        struct hostent* he = gethostbyname(arr[i]->RX_UE_INFORMATION_TAG); // replace RX_UE_INFORMATION_TAG with hostname
        if (!he) continue;

        printf("DNS resolution successful for %s\n", inet_ntoa(*he->h_addr));
    }

    // Periodically check and remove unset CRCFLAG structures
    int set_crcflag_iterations = 0;
    while (set_crcflag_iterations < 5 && i > 0) {
        for (int j = i - 1; j >= 0; j--) {
            if (!arr[j]->CRCFLAG) break;
            arr[j]->CRCFLAG = rand() % 2;
            set_crcflag_iterations++;
        }
    }

    // Free allocated memory
    for (int i = num_structures - 1; i >= 0; i--) {
        nfa_free(arr[i]);
    }
    free(arr);

    return 0;
}

int main(int argc, char* argv[]) {
    int num_structures = 10000;
    return nfa_crc_indication_pdu_arr_mgmt(num_structures);
}
