#include <mutex>
#include <thread>
#include <atomic>

class NFARangeManager {
private:
    std::map<int, struct Range> ranges;
    std::mutex mtx;
    std::atomic<bool> crcFlag[10000];

public:
    struct Range {
        int min, max;
        bool inclusive;
    };

    NFARangeManager() {}

    void addRange(int key, int min, int max, bool inclusive) {
        if (ranges.find(key) != ranges.end()) {
            // Handle duplicate range
            logError("Duplicate range detected");
            return;
        }
        Range r = {min, max, inclusive};
        ranges[key] = r;
        crcFlag[key] = false; // Reset CRC flag for new range
    }

    void removeRange(int key) {
        if (ranges.erase(key)) {
            crcFlag[key] = false; // Reset CRC flag after removal
        } else {
            logError("Range not found");
        }
    }

    void updateRange(int key, int min, int max, bool inclusive) {
        if (ranges.find(key) == ranges.end()) {
            logError("Range not found");
            return;
        }
        Range& r = ranges[key];
        // Update range values
        r.min = min;
        r.max = max;
        r.inclusive = inclusive;
    }

    void resetRange(int key) {
        if (ranges.find(key) == ranges.end()) {
            logError("Range not found");
            return;
        }
        Range& r = ranges[key];
        // Reset range values to default
        r.min = 0;
        r.max = 0;
        r.inclusive = false;
    }

    void resetAllRanges() {
        for (auto& p : ranges) {
            p.second.min = 0;
            p.second.max = 0;
            p.second.inclusive = false;
        }
    }

    void partialReset(int key, int min, int max, bool inclusive) {
        if (ranges.find(key) == ranges.end()) {
            logError("Range not found");
            return;
        }
        Range& r = ranges[key];
        // Partially reset range values
        r.min = min;
        r.max = max;
        r.inclusive = inclusive;
    }

    void checkCRCFlag() {
        for (int i = 0; i < 10000; ++i) {
            if (!crcFlag[i]) continue;
            if (ranges.find(i) == ranges.end()) {
                // Handle CRC flag without corresponding range
                logError("Invalid CRC flag detected");
                return;
            }
            // Check for consecutive unset CRC flags
            int count = 0;
            while (++i < 10000 && !crcFlag[i]) {
                ++count;
            }
            if (count > 5) {
                // Remove range with stale CRC flag
                removeRange(i - 1);
            }
        }
    }

private:
    void logError(const std::string& message) {
        // Implement logging mechanism here
    }
};
