#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int n, char** result) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;
    size_t i;
    for (i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            *result = "Memory allocation failed";
            return NULL;
        }
        pdu->ue_tag = (RX_UE_INFORMATION_TAG){.tag = i};
        pdu->rnti = (RNTI)i;
        pdu->crc_tag = (CRC_INDICATION_REL8_TAG){.tag = i};
        if ((rand() % 2) == 0)
            pdu->crcflag = 1;
        else
            pdu->crcflag = 0;
        if (!pdu_array) {
            pdu_array = pdu;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* temp = pdu_array;
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = pdu;
        }
    }
    return pdu_array;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, char** result) {
    NFAPI_CRC_INDICATION_PDU_T* temp = pdu;
    while (temp) {
        NFAPI_CRC_INDICATION_PDU_T* next = temp->next;
        free(temp);
        temp = next;
    }
