LOG_EVENT_RECORD_T* log_event_record_new(int log_id, LOG_SEVERITY_LEVEL severity_level) {
    LOG_EVENT_RECORD_T* new_log = (LOG_EVENT_RECORD_T*)malloc(sizeof(LOG_EVENT_RECORD_T));
    if (!new_log) return NULL;
    new_log->log_id = log_id;
    new_log->severity_level = severity_level;
    new_log->message = NULL;
    new_log->next = NULL;
    new_log->prev = NULL;
    return new_log;
}

void log_event_record_free(LOG_EVENT_RECORD_T* log) {
    if (!log) return;
    free(log->message);
    free(log);
}

void log_event_insert_front(LOG_EVENT_RECORD_T** head, LOG_EVENT_RECORD_T* new_log) {
    if (*head == NULL || (*head)->next == NULL) {
        *head = new_log;
    } else {
        new_log->next = *head;
        (*head)->prev = new_log;
        *head = new_log;
    }
}

void log_event_insert_last(LOG_EVENT_RECORD_T** head, LOG_EVENT_RECORD_T* new_log) {
    if (*head == NULL || (*head)->next == NULL) {
        *head = new_log;
    } else {
        new_log->prev = (*head)->prev;
        new_log->next = *head;
        (*head)->prev = new_log;
        *head = new_log;
    }
}

void log_event_remove(LOG_EVENT_RECORD_T** head, LOG_EVENT_RECORD_T* log) {
    if (log == NULL || head == NULL) return;

    if (log == *head) {
        *head = log->next;
        if (*head != NULL) (*head)->prev = NULL;
    } else {
        log->prev->next = log->next;
        if (log->next != NULL) log->next->prev = log->prev;
    }

    free(log);
}

int main() {
    LOG_EVENT_RECORD_T* head = NULL;
    // Create some logs...
    for (int i = 0; i < 5; ++i) {
        LOG_EVENT_RECORD_T* new_log = log_event_record_new(i, LOG_SEVERITY_LEVEL_INFO);
        log_event_insert_last(&head, new_log);
    }
    return 0;
}

