// Function to dynamically manage the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** manage_list(int* size, FILE* log_file) {
    NFAPI_CRC_INDICATION_PDU_T** list = NULL;
    int allocated_size = 0;
    int current_size = 0;

    while (1) {
        // Allocate a new chunk of memory
        if ((list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (allocated_size + MAX_LIST_SIZE))) == NULL) {
            fprintf(log_file, "Error: Failed to allocate memory for the list.\n");
            return NULL;
        }

        // Initialize the new chunk of memory
        memset(&list[allocated_size], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (MAX_LIST_SIZE));

        allocated_size += MAX_LIST_SIZE;
        current_size = allocated_size;

        // Check for exceeding the maximum list size
        if (current_size > *size) {
            fprintf(log_file, "Error: List exceeded its maximum size.\n");
            return NULL;
        }

        // Set CRCFLAG probabilistically
        srand(time(NULL));
        for (int i = 0; i < current_size; i++) {
