#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int initialize_network_simulation(const char* config_file_path, int max_interfaces) {
    // Load configuration file
    FILE* config_file = fopen(config_file_path, "r");
    if (config_file == NULL) {
        return -1; // Error: Unable to load configuration file
    }

    // Initialize network environment
    struct network_env* env = malloc(sizeof(struct network_env));
    if (env == NULL) {
        fclose(config_file);
        return -2; // Error: Out of memory
    }
    env->max_interfaces = max_interfaces;
    env->interfaces = NULL;

    // Dynamically allocate memory for interfaces
    int num_interfaces = 0;
    while (num_interfaces < max_interfaces && fscanf(config_file, "%d %s %s\n", &env->interfaces[num_interfaces].id, &env->interfaces[num_interfaces].ip4_addr, &env->interfaces[num_interfaces].ip6_addr) == 3) {
        env->interfaces[num_interfaces].pps = 0; // Initialize packet processing rate
        num_interfaces++;
    }
    fclose(config_file);

    if (num_interfaces < max_interfaces) {
        free(env);
        return -3; // Error: Unable to load all interfaces from configuration file
    }

    // Initialize each interface with IPv4 and IPv6 support
    for (int i = 0; i < num_interfaces; i++) {
        env->interfaces[i].ip4_sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
        if (env->interfaces[i].ip4_sock == -1) {
            free(env);
            return -4; // Error: Unable to create IPv4 socket
        }
        env->interfaces[i].ip6_sock = socket(AF_INET6, SOCK_DGRAM, IPPROTO_UDP);
        if (env->interfaces[i].ip6_sock == -1) {
            close(env->interfaces[i].ip4_sock);
            free(env);
            return -5; // Error: Unable to create IPv6 socket
        }
    }

    return num_interfaces;
}

// Structure for network environment
struct network_env {
    int max_interfaces;
    struct interface* interfaces;
};

// Structure for a single interface
struct interface {
    int id;
    char ip4_addr[17];
    char ip6_addr[45];
    int pps; // Packet processing rate (packets per second)
    int ip4_sock;
    int ip6_sock;
};
