#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <dlfcn.h>
#include <pthread.h>

#define MAX_UES 100
#define TESTS 5

typedef struct {
    int UE_ID;
    char RX_UE_INFORMATION_TAG[10];
    char CQI_REPORT_TAG[10];
} UE_CONNECTION_INFO;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* ue_connections[MAX_UES];
pthread_mutex_t ue_lock = PTHREAD_MUTEX_INITIALIZER;
int ue_count = 0;

void* crc_indications[TESTS];
pthread_mutex_t crc_lock = PTHREAD_MUTEX_INITIALIZER;
int crc_count = 0;

void init_ue_connections() {
    for (int i = 0; i < MAX_UES; i++) {
        UE_CONNECTION_INFO* ue = (UE_CONNECTION_INFO*)malloc(sizeof(UE_CONNECTION_INFO));
        if (!ue) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        ue->UE_ID = i;
        strcpy(ue->RX_UE_INFORMATION_TAG, "RX_UE_INFO_TAG");
        strcpy(ue->CQI_REPORT_TAG, "CQI_REPORT_TAG");
        pthread_mutex_lock(&ue_lock);
        ue_connections[i] = (void*)ue;
        pthread_mutex_unlock(&ue_lock);
    }
}

void add_ue_connection(int UE_ID) {
    if (ue_count < MAX_UES) {
        UE_CONNECTION_INFO* ue = (UE_CONNECTION_INFO*)malloc(sizeof(UE_CONNECTION_INFO));
        if (!ue) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        ue->UE_ID = UE_ID;
        strcpy(ue->RX_UE_INFORMATION_TAG, "RX_UE_INFO_TAG");
        strcpy(ue->CQI_REPORT_TAG, "CQI_REPORT_TAG");
        pthread_mutex_lock(&ue_lock);
        ue_connections[ue_count++] = (void*)ue;
        pthread_mutex_unlock(&ue_lock);
    } else {
        fprintf(stderr, "Maximum number of UEs reached\n");
    }
}

void remove_ue_connection(int UE_ID) {
    int i;
    for (i = 0; i < ue_count; i++) {
        if (((UE_CONNECTION_INFO*)ue_connections[i])->UE_ID == UE_ID) {
            free(ue_connections[i]);
            pthread_mutex_lock(&ue_lock);
            memmove(ue_connections + i, ue_connections + i + 1, sizeof(void*) * (ue_count - i));
            ue_count--;
            pthread_mutex_unlock(&ue_lock);
            return;
        }
    }
}

void* load_library(const char* lib_name) {
    void* handle = dlopen(lib_name, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading library: %s\n", dlerror());
        return NULL;
    }
    return handle;
}

int execute_test(void* lib_handle, int test_id) {
    void (*test_func)(void*, NFAPI_CRC_INDICATION_PDU_T*) = dlsym(lib_handle, (const char*)test_id);
    if (!test_func) {
        fprintf(stderr, "Error finding symbol: %s\n", dlerror());
        return -1;
    }
    test_func(NULL, NULL);
    return 0;
}

void run_tests(void* lib_handle) {
    for (int i = 0; i < TESTS; i++) {
        int result = execute_test(lib_handle, i);
        if (result != 0) {
            fprintf(stderr, "Test %d failed\n", i);
        } else {
            printf("Test %d passed\n", i);
        }
    }
}

void init_crc_indications() {
    for (int i = 0; i < TESTS; i++) {
        NFAPI_CRC_INDICATION_PDU_T* crc = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        crc->RX_UE_INFORMATION_TAG = i;
        crc->RNTI = i;
        strcpy(crc->CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG");
        crc->CRCFLAG = rand() % 2;
        pthread_mutex_lock(&crc_lock);
        crc_indications[i] = (void*)crc;
        pthread_mutex_unlock(&crc_lock);
    }
}

int main() {
    init_ue_connections();
    init_crc_indications();
    void* lib_handle = load_library("mylib.so");
    run_tests(lib_handle);
    return 0;
}
