int loadResourceBundleAndEncrypt(const char* filePath, const char* configParamSource) {
    // Load the resource bundle from the specified file path
    ResourceBundle* bundle = loadResourceBundle(filePath);

    if (!bundle) {
        return 0;
    }

    // Retrieve configuration parameters for encryption mode
    int encryptionMode = retrieveConfigParameter(configParamSource, "encryption_mode");

    // Initialize the EVP_CIPHER structure with the selected encryption mode
    EVP_CIPHER* cipher;
    switch (encryptionMode) {
        case ECB_MODE:
            cipher = EVP_get_cipherbyname("ecb");
            break;
        case EDE_MODE:
            cipher = EVP_get_cipherbyname("ede");
            break;
        case EDE3_MODE:
            cipher = EVP_get_cipherbyname("ede3");
            break;
        case CFB_MODE:
            cipher = EVP_get_cipherbyname("cfb");
            break;
        default:
            cipher = NULL; // or use a default encryption mode if no parameter is set
    }

    // Encrypt the resource bundle using the selected cipher
    int encryptedSize = encryptResourceBundle(bundle, cipher);

    // Clean up memory allocation and deallocation
    freeBundleResources(bundle);

    return encryptedSize;
}
