        pthread_mutex_lock(&lock);
        pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pdu_list, (num_pdu + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu_list[num_pdu++] = *pdu;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void free_pdu() {
