#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    enum { CRCFLAG_ON, CRCFLAG_OFF } CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct list_node* next;
};

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void add_to_list(struct list_node** head_ref, NFAPI_CRC_INDICATION_PDU_T* new_data) {
    pthread_mutex_lock(&list_lock);
    struct list_node* new_node = (struct list_node*)malloc(sizeof(struct list_node));
    new_node->data = new_data;
    new_node->next = *head_ref;
    *head_ref = new_node;
    pthread_mutex_unlock(&list_lock);
}

void remove_from_list(struct list_node** head_ref, int RNTI) {
    pthread_mutex_lock(&list_lock);
    struct list_node* current = *head_ref;
    struct list_node* prev = NULL;
    while (current != NULL) {
        if (current->data->RNTI == RNTI) {
            if (prev == NULL) {
                *head_ref = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

void update_crcflag(struct list_node** head_ref, int RNTI, enum { CRCFLAG_ON, CRCFLAG_OFF } new_CRCFLAG) {
    pthread_mutex_lock(&list_lock);
    struct list_node* current = *head_ref;
    while (current != NULL) {
        if (current->data->RNTI == RNTI) {
            current->data->CRCFLAG = new_CRCFLAG;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

int serialize_list(struct list_node* head, FILE* file) {
    if (head == NULL) return 0;

    fwrite(&head->data->RX_UE_INFORMATION_TAG, sizeof(char), 16, file);
    fwrite(&head->data->RNTI, sizeof(int), 1, file);
    fwrite(&head->data->CRCFLAG, sizeof(enum { CRCFLAG_ON, CRCFLAG_OFF }), 1, file);

    int result = serialize_list(head->next, file);

    return result;
}

int deserialize_list(struct list_node** head_ref, FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fread(new_data->RX_UE_INFORMATION_TAG, sizeof(char), 16, file);
    fread(&new_data->RNTI, sizeof(int), 1, file);
    fread(&new_data->CRCFLAG, sizeof(enum { CRCFLAG_ON, CRCFLAG_OFF }), 1, file);

    add_to_list(head_ref, new_data);

    int result = deserialize_list(head_ref, file);

    return result;
}

int main() {
    // Example usage
    struct list_node* head = NULL;

    NFAPI_CRC_INDICATION_PDU_T data1 = {"Tag1", 1, CRCFLAG_ON};
    NFAPI_CRC_INDICATION_PDU_T data2 = {"Tag2", 2, CRCFLAG_OFF};

    add_to_list(&head, &data1);
    add_to_list(&head, &data2);

    FILE* file = fopen("example.bin", "wb");
    serialize_list(head, file);
    fclose(file);

    return 0;
}

