typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_crc_indication_pdu(int n, int bits_per_sample_max);
void extract_image_info(TIFF* tif, NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc);

int main() {
    // Example usage
    int n = 5;  // Number of structures to create
    int bits_per_sample_max = 16;  // Maximum bits per sample

    NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crcs = create_nfapi_crc_indication_pdu(n, bits_per_sample_max);

    for (int i = 0; i < n; i++) {
        // Open a TIFF file
        TIFF* tif = ...;

        extract_image_info(tif, &nfa_pi_crcs[i]);
    }

    // Free memory
    for (int i = 0; i < n; i++) {
        free(&nfa_pi_crcs[i]);
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_crc_indication_pdu(int n, int bits_per_sample_max) {
    NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crcs = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        // Initialize RX_UE_INFORMATION_TAG and RNTI
        NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc = &nfa_pi_crcs[i];
        nfa_pi_crc->rx_ue_info = ...;
        nfa_pi_crc->rnti = ...;

        // Randomly set CRCFLAG
        nfa_pi_crc->crcflag = rand() % 2;

        // Initialize CRC_INDICATION_REL8_TAG
        nfa_pi_crc->crc_ind_rel8_tag = ...;
    }

    return nfa_pi_crcs;
}

void extract_image_info(TIFF* tif, NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc) {
    // Get image dimensions
    uint16_t width = tgetfield(tif, TIFFTAG_IMAGEWIDTH);
    uint16_t height = tgetfield(tif, TIFFTAG_IMAGELENGTH);

    // Extract bits per sample, samples per pixel, and extra samples
    int bits_per_sample = tgetfield(tif, TIFFTAG_BITSPERSAMPLE);
    int samples_per_pixel = tgetfield(tif, TIFFTAG_SAMPLESPERPIXEL);
    uint16_t extra_samples = tgetfield(tif, TIFFTAG_EXTRASAMPLES);

    // Calculate MD5 hash of the image file's metadata
    uint8_t* md5_hash = (uint8_t*)malloc(16 * sizeof(uint8_t));
    tmd5(tif, md5_hash);

    // Store extracted information in NFAPI_CRC_INDICATION_PDU_T structure
    nfa_pi_crc->rx_ue_info.image_width = width;
    nfa_pi_crc->rx_ue_info.image_height = height;
    nfa_pi_crc->rx_ue_info.bits_per_sample = bits_per_sample;
    nfa_pi_crc->rx_ue_info.samples_per_pixel = samples_per_pixel;
    nfa_pi_crc->rx_ue_info.extra_samples = extra_samples;
    memcpy(&nfa_pi_crc->md5_hash, md5_hash, 16);

    // Free memory
    free(md5_hash);
}
