#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct LTE_PHY_RX_FRAME_INFO_T {
    uint32_t RX_UE_CONFIGURATION_TAG;
    uint32_t RRC_CONNECTION_TAG;
    uint32_t PROCESSING_DELAY_STATS;
} LTE_PHY_RX_FRAME_INFO_T;

typedef struct Node {
    LTE_PHY_RX_FRAME_INFO_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int count = 0;

void init_list() {
    srand(time(NULL));
    for (int i = 0; i < 1000000; i++) {
        LTE_PHY_RX_FRAME_INFO_T info;
        info.RX_UE_CONFIGURATION_TAG = rand();
        info.RRC_CONNECTION_TAG = rand();
        info.PROCESSING_DELAY_STATS = rand();
        Node* newNode = malloc(sizeof(Node));
        newNode->data = info;
        newNode->next = head;
        pthread_mutex_lock(&lock);
        if (head == NULL) {
            head = newNode;
        } else {
            Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newNode;
        }
        pthread_mutex_unlock(&lock);
    }
}

void insert_node(LTE_PHY_RX_FRAME_INFO_T info) {
    pthread_mutex_lock(&lock);
    Node* newNode = malloc(sizeof(Node));
    newNode->data = info;
    newNode->next = head;
    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&lock);
}

void delete_node(LTE_PHY_RX_FRAME_INFO_T info) {
    pthread_mutex_lock(&lock);
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL && current->data != info) {
        previous = current;
        current = current->next;
    }
    if (current != NULL) {
        if (previous == NULL) {
            head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&lock);
}

void traverse_list() {
    Node* current = head;
    while (current != NULL) {
