#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_M 100 // configurable maximum number of elements
#define MEMORY_THRESHOLD 1024 * 1024 // memory threshold in bytes (1MB)

// Structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic list structure with partial update mechanism
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int size; // current number of elements
    int capacity; // allocated memory size in bytes
} DynamicList;

// Function to manage the dynamic list
DynamicList* init_dynamic_list(int initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    return list;
}

// Function to update CRCFLAG for a subset of elements
void partial_update_crc_flag(DynamicList* list, int start_index, int end_index, condition_func_t condition) {
    // iterate over the range [start_index, end_index] and apply condition function
    for (int i = start_index; i <= end_index; i++) {
        if (condition(list->elements[i].tag)) {
            list->elements[i].crc_flag |= CRC_FLAG_UPDATE_MASK;
        }
    }
}

// Function to iterate over the dynamic list
void iterate_list(DynamicList* list, list_iter_func_t func) {
    for (int i = 0; i < list->size; i++) {
        func(list->elements[i]);
    }
}

// Function to free allocated resources
void free_dynamic_list(DynamicList* list) {
    if (list != NULL) {
        free(list->elements);
        free(list);
    }
}
