NFAPI_CRC_INDICATION_PDU_T* init_and_populate_NFAPICRCIndicationPDU(int n, int max_size) {
    if (n <= 0 || max_size <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MEMORY_POOL_SIZE);
    if (!p) return NULL;

    srand(time(NULL));
