#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure type
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a doubly-linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Define the list structure itself
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
    size_t capacity;
    size_t size;
} NFAPI_CRC_INDICATION_PDU_LIST_T;

// Initialize and return a new, empty list
NFAPI_CRC_INDICATION_PDU_LIST_T* init_list(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_PDU_LIST_T* list = (NFAPI_CRC_INDICATION_PDU_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST_T));
    list->head = NULL;
    list->tail = NULL;
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Insert a new element at the end of the list
void insert_list(NFAPI_CRC_INDICATION_PDU_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = *element;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    pthread_mutex_lock(&list->mutex);
    list->size++;
    if (list->size >= list->capacity * 0.7) { // resize when 70% full
        size_t new_capacity = list->capacity * 2;
        Node** nodes = (Node**)malloc(sizeof(Node*) * new_capacity);
        for (int i = 0; i < list->size; i++) {
            nodes[i] = list->head->prev->next;
        }
        free(list->head);
        list->head = NULL;
        list->tail = NULL;
        pthread_mutex_unlock(&list->mutex);
        for (int i = 0; i < list->size; i++) {
            Node* current_node = nodes[i];
            if (current_node) {
                if (!list->head) {
                    list->head = current_node;
                    list->tail = current_node;
                } else {
                    current_node->next = NULL;
                    current_node->prev = list->tail;
                    list->tail->next = current_node;
                    list->tail = current_node;
                }
            }
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

// Remove the first element with a specific `RNTI` value
void remove_by_RNTI(NFAPI_CRC_INDICATION_PDU_LIST_T* list, int target_RNTI) {
    Node* current_node = list->head;
    while (current_node) {
        if (current_node->data.RNTI == target_RNTI) {
            if (!list->head) {
                list->tail = NULL;
            } else {
                list->head = current_node->next;
                if (list->head) {
                    list->head->prev = NULL;
                } else {
                    list->tail = NULL;
                }
            }

            Node* temp_node = current_node;
            current_node = current_node->next;

            pthread_mutex_lock(&list->mutex);
            list->size--;
            free(temp_node);

            // Log the removal event
            FILE* log_file = fopen("log.txt", "a");
            fprintf(log_file, "Removed element with RNTI %d\n", target_RNTI);
            fclose(log_file);

            pthread_mutex_unlock(&list->mutex);
            return;
        }
        current_node = current_node->next;
    }
}

// Iterate and retrieve elements with a specific `CRCFLAG` value
void iterate_by_CRCFLAG(NFAPI_CRC_INDICATION_PDU_LIST_T* list, int target_CRCFLAG) {
    Node* current_node = list->head;
    while (current_node) {
        if (current_node->data.CRCFLAG == target_CRCFLAG) {
            printf("Element with CRCFLAG %d: RNTI=%d, RX_UE_INFORMATION_TAG=%d, "
                   "CRC_INDICATION_REL8_TAG=%d\n",
                   target_CRCFLAG, current_node->data.RNTI,
                   current_node->data.RX_UE_INFORMATION_TAG,
                   current_node->data.CRC_INDICATION_REL8_TAG);
            current_node = current_node->next;
        } else {
            current_node = current_node->next;
        }
    }
}

int main() {
