#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a DCI message
typedef struct {
    int valid;
    int pci;
    int cqi;
} DCIMessage;

// Define the structure to manage the dynamic list of DCI messages
typedef struct {
    DCIMessage* messages;
    int size;
    int capacity;
    pthread_mutex_t lock; // Lock for concurrency-safe access
} DCIMessages;

// Function to create a new DCIMessages structure with initial capacity and lock
DCIMessages* dcimessages_create(int initial_capacity) {
    DCIMessages* result = (DCIMessages*)malloc(sizeof(DCIMessages));
    result->messages = (DCIMessage*)calloc(initial_capacity, sizeof(DCIMessage));
    result->size = 0;
    result->capacity = initial_capacity;
    pthread_mutex_init(&result->lock, NULL);
    return result;
}

// Function to add a new DCI message to the list
void dcimessages_add(DCIMessages* messages, int pci, int cqi) {
    pthread_mutex_lock(&messages->lock);

    // Check if there's already an entry with the same PCI
    for (int i = 0; i < messages->size; i++) {
        if (messages->messages[i].pci == pci) {
            // Update the CQI value of the existing message
            messages->messages[i].cqi = cqi;
            pthread_mutex_unlock(&messages->lock);
            return;
        }
    }

    // If no duplicate PCI found, add a new DCI message to the list
    if (messages->size == messages->capacity) {
        int new_capacity = messages->capacity * 2;
        DCIMessage* new_messages = (DCIMessage*)realloc(messages->messages, new_capacity * sizeof(DCIMessage));
        messages->messages = new_messages;
        messages->capacity = new_capacity;
    }

    messages->messages[messages->size].valid = 1;
    messages->messages[messages->size].pci = pci;
    messages->messages[messages->size].cqi = cqi;
    messages->size++;

    pthread_mutex_unlock(&messages->lock);
}

// Function to update the CQI value of an existing DCI message
void dcimessages_update_cqi(DCIMessages* messages, int pci, int cqi) {
    pthread_mutex_lock(&messages->lock);

    for (int i = 0; i < messages->size; i++) {
        if (messages->messages[i].pci == pci) {
            // Update the CQI value of the existing message
            messages->messages[i].cqi = cqi;
            pthread_mutex_unlock(&messages->lock);
            return;
        }
    }

    pthread_mutex_unlock(&messages->lock);
}

// Function to retrieve a DCI message by its PCI value
DCIMessage* dcimessages_get(DCIMessages* messages, int pci) {
    pthread_mutex_lock(&messages->lock);

    for (int i = 0; i < messages->size; i++) {
        if (messages->messages[i].pci == pci) {
            DCIMessage* result = &messages->messages[i];
            pthread_mutex_unlock(&messages->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&messages->lock);
    return NULL;
}

// Function to remove DCI messages associated with inactive cells
void dcimessages_remove_inactive(DCIMessages* messages) {
    int new_size = 0;

    pthread_mutex_lock(&messages->lock);

    for (int i = 0; i < messages->size; i++) {
        if (messages->messages[i].valid) {
            // Move the valid message to a new position
            messages->messages[new_size] = messages->messages[i];
            new_size++;
        }
    }

    free(messages->messages);
    messages->messages = NULL;
    messages->size = 0;
    messages->capacity = 0;

    pthread_mutex_unlock(&messages->lock);

    // Reset the lock to ensure it's not corrupted
    pthread_mutex_init(&messages->lock, NULL);
}

// Example usage:
int main() {
    DCIMessages* messages = dcimessages_create(4);

    dcimessages_add(messages, 1, 5);
    dcimessages_add(messages, 2, 3);
    dcimessages_add(messages, 1, 7); // Update CQI for existing PCI

    DCIMessage* retrieved_message = dcimessages_get(messages, 1);
    if (retrieved_message) {
