typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node structure
typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

// Function to create a new linked list node with random RNTI and CRC flag
LinkedListNode* createNode() {
    LinkedListNode* newNode = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!newNode) return NULL;  // Handle memory allocation failure

    // Set random RNTI and CRC flag
    newNode->data.RNTI = rand() % 1000;  // Adjust the range as needed
    newNode->data.CRCFLAG = (rand() % 2) ? 1 : 0;
    return newNode;
}

// Function to add a new node to the end of the linked list, handling capacity limits and RNTI uniqueness
void addNode(LinkedListNode** head, int maxCapacity) {
    LinkedListNode* newNode = createNode();
    if (!newNode || *head == NULL) return;  // Handle memory allocation failure or empty list

    // Check for capacity limit and remove the least recently added node if exceeded
    if (listLength(*head) >= maxCapacity) {
        LinkedListNode* oldHead = *head;
        *head = (*head)->next;
        free(oldHead);
    }

    // Ensure RNTI uniqueness
    int rntiFound = 0;
    LinkedListNode* current = *head;
    while (current && !rntiFound) {
        if (newNode->data.RNTI == current->data.RNTI) {
            free(newNode);
            return;  // RNTI already exists in the list
        }
        current = current->next;
    }

    // Add new node to the end of the linked list
    newNode->next = *head;
    *head = newNode;
}

// Function to calculate the length of a linked list
int listLength(LinkedListNode* head) {
    int length = 0;
    while (head) {
        length++;
        head = head->next;
    }
    return length;
}

// Function to export linked list contents to a specified file, handling potential disk full or write failure scenarios
void exportListToFile(const char* filename, LinkedListNode* head) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        printf("Error: unable to open file for writing.\n");
        return;  // Handle file opening failure
    }

    LinkedListNode* current = head;
    while (current) {
        fprintf(file, "%d %d %d\n", current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
    fclose(file);
}

int main() {
    srand(time(NULL));  // Initialize random number generator
    LinkedListNode* head = NULL;  // Initialize linked list

    int maxCapacity = 1000;  // Configure maximum capacity for the linked list
    addNode(&head, maxCapacity);  // Add initial node to the list
    printf("Added node with RNTI: %d\n", head->data.RNTI);

    // Simulate adding nodes to the list and exporting contents to a file
    for (int i = 1; i <= 10; i++) {
        addNode(&head, maxCapacity);
        exportListToFile("output.txt", head);
        printf("Exported list contents to file 'output.txt'\n");
    }

    return 0;
}

