#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void create_and_populate_list(int n, int* list_size, NFAPI_CRC_INDICATION_PDU_T*** list) {
    *list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < n; i++) {
        (*list)[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        srand(time(NULL));
        (*(*list)[i]).RX_UE_INFORMATION_TAG = rand() % 100;
        (*(*list)[i]).RNTI = rand() % 65535;
        (*(*list)[i]).CRC_INDICATION_REL8_TAG = rand() % 1000;
        (*(*list)[i]).CRCFLAG = (rand() % 2) ? 1 : 0;

    }
}

void destroy_list(NFAPI_CRC_INDICATION_PDU_T** list, int size) {
    for (int i = 0; i < size; i++) {
        free((*list)[i]);
    }
    free(list);
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T* list, int size, unsigned char** buffer) {
    *buffer = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < size; i++) {
        memcpy(*buffer + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), &list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

void deserialize_list(unsigned char* buffer, int size, NFAPI_CRC_INDICATION_PDU_T** list) {
    *list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < size; i++) {
        (*list)[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy((*list)[i], buffer + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

int main() {
    int n = 10;
    NFAPI_CRC_INDICATION_PDU_T** list;
    create_and_populate_list(n, &n, &list);

    // Serialize the list
    unsigned char* buffer;
    serialize_list(*list, n, &buffer);

    // Deserialize the list
    NFAPI_CRC_INDICATION_PDU_T** deserialized_list;
    deserialize_list(buffer, n, &deserialized_list);

    destroy_list(list, n);
    free(buffer);

    return 0;
}
