void initAES256CBC(char *password) {
    unsigned char passwordHash[SHA_DIGEST_LENGTH];
    SHA1_CTX sha_ctx;
    SHA1_Init(&sha_ctx);
    SHA1_Update(&sha_ctx, password, strlen(password));
    SHA1_Final(passwordHash, &sha_ctx);

    int keySize = AES_KEY_SIZE_256;
    unsigned char aesKey[keySize];
    for (int i = 0; i < keySize; i++) {
        aesKey[i] = passwordHash[i % SHA_DIGEST_LENGTH];
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, aesKey, NULL);
}

