typedef struct {
    int id;
    char name[20];
    float bandwidthUsage;
} MobileCore_Config;

// Function to initialize and manage a dynamic list of MobileCore_Config structures
void* configManager_init() {
    // Initialize the maximum number of configurations ever created simultaneously
    int maxConfigCount = 0;

    // Initialize the first configuration pointer
    MobileCore_Config** configList = (MobileCore_Config**)malloc(sizeof(MobileCore_Config*) * 1);
    MobileCore_Config* currentConfig = NULL;

    return (void*) { .maxConfigCount = &maxConfigCount, .configList = &configList, .currentConfig = &currentConfig };
}

// Function to add a new network configuration
void configManager_add(void* configManagerPtr) {
    int maxConfigCount;
    MobileCore_Config** configList;
    MobileCore_Config* currentConfig;

    // Get the maximum number of configurations ever created simultaneously
    maxConfigCount = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->maxConfigCount;

    // Check if the maximum number of configurations has been exceeded
    if (maxConfigCount >= 10) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Maximum number of configurations reached.\n");
        return;
    }

    // Allocate space for a new configuration structure
    configList = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->configList;
    *configList = (MobileCore_Config**)realloc(*configList, sizeof(MobileCore_Config*) * ++maxConfigCount);
    ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->maxConfigCount = maxConfigCount;

    // Initialize the new configuration structure
    currentConfig = (MobileCore_Config*)malloc(sizeof(MobileCore_Config));
    strcpy(currentConfig->name, "New Network Interface");
    currentConfig->bandwidthUsage = 0.0;
    *configList = (MobileCore_Config**)realloc(*configList, sizeof(MobileCore_Config*) * maxConfigCount);
}

// Function to update an existing network configuration
void configManager_update(void* configManagerPtr) {
    int maxConfigCount;
    MobileCore_Config** configList;
    MobileCore_Config* currentConfig;

    // Get the maximum number of configurations ever created simultaneously
    maxConfigCount = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->maxConfigCount;

    // Iterate over all configurations to update bandwidth usage
    for (int i = 0; i < maxConfigCount; i++) {
        // Access the ith configuration structure
        configList = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->configList;
        currentConfig = *configList + i;

        // Update bandwidth usage for the ith configuration
        currentConfig->bandwidthUsage += 0.5;
    }
}

// Function to compute and report the average bandwidth usage across all interfaces
void configManager_reportAverageBandwidth(void* configManagerPtr) {
    int maxConfigCount;
    MobileCore_Config** configList;

    // Get the maximum number of configurations ever created simultaneously
    maxConfigCount = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->maxConfigCount;

    // Initialize sum and count for average bandwidth usage calculation
    float sum = 0.0;
    int count = 0;

    // Iterate over all configurations to calculate the average bandwidth usage
    for (int i = 0; i < maxConfigCount; i++) {
        // Access the ith configuration structure
        configList = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->configList;
        sum += (*configList + i)->bandwidthUsage;
        count++;
    }

    // Calculate and report the average bandwidth usage
    printf("Average bandwidth usage: %f\n", (sum / count));
}

// Function to iterate over all configurations for reporting purpose
void configManager_reportConfigurations(void* configManagerPtr) {
    int maxConfigCount;
    MobileCore_Config** configList;

    // Get the maximum number of configurations ever created simultaneously
    maxConfigCount = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->maxConfigCount;

    // Iterate over all configurations for reporting purpose
    for (int i = 0; i < maxConfigCount; i++) {
        // Access the ith configuration structure
        configList = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->configList;
        printf("Configuration %d: Name - %s, Bandwidth Usage - %.2f\n", i + 1, (*configList + i)->name, (*configList + i)->bandwidthUsage);
    }
}

// Function to free the resources allocated by configManager_init
void configManager_free(void* configManagerPtr) {
    int maxConfigCount;
    MobileCore_Config** configList;

    // Get the maximum number of configurations ever created simultaneously
    maxConfigCount = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->maxConfigCount;

    // Free each configuration structure
    for (int i = 0; i < maxConfigCount; i++) {
        configList = ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->configList;
        free(*configList + i);
    }

    // Free the array of configuration structures
    free(configList);

    // Reset the maximum number of configurations ever created simultaneously
    ((struct {int maxConfigCount; void* configList; MobileCore_Config* currentConfig; }*)configManagerPtr)->maxConfigCount = 0;
}

int main() {
    // Initialize and manage a dynamic list of MobileCore_Config structures
    void* configManagerPtr = configManager_init();

    // Add new network configurations
    configManager_add(configManagerPtr);
    configManager_add(configManagerPtr);

    // Update existing network configurations
    configManager_update(configManagerPtr);

    // Compute and report the average bandwidth usage across all interfaces
    configManager_reportAverageBandwidth(configManagerPtr);

    // Iterate over all configurations for reporting purpose
    configManager_reportConfigurations(configManagerPtr);

    // Free the resources allocated by configManager_init
    configManager_free(configManagerPtr);

    return 0;
}
