    void addChannel(int** channels, int* numChannels) {
        *numChannels = (*numChannels + 1);
        *maxChannels = (*maxChannels > *numChannels ? *maxChannels : *numChannels);
        int* newChannel = (int*)malloc(sizeof(int));
        *(channels + *numChannels - 1) = newChannel;
    }

