    void updateChannel(int** channels, int numChannels, int index, int config, int status) {
        if(index < 0 || index >= numChannels) {
            printf("Invalid channel index. Aborting.\n");
            return;
        }
        (*channels)[index]->config = config;
        (*channels)[index]->status = status;
    }

    // Iterate over channels to calculate total number of active channels
    int countActiveChannels(int** channels, int numChannels) {
        int activeChannels = 0;
        for (int i = 0; i < numChannels; i++) {
            if ((*channels)[i]->status == 1) {
                activeChannels++;
            }
        }
        return activeChannels;
    }

    // Function to handle memory allocation failure
    void handleMemoryAllocationFailure() {
        printf("Memory allocation failed. Aborting.\n");
    }

