#define JSON_FILE "config.json"

struct SimulationNode {
    int id;
    char state[10];
    float throughput, latency, packet_loss_rate;
};

void initializeSimulationEnvironment() {
    json_object *jobj = NULL;
    FILE *fp = fopen(JSON_FILE, "r");

    if (!fp) {
        fprintf(stderr, "Error opening file %s\n", JSON_FILE);
        return;
    }

    jobj = json_load_file(fp, 0, NULL);
    fclose(fp);

    if (!jobj) {
        fprintf(stderr, "Failed to load configuration from file %s\n", JSON_FILE);
        return;
    }

    int N = json_object_get_int(jobj, "N");
    float bandwidth = json_object_get_float(jobj, "bandwidth");
    float latency = json_object_get_float(jobj, "latency");
    float packet_loss_rate = json_object_get_float(jobj, "packet_loss_rate");

    // Validate configuration settings
    if (N > 1000 || N < 1) {
        fprintf(stderr, "Invalid number of nodes: %d\n", N);
        return;
    }
    if (bandwidth > 10000 || bandwidth < 0.01f) {
        fprintf(stderr, "Invalid network bandwidth: %.2f\n", bandwidth);
        return;
    }
    if (latency > 10 || latency < 0.1f) {
        fprintf(stderr, "Invalid network latency: %.2f\n", latency);
        return;
    }
    if (packet_loss_rate > 0.5 || packet_loss_rate < 0.01f) {
        fprintf(stderr, "Invalid packet loss rate: %.2f\n", packet_loss_rate);
        return;
    }

    // Initialize nodes
    struct SimulationNode *nodes = malloc(N * sizeof(struct SimulationNode));
    for (int i = 0; i < N; i++) {
        nodes[i].id = i + 1;
        nodes[i].state = "INITIAL";
        nodes[i].throughput = 1000.0f;
        nodes[i].latency = latency;
        nodes[i].packet_loss_rate = packet_loss_rate;
    }

    // Initialize simulation environment
    printf("Simulation environment initialized with %d nodes.\n", N);

    // Release resources
    free(nodes);
    json_object_put(jobj);
}

int main() {
    initializeSimulationEnvironment();
    return 0;
}
