int nfaListSize = 0;
int threshold = 500;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* logFile = fopen("nfaLog.txt", "w");

void insertElement(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&mutex);
    if (nfaListSize >= MAX_SIZE) {
        removeLRUElement();
    }
    nfaList = realloc(nfaList, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfaListSize + 1));
    nfaList[nfaListSize] = *element;
    nfaListSize++;
    fprintf(logFile, "Added element RNTI: %d, CRCFLAG: %d at time %lld\n", element->RNTI, element->CRCFLAG, (long long)time(NULL));
    pthread_mutex_unlock(&mutex);
}

void removeElement(int RNTI) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < nfaListSize; i++) {
        if (nfaList[i].RNTI == RNTI) {
            memmove(&nfaList[i], &nfaList[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfaListSize - i));
            nfaListSize--;
            fprintf(logFile, "Removed element RNTI: %d at time %lld\n", RNTI, (long long)time(NULL));
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void removeLRUElement() {
    int leastRecent = 0;
    for (int i = 1; i < nfaListSize; i++) {
        if (nfaList[i].CRCFLAG > nfaList[leastRecent].CRCFLAG) {
            leastRecent = i;
        }
    }
    memmove(&nfaList[0], &nfaList[leastRecent], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfaListSize--;
    fprintf(logFile, "Evicted element RNTI: %d, CRCFLAG: %d at time %lld\n", nfaList[leastRecent].RNTI, nfaList[leastRecent].CRCFLAG, (long long)time(NULL));
}

