    for (int i = 0; i < nfaListSize; i++) {
        if ((*callback)(&nfaList[i])) {
            return (void*)1;
        }
    }
    return (void*)0;
}

int getElementsByRNTI(int RNTI) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < nfaListSize; i++) {
        if (nfaList[i].RNTI == RNTI) {
