typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* nfaapi_crc_indication_pdu_pool = NULL;
int pool_size = 0;
int used_pool_size = 0;

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int RNTI) {
    if (!nfaapi_crc_indication_pdu_pool || used_pool_size >= pool_size) {
        // Reallocate the memory pool if it's full or not initialized
        free(nfaapi_crc_indication_pdu_pool);
        nfaapi_crc_indication_pdu_pool = malloc(POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool_size = POOL_SIZE;
        used_pool_size = 0;
    }

    // Find an existing PDU with the same RNTI and update it instead of creating a new one
    for (int i = 0; i < used_pool_size; i++) {
        if (nfaapi_crc_indication_pdu_pool[i].RNTI == RNTI) {
            return &nfaapi_crc_indication_pdu_pool[i];
        }
    }

    // Create a new PDU
    NFAPI_CRC_INDICATION_PDU_T* pdu = &nfaapi_crc_indication_pdu_pool[used_pool_size];
    used_pool_size++;
    pdu->RX_UE_INFORMATION_TAG = 0;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 1000000;
    pdu->CRCFLAG = (rand() & 1) ? 1 : 0;
    return pdu;
}

void iterate_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, int direction) {
    for (int i = 0; i < used_pool_size; i++) {
        // Use the modulo operator to handle circular iteration
        int index = (direction == 1) ? i : used_pool_size - 1 - i;
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               array[index].RX_UE_INFORMATION_TAG, array[index].RNTI,
               array[index].CRC_INDICATION_REL8_TAG, array[index].CRCFLAG);
    }
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = create_pdu(1);

    // Example usage: Iterate through the PDU array in both directions
    iterate_pdu_array(pdu_array, 1); // Forward direction
    iterate_pdu_array(pdu_array, -1); // Reverse direction

    free(nfaapi_crc_indication_pdu_pool);
    return 0;
}
