#include <stdio.h>
#include <stdlib.h>

// Define the LTE PHY Layer Configuration Structure
typedef struct {
    int cell_id;
    char frequency_band[16];
    int bandwidth;
} ConfigStruct;

// Dynamic array of configuration structures
typedef struct {
    ConfigStruct* configs;
    int size;
    int capacity;
} ConfigArray;

// Function to create a new config array with initial capacity
ConfigArray* create_config_array(int capacity) {
    ConfigArray* arr = (ConfigArray*)malloc(sizeof(ConfigArray));
    arr->configs = (ConfigStruct*)malloc(capacity * sizeof(ConfigStruct));
    arr->size = 0;
    arr->capacity = capacity;
    return arr;
}

// Function to add a new configuration to the array
void add_config(ConfigArray* arr, ConfigStruct config) {
    if (arr->size >= arr->capacity) {
        // Double the capacity when full
        arr->configs = (ConfigStruct*)realloc(arr->configs, 2 * arr->capacity * sizeof(ConfigStruct));
        arr->capacity *= 2;
    }
    arr->configs[arr->size++] = config;
}

// Function to remove a configuration from the array
void remove_config(ConfigArray* arr, int cell_id) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->configs[i].cell_id == cell_id) {
            // Shift remaining configurations to fill the gap
            memmove(&arr->configs[i], &arr->configs[i + 1], (arr->size - i - 1) * sizeof(ConfigStruct));
            arr->size--;
            return;
        }
    }
}

// Function to retrieve a configuration by cell ID
ConfigStruct* get_config_by_cell_id(ConfigArray* arr, int cell_id) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->configs[i].cell_id == cell_id)
            return &arr->configs[i];
    }
    return NULL;
}

// Function to iterate through configurations by frequency band
void foreach_config_by_frequency_band(ConfigArray* arr, void (*callback)(ConfigStruct*)) {
    for (int i = 0; i < arr->size; i++) {
        callback(arr->configs[i]);
    }
}

// Function to free the config array and its contents
void destroy_config_array(ConfigArray* arr) {
    if (arr != NULL) {
        free(arr->configs);
        free(arr);
    }
}
