NFAPI_CRC_INDICATION_PDU_T* create_list(int n, pthread_mutex_t* mutex) {
    int i, N = 1; // N is configurable parameter
    while (n > MAX_BUFFER_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        N *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(N * sizeof(NFAPI_CRC_INDATION_PDU_T));
    if (!list) {
        for (i = 0; i < 3; ++i) {
            pthread_mutex_lock(mutex);
            sleep(2 * (1 << i)); // exponential backoff
            free(list); // release any partially allocated memory
            list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!list) {
                break;
            }
            pthread_mutex_unlock(mutex);
        }
        if (!list) {
            return NULL; // failed to allocate after 3 retries
        }
    }
    for (i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        list[i].RNTI = rand() % 1000;
        list[i].CRCFLAG = rand() % 2; // randomly set CRCFLAG
    }
    return list;
}
