#include <time.h>
#include <pthread.h>

#define MAX_NFAPI_CRC_INDICATION_PDU_T 1000
#define MAX_ARRAY_SIZE 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCIndicationPDUArray(int numElements) {
    if (numElements > MAX_NFAPI_CRC_INDICATION_PDU_T) {
        return NULL; // Limit exceeded
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < numElements; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = rand() % 256;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 100;

        printf("Created structure: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n", array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG);
    }

    return array;
}

void findLargestInteger(int* array, int numElements) {
    if (numElements <= 0) {
        return; // Empty or invalid array
    }

    int largest = array[0];

    for (int i = 1; i < numElements; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

int main() {
    int maxStructures = MAX_NFAPI_CRC_INDICATION_PDU_T;
    NFAPI_CRC_INDICATION_PDU_T* nfapiArray = createNFAPICRCIndicationPDUArray(maxStructures);

    if (!nfapiArray) {
        printf("Error creating NFAPICRCIndicationPDU array\n");
        return -1; // Error occurred
    }

    int maxArraySize = MAX_ARRAY_SIZE;
    int* array = (int*)malloc(maxArraySize * sizeof(int));

    if (!array) {
        printf("Error allocating memory for array\n");
        free(nfapiArray);
        return -1; // Memory allocation failed
    }

    int numElements = 0;

    while (numElements < maxArraySize && scanf("%d", &array[numElements]) == 1) {
        numElements++;
    }

    findLargestInteger(array, numElements);

    free(nfapiArray);
    free(array);

    return 0; // Success
