#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int RX_UE_CONFIGURATION_TAG;
    int RRC_CONNECTION_TAG;
    int PROCESSING_DELAY_STATS;
} LTE_PHY_RX_FRAME_INFO_T;

typedef struct node {
    LTE_PHY_RX_FRAME_INFO_T data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initList() {
    for (int i = 0; i < 10; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            printf("Memory error\n");
            return;
        }
        newNode->data.RX_UE_INFORMATION_TAG = rand();
        newNode->data.RNTI = rand();
        newNode->data.CRC_INDICATION_REL8_TAG = rand();
        newNode->data.RX_UE_CONFIGURATION_TAG = rand();
        newNode->data.RRC_CONNECTION_TAG = rand();
        newNode->data.PROCESSING_DELAY_STATS = rand();
        newNode->next = head;
        pthread_mutex_lock(&lock);
        if (head) {
            Node* temp = head;
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = newNode;
        } else {
            head = newNode;
        }
        pthread_mutex_unlock(&lock);
    }
}

void* threadFunction(void* arg) {
    for (int i = 0; i < 10; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            printf("Memory error\n");
            return NULL;
        }
        node->data.RX_UE_INFORMATION_TAG = rand();
        node->data.RNTI = rand();
        node->data.CRC_INDICATION_REL8_TAG = rand();
        node->data.RX_UE_CONFIGURATION_TAG = rand();
        node->data.RRC_CONNECTION_TAG = rand();
        node->data.PROCESSING_DELAY_STATS = rand();
        pthread_mutex_lock(&lock);
        if (head) {
            Node* temp = head;
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = node;
        } else {
            head = node;
        }
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void printList() {
    Node* temp = head;
    while (temp) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, RX_UE_CONFIGURATION_TAG: %d, RRC_CONNECTION_TAG: %d, PROCESSING_DELAY_STATS: %d\n",
               temp->data.RX_UE_INFORMATION_TAG, temp->data.RNTI, temp->data.CRC_INDICATION_REL8_TAG,
               temp->data.RX_UE_CONFIGURATION_TAG, temp->data.RRC_CONNECTION_TAG, temp->data.PROCESSING_DELAY_STATS);
        temp = temp->next;
    }
}

int main() {
    pthread_t thread[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&thread[i], NULL, threadFunction, NULL);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(thread[i], NULL);
    }
    printList();
    return 0;
}
