struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

void free_list(struct Node** head) {
    struct Node* current = *head;
    struct Node* next_temp;

    while (current != NULL) {
        next_temp = current->next;
        free(current);
        current = next_temp;
    }
    *head = NULL;
}

struct Node* reverse_list(struct Node** head_ref) {
    struct Node* prev = NULL;
    struct Node* current = *head_ref;
    struct Node* next = NULL;

    while (current != NULL) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
    *head_ref = prev;
    return *head_ref;
}

int main() {
