        struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
        new_node->data = data;
        new_node->next = head;
        head = new_node;
    }

    // Reverse the list
    head = reverse_list(&head);

    // Free the list
    free_list(&head);

    return 0;
}
