#define MAX_CIFG_LIM 255
#define TAG_LIM 256

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfa_api_crc_indication_pdu_array = NULL;
pthread_mutex_t nfa_api_crc_indication_pdu_array_lock = PTHREAD_MUTEX_INITIALIZER;
int array_size = 0;
int current_tag = 1;

void init_nfa_api_crc_indication_pdu_array(int size) {
    if (size > MAX_ELEMENT_COUNT) {
        printf("Array size exceeds maximum limit.\n");
        return;
    }
    nfa_api_crc_indication_pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < size; i++) {
        pthread_mutex_lock(&nfa_api_crc_indication_pdu_array_lock);
        nfa_api_crc_indication_pdu_array[i].RX_UE_INFORMATION_TAG = current_tag++;
        nfa_api_crc_indication_pdu_array[i].RNTI = i;
        nfa_api_crc_indication_pdu_array[i].CRC_INDICATION_REL8_TAG = i;
        if (rand() % (MAX_CIFG_LIM - MIN_CIFG_LIM + 1) + MIN_CIFG_LIM == 0)
            nfa_api_crc_indication_pdu_array[i].CRCFLAG = rand() % TAG_LIM;
        else
            nfa_api_crc_indication_pdu_array[i].CRCFLAG = rand() % (TAG_LIM - 1);
        pthread_mutex_unlock(&nfa_api_crc_indation_pdu_array_lock);
    }
    array_size = size;
}

void add_element(NFAPI_CRC_INDICATION_PDU_T *new_element) {
    if (!nfa_api_crc_indication_pdu_array || array_size >= MAX_ELEMENT_COUNT) {
        printf("Array is full or not initialized.\n");
        return;
    }
    pthread_mutex_lock(&nfa_api_crc_indication_pdu_array_lock);
    nfa_api_crc_indication_pdu_array[array_size] = *new_element;
    array_size++;
    pthread_mutex_unlock(&nfa_api_crc_indation_pdu_array_lock);
}

void remove_element(int index) {
    if (!nfa_api_crc_indication_pdu_array || index >= array_size) {
        printf("Index out of bounds or array is empty.\n");
        return;
    }
    pthread_mutex_lock(&nfa_api_crc_indication_pdu_array_lock);
    for (int i = index; i < array_size - 1; i++) {
        nfa_api_crc_indication_pdu_array[i] = nfa_api_crc_indication_pdu_array[i + 1];
    }
    free(nfa_api_crc_indication_pdu_array[--array_size]);
    pthread_mutex_unlock(&nfa_api_crc_indation_pdu_array_lock);
}

void update_element(int index, NFAPI_CRC_INDICATION_PDU_T *new_element) {
    if (!nfa_api_crc_indication_pdu_array || index >= array_size) {
        printf("Index out of bounds or array is empty.\n");
        return;
    }
    pthread_mutex_lock(&nfa_api_crc_indication_pdu_array_lock);
    nfa_api_crc_indication_pdu_array[index] = *new_element;
    pthread_mutex_unlock(&nfa_api_crc_indation_pdu_array_lock);
}

void* monitor_function(void* arg) {
    while (1) {
        for (int i = 0; i < array_size; i++) {
            if (rand() % TAG_LIM == nfa_api_crc_indication_pdu_array[i].CRCFLAG)
                printf("Anomaly detected at index %d.\n", i);
        }
        sleep(5); // adjust the interval as needed
    }
    return NULL;
}

int main() {
    pthread_t monitor_thread;

    init_nfa_api_crc_indication_pdu_array(MAX_ELEMENT_COUNT);

    if (pthread_create(&monitor_thread, NULL, monitor_function, NULL) != 0) {
        printf("Failed to create the monitoring thread.\n");
        return -1;
    }

    // add and remove elements from the array
    for (int i = 0; i < MAX_ELEMENT_COUNT / 2; i++) {
        NFAPI_CRC_INDICATION_PDU_T new_element;
        init_nfa_api_crc_indication_pdu_array(10);
        add_element(&new_element);
        sleep(1); // adjust the interval as needed
        remove_element(array_size - 1);
    }

    pthread_join(monitor_thread, NULL);

    return 0;
}
