            .frequency_start = 1000000 + i,
            .frequency_end = 1100000 + i,
            .modulation = modulation_type_GMSK,
            .channel_plan = channel_plan
        };

        (*config_ptr)[i] = entry;
    }

    return *config_ptr;
}

// Function to free the configuration array and its entries
void free_config(configuration_entry_t** config) {
    if (*config == NULL) {
        return;
    }

    for (int i = 0; i < num_entries; i++) {
        // Free each entry's channel plan
        free((*config)[i].channel_plan);
    }

    // Free the configuration array itself
    free(*config);
}

// Helper function to convert modulation type to string
const char* modulation_type_to_string(modulation_type_t modulation) {
