        case modulation_type_AM:
            return "AM";
        case modulation_type_FM:
            return "FM";
        case modulation_type_GMSK:
            return "GMSK";
        case modulation_type_OFDM:
            return "OFDM";
        default:
            return "Unknown";
    }
