#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <tiffio.h>
#include <openssl/md5.h>

typedef struct {
    int rnti;
    uint16_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    uint8_t* metadata;
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
} ImageInformation_T;

ImageInformation_T extract_image_info(const char* file_path) {
    TIFF *tif = TIFFOpen(file_path, "r");
    if (!tif) {
        // handle error
        return (ImageInformation_T){0};
    }

    uint32_t bits_per_sample = 0;
    uint16_t samples_per_pixel = 1;
    int extra_samples = 0;

    TIFFGetField(tif, TIFF_FIELD_BITSPERSAMPLE, &bits_per_sample);
    TIFFGetField(tif, TIFF_FIELD_SAMPLESPERPIXEL, &samples_per_pixel);

    // calculate CRCflag
    srand(time(NULL));
    uint16_t crcflag = rand() % (1 << 15);

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * samples_per_pixel);
    for (int i = 0; i < samples_per_pixel; i++) {
        pdus[i].rnti = rand() % (1 << 15);
        pdus[i].crcflag = crcflag;
    }

    unsigned char* metadata = malloc(TIFFDirectoryGetFieldCount(tif, 0) * sizeof(char));
    TIFFReadDirectory(tif, metadata);

    // calculate MD5 hash
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);
    MD5_Update(&md5_ctx, file_path, strlen(file_path));
    MD5_Final(md5_ctx.md5, metadata);

    ImageInformation_T info = (ImageInformation_T){
        .bits_per_sample = bits_per_sample,
        .samples_per_pixel = samples_per_pixel,
        .extra_samples = extra_samples,
        .metadata = metadata,
        .md5_hash = md5_ctx.md5
    };

    free(pdus);
    TIFFClose(tif);

    return info;
}
