NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int N, int* rntis) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(result == NULL) return NULL;

    for(int i = 0; i < N; i++) {
        int rnti;
        do {
            rnti = rand() % (10000); // Generate random RNTI
        } while(find_rnti(rntis, N, rnti)); // Check if RNTI is unique

        result[i].RX_UE_INFORMATION_TAG = i; // Set RX_UE_INFORMATION_TAG to the list index
        result[i].RNTI = rnti;
        result[i].CRCFLAG = rand() % (2); // Randomly set CRCFLAG
    }

    return result;
}

int find_rnti(int* rntis, int N, int target) {
    for(int i = 0; i < N; i++) {
        if(rntis[i] == target) {
            return 1; // RNTI found
        }
    }
    return 0; // RNTI not found
}

int main() {
    int N = 10; // Number of elements in the list
    int* rntis = (int*)malloc(N * sizeof(int)); // Dynamic array to store RNTIs

    for(int i = 0; i < N; i++) {
        rntis[i] = rand() % (10000); // Generate random RNTI
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = create_crc_indication_pdu(N, rntis);

    if(crc_indications == NULL) {
        printf("Memory allocation failed.\n");
