            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", crc_indications[i].RX_UE_INFORMATION_TAG, crc_indications[i].RNTI, crc_indications[i].CRCFLAG);
        }
    }

    free(rntis);
    free(crc_indications);

    return 0;
}
