const fs = require('fs').promises;
const path = require('path');
const { Transform } = require('stream');

function readFiles(directory, extension, {
  concurrency = 5,
  timeout = 5000,
  retryAttempts = 3,
  logService,
}) {
  const fileStream = new Transform({
    transform(chunk, encoding, callback) {
      const files = [];
      let i = 0;

      async function processFile() {
        try {
          while (i < concurrency) {
            const file = await fs.readdir(directory);
            if (!file.length) return;
            const filePath = path.join(directory, file.shift());
            if (path.extname(filePath) === `.${extension}`) {
              files.push(await fs.readFile(filePath, 'utf8'));
              i++;
            }
          }
        } catch (error) {
          logService.error('Error reading file:', error);
          await retryReadFile(filePath, timeout, retryAttempts);
        } finally {
          i = 0;
        }
      }

      processFile();

      callback(null, files.join('\n'));
    },
  });
}
