#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <stdint.h>
#include <openssl/sha256.h>

typedef struct {
    uint32_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char* filename;
    int num_channels;
    int bit_depth;
    int sample_rate;
    char* format;
} AudioInfoT;

typedef struct {
    AudioInfoT audio_info;
    SHA256_CTX ctx;
    uint8_t hash[SHA256_DIGEST_LENGTH];
} ExtractionResultT;

ExtractionResultT extract_audio_info(const char* filename) {
    // Initialize result structure
    ExtractionResultT result = {0};
    result.audio_info.filename = (char*)malloc(strlen(filename) + 1);
    strcpy(result.audio_info.filename, filename);

    // Initialize SHA256 context
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    // Open file and read header metadata
    FILE* file = fopen(filename, "rb");
    if (!file) {
        return (ExtractionResultT){.audio_info.filename = NULL};
    }

    // Read audio format information
    uint8_t format[4];
    fread(format, 1, 4, file);
    result.audio_info.format = (char*)malloc(5);
    sprintf(result.audio_info.format, "%c%c%c%c", format[0], format[1], format[2], format[3]);

    // Read number of channels
    uint16_t num_channels;
    fread(&num_channels, 1, 2, file);
    result.audio_info.num_channels = ntohs(num_channels);

    // Read bit depth
    uint8_t bit_depth;
    fread(&bit_depth, 1, 1, file);
    result.audio_info.bit_depth = bit_depth;

    // Read sample rate
    int32_t sample_rate;
    fread(&sample_rate, 1, 4, file);
    result.audio_info.sample_rate = ntohl(sample_rate);

    // Read CRC flag (assuming it's present)
    uint8_t crcflag;
    fread(&crcflag, 1, 1, file);

    // Close file
    fclose(file);

    // Calculate SHA256 hash of header metadata
    unsigned char* input = (unsigned char*)malloc(result.audio_info.num_channels * sizeof(unsigned char));
    fread(input, 1, result.audio_info.num_channels, file);
    SHA256_Update(&ctx, input, result.audio_info.num_channels);
    free(input);

    // Get hash
    SHA256_Final(result.hash, &ctx);

    // Generate NFAPI_CRC_INDICATION_PDU_T structures
    uint16_t pdu_count = 1; // assume one RX_UE_INFORMATION_TAG per audio file
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < pdu_count; i++) {
        pdus[i].rnti = 0x0001;
        pdus[i].crcflag = crcflag;
    }

    // Clean up
    free(result.audio_info.filename);
    SHA256_Free(&ctx);

    return result;
}
