function runIntegrationTests(endpoint, testCases, logger, retryConfig, cacheConfig) {
  const tests = testCases.map((testCase) => {
    const { label, testFn } = testCase;
    return async () => {
      try {
        await resetState();
        const response = await testFn();
        const isValid = validateResponse(response);
        if (!isValid) throw new Error(`Test ${label} failed`);
        logger.info(`Test ${label} passed`);
      } catch (error) {
        if (retryConfig.maxRetries > 0 && retryConfig.backoffStrategy(error)) {
          await sleep(retryConfig.initialBackoff);
          return runIntegrationTests(endpoint, testCases, logger, retryConfig, cacheConfig);
        }
        throw error;
      }
    };
  });

  const testResults = await Promise.all(tests.map((test) => test()));
  tests.forEach((_, i) => {
    const result = testResults[i];
    if (result instanceof Error) {
      logger.error(`Test ${testCases[i].label} failed: ${result.message}`);
    } else {
      logger.info(`Test ${testCases[i].label} passed`);
    }
  });

