typedef struct {
    int id;
    char* name;
} Peer;

typedef struct {
    int interfaceId;
    Peer** peers;
    int numPeers;
    int isConfigured;
} NetworkInterfaceConfig;

NetworkInterfaceConfig* createNetworkInterface(int interfaceId) {
    NetworkInterfaceConfig* config = (NetworkInterfaceConfig*)malloc(sizeof(NetworkInterfaceConfig));
    config->interfaceId = interfaceId;
    config->numPeers = 0;
    config->isConfigured = 0;
    return config;
}

void addPeer(NetworkInterfaceConfig* config, Peer* peer) {
    if(config->peers == NULL) {
        config->peers = (Peer**)malloc(sizeof(Peer*) * 2);
        config->numPeers = 1;
    } else if(config->numPeers >= sizeof(config->peers) / sizeof(config->peers[0])) {
        config->peers = (Peer**)realloc(config->peers, sizeof(Peer*) * (config->numPeers * 2));
    }
    config->peers[config->numPeers++] = peer;
}

int hasPeer(NetworkInterfaceConfig* config, int peerId) {
    for(int i = 0; i < config->numPeers; i++) {
        if(config->peers[i]->id == peerId) {
            return 1;
        }
    }
    return 0;
}

void updatePeer(NetworkInterfaceConfig* config, int peerId, Peer* updatedPeer) {
    for(int i = 0; i < config->numPeers; i++) {
        if(config->peers[i]->id == peerId) {
            memcpy(config->peers[i], updatedPeer, sizeof(Peer));
            return;
        }
    }
}

void configureInterface(NetworkInterfaceConfig* config) {
    config->isConfigured = 1;
}

void freeNetworkInterface(NetworkInterfaceConfig* config) {
    for(int i = 0; i < config->numPeers; i++) {
        free(config->peers[i]->name);
        free(config->peers[i]);
    }
    free(config->peers);
    free(config);
}
