#include <string.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define CRCFLAG_MAX_LENGTH 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[CRCFLAG_MAX_LENGTH];
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* head = NULL;
int list_size = 0;

void print_list(NFAPI_CRC_INDICATION_PDU_T* current) {
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %s, CRCFLAG: %s\n",
               current->RX_UE_INFORMATION_TAG, current->RNTI,
               current->CRC_INDICATION_REL8_TAG, (current->CRCFLAG ? "True" : "False"));
        current = current->next;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, char* CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    strcpy(new_node->CRC_INDICATION_REL8_TAG, CRC_INDICATION_REL8_TAG);
    new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    return new_node;
}

void add_node(NFAPI_CRC_INDICATION_PDU_T* new_node) {
    pthread_mutex_lock(&list_lock);

    if (head == NULL || new_node->RNTI > head->RNTI) {
        if (head != NULL) {
            new_node->next = head;
            head->prev = new_node;
        } else {
            head = new_node;
        }
    } else if (new_node->RNTI < head->RNTI) {
        NFAPI_CRC_INDICATION_PDU_T* current = head;
        while (current->next != NULL && current->next->RNTI > new_node->RNTI) {
            current = current->next;
        }
        if (new_node->RNTI < current->RNTI) {
            new_node->next = current;
            new_node->prev = current->prev;
            current->prev = new_node;
            if (current == head) {
                head = new_node;
            } else {
                current->prev->next = new_node;
            }
        }
    }

    list_size++;
    pthread_mutex_unlock(&list_lock);
}

void serialize_list(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list_lock);

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        fwrite(&current->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fwrite(&current->RNTI, sizeof(int), 1, file);
        fwrite(current->CRC_INDICATION_REL8_TAG, strlen(current->CRC_INDICATION_REL8_TAG) + 1, 1, file);
        fwrite(&current->CRCFLAG, sizeof(bool), 1, file);

        current = current->next;
    }

    pthread_mutex_unlock(&list_lock);
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* new_head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[CRCFLAG_MAX_LENGTH];
    bool CRCFLAG;

    while (fread(&RX_UE_INFORMATION_TAG, sizeof(int), 1, file) == 1 &&
           fread(&RNTI, sizeof(int), 1, file) == 1 &&
           fread(CRC_INDICATION_REL8_TAG, strlen(CRC_INDICATION_REL8_TAG) + 1, 1, file) == 1 &&
           fread(&CRCFLAG, sizeof(bool), 1, file) == 1) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
        if (!new_node) break;

        if (new_head == NULL) {
            new_head = new_node;
            current = new_head;
        } else {
            current->next = new_node;
            new_node->prev = current;
            current = current->next;
        }
    }

    fclose(file);
    return new_head;
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* node1 = create_node(123, 456, "CRCFLAG_VALUE_1");
    NFAPI_CRC_INDICATION_PDU_T* node2 = create_node(789, 901, "CRCFLAG_VALUE_2");

    add_node(node1);
    add_node(node2);

    print_list(head);

    serialize_list("list.dat");

    NFAPI_CRC_INDICATION_PDU_T* deserialized_head = deserialize_list("list.dat");

    if (deserialized_head) {
        print_list(deserialized_head);
        free(deserialized_head);
    }

    return 0;
}
