// Memory pool management strategy
void *malloc_or_die(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

int nfaapi_crc_indication_pdu_t_array_manager(int* array, int* size, NFAPI_CRC_INDICATION_PDU_T** pdu_array) {
    // Initialize an empty array if it doesn't exist
    if (!array || !(*size)) {
        *array = 0;
        *pdu_array = NULL;
    }

    // Calculate the maximum number of elements that can be added without reallocation
    int max_elements = *size - 1;

    while (true) {
        NFAPI_CRC_INDICATION_PDU_T* pdu;
        if (!(*size)) {
            pdu = malloc_or_die(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            (*pdu_array) = &pdu;
        } else {
            // Dynamically allocate memory for the next element
            pdu = realloc((*pdu_array), (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu) {
                fprintf(stderr, "Memory reallocation failed\n");
                exit(1);
            }
            (*pdu_array) = &pdu;
        }

        // Initialize the next element with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
