            if (!i || rand() % 2) {  // Ensure no two adjacent elements have the same CRCFLAG
                pdu[i].RX_UE_INFORMATION_TAG = i;
                pdu[i].RNTI = i + 1;
                pdu[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256;  // Randomly set CRCFLAG within specified limits
            } else {
                pdu[i].RX_UE_INFORMATION_TAG = i - 1;
                pdu[i].RNTI = i;
                pdu[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 255;  // Ensure no two adjacent elements have the same CRCFLAG
            }
        }

        (*size)++;
    }
}

