class SensorDataRecord {
public:
    int sensorId;
    long timestamp;
    double measurementValue;
    bool operationalStatus;

    SensorDataRecord(int id, long ts, double value, bool status) : 
        sensorId(id), timestamp(ts), measurementValue(value), operationalStatus(status) {}
};

class SensorDataComponent {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<SensorDataRecord> records;
    std::map<int, size_t> cache;
    std::ofstream diskFile;

public:
    SensorDataComponent(const std::string& filename) : 
        diskFile(filename, std::ios::binary | std::ios::app) {}

    void addRecord(SensorDataRecord record) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            records.push_back(record);
        }
        cv.notify_one();
    }

    SensorDataRecord getRecord(int sensorId) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            if (cache.count(sensorId)) {
                return records[cache.at(sensorId)];
            } else {
                // disk-based persistence
                diskFile.seekp(0, std::ios::end);
                int offset = diskFile.tellg();
                diskFile.write(reinterpret_cast<char*>(&record), sizeof(record));
                cache[sensorId] = offset / sizeof(record);
                return record;
            }
        }
    }

    void processRecords() {
        while (true) {
            SensorDataRecord record;
            {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this]{return !records.empty();});
                record = records.back();
                records.pop_back();
            }
            // send to external data processing service
            // ...
        }
    }

    void logChanges() {
        while (true) {
            SensorDataRecord record;
            {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this]{return !records.empty();});
                record = records.back();
                records.pop_back();
                // write to disk or send to logging service
                // ...
            }
        }
    }
};

int main() {
    SensorDataComponent component("data.bin");
    std::thread processThread(&SensorDataComponent::processRecords, &component);
    std::thread logThread(&SensorDataComponent::logChanges, &component);

    return 0;
}
