void init_ue_contexts(int num_ue, UEContext** ue_contexts) {
    pthread_setenv("LOG_LEVEL", "DEBUG"); // Set log level to debug

    if (num_ue > MAX_UE_CONTEXTS) {
        printf("Error: Maximum number of UE contexts exceeded.\n");
        return;
    }

    *ue_contexts = (UEContext*) malloc(num_ue * sizeof(UEContext));

    for (int i = 0; i < num_ue; i++) {
        UEContext* ue_ctx = &((*ue_contexts)[i]);
        ue_ctx->ueId = i + 1;
        ue_ctx->measurements = (MeasurementReport*) aligned_alloc(CACHE_LINE_SIZE, num_ue * sizeof(MeasurementReport));
        for (int j = 0; j < num_ue; j++) {
            MeasurementReport* measurement = &((*ue_ctx->measurements)[j]);
            measurement->measurementId = i + j;
            measurement->signalStrength = (double) rand() / RAND_MAX;
        }
        ue_ctx->parameters.numAntennas = 4;
        ue_ctx->parameters.frequencyGHz = 28.0;
    }
}
