#define MAX_POOL_SIZE 10000
#define MAX_ATTRIBUTES 20
#define MAX_ATTRIBUTE_LENGTH 50

typedef struct NFAPI_CELL_INFO_PDU_T {
    int CELL_ID;
    int PCI;
    char BANDWIDTH[MAX_ATTRIBUTE_LENGTH];
} NFAPI_CELL_INFO_PDU_T;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CELL_INFO_PDU_T* cell_info_pool = NULL;
int pool_size = 0;

void init_cell_info_pool() {
    if (cell_info_pool != NULL) {
        return; // Pool already initialized
    }

    pthread_mutex_init(&pool_lock, NULL);

    cell_info_pool = (NFAPI_CELL_INFO_PDU_T*)malloc(MAX_POOL_SIZE * sizeof(NFAPI_CELL_INFO_PDU_T));
    pool_size = 0;

    if (cell_info_pool == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
}

void update_cell_info_pool(int CELL_ID, int PCI, const char* BANDWIDTH) {
    pthread_mutex_lock(&pool_lock);

    NFAPI_CELL_INFO_PDU_T* new_cell_info = (NFAPI_CELL_INFO_PDU_T*)malloc(sizeof(NFAPI_CELL_INFO_PDU_T));

    if (new_cell_info == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&pool_lock);
        return;
    }

    new_cell_info->CELL_ID = CELL_ID;
    new_cell_info->PCI = PCI;
    strncpy(new_cell_info->BANDWIDTH, BANDWIDTH, MAX_ATTRIBUTE_LENGTH);

    if (pool_size < MAX_POOL_SIZE) {
        cell_info_pool[pool_size] = *new_cell_info;
        pool_size++;
    } else {
        // Handle overflow
        fprintf(stderr, "Pool overflow. Unable to add new cell configuration.\n");
    }

    free(new_cell_info);
    pthread_mutex_unlock(&pool_lock);
}

void print_cell_info_pool() {
    pthread_mutex_lock(&pool_lock);

    for (int i = 0; i < pool_size; i++) {
        printf("CELL_ID: %d, PCI: %d, BANDWIDTH: %s\n", cell_info_pool[i].CELL_ID, cell_info_pool[i].PCI, cell_info_pool[i].BANDWIDTH);
    }

    pthread_mutex_unlock(&pool_lock);
}

void* update_cell_info_thread(void* arg) {
    // Simulate receiving updates from external sources
    for (int i = 0; i < 50; i++) {
        int CELL_ID = rand() % 10000;
        int PCI = rand() % 8;
        char BANDWIDTH[MAX_ATTRIBUTE_LENGTH];
        sprintf(BANDWIDTH, "Bandwidth-%d", rand() % 5);

        update_cell_info_pool(CELL_ID, PCI, BANDWIDTH);
    }

    return NULL;
}

int main() {
    init_cell_info_pool();

    pthread_t threads[10];

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, update_cell_info_thread, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    print_cell_info_pool();

    return 0;
}
