void* initializeAndFilterTransactions(void* params) {
    Parameters* p = (Parameters*)params;
    UEContext** contexts = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int total_entries = 0;

    // Initialize dynamic array
    contexts = (UEContext**)malloc(sizeof(UEContext*) * 100);

    // Initialize and fill context entries
    for(int i=0; i<10; i++) {
        UEContext* context = (UEContext*)malloc(sizeof(UEContext));
        context->ueId = i;
        // Fill MeasurementReport entries
        // Fill Parameters configuration
        contexts[total_entries] = context;
        total_entries++;
    }

    pthread_mutex_init(&lock, NULL);

    for(int i=0; i<total_entries; i++) {
        UEContext* context = contexts[i];
        pthread_mutex_lock(&lock);

        // Filter transactions based on criteria
        int recent_count = 0;
        double weighted_sum = 0.0;
        for(int j=0; j<5; j++) {
            MeasurementReport* report = &context->measurement_reports[j];
            if(report->id < p->threshold_age) {
                recent_count++;
                weighted_sum += report->value * p->weight_age;
            } else {
                weighted_sum += report->value * p->weight_recent;
            }
        }

        pthread_mutex_unlock(&lock);

        // Update set of metrics and return maximum weighted sum along with corresponding transaction ID
    }

    free(contexts);
    return NULL;
}

int main() {
    Parameters params = {10, 5, 0.8, 0.2};
    pthread_t thread;
    pthread_create(&thread, NULL, initializeAndFilterTransactions, &params);
    pthread_join(thread, NULL);
    return 0;
}
