    }

    trafficFlows = (TrafficFlow*)realloc(trafficFlows, sizeof(TrafficFlow) * numFlows);
    if (trafficFlows == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < numFlows; i++) {
        trafficFlows[i] = newFlow;
        free(newFlow);
    }

    return trafficFlows;
}
