    RAND_bytes(key, sizeof(key));

    // Encrypt each node in the linked list
    while (current) {
        EVP_CIPHER_CTX_init(ctx);
        ctx->cipher = EVP_aes_256_cbc();
        ctx->init_key = key;
        ctx->init_iv = iv;
        len = strlen((char*)current->ue_info.data);

