        unsigned char* encrypted_data = malloc(len + 16);
        int out_len;
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, encrypted_data, &out_len, current->ue_info.data, len);

        // Store the encrypted data in the node
        free(current->ue_info.data);
        current->ue_info.data = encrypted_data;

        current = current->next;
    }

    EVP_CIPHER_CTX_cleanup(ctx);
}

int main() {
    int n = 10; // Change this to your desired linked list size
    NFAPI_CRC_INDICATION_PDU_T* head = generate_linked_list(n);
