int resolveHostname(const char* hostname, uint8_t buffer[4]) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) return -1;

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(53);
    inet_pton(AF_INET, "8.8.8.8", &server_addr.sin_addr);

    int rc = connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (rc < 0) {
        close(sockfd);
        return -1;
    }

    uint8_t buffer[4];
    sendto(sockfd, hostname, strlen(hostname), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));

    recvfrom(sockfd, buffer, 4, 0, NULL, NULL);

    close(sockfd);

    if (inet_pton(AF_INET, buffer, &server_addr.sin_addr) != 1) {
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        buffer[i] = server_addr.sin_addr.s_addr >> (8 * 3);
    }

    return 0;
}

