#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_SIZE 1024
#define CRCFLAG_MAX_VALUE 0xFF

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

typedef struct {
    LinkedListNode* head;
    int size;
    pthread_mutex_t mutex;
} LinkedList;

void list_init(LinkedList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int list_insert(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    LinkedListNode* new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!new_node) return -1;

    new_node->data = *data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_SIZE) {
        fprintf(stderr, "List exceeded maximum size of %d entries\n", MAX_SIZE);
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    if (!list->head) {
        list->head = new_node;
    } else {
        LinkedListNode* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void list_reset(LinkedList* list) {
    LinkedListNode* temp = NULL;
    LinkedListNode* current = list->head;

    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->size = 0;
}

void* list_traverse(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    LinkedListNode* current = list->head;

    while (current) {
        callback(current->data);
        current = current->next;
    }

    return NULL;
}
