// Function to resolve a list of hostnames asynchronously
int async_dns_resolution(size_t num_hosts, char** hosts, u_char* resolved_ips) {
    int sockfd;
    struct sockaddr_in serv_addr;
    char buffer[256];
    pthread_t thread;

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Set up DNS server
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(53);
    inet_pton(AF_INET, "8.8.8.8", &serv_addr.sin_addr);

    for (size_t i = 0; i < num_hosts; i++) {
        // Resolve hostname
        sendto(sockfd, hosts[i], strlen(hosts[i]), 0, (struct sockaddr*)&serv_addr, sizeof(serv_addr));

        // Handle DNS resolution error
        if (recv(sockfd, buffer, 256, 0) < 0) {
            perror("DNS resolution failed");
            return -1;
        }

        // Store resolved IP address in u_char array
        resolved_ips[i] = (u_char*)buffer;
    }

    // Close socket
    close(sockfd);

    return 0;
}

// Function to handle DNS caching and concurrent access
void* dns_cache_thread(void* arg) {
    pthread_mutex_lock(&mutex); // Acquire lock for cache operations

    // Cache DNS resolutions and reuse them for subsequent requests
    u_char* cached_ips = (u_char*)malloc(num_hosts * sizeof(u_char));

    for (size_t i = 0; i < num_hosts; i++) {
        // Retrieve resolved IP address from cache
        if (cached_ips[i] != NULL) {
            continue;
        }

        // Perform DNS resolution and store in cache
        sendto(sockfd, hosts[i], strlen(hosts[i]), 0, (struct sockaddr*)&serv_addr, sizeof(serv_addr));

        // Handle DNS resolution error
        if (recv(sockfd, buffer, 256, 0) < 0) {
            perror("DNS resolution failed");
            return NULL;
        }

        // Store resolved IP address in cache
        cached_ips[i] = (u_char*)buffer;
    }

    pthread_mutex_unlock(&mutex); // Release lock for cache operations

    return cached_ips;
}

