    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_list(int num_structures) {
    // Initialize the list with NULL pointers
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the lock for thread-safe operations
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Generate unique RNTIs and populate the list
    for (int i = 0; i < num_structures; i++) {
        int rnti = -1;
        while (rnti <= 0 || (pthread_mutex_lock(&lock) != 0)) {
            rnti = rand() % INT_MAX;
        }

        // Check for uniqueness
        bool unique = true;
        for (int j = 0; j < i; j++) {
            if (list[j].RNTI == rnti) {
                unique = false;
                break;
            }
        }

        // If not unique, try again
        while (!unique) {
            rnti = rand() % INT_MAX;
            for (int j = 0; j < i; j++) {
                if (list[j].RNTI == rnti) {
                    unique = false;
                    break;
                }
            }
        }

        // Fill the structure
        list[i].RX_UE_INFORMATION_TAG = rand() % INT_MAX;
        list[i].RNTI = rnti;
        list[i].CRC_INDICATION_REL8_TAG = rand() % INT_MAX;
        list[i].CRCFLAG = (rand() & 1) ? 0 : 1;

        // Release the lock
        pthread_mutex_unlock(&lock);
    }

    return list;
}

int main(int argc, char const* argv[]) {
    int num_structures = 10000; // Adjust this value as needed

    NFAPI_CRC_INDICATION_PDU_T* list = generate_list(num_structures);

    // Log the generated list
