    for (int i = 0; i < num_structures; i++) {
        printf("(RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d)\n",
               list[i].RX_UE_INFORMATION_TAG,
               list[i].RNTI,
               list[i].CRC_INDICATION_REL8_TAG,
               list[i].CRCFLAG);
    }

    // Free the memory
    free(list);

    return 0;
}
