typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *populate_nfa_pi_crc_indication_pdu(int num_entries) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int last_used_rnti = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < num_entries; i++) {
        pthread_mutex_lock(&mutex);
        while (true) {
            int rnti = (last_used_rnti + 1) % RNTI_SPACE;
            if (i % BATCH_SIZE == 0) {
                for (int j = 0; j < BATCH_SIZE && j <= i; j++) {
                    pdu_list[j].RNTI = (uint16_t)rnti++;
                }
                last_used_rnti = rnti - 1;
            } else {
                pdu_list[i].RNTI = (uint16_t)rnti++;
                if (++rnti % RNTI_SPACE == 0) {
                    last_used_rnti = rnti - 1;
                }
            }
            pthread_mutex_unlock(&mutex);
        }
    }
    for (int i = 0; i < num_entries; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = (uint32_t)i;
        pdu_list[i].CRC_INDICATION_REL8_TAG = (uint8_t)(i % 256);
        if (rand() & 1) {
            pdu_list[i].CRCFLAG = 0x01;
        } else {
            pdu_list[i].CRCFLAG = 0x02;
        }
    }
    return pdu_list;
}
