#include <stdlib.h>
#include <stdio.h>

#define MAX_DCI_LENGTH 100
#define MAX_MEMORY_USAGE 0.8
#define CQI_UPDATE_BATCH 10

typedef struct {
    int pci;
    int cqi;
} dci_message;

void *dci_pool = NULL;
size_t dci_pool_size = 0;
size_t total_memory_usage = 0;

pthread_mutex_t dcimutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t dcicond = PTHREAD_COND_INITIALIZER;

void *add_dci_message(int pci, int cqi);
int update_cqi_range(int start_pci, int end_pci, int new_cqi);
dci_message* get_dci_message(int pci);
void clean_dci_messages(int start_pci, int end_pci);

void init_dci_pool(size_t pool_size) {
    dci_pool = malloc(pool_size);
    dci_pool_size = pool_size;
}

int is_dci_pool_full() {
    return total_memory_usage + MAX_DCI_LENGTH > pool_size * (1 - MAX_MEMORY_USAGE);
}

dci_message* add_dci_message(int pci, int cqi) {
    pthread_mutex_lock(&dcimutex);

    if (is_dci_pool_full()) {
        // Dynamically expand memory
        size_t new_pool_size = dci_pool_size + (size_t)(pool_size * MAX_MEMORY_USAGE);
        void* new_pool = realloc(dci_pool, new_pool_size);
        if (!new_pool) {
            // Handle allocation failure gracefully
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&dcimutex);
            return NULL;
        }
        dci_pool_size = new_pool_size;
    }

    // Allocate memory for the new DCI message
    size_t offset = total_memory_usage;
    void* new_message = malloc(MAX_DCI_LENGTH);
    if (!new_message) {
        // Handle allocation failure gracefully
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&dcimutex);
        return NULL;
    }

    dci_message* message = (dci_message*)new_message;
    message->pci = pci;
    message->cqi = cqi;

    total_memory_usage += MAX_DCI_LENGTH;
    pthread_cond_signal(&dcicond);

    pthread_mutex_unlock(&dcimutex);
    return message;
}

int update_cqi_range(int start_pci, int end_pci, int new_cqi) {
    pthread_mutex_lock(&dcimutex);

    for (int pci = start_pci; pci <= end_pci; pci++) {
        dci_message* message = get_dci_message(pci);
        if (message) {
            message->cqi = new_cqi;
        }
    }

    pthread_mutex_unlock(&dcimutex);
    return 0;
}

dci_message* get_dci_message(int pci) {
    pthread_mutex_lock(&dcimutex);

    for (size_t i = 0; i < total_memory_usage / MAX_DCI_LENGTH; i++) {
        dci_message* message = (dci_message*) ((char*)dci_pool + i * MAX_DCI_LENGTH);
        if (message->pci == pci) {
            pthread_mutex_unlock(&dcimutex);
            return message;
        }
    }

    pthread_mutex_unlock(&dcimutex);
    return NULL;
}

void clean_dci_messages(int start_pci, int end_pci) {
    pthread_mutex_lock(&dcimutex);

    for (int pci = start_pci; pci >= end_pci; pci--) {
        dci_message* message = get_dci_message(pci);
        if (message) {
            // Free the memory
            free(message);
        }
    }

    pthread_mutex_unlock(&dcimutex);
}

void *thread_func(void *arg) {
    // Critical section: Perform thread-specific tasks
    pthread_mutex_lock(&dcimutex);

    // Signal to other threads that this slot is taken
    pthread_cond_signal(&dcicond);

    // Release the lock when leaving the critical section
    pthread_mutex_unlock(&dcimutex);

    return NULL;
}

int main() {
    init_dci_pool(1024 * 1024); // Initialize the memory pool

    // Create threads to demonstrate concurrent access control
    pthread_t thread[10];
    for (int i = 0; i < 10; i++) {
        int ret = pthread_create(&thread[i], NULL, thread_func, NULL);
        if (ret) {
            printf("Thread creation failed\n");
            return -1;
        }
    }

    // Example usage
    dci_message* message1 = add_dci_message(1, 10);
    dci_message* message2 = add_dci_message(2, 20);
    update_cqi_range(1, 2, 30);
    dci_message* message3 = get_dci_message(2);

    // Clean up unused messages
    clean_dci_messages(0, 2);

    for (int i = 0; i < 10; i++) {
        pthread_join(thread[i], NULL);
    }

    return 0;
}

