#define ERROR_CODE 1

typedef struct {
    int CHANNEL_ID;
    float RF_BANDWIDTH;
    float CENTER_FREQUENCY;
} PHY_CHANNEL_STATE_PDU_T;

int phy_channel_state_pdu_list_init(int *size, int **list) {
    *size = 0;
    *list = NULL;
    return 0;
}

void* phy_channel_state_pdu_create(pthread_mutex_t *mutex, int channel_id, float rf_bandwidth, float center_frequency, int **size, int **list) {
    PHY_CHANNEL_STATE_PDU_T *pdu;
    int error_code;

    pdu = (PHY_CHANNEL_STATE_PDU_T*) malloc(sizeof(PHY_CHANNEL_STATE_PDU_T));
    if (!pdu) {
        return NULL;
    }

    pdu->CHANNEL_ID = channel_id;
    pdu->RF_BANDWIDTH = rf_bandwidth;
    pdu->CENTER_FREQUENCY = center_frequency;

    pthread_mutex_lock(mutex);
    int new_size = *size + 1;
    if (new_size > MAX_CHANNEL_ID) {
        error_code = ERROR_CODE;
        goto free_pdu_and_return_error;
    }

    *list = realloc(*list, sizeof(PHY_CHANNEL_STATE_PDU_T*) * new_size);
    if (!*list) {
        error_code = ERROR_CODE;
        goto free_pdu_and_return_error;
    }

    (*list)[*size] = pdu;
    (*size)++;
    pthread_mutex_unlock(mutex);

    return pdu;

free_pdu_and_return_error:
    free(pdu);
    pthread_mutex_unlock(mutex);
    return (void*)error_code;
}

int phy_channel_state_pdu_list_finalize(int *size, int **list) {
    for (int i = 0; i < *size; i++) {
        free((*list)[i]);
    }
    free(*list);
    *size = 0;
    *list = NULL;
    return 0;
}

void phy_channel_state_pdu_log(const char* timestamp, int error_code) {
    printf(LOG_FORMAT, timestamp, error_code);
}
