#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node structure
typedef struct _node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _node* next;
} node_t;

// Define the linked list structure
typedef struct {
    node_t* head;
    pthread_mutex_t mutex;
} linked_list_t;

// Function to create a new linked list node with given data
static node_t* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    node_t* node = (node_t*)malloc(sizeof(node_t));
    if (!node) return NULL; // Allocation failed, return NULL

    node->data = data;
    node->next = NULL;

    return node;
}

// Function to add a new element to the linked list
int add_element(linked_list_t* list, NFAPI_CRC_INDICATION_PDU_T data) {
    node_t* new_node = create_node(data);

    if (!new_node) return -1; // Allocation failed, return error

    pthread_mutex_lock(&list->mutex);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Element added successfully
}

// Function to free the linked list
void free_list(linked_list_t* list) {
    node_t* current = list->head;
    node_t* next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);

    free(list);
}

// Function to manage the linked list
int manage_list(linked_list_t* list, int max_elements) {
    // Initialize the list if it's not already created
    if (!list->head) {
        list->head = NULL;
