#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the maximum number of elements in the list (10,000)
#define MAX_ELEMENTS 10000

// Define the maximum size of each element's data
#define ELEMENT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

// Define a structure to hold the linked list and its lock
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    pthread_mutex_t lock;
    int count;
} NFAPI_CRC_LIST;

// Function to initialize the linked list
NFAPI_CRC_LIST* nfaapi_crc_list_init() {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)malloc(sizeof(NFAPI_CRC_LIST));
    list->elements = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add an element to the linked list
void nfaapi_crc_list_add(NFAPI_CRC_LIST* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->lock);

    // Allocate memory for a new element if necessary
    if (list->count >= MAX_ELEMENTS) {
        printf("Error: List is full.\n");
        return;
    }

    element->next = NULL;

    // Add the element to the list
    if (list->elements == NULL) {
        list->elements = element;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = list->elements;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = element;
    }

    // Increment the count
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

// Function to free the linked list
void nfaapi_crc_list_free(NFAPI_CRC_LIST* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->elements;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    free(list);

    pthread_mutex_unlock(&list->lock);
}

// Function to validate the CRC flag
int nfaapi_crc_flag_validate(NFAPI_CRC_INDICATION_PDU_T* element) {
    // Validate the CRC flag against predefined valid states
    if (element->CRCFLAG == 0 || element->CRCFLAG == 1) {
        return 1;
    } else {
        return 0;
    }
}

// Function to process the linked list
void nfaapi_crc_list_process(NFAPI_CRC_LIST* list, int interval) {
    pthread_mutex_lock(&list->lock);

    // Process each element in the list
    NFAPI_CRC_INDICATION_PDU_T* current = list->elements;
    while (current != NULL) {
        // Validate the CRC flag
        if (nfaapi_crc_flag_validate(current)) {
            // Log the count of CRC-indicated UE instances
            printf("CRC-indicated UE instances: %d\n", list->count);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    // Update the log at the specified interval
    sleep(interval);
}

// Define the data processing pipeline function
void nfaapi_crc_data_pipeline(NFAPI_CRC_LIST* list, int interval) {
    while (1) {
        nfaapi_crc_list_process(list, interval);
    }
}

int main() {
    // Initialize the linked list
    NFAPI_CRC_LIST* list = nfaapi_crc_list_init();

    // Add elements to the list
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = malloc(ELEMENT_SIZE);
        // Initialize the CRC flag and other fields of the element
        element->CRCFLAG = 1;
        nfaapi_crc_list_add(list, element);
    }

    // Start the data processing pipeline
    pthread_t thread;
    pthread_create(&thread, NULL, (void*)nfaapi_crc_data_pipeline, list);

    return 0;
}
