#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[100];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* construct_NFAPI_CRC_INDICATION_PUDU(int N, char** TIFF_files) {
    NFAPI_CRC_INDICATION_PDU_T* NFAPDUs = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        NFAPDUs[i].RX_UE_INFORMATION_TAG = rand() % 100;
        NFAPDUs[i].RNTI = rand() % 10;

        char CRCFLAG[3];
        sprintf(CRCFLAG, "%c%c", (rand() % 2 ? '1' : '0'), (rand() % 2 ? '1' : '0'));
        strcpy(NFAPDUs[i].CRC_INDICATION_REL8_TAG, CRCFLAG);
    }

    return NFAPDUs;
}

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    char metadata[100];
} TIFF_IMAGE_INFO_T;

TIFF_IMAGE_INFO_T* extract_image_info(char* TIFF_file) {
    TIFF_IMAGE_INFO_T* image_info = (TIFF_IMAGE_INFO_T*)malloc(sizeof(TIFF_IMAGE_INFO_T));

    FILE* file = fopen(TIFF_file, "rb");

    if (!file) {
        printf("Error opening file %s.\n", TIFF_file);
        return NULL;
    }

    fseek(file, 0x02e, SEEK_SET);
    fread(&image_info->bits_per_sample, sizeof(int), 1, file);
    fread(&image_info->samples_per_pixel, sizeof(int), 1, file);
    fread(&image_info->extra_samples, sizeof(int), 1, file);

    char* buffer = (char*)malloc(100);
    fread(buffer, sizeof(char), 99, file);
    buffer[99] = '\0';
    strcpy(image_info->metadata, buffer);

    free(buffer);
    fclose(file);

    return image_info;
}

int main() {
    int N = 10; // Number of NFAPDUs to construct
    char* TIFF_files[] = {"image1.tiff", "image2.tiff", ...}; // List of TIFF files

    NFAPI_CRC_INDICATION_PDU_T* NFAPDUs = construct_NFAPI_CRC_INDICATION_PUDU(N, TIFF_files);

    for (int i = 0; i < N; i++) {
        printf("RX_UE_INFORMATION_TAG: %d\nRNTI: %d\nCRC_INDICATION_REL8_TAG: %s\n", 
               NFAPDUs[i].RX_UE_INFORMATION_TAG, NFAPDUs[i].RNTI, NFAPDUs[i].CRC_INDICATION_REL8_TAG);
    }

    for (int i = 0; i < N; i++) {
        TIFF_IMAGE_INFO_T* image_info = extract_image_info(TIFF_files[i]);

        if (!image_info) {
            continue;
        }

        printf("Image %d: bits_per_sample: %d, samples_per_pixel: %d, extra_samples: %d, metadata: %s\n", 
               i + 1, image_info->bits_per_sample, image_info->samples_per_pixel, image_info->extra_samples, image_info->metadata);

        free(image_info);
    }

    for (int i = 0; i < N; i++) {
        free(NFAPDUs[i].CRC_INDICATION_REL8_TAG);
    }

    free(NFAPDUs);

    return 0;
}
