// Function to populate the array with 'N' elements, ensuring no two elements share the same RNTI value
void nfapi_crc_indication_pdu_init(uint8_t* config_bitmask, int N, NFAPI_CRC_INDICATION_PDU_T** array) {
    // Initialize the array
    *array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (*array == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    uint16_t rnti_count[1 << 5] = {0};
    int i, j;

    for (i = 0; i < N; i++) {
        bool found = false;
        do {
            int rnti = rand() % (1 << 5);
            if (rnti_count[rnti] == 0) {
                found = true;
                break;
            }
