typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_indication_pdu_list(int num_elements) {
    int error_code = 0;
    int unique_rnti_count = 0;
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = NULL;
    FILE* log_file = fopen("crc_indication_pdu_log.txt", "w");

    if (num_elements > 1000) {
        error_code = 1;
        fprintf(log_file, "%s: Error creating list due to RNTI limit exceeded.\n", __func__);
        return error_code;
    }

    crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        error_code = 2;
        fprintf(log_file, "%s: Memory allocation failed.\n", __func__);
        return error_code;
    }

    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % 100;
        int rnti = rand() % 500;
        while (unique_rnti_count && find_rnti(crc_indications, unique_rnti_count - 1, rnti) >= 0) {
            rnti = rand() % 500;
        }
        crc_indications[i].RNTI = rnti;
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        if (rand() % 2) {
            crc_indications[i].CRCFLAG = 1;
        } else {
            crc_indications[i].CRCFLAG = 0;
        }
        fprintf(log_file, "%s: Created PDU with RNTI %d at time %ld.\n", __func__, crc_indications[i].RNTI, time(NULL));
    }

    unique_rnti_count = get_unique_rnti_count(crc_indications, num_elements);
    fprintf(log_file, "%s: Created list with %d unique RNTIs.\n", __func__, unique_rnti_count);

    free(crc_indications);
    fclose(log_file);
    return error_code;
}

int find_rnti(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int count, int rnti) {
    for (int i = 0; i < count; i++) {
        if (crc_indications[i].RNTI == rnti) {
            return i;
        }
    }
    return -1;
}

int get_unique_rnti_count(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int num_elements) {
    int unique_rntis[500];
    int count = 0;

    for (int i = 0; i < num_elements; i++) {
        int found = 0;
        for (int j = 0; j < count; j++) {
            if (crc_indications[i].RNTI == unique_rntis[j]) {
                found = 1;
                break;
            }
        }
        if (!found) {
            unique_rntis[count++] = crc_indications[i].RNTI;
        }
    }

    return count;
}
