    if (log_file == NULL) {
        return;
    }

    while (1) {
        sleep(interval); // Wait for archival interval

        // Compress and archive logs...
        rewind(log_file);
        // ...
        fseek(log_file, 0L, SEEK_END);
        // ...

        fclose(log_file);
    }
}

