void populateAndManageCRCIndications(int N, NFAPI_CRC_INDICATION_PDU_T **indications) {
    *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*indications == NULL) {
        printf("Allocation failed\n");
        return;
