        (*indications)[i].RX_UE_INFORMATION_TAG = i;
        (*indications)[i].RNTI = i+1;
        (*indications)[i].CRC_INDICATION_REL8_TAG = rand() % 10000;
        (*indications)[i].CRCFLAG = rand() % 2;
    }

    printf("Populated array of size: %d\n", N);
}

void asyncReduceOperation(int *numbers, int start, int end, void (*callback)(int), int **reduced) {
    if(start > end) return;

    int sum = 0;
    for(int i=start; i<=end; i++) {
        sum += numbers[i];
    }

    callback(sum);

    *reduced = (int *)malloc((end-start+1)*sizeof(int));
    if(*reduced == NULL) {
        printf("Allocation failed\n");
        return;
    }

    for(int i=start; i<=end; i++) {
        (*reduced)[i-start] = numbers[i];
    }
}

void callback(int result) {
    printf("Reduced result: %d\n", result);
}
