NFAPI_CRC_INDICATION_PDU_T* generate_structures(int num_structures) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    void* pool = malloc(POOL_SIZE);
    if (!pool) {
        return NULL;
    }

    int i;
    for (i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structure) {
            // Handle allocation failure
            printf("Failed to allocate memory for structure.\n");
            continue;
