        structure->rx_ue_info.tag = generate_random_tag();
        structure->rnti = generate_random_rnti();
        structure->crc_indication_rel8_tag.crcflag = rand() % 2;

        if (!pthread_mutex_trylock(&lock)) {
            // Add to pool
            void* addr = pool + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
            memcpy(addr, structure, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&lock);
        } else {
            // Handle concurrent access failure
            printf("Failed to acquire lock for concurrent access.\n");
            free(structure);
        }
    }

    if (i == 0) {
        // Handle no structures generated
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(i * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) {
        // Handle allocation failure
        printf("Failed to allocate memory for result.\n");
        return NULL;
    }

    memcpy(result, pool, i * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    free(pool);
