typedef struct {
    int connection_id;
    char* peer_address;
    double packet_size;
} NCO;

// Function to add a new session
void add_session(NCO** sessions, int* num_sessions, char* address) {
    *num_sessions = (*num_sessions) + 1;
    *sessions = (NCO*) realloc(*sessions, sizeof(NCO) * (*num_sessions));
    (*sessions)[*num_sessions - 1].connection_id = rand();
    (*sessions)[*num_sessions - 1].peer_address = address;
}

// Function to update the packet size for an existing session
void update_packet_size(NCO** sessions, int num_sessions, double packet_size) {
    for (int i = 0; i < num_sessions; i++) {
        if (strcmp(sessions[i]->peer_address, "insert_new_session") == 0) {
            sessions[i]->packet_size += packet_size;
            break;
        }
    }
}

// Function to calculate the rolling average packet size
double get_rolling_average(NCO** sessions, int num_sessions) {
    double sum = 0.0;
    for (int i = 0; i < num_sessions; i++) {
        sum += sessions[i]->packet_size;
    }
    return sum / num_sessions;
}

// Function to read integers from standard input and find the largest
void read_integers() {
    int n;
    printf("Enter number of elements: ");
    scanf("%d", &n);
    int arr[n];
    for (int i = 0; i < n; i++) {
        printf("Enter element %d: ", i+1);
        scanf("%d", &arr[i]);
    }
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

int main() {
    NCO* sessions = NULL;
    int num_sessions = 0;

    // Add new session
    add_session(&sessions, &num_sessions, "192.168.1.100");

    // Update packet size for existing session
    update_packet_size(&sessions, num_sessions, 1024.0);

    // Calculate rolling average packet size
    double average = get_rolling_average(&sessions, num_sessions);

    // Read integers from standard input and find the largest
    read_integers();

    return 0;
}

