#include <string.h>

typedef struct {
    int connection_id;
    char peer_ip[16];
    long int transmit_bytes;
    long int receive_bytes;
} SessionRecord;

SessionRecord* session_list = NULL;
int num_sessions = 0;

void add_session(int connection_id, const char* peer_ip) {
    // Allocate memory for the new session record
    SessionRecord* new_session = (SessionRecord*)malloc(sizeof(SessionRecord));
    strcpy(new_session->peer_ip, peer_ip);
    new_session->connection_id = connection_id;
    new_session->transmit_bytes = 0;
    new_session->receive_bytes = 0;

    // Insert the new session at the beginning of the list
    if (num_sessions > 0) {
        SessionRecord* temp = session_list;
        session_list = new_session;
        new_session->next = temp;
    } else {
        session_list = new_session;
    }
    num_sessions++;
}

void update_session(int connection_id, long int transmit_bytes, long int receive_bytes) {
    // Find the session with the matching ID
    SessionRecord* current = session_list;
    while (current != NULL) {
        if (current->connection_id == connection_id) {
            current->transmit_bytes += transmit_bytes;
            current->receive_bytes += receive_bytes;
            return;
        }
        current = current->next;
    }

    // If the session is not found, do nothing
}

long int calculate_bandwidth(int window_size) {
    long int total_bytes = 0;

    SessionRecord* current = session_list;
    while (current != NULL) {
        total_bytes += current->transmit_bytes + current->receive_bytes;
        current = current->next;
    }

    return total_bytes / window_size;
}

void parse_csv_file(const char* filename) {
    // Open the file and read each line
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return;
    }

    while (1) {
        char line[1024];
        if (fscanf(file, "%d,%15s", &connection_id, peer_ip) != 2) {
            break;
        }
        add_session(connection_id, peer_ip);
    }

    fclose(file);
}

// Helper functions
void free_sessions() {
    SessionRecord* current = session_list;
    while (current != NULL) {
        SessionRecord* next = current->next;
        free(current);
        current = next;
    }
    session_list = NULL;
    num_sessions = 0;
}
