int pool_index = 0;
socket_t* socket_pool[POOL_SIZE];

void init_socket_pool() {
    for (int i = 0; i < POOL_SIZE; i++) {
        socket_pool[i] = socket(AF_INET, SOCK_STREAM, 0);
        if (!socket_pool[i]) {
            perror("Failed to create socket");
            exit(EXIT_FAILURE);
        }
    }
}

void free_socket_pool() {
    for (int i = 0; i < POOL_SIZE; i++) {
        close(socket_pool[i]);
    }
}

connection_t* get_connection() {
    if (pool_index >= POOL_SIZE) {
        return NULL;
    }

    connection_t* conn = connections[num_connections];
    num_connections++;

    if (!conn) {
        perror("Failed to allocate connection");
        exit(EXIT_FAILURE);
    }

    conn->sock_fd = socket_pool[pool_index].fd;
    pool_index++;
    return conn;
}

void release_connection(connection_t* conn) {
    if (num_connections > 0 && conn == connections[num_connections - 1]) {
        num_connections--;
        close(conn->sock_fd);
    }
}

void log_event(const char* event) {
    if (LOG_ENABLED) {
        printf("Event: %s\n", event);
    }
}

int main() {
    init_socket_pool();

