    void addProfile(const UserProfile& profile) {
        std::unique_lock<std::mutex> lock(profileMutex);
        UserProfile* newProfile = new UserProfile();
        *newProfile = profile;
        profiles.push_back(*newProfile);
        profileMap[profile.name] = newProfile;
        nextId++;
