        std::unique_lock<std::mutex> lock(profileMutex);
        if (profileMap.find(name) != profileMap.end()) {
            delete profileMap[name];
            profiles.erase(std::remove_if(profiles.begin(), profiles.end(),
                [name](const UserProfile& p) { return p.name == name; }), profiles.end());
            profileMap.erase(name);
        }
    }

    void updateProfile(const std::string& name, const UserProfile& updatedProfile) {
        std::unique_lock<std::mutex> lock(profileMutex);
        if (profileMap.find(name) != profileMap.end()) {
            UserProfile* existingProfile = profileMap[name];
            *existingProfile = updatedProfile;
        }
    }

