#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    void* PDCP_SN;
    void* PDCP_RB_ID;
    void* NAS_MESSAGE;
} LTE_PDCP_RX_PDU_T;

typedef struct {
    LTE_PDCP_RX_PDU_T* packet;
    time_t timestamp;
    struct Node* next;
} Node;

void* alloc_array(int size) {
    return calloc(size, sizeof(LTE_PDCP_RX_PDU_T));
}

Node* create_node(LTE_PDCP_RX_PDU_T* packet, time_t timestamp) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->packet = packet;
    node->timestamp = timestamp;
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    free(node);
}

int retransmit_queue_init(int max_size, int log_retransmits) {
    // Initialize the queue
    Node* head = NULL;
    Node* tail = NULL;

    // Set up logging options
    int packet_count = 0;
    int dropped_packets = 0;
    FILE* log_file = fopen("retransmit.log", "w");
    if (log_retransmits) {
        fprintf(log_file, "Packet Retransmission Log\n");
    }

    return max_size;
}

void retransmit_queue_add(LTE_PDCP_RX_PDU_T* packet, time_t timestamp) {
    // Add the packet to the queue
    Node* node = create_node(packet, timestamp);

    if (head == NULL) {
        head = node;
        tail = node;
    } else {
        tail->next = node;
        tail = node;
    }

    // Check for overflow and handle dropped packets
    if (tail->next != NULL) {
        packet_count++;
        if (packet_count > max_size) {
            dropped_packets++;
            free_node(tail);
            tail = head;
            while (tail->next != NULL) {
                tail = tail->next;
            }
        }
    }

    // Log the addition
    if (log_retransmits) {
        fprintf(log_file, "Packet added to queue at timestamp %ld\n", timestamp);
    }
}

void retransmit_queue_free() {
    Node* node = head;
    while (node != NULL) {
        free_node(node);
        node = node->next;
    }

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }
}
