NFAPI_CRC_INDICATION_PDU_T* create_structures_from_yaml(yaml_parser_t* p, int total, unsigned seed) {
    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total * sizeof(NFAPI_CRC_INDATION_PDU_T));
    if (!structures) {
