        LOG_ERROR("Failed to allocate memory for structures");
        return NULL;
    }

    int rnti_min = 0, rnti_max = 1000; // default RNTI range from YAML config
    int crc_flag_min = 0, crc_flag_max = 255; // default CRCFLAG range from YAML config

    yaml_event_t event;
    while (yaml_parser_parse(p, &event) != 0) {
        if (event.type == YAML_STREAM_START_EVENT) {
            // get RNTI and CRCFLAG ranges from YAML config
            rnti_min = atoi(yaml_event_get_value(&event));
            rnti_max = atoi(yaml_event_get_end_of_stream(&event));
            crc_flag_min = atoi(yaml_event_get_value(&event));
            crc_flag_max = atoi(yaml_event_get_end_of_stream(&event));

            for (int i = 0; i < total; i++) {
                structures[i].RX_UE_INFORMATION_TAG = i;
                structures[i].RNTI = rnti_min + rand() % (rnti_max - rnti_min);
                structures[i].CRCFLAG = crc_flag_min + rand() % (crc_flag_max - crc_flag_min);
            }
        } else if (event.type == YAML_STREAM_END_EVENT) {
            // log creation process
            LOG_INFO("Created structures: %d", total);
            return structures;
        }
    }

    free(structures); // handle parsing error
    return NULL;
}

void verify_structures(NFAPI_CRC_INDICATION_PDU_T* structures, int total) {
    for (int i = 0; i < total; i++) {
        if (structures[i].RX_UE_INFORMATION_TAG >= total || structures[i].RNTI > rnti_max || structures[i].CRCFLAG > crc_flag_max) {
            // handle invalid structure values
            LOG_ERROR("Invalid structure at index %d", i);
        }
    }
}

int main() {
    yaml_parser_t p;
    yaml_parser_init(&p, YAML_NOFLAGS);

    int total = 10; // specify the number of structures to create
    unsigned seed = time(NULL); // get current timestamp as random seed

    NFAPI_CRC_INDICATION_PDU_T* structures = create_structures_from_yaml(&p, total, seed);
    if (structures) {
        verify_structures(structures, total);
        free(structures);
    }

    yaml_parser_free(&p);

    return 0;
}
