// Define the TrafficEvent structure
typedef struct {
    time_t timestamp;
    char event_type[16];
    int vehicle_id;
} TrafficEvent;

// Define the TrafficManager structure
typedef struct {
    TrafficEvent **events; // dynamic array of events
    int size, capacity;
    sem_t *mutex; // semaphore for synchronization
} TrafficManager;

// Function to read traffic events from file
TrafficEvent* read_events(const char* filename, int* num_events) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return NULL;
    }

    int count = 0;
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    TrafficEvent* events = (TrafficEvent*) malloc(size);
    fread(events, sizeof(TrafficEvent), size / sizeof(TrafficEvent), file);

    fclose(file);
    *num_events = size / sizeof(TrafficEvent);
    return events;
}

// Function to filter traffic events by timestamp and vehicle ID
void filter_events(TrafficManager* manager, time_t start, time_t end, int min_vehicle_id, int max_vehicle_id) {
    sem_wait(manager->mutex);

    for (int i = 0; i < manager->size; i++) {
        TrafficEvent* event = manager->events[i];
        if ((event->timestamp >= start && event->timestamp <= end) &&
            (event->vehicle_id >= min_vehicle_id && event->vehicle_id <= max_vehicle_id)) {
            // Process the filtered event
        }
    }

    sem_post(manager->mutex);
}

// Function to initialize the TrafficManager
TrafficManager* init_traffic_manager(int initial_capacity) {
    TrafficManager* manager = (TrafficManager*) malloc(sizeof(TrafficManager));
    manager->events = (TrafficEvent**) malloc(initial_capacity * sizeof(TrafficEvent*));
    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->mutex = sem_open("/traffic_manager_mutex", O_CREAT | O_RDWR, S_IRUSR | S_IWUSR, 1);
    return manager;
}

// Function to add traffic events to the TrafficManager
void add_events(TrafficManager* manager, TrafficEvent** new_events, int num_new_events) {
    sem_wait(manager->mutex);

    if (manager->size + num_new_events > manager->capacity) {
        // Reallocate memory for larger capacity
        manager->events = (TrafficEvent**) realloc(manager->events, (manager->size + num_new_events) * sizeof(TrafficEvent*));
        manager->capacity += num_new_events;
    }

    memcpy(&manager->events[manager->size], new_events, num_new_events * sizeof(TrafficEvent*));
    manager->size += num_new_events;

    sem_post(manager->mutex);
}

// Function to free the TrafficManager
void free_traffic_manager(TrafficManager* manager) {
    sem_close(manager->mutex);
    free(manager->events);
    free(manager);
}
