void crc_indication_list_init() {
    if (list != NULL) {
        free(list);
    }
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE_NAMED);
    pthread_mutex_init(&lock, &attr);
}

void* create_crc_indication(PARAM) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
        printf("Error allocating memory\n");
        return NULL;
    }
    // Initialize the pdu structure with random crcflag value
    new_pdu->crcflag = rand() % 2; 
    return new_pdu;
}

void crc_indication_list_add(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&lock);
    if (list_size >= MAX_LIST_SIZE) {
        printf("List reached maximum capacity\n");
        // Notify the caller that the list is full
        // Add the pdu to a temporary list or queue and try again later
        return;
    }
    if (total_bytes + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_BYTES) {
        printf("List exceeded maximum bytes\n");
        // Handle this situation as per requirement
        return;
    }
    list = realloc(list, (list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Error allocating memory\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    list[list_size] = *pdu;
    total_bytes += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    list_size++;
    pthread_mutex_unlock(&lock);
}

void crc_indication_list_process() {
    pthread_mutex_lock(&lock);
    // Implement the logic to process the CRC indications in the list
    for (int i = 0; i < list_size; i++) {
        printf("Processing pdu %d with flag %d\n", i, list[i]->crcflag);
    }
    pthread_mutex_unlock(&lock);
}

void crc_indication_list_log() {
    pthread_mutex_lock(&lock);
    if (list_size > LOG_INTERVAL) {
        printf("CRC indications processed: %d\n", list_size);
        printf("Total bytes used by the list: %d\n", total_bytes);
    }
    pthread_mutex_unlock(&lock);
}

void crc_indication_list_free() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < list_size; i++) {
        free(&list[i]);
    }
    free(list);
    list = NULL;
    list_size = 0;
    total_bytes = 0;
    pthread_mutex_unlock(&lock);
}

