        {
            XPathDocument doc = new XPathDocument("config.xml");
            XPathNavigator nav = doc.CreateNavigator();
            XPathExpression expr = nav.Compile("/root/" + elementName);
            XPathNodeIterator iterator = nav.Select(expr);

            if (iterator.MoveNext())
