int generateNfaPduAndConvertImage(int N, const char* inputFile, const char* outputFile, const char* conversionTool, int timeout, const char** outputFormats) {
    // Initialize a list of NFAPI structures
    NFAPI_CRC_INDICATION_PDU_T* nfaPdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!nfaPdus) {
        return 1; // Unable to allocate memory for NFAPI structures
    }

    // Populate the list of NFAPI structures with random data
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        nfaPdus[i].RX_UE_INFORMATION_TAG = rand() % 100;
        strcpy(nfaPdus[i].RNTI, "RNTI");
        nfaPdus[i].CRCFLAG = rand() % 2;
    }

    // Determine the appropriate conversion tool to use
    const char* primaryConversionTool = conversionTool;
    for (int i = 0; outputFormats[i]; i++) {
        if (!strcmp(outputFormats[i], "PDF")) {
            primaryConversionTool = outputFormats[i];
            break;
        }
    }

    // Convert the input image using the determined conversion tool
    char* command = (char*)malloc(strlen(primaryConversionTool) + strlen(inputFile) + 10);
    sprintf(command, "%s %s", primaryConversionTool, inputFile);

    FILE* file = popen(command, "w");
    if (!file) {
        return 1; // Unable to execute conversion command
    }

    // Manage any errors generated during the process
    if (perror("conversion") != NULL) {
        return 1; // Conversion failed due to system error
    }

    // Wait for the conversion process to complete within the timeout duration
    int seconds = 0;
    while (seconds < timeout && pclose(file) == -1) {
        sleep(1);
        seconds++;
    }

    if (pclose(file) == -1) {
        return 1; // Conversion timed out or failed
    }

    free(command);

    // Generate the NFAPI structures within the timeout duration
    int nfaPduCount = 0;
    while (seconds < timeout && nfaPduCount < N) {
        sleep(1);
        seconds++;
    }

    if (nfaPduCount != N) {
        return 1; // Generation of NFAPI structures timed out or failed
    }

    free(nfaPdus);

    return 0;
}

