public class XmlConfigParser
{
    public static string ParseXml(string xmlFile, string configName)
    {
        try
        {
            XmlDocument doc = new XmlDocument();
            doc.Load(xmlFile);
            XmlNodeList nodeList = doc.SelectNodes("//" + configName);

            if (nodeList.Count == 0) return "DefaultConfigValue";

