#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    char md5_hash[33];
    int error_code;
    char *error_message;
} IMAGE_INFO_T;

IMAGE_INFO_T extract_image_info(const char *image_path) {
    FILE *file = fopen(image_path, "rb");
    if (file == NULL) {
        return (IMAGE_INFO_T){0};
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    IMAGE_INFO_T image_info;
    char buffer[16];

    // Extract bits per sample
    fread(buffer, 1, 4, file);
    image_info.bits_per_sample = *(int *)buffer;

    // Extract samples per pixel
    fread(buffer, 1, 2, file);
    image_info.samples_per_pixel = *(unsigned short *)buffer;

    // Extract extra samples
    fread(buffer, 1, 2, file);
    image_info.extra_samples = *(unsigned short *)buffer;

    // Calculate MD5 hash
    unsigned char md5[16];
    FILE *md5_file = fopen("md5.txt", "wb");
    if (md5_file == NULL) {
        fclose(file);
        return (IMAGE_INFO_T){0};
    }
    fseek(file, 0, SEEK_END);
    file_size -= ftell(file);
    rewind(file);
    fread(buffer, 1, file_size, file);
    fwrite(buffer, 1, file_size, md5_file);
    fclose(md5_file);

    // Generate CRC FLAG
    int crcflag = (rand() % 2) ? 0 : 1;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications = malloc(5 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < 5; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = i;
        crc_indications[i].RNTI = rand() % 100;
        crc_indications[i].CRCFLAG = crcflag;
    }

    fclose(file);
    return image_info;
}
