struct list {
    pthread_mutex_t mutex;
    size_t size;
    size_t capacity;
    void** memory;
};

void nfaapi_crc_indication_pdu_list_init(struct list* list, size_t initial_capacity) {
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    list->size = 0;
    list->capacity = initial_capacity;
    list->memory = (void**)malloc(initial_capacity * sizeof(void*));
}

int nfaapi_crc_indication_pdu_list_insert(struct list* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        void** new_memory = realloc(list->memory, new_capacity * sizeof(void*));
        list->memory = new_memory;
        list->capacity = new_capacity;
    }
    void* ptr = nfaapi_crc_indication_pdu_t_allocate(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(ptr, element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->memory[list->size] = ptr;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void nfaapi_crc_indication_pdu_list_free(struct list* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; i++) {
        void* ptr = list->memory[i];
        nfaapi_crc_indication_pdu_t_free(ptr);
    }
    free(list->memory);
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
}
