typedef struct {
    char RX_UE_INFORMATION_TAG[256];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[256];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void appendSlashIfWithinLimit(char* statusMessage, int sizeLimit) {
    if (strlen(statusMessage) < sizeLimit - 1) {
        strcat(statusMessage, "/");
    } else {
        return NULL;
    }
}

void processNfarcrcindication(int N, char* statusMessage) {
    MD5_CTX md5ctx;
    unsigned char md5digest[16];
    NFAPI_CRC_INDICATION_PDU_T* nfapiStructures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

