        sprintf(nfapiStructures[i].RX_UE_INFORMATION_TAG, "RX_UE_INFO_TAG_%d", i);
        nfapiStructures[i].RNTI = i;
        sprintf(nfapiStructures[i].CRC_INDICATION_REL8_TAG, "CRC_INDIC_REL8_TAG_%d", i);
        nfapiStructures[i].CRCFLAG = rand() % 2;
    }

    appendSlashIfWithinLimit(statusMessage, 255);

    MD5Init(&md5ctx);
    MD5Update(&md5ctx, statusMessage, strlen(statusMessage));
    MD5Final(md5digest, &md5ctx);

    printf("Status Message: %s\n", statusMessage);
    for (int i = 0; i < N; i++) {
        printf("NFAPI Structure %d:\nRX_UE_INFO_TAG: %s\nRNTI: %d\nCRC_INDIC_REL8_TAG: %s\nCRCFLAG: %d\n", i, nfapiStructures[i].RX_UE_INFORMATION_TAG, nfapiStructures[i].RNTI, nfapiStructures[i].CRC_INDICATION_REL8_TAG, nfapiStructures[i].CRCFLAG);
    }

    printf("MD5 Hash: ");
    for (int i = 0; i < 16; i++) {
        printf("%02x", md5digest[i]);
