class DLDataPacket {
public:
    int PDCP_PDU_Tag;
    int sequence_number;
    std::string UE_ID;
    bool ACK_NACK_Flag;

    DLDataPacket(int PDCP_PDU_Tag, int sequence_number, const std::string& UE_ID, bool ACK_NACK_Flag)
        : PDCP_PDU_Tag(PDCP_PDU_Tag), sequence_number(sequence_number), UE_ID(UE_ID), ACK_NACK_Flag(ACK_NACK_Flag) {}
};

class DLDataPacketManager {
public:
    static const int MAX_LIST_SIZE = 1000;

private:
    std::list<DLDataPacket> packets;
    std::mutex mutex;
    std::condition_variable cv;
    bool is_list_full = false;
    int max_size_threshold = MAX_LIST_SIZE;

public:
    DLDataPacketManager(int max_size_threshold) : max_size_threshold(max_size_threshold) {}

    void addPacket(DLDataPacket packet) {
        std::unique_lock<std::mutex> lock(mutex);
        if (packets.size() >= max_size_threshold) {
            if (!is_list_full) {
                is_list_full = true;
                cv.notify_one();
            }
        } else {
            packets.push_back(packet);
        }
    }

    DLDataPacket getPacket(int sequence_number) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto it = packets.begin(); it != packets.end(); ++it) {
            if (it->sequence_number == sequence_number) {
                DLDataPacket packet = *it;
                packets.erase(it);
                return packet;
            }
        }
        throw std::runtime_error("Packet not found");
    }

    void cleanup() {
        std::unique_lock<std::mutex> lock(mutex);
        while (packets.size() > max_size_threshold / 2) {
            packets.pop_front();
        }
    }

    bool isListFull() const {
        return is_list_full;
    }

    int getMaxSizeThreshold() const {
        return max_size_threshold;
    }

    void setMaxSizeThreshold(int threshold) {
        if (threshold < MAX_LIST_SIZE) {
            max_size_threshold = threshold;
        } else {
            std::cerr << "Maximum size threshold cannot be less than the minimum allowed value." << std::endl;
        }
    }

    bool adjustMaxSizeThreshold() {
        // Adjust maximum size threshold based on real-time system metrics
        return false; // TO DO: Implement this feature
    }
};

