    for (i = 0; i < num_sessions; i++) {
        UeSessionData* session = (UeSessionData*)malloc(sizeof(UeSessionData));
        if (!session) {
            printf("Memory allocation failed for session %d.\n", i);
            // Handle memory allocation failures gracefully
            while (i > 0 && !sessions[i - 1]) {
                free(sessions[--i]);
            }
            return NULL;
        }

        session->ue_id = rand() % 10000; // Generate a unique ue_id value
        if (session->ue_id > max_ue_id) {
            max_ue_id = session->ue_id;
        }
        session->rnti = rand() % 10; // Random rnti value
        session->crc_status = rand() % 2; // Random crc status

        sessions[i] = session;

        // Log any failed allocations for monitoring purposes
        if (!session) {
            printf("Memory allocation failed for session %d.\n", i);
        }
    }

    return sessions;
}
