        list[i].CRCFLAG = rand() % 256;

        // Validate data structures
        if (list[i].RX_UE_INFORMATION_TAG < 0 || list[i].RX_UE_INFORMATION_TAG > 65535) {
            printf("Error: Invalid RX_UE_INFORMATION_TAG.\n");
            return;
        }
        if (list[i].RNTI < 0 || list[i].RNTI > 4294967295) {
            printf("Error: Invalid RNTI.\n");
            return;
        }
    }

    // Serialize the list into a binary format
    uint8_t* serialized_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!serialized_list) {
        printf("Error: Memory allocation failed for serialization.\n");
        free(list);
        return;
    }

    for (int i = 0; i < N; i++) {
        // Serialize each structure
        serialized_list[i].RX_UE_INFORMATION_TAG = htons(list[i].RX_UE_INFORMATION_TAG);
        serialized_list[i].RNTI = htonl(list[i].RNTI);
        memcpy(serialized_list[i].CRC_INDICATION_REL8_TAG, list[i].CRC_INDICATION_REL8_TAG, 4);

        // Add metadata (timestamp or sequence number)
        uint16_t timestamp = htons(time(NULL));
        memcpy(&serialized_list[i], &timestamp, 2);

        // Generate and validate checksum
        uint32_t crc32 = crc32_check(serialized_list, i + 1);
        if (crc32 != 0) {
            printf("Error: Serialization integrity check failed.\n");
            return;
        }
    }

    free(list);
    free(serialized_list);
}

uint32_t crc32_check(uint8_t* data, int length) {
    uint32_t crc = 0xffffffff;
    for (int i = 0; i < length; i++) {
        crc = (crc >> 8) ^ ((crc & 0xff0000) >> 5) ^ ((crc & 0x00ff00) >> 3) ^ ((crc & 0x0000ff) << 3);
        crc ^= data[i];
    }
    return ~crc;
}

int main() {
    manage_list(10); // Test with a small number of structures
    return 0;
}
