// Define the LTE_RRC_CU_MESSAGE structure
typedef struct {
    // Add your RRC NAS Message and MAC PDU fields here
} LTE_RRC_CU_MESSAGE;

// Thread-safe dynamic array to store LTE_RRC_CU_MESSAGE structures
typedef struct {
    int size;
    int capacity;
    LTE_RRC_CU_MESSAGE** messages;
} DynamicArray;

// Initialize the dynamic array with a given initial capacity
DynamicArray* dynamic_array_init(int capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->size = 0;
    arr->capacity = capacity;
    arr->messages = (LTE_RRC_CU_MESSAGE**)calloc(capacity, sizeof(LTE_RRC_CU_MESSAGE*));
    return arr;
}

// Add a new LTE_RRC_CU_MESSAGE to the dynamic array
void dynamic_array_add(DynamicArray* arr, LTE_RRC_CU_MESSAGE* message) {
    if (arr->size == arr->capacity) {
        // Double the capacity when the array is full
        int new_capacity = 2 * arr->capacity;
        arr->messages = (LTE_RRC_CU_MESSAGE**)realloc(arr->messages, new_capacity * sizeof(LTE_RRC_CU_MESSAGE*));
        arr->capacity = new_capacity;
    }
    arr->messages[arr->size] = message;
    arr->size++;
}

// Update an existing LTE_RRC_CU_MESSAGE in the dynamic array
void dynamic_array_update(DynamicArray* arr, int sequence_number, LTE_RRC_CU_MESSAGE* updated_message) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->messages[i]->sequence_number == sequence_number) {
            // Update the existing message
            *arr->messages[i] = *updated_message;
            return;
        }
    }
}

// Retrieve an LTE_RRC_CU_MESSAGE from the dynamic array by its sequence number
LTE_RRC_CU_MESSAGE* dynamic_array_get(DynamicArray* arr, int sequence_number) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->messages[i]->sequence_number == sequence_number) {
            return arr->messages[i];
        }
    }
    return NULL;
}

// Free the dynamic array and its contents
void dynamic_array_free(DynamicArray* arr) {
    for (int i = 0; i < arr->size; i++) {
        free(arr->messages[i]);
    }
    free(arr->messages);
    free(arr);
}
