typedef struct {
    int media_stream_id;
    long record_start_time;
    int recorder_status;
} MEDIA_STREAM_RECORDING_T;

MEDIA_STREAM_RECORDING_T* media_stream_recording_pool = NULL;
int pool_size = 0;
pthread_mutex_t lock;

void* create_media_stream_recording(int media_stream_id, long record_start_time, int recorder_status) {
    MEDIA_STREAM_RECORDING_T* new_stream = (MEDIA_STREAM_RECORDING_T*)malloc(sizeof(MEDIA_STREAM_RECORDING_T));
    if(new_stream == NULL) return NULL;

    new_stream->media_stream_id = media_stream_id;
    new_stream->record_start_time = record_start_time;
    new_stream->recorder_status = recorder_status;

    pthread_mutex_lock(&lock);
    for(int i = 0; i < pool_size; i++) {
        if(media_stream_recording_pool[i]->media_stream_id == media_stream_id) {
            free(new_stream);
            pthread_mutex_unlock(&lock);
            return NULL; // duplicate id
        }
    }
    media_stream_recording_pool = (MEDIA_STREAM_RECORDING_T**)realloc(media_stream_recording_pool, sizeof(MEDIA_STREAM_RECORDING_T*) * (pool_size + 1));
    media_stream_recording_pool[pool_size] = new_stream;
    pool_size++;
    pthread_mutex_unlock(&lock);

    return new_stream;
}

void destroy_media_stream_recording(int media_stream_id) {
    int i = 0;
    bool found = false;

    pthread_mutex_lock(&lock);
    for(i = 0; i < pool_size; i++) {
        if(media_stream_recording_pool[i]->media_stream_id == media_stream_id) {
            free(media_stream_recording_pool[i]);
            while(i < pool_size - 1) {
                media_stream_recording_pool[i] = media_stream_recording_pool[i + 1];
                i++;
            }
            pool_size--;
            found = true;
        }
    }

    if(!found) pthread_mutex_unlock(&lock);

    return;
}

void check_and_remove_inactive_streams() {
    int i, j = 0;

    pthread_mutex_lock(&lock);
    for(i = 0; i < pool_size; i++) {
        if(media_stream_recording_pool[i]->record_start_time + 86400 <= time(NULL) && media_stream_recording_pool[i]->recorder_status != 1) {
            while(j < i) {
                media_stream_recording_pool[j] = media_stream_recording_pool[j + 1];
                j++;
            }
            pool_size--;
        } else j++;
    }

    pthread_mutex_unlock(&lock);

    return;
}
