class MediaSessionManager {

    private $streamPool;

    public function __construct() {
        $this->streamPool = array();
    }

    public function createMediaStreamRecording($mediaStreamId, $recordStartTime, $recorderStatus) {
        if (in_array($mediaStreamId, array_keys($this->streamPool))) {
            return null; // duplicate id
        }

        $newStream = array('media_stream_id' => $mediaStreamId, 'record_start_time' => $recordStartTime, 'recorder_status' => $recorderStatus);
        $this->streamPool[$mediaStreamId] = $newStream;
    }

    public function destroyMediaStreamRecording($mediaStreamId) {
        unset($this->streamPool[$mediaStreamId]);

        return;
    }

    public function checkAndRemoveInactiveStreams() {
        foreach ($this->streamPool as $stream) {
            if (($stream['record_start_time'] + 86400) <= time() && $stream['recorder_status'] != 1) {
                unset($this->streamPool[$stream['media_stream_id']]);
            }
        }

        return;
    }

