    }
    nfa_pi_crc_indication_pdu_t_pool.capacity = capacity;
    nfa_pi_crc_indation_pdu_t_pool.arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&nfa_pi_crc_indication_pdu_t_pool.mutex, NULL);
}

void* nfa_pi_crc_indication_pdu_t_pool_alloc(void) {
    pthread_mutex_lock(&nfa_pi_crc_indication_pdu_t_pool.mutex);
    for (size_t i = 0; i < nfa_pi_crc_indation_pdu_t_pool.size; ++i) {
        if (nfa_pi_crc_indation_pdu_t_pool.arr[i].CRCFLAG == 0) {
            pthread_mutex_unlock(&nfa_pi_crc_indication_pdu_t_pool.mutex);
            return &nfa_pi_crc_indation_pdu_t_pool.arr[i];
        }
    }
    if (nfa_pi_crc_indation_pdu_t_pool.size < nfa_pi_crc_indation_pdu_t_pool.capacity) {
        NFAPI_CRC_INDICATION_PDU_T* new_arr = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfa_pi_crc_indation_pdu_t_pool.arr, (nfa_pi_crc_indation_pdu_t_pool.size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_arr) {
            pthread_mutex_unlock(&nfa_pi_crc_indation_pdu_t_pool.mutex);
            return NULL;
        }
        nfa_pi_crc_indation_pdu_t_pool.arr = new_arr;
    } else {
        // Handle full pool
    }
    pthread_mutex_unlock(&nfa_pi_crc_indation_pdu_t_pool.mutex);
    return NULL; // Not found
}

void nfa_pi_crc_indication_pdu_t_pool_free(void) {
    free(nfa_pi_crc_indation_pdu_t_pool.arr);
    pthread_mutex_destroy(&nfa_pi_crc_indation_pdu_t_pool.mutex);
}
