typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct Node* next;
} Node;

Node* insert(Node** head_ref, NFAPI_CRC_INDATION_PDU_T new_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL; // Handle memory allocation failure

    new_node->data = new_data;
    new_node->next = (*head_ref);
    (*head_ref) = new_node;

    return *head_ref;
}

void reverse_insert(Node** head_ref, NFAPI_CRC_INDATION_PDU_T new_data) {
    Node* prev = NULL;
    Node* current = *head_ref;
    Node* next = NULL;
    while (current != NULL) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
    if (!prev) return; // List was empty, do nothing
    (*head_ref) = prev;

    new_data = new_data;
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL; // Handle memory allocation failure

    new_node->data = new_data;
    new_node->next = prev;
    prev = new_node;

    (*head_ref) = prev;
}

void check_sum_validation(Node* head) {
    int checksum = 0;
    Node* current = head;
    while (current != NULL) {
        checksum += current->data.RX_UE_INFORMATION_TAG ^ current->data.RNTI ^ current->data.CRC_INDICATION_REL8_TAG ^ current->data.CRCFLAG;
        current = current->next;
