void generateCrcIndicationList(int* listSize, NFAPI_CRC_INDICATION_PDU_T** list) {
    // Initialize random number generator
    srand(time(NULL));

    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*list == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < *listSize; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*list)[i].RNTI = rand() % 256;
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 100;

        // Determine CRCFLAG based on pseudo-random value
        int crcFlag = (rand() % 2) ? 1 : 0; // Randomly select 0 or 1

        if (crcFlag == 1) {
            (*list)[i].CRC_INDICATION_REL8_TAG |= (1 << 7); // Set CRCFLAG to 1
        }
    }
}

void executeSqlCommandWithParameters(NFAPI_CRC_INDICATION_PDU_T* list, int listSize, SQLConnection* conn, char* sqlCommand, SQLParameter* parameters) {
    // Parameterize the SQL command based on the provided structures

