        AddSqlParameter(sqlCommand, parameters[i].RNTI);
        AddSqlParameter(sqlCommand, parameters[i].CRC_INDICATION_REL8_TAG);
    }

    // Execute the SQL command
    conn->Execute(sqlCommand);

    // Clean up resources
    ReleaseSQLParameter(parameters);
}

