    SQLParameter parameters[listSize];

    for (int i = 0; i < listSize; i++) {
        // Initialize parameters
        parameters[i].RX_UE_INFORMATION_TAG = list[i].RX_UE_INFORMATION_TAG;
        parameters[i].RNTI = list[i].RNTI;
        parameters[i].CRC_INDICATION_REL8_TAG = list[i].CRC_INDICATION_REL8_TAG;

