LTE_PHY_RX_FRAME_T* init_phy_rx_frames(int num_frames, int max_subframes) {
    LTE_PHY_RX_FRAME_T* frames = (LTE_PHY_RX_FRAME_T*)malloc(num_frames * sizeof(LTE_PHY_RX_FRAME_T));
    if (!frames) return NULL;

    for (int i = 0; i < num_frames; i++) {
        frames[i].frame_tag = i % MAX_SUBFRAMES; // Initialize frame tag with the subframe number
        frames[i].cell_id = 0x0001; // Initialize cell ID to a default value
        frames[i].pci = 0x0011; // Initialize PCI to a default value

        // Allocate memory for up to max_subframes PHY_RX_SUBFRAME_T structures
        PHY_RX_SUBFRAME_T** subframes = (PHY_RX_SUBFRAME_T**)malloc(max_subframes * sizeof(PHY_RX_SUBFRAME_T*));

        if (!subframes) {
            free(frames);
            return NULL;
        }

        frames[i].subframes = subframes; // Store the allocated subframes array in the frame
    }

    return frames;
}

void free_phy_rx_frames(LTE_PHY_RX_FRAME_T* frames) {
    for (int i = 0; i < sizeof(frames) / sizeof(*frames); i++) {
        if (frames[i].subframes) {
            for (int j = 0; j < MAX_SUBFRAMES; j++) {
                free(frames[i].subframes[j]);
            }
            free(frames[i].subframes);
        }
    }
    free(frames);
}

void serialize_phy_rx_frames(LTE_PHY_RX_FRAME_T* frames, FILE* file) {
    // Serialize each frame into the binary format
    for (int i = 0; i < sizeof(frames) / sizeof(*frames); i++) {
        fwrite(&frames[i].frame_tag, sizeof(LTE_PHY_RX_FRAME_TAG), 1, file);
        fwrite(&frames[i].cell_id, sizeof(LTE_CELL_ID), 1, file);
        fwrite(&frames[i].pci, sizeof(LTE_PCI), 1, file);

        // Serialize each subframe
        for (int j = 0; j < MAX_SUBFRAMES; j++) {
            fwrite(frames[i].subframes[j], FRAME_MAX_SIZE, 1, file);
        }
    }
}

LTE_PHY_RX_FRAME_T* deserialize_phy_rx_frames(FILE* file) {
    LTE_PHY_RX_FRAME_T* frames = (LTE_PHY_RX_FRAME_T*)malloc(sizeof(LTE_PHY_RX_FRAME_T));

    // Deserialize each frame from the binary format
    for (int i = 0; i < sizeof(frames) / sizeof(*frames); i++) {
        fread(&frames[i].frame_tag, sizeof(LTE_PHY_RX_FRAME_TAG), 1, file);
        fread(&frames[i].cell_id, sizeof(LTE_CELL_ID), 1, file);
        fread(&frames[i].pci, sizeof(LTE_PCI), 1, file);

        // Deserialize each subframe
        for (int j = 0; j < MAX_SUBFRAMES; j++) {
            fread(frames[i].subframes[j], FRAME_MAX_SIZE, 1, file);
        }
    }

    return frames;
}
