#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int valid;
    long time_alignment_timer;
    float cqi;
} lte_frame_sync;

pthread_mutex_t sync_list_lock = PTHREAD_MUTEX_INITIALIZER;
lte_frame_sync** frame_sync_list;
int list_size;
int current_index = 0;

void* get_frame_sync(void* idx) {
    int* ptr_idx = (int*)idx;
    return (void*)frame_sync_list[(*ptr_idx)];
}

void add_frame_sync(lte_frame_sync* new_sync) {
    pthread_mutex_lock(&sync_list_lock);

    if (list_size < current_index + 1) {
        list_size = current_index + 2;
        frame_sync_list = realloc(frame_sync_list, sizeof(lte_frame_sync*) * list_size);
    }

    frame_sync_list[current_index] = new_sync;
    current_index++;

    pthread_mutex_unlock(&sync_list_lock);
}

void remove_frame_sync(int idx) {
    pthread_mutex_lock(&sync_list_lock);

    if (idx < 0 || idx >= current_index) {
        pthread_mutex_unlock(&sync_list_lock);
        return;
    }

    for (int i = idx; i < current_index - 1; i++) {
        frame_sync_list[i] = frame_sync_list[i + 1];
    }

    current_index--;
    if (current_index * sizeof(lte_frame_sync*) > list_size) {
        list_size = current_index;
        frame_sync_list = realloc(frame_sync_list, sizeof(lte_frame_sync*) * list_size);
    }

    pthread_mutex_unlock(&sync_list_lock);
}

int get_cqi(int idx) {
    pthread_mutex_lock(&sync_list_lock);

    if (idx < 0 || idx >= current_index) {
        pthread_mutex_unlock(&sync_list_lock);
        return -1;
    }

    lte_frame_sync* frame = frame_sync_list[idx];
    pthread_mutex_unlock(&sync_list_lock);

    return frame->cqi;
}

void update_cqi(int idx, float new_cqi) {
    pthread_mutex_lock(&sync_list_lock);

    if (idx < 0 || idx >= current_index) {
        pthread_mutex_unlock(&sync_list_lock);
        return;
    }

    lte_frame_sync* frame = frame_sync_list[idx];
    frame->cqi = new_cqi;
    pthread_mutex_unlock(&sync_list_lock);
}

void print_frame_syncs() {
    pthread_mutex_lock(&sync_list_lock);

    for (int i = 0; i < current_index; i++) {
        lte_frame_sync* frame = frame_sync_list[i];

        if (!frame->valid) {
            printf("Invalid frame synchronization at index %d\n", i);
            continue;
        }

        printf("Frame Sync Index: %d, Time Alignment Timer: %ld, CQI: %.2f\n", i, frame->time_alignment_timer, frame->cqi);
    }

    pthread_mutex_unlock(&sync_list_lock);
}
