// Function to manage a list of NFAPI_CRC_INDICATION_PDU_T structures
void* manage_NFAPI_CRC_INDICATION_PDU_T_list(int size, void** arr) {
    // Initialize the head and tail pointers
    void* head = NULL;
    void* tail = NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Initialize a mutex for thread safety

    // Function to dynamically allocate memory
    void* alloc(size_t size) {
        void* p = malloc(size);
        if (!p) {
            printf("Memory allocation failed!\n");
            return NULL;
        }
        return p;
    }

    // Function to deallocate memory
    void free_(void* p) {
        free(p);
    }

    // Allocate initial memory for the list
    size_t elem_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    head = alloc(elem_size * 1); // Initialize with one element

    if (head != NULL) {
        tail = ((NFAPI_CRC_INDICATION_PDU_T*) head + size - 1);

        for (int i = 0; i < size; i++) {
            NFAPI_CRC_INDICATION_PDU_T* p = ((NFAPI_CRC_INDICATION_PDU_T*)head + i);
            p->valid_RX_UE_INFORMATION_TAG = rand() % 2;
            p->RNTI = (unsigned int) rand();
            p->CRCFLAG = (unsigned char) rand();

            // Ensure no two consecutive structures share the same RNTI value
            while (i > 0 && ((NFAPI_CRC_INDICATION_PDU_T*)head + i - 1)->RNTI == p->RNTI)
                p->RNTI = (unsigned int) rand();
        }
    }

    // Perform concurrent access from multiple threads
    pthread_mutex_lock(&lock);
    void* result = head;
    pthread_mutex_unlock(&lock);

    return result;
}

// Function to free the list when it's no longer needed
void free_NFAPI_CRC_INDICATION_PDU_T_list(void* p) {
    if (p != NULL) {
        free_(p);
    }
}
