// Structure for LTE Uplink Turbo Decoded MAC PDU
typedef struct {
    uint8_t* data;
    size_t len;
    uint32_t crc32;
} PDU;

// Collection of PDUs with memory management and CRC validation
typedef struct {
    PDU** pdus;
    size_t capacity;
    size_t count;
} PDUCollection;

PDUCollection* pdu_collection_create(size_t initial_capacity) {
    PDUCollection* collection = (PDUCollection*)malloc(sizeof(PDUCollection));
    collection->pdus = (PDU**)calloc(initial_capacity, sizeof(PDU*));
    collection->capacity = initial_capacity;
    collection->count = 0;
    return collection;
}

void pdu_collection_free(PDUCollection* collection) {
    for(size_t i = 0; i < collection->count; i++) {
        free(collection->pdus[i]->data);
        free(collection->pdus[i]);
    }
    free(collection->pdus);
    free(collection);
}

int pdu_collection_add(PDUCollection* collection, PDU* pdu) {
    if(collection->count >= collection->capacity) {
        // Reallocate memory and resize the collection
        size_t new_capacity = collection->capacity * 2;
        PDU** new_pdus = (PDU**)realloc(collection->pdus, new_capacity * sizeof(PDU*));
        collection->pdus = new_pdus;
        collection->capacity = new_capacity;
    }
    collection->pdus[collection->count] = pdu;
    collection->count++;
    return 0;
}

int pdu_collection_update(PDUCollection* collection, size_t index, PDU* pdu) {
    if(index >= collection->count || !pdu) return -1;
    // Update the CRC checksum and data
    pdu->crc32 = crc32(pdu->data, pdu->len);
    for(size_t i = 0; i < collection->count; i++) {
        if(i == index) {
            collection->pdus[i]->data = pdu->data;
            collection->pdus[i]->len = pdu->len;
            collection->pdus[i]->crc32 = pdu->crc32;
            break;
        }
    }
    return 0;
}

int pdu_collection_iterate(PDUCollection* collection, void (*callback)(PDU*)) {
    for(size_t i = 0; i < collection->count; i++) {
        callback(collection->pdus[i]);
    }
    return 0;
}

