typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct node* prev;
    struct node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(1);
    }
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

int list_insert(Node** head, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
        return 0;
    }

    Node* curr = *head;
    while (curr->next != NULL) {
        curr = curr->next;
    }
    curr->next = new_node;
    new_node->prev = curr;
    return 1;
}

int list_delete(Node** head, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (*head == NULL || (*head)->data != data) {
        return -1; // Node not found
    }

    Node* temp = *head;
    *head = (*head)->next;

    if ((*head)) {
        (*head)->prev = NULL;
    } else {
