void* alloc_array(int N) {
    size_t total_size = sizeof(MAC_PDU_T) * N;

    // Check system resource limitations
    if (total_size > sysconf(_SC_PAGESIZE) * (sysconf(_SC_PHYS_PAGES))) {
        printf("Error: System memory capacity exceeded.\n");
        N = (int)(sysconf(_SC_PHYS_PAGES) / 2); // Try to allocate half of the available memory
