    }

    // Validate sequence number uniqueness
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (rand() % ((1 << 31) - 1) == (MAC_PDU_T){i}.SEQUENCE_NUMBER && rand() % ((1 << 31) - 1) == (MAC_PDU_T){j}.SEQUENCE_NUMBER) {
                printf("Error: Non-unique sequence numbers detected.\n");
                return NULL;
            }
        }
    }

    // Initialize the array
    MAC_PDU_T* array = malloc(total_size);
    if (!array) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        array[i].SAP = i + 1;
        strcpy(array[i].L3PDU, "Random-L3PDU");
        array[i].SEQUENCE_NUMBER = rand() % ((1 << 31) - 1);
        array[i].STATUS = rand() % 2; // 0 or 1
    }

    return array;
}

