sem_t semaphore;
NFAPI_CRC_INDICATION_PDU_T *nfapis[MAX_NFAPIS];
int nfapi_count = 0;

void* create_nfa_pdu(void* thread_id) {
    int i = *(int*)thread_id;
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(pdu == NULL){
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        return NULL;
    }

    pdu->RX_UE_INFORMATION_TAG = i;  // Initialize structure fields
    pdu->RNTI = rand() % RNTI_VALID_RANGE + 1;
    pdu->CRC_INDICATION_REL8_TAG = rand();

    if(pdu->RNTI < RNTI_VALID_RANGE){
        // Log and handle validation error
        printf("Invalid RNTI value: %d\n", pdu->RNTI);
    }

    // Log creation of each NFAPI CRC indication PDU T instance
    printf("NFAPI CRC Indication PDU T created with RNTI:%d\n", pdu->RNTI);

    sem_wait(&semaphore);  // Acquire the semaphore for thread safety
    nfapis[nfapi_count] = pdu;
    nfapi_count++;
    sem_post(&semaphore);  // Release the semaphore

    return NULL;
}

void init_nfa_pdu_manager() {
    int i;

    // Initialize semaphore for thread safety
    if(sem_init(&semaphore, 0, 1) != 0){
        printf("Semaphore initialization failed\n");
        exit(1);
    }

    pthread_t threads[MAX_NFAPIS];

    for(i = 0; i < MAX_NFAPIS; i++){
        int* thread_id = (int*)malloc(sizeof(int));
        *thread_id = i;
        if(pthread_create(&threads[i], NULL, create_nfa_pdu, thread_id) != 0){
            printf("Thread creation failed\n");
            exit(1);
        }
    }

    for(i = 0; i < MAX_NFAPIS; i++){
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&semaphore);  // Destroy the semaphore
}

int main() {
    init_nfa_pdu_manager();
    return 0;
}
