// Custom memory pool structure
typedef struct {
    void **blocks;
    int size;
    pthread_mutex_t mutex;
} MemoryPool;

// Function to initialize the custom memory pool
MemoryPool* init_memory_pool(int initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->size = initial_size;
    pool->blocks = (void**)malloc(initial_size * sizeof(void*));
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

// Function to allocate memory from the custom memory pool
void* malloc_memory_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);

    int i;
    for (i = 0; i < pool->size; i++) {
        if (!pool->blocks[i]) {
            break;
        }
    }

    void* block = pool->blocks[i];
    pool->blocks[i] = NULL;

    pthread_mutex_unlock(&pool->mutex);
    return block;
}

// Function to deallocate memory from the custom memory pool
void free_memory_pool(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->mutex);

    for (int i = 0; i < pool->size; i++) {
        if (pool->blocks[i] == ptr) {
            pool->blocks[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
}

