#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[10];
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe linked list node structure
typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct Node* next;
} Node;

// Global lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Linked list head
Node* head = NULL;

// Function to dynamically allocate and manage a linked list
void ue_info_list_init(int N) {
    int i;
    for (i = 0; i < N; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Initialize random CRCFLAG values
        node->data.CRCFLAG = rand() % 2;

        pthread_mutex_lock(&lock);
        // Check for duplicate RNTI values
        int found = 0;
        Node* current = head;
        while (current != NULL) {
            if (current->data.RNTI == node->data.RNTI) {
                found = 1;
                break;
            }
            current = current->next;
        }

        if (!found) {
            // Add the new node to the list
            if (head == NULL)
                head = node;
            else {
                Node* last_node = head;
                while (last_node->next != NULL)
                    last_node = last_node->next;
                last_node->next = node;
            }
        } else {
            printf("Duplicate RNTI value detected.\n");
        }

        pthread_mutex_unlock(&lock);
    }
}

// Function to deallocate the linked list
void ue_info_list_free() {
