        time_t timestamp;
        float power_level;
    } power_level_record;
} TX_POWER_LEVEL_RECORD;

void* tx_power_level_records = NULL;
int record_count = 0;

TX_POWER_LEVEL_RECORD* create_tx_power_level_record(int freq_band, int cell_id) {
    if (record_count >= MAX_RECORDS) {
        printf("Error: Maximum number of records exceeded.\n");
        return NULL;
    }

    TX_POWER_LEVEL_RECORD* new_record = (TX_POWER_LEVEL_RECORD*)malloc(sizeof(TX_POWER_LEVEL_RECORD));
    if (!new_record) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    new_record->freq_band = freq_band;
    new_record->cell_id = cell_id;
    new_record->power_level_record.timestamp = time(NULL);
    new_record->power_level_record.power_level = 0.0;

    if (record_count == 0) {
        tx_power_level_records = &new_record;
    } else {
        TX_POWER_LEVEL_RECORD* last_record = (TX_POWER_LEVEL_RECORD*)((char*)tx_power_level_records + sizeof(TX_POWER_LEVEL_RECORD) * (record_count - 1));
        new_record->power_level_record.timestamp = last_record->power_level_record.timestamp;
        tx_power_level_records = (void*)(((char*)tx_power_level_records) + sizeof(TX_POWER_LEVEL_RECORD) * record_count);
    }

    record_count++;

    return new_record;
}

int update_tx_power_level_record(int freq_band, int cell_id, float power_level) {
    for (int i = 0; i < record_count; i++) {
        TX_POWER_LEVEL_RECORD* current_record = (TX_POWER_LEVEL_RECORD*)((char*)tx_power_level_records + sizeof(TX_POWER_LEVEL_RECORD) * i);

        if (current_record->freq_band == freq_band && current_record->cell_id == cell_id) {
            current_record->power_level_record.power_level = power_level;

            return 1; // Record found and updated
        }
    }

    printf("Error: Record not found.\n");

    return -1; // Record not found
}

void log_tx_power_level_records() {
    for (int i = 0; i < record_count; i++) {
        TX_POWER_LEVEL_RECORD* current_record = (TX POWER LEVEL RECORD*)((char*)tx_power_level_records + sizeof(TX POWER LEVEL RECORD) * i);

        printf("Frequency Band: %d, Cell ID: %d, Power Level: %f, Timestamp: %ld\n", current_record->freq_band, current_record->cell_id, current_record->power_level_record.power_level, current_record->power_level_record.timestamp);
    }
}
