void dynamic_allocation_and_population(int N) {
    srand(time(NULL));

    // Memory pool allocation (to minimize memory fragmentation)
    int* memory_pool = malloc(N * sizeof(int));
    if (memory_pool == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize the CRC_INDICATION_REL8_TAG
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* nfaPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfaPdu == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Set the RX_UE_INFORMATION_TAG and RNTI
        nfaPdu->RX_UE_INFORMATION_TAG = i;
        nfaPdu->RNTI = rand() % 100; // Randomly set RNTI

        // Initialize the CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        nfaPdu->CRC_INDICATION_REL8_TAG = malloc(sizeof(int));
        if (nfaPdu->CRC_INDICATION_REL8_TAG == NULL) {
            printf("Memory allocation failed.\n");
            free(nfaPdu);
            return;
        }

        // Release the memory pool for re-use
        free(memory_pool);

        // Store the dynamically allocated structures in an array
        NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Copy the data from the memory pool to the dynamically allocated array
        for (int i = 0; i < N; i++) {
            array[i] = *nfaPdu;
        }
    }

    // Release all allocated resources upon completion of operations
    free(array);
}
