pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int list_size = 0;
NFAPI_CRC_INDICATION_PDU_T* list = NULL;

void create_list(int n) {
    pthread_mutex_lock(&lock);
    int i;
    for (i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_item = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_item) {
            printf("Error allocating memory.\n");
            return;
        }
        // Randomly set CRC flag
        int crc = rand() % 2;
        new_item->RX_UE_INFORMATION_TAG = i;
        new_item->RNTI = i * 2;
        new_item->CRC_INDICATION_REL8_TAG = crc;
        if (crc) {
            printf("CRC flag set for item %d.\n", i);
        }
        list = realloc(list, (list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!list) {
            printf("Error allocating memory.\n");
            free(new_item);
            return;
        }
        list[list_size++] = new_item;
    }
    pthread_mutex_unlock(&lock);
}

void destroy_list() {
    int i;
    for (i = 0; i < list_size; i++) {
        free(list[i]);
    }
    free(list);
    list = NULL;
    list_size = 0;
}

int serialize(NFAPI_CRC_INDICATION_PDU_T* item, char** buffer) {
    // Serialize the structure to a binary format
    *buffer = malloc(24); // Assuming 24 bytes per structure
    if (!(*buffer)) {
        return -1; // Memory allocation failed
    }
    memcpy(*buffer, &item->RX_UE_INFORMATION_TAG, sizeof(int));
    memcpy((*buffer + 4), &item->RNTI, sizeof(int));
    memcpy((*buffer + 8), &item->CRC_INDICATION_REL8_TAG, sizeof(int));
    return 0; // Serialization successful
}

int deserialize(char* buffer, NFAPI_CRC_INDICATION_PDU_T* item) {
    // Deserialize the structure from a binary format
    memcpy(&item->RX_UE_INFORMATION_TAG, buffer, sizeof(int));
    memcpy(&item->RNTI, buffer + 4, sizeof(int));
    memcpy(&item->CRC_INDICATION_REL8_TAG, buffer + 8, sizeof(int));
    return 0; // Deserialization successful
}

int main() {
    int n = 10;
    create_list(n);
    for (int i = 0; i < list_size; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
              list[i]->RX_UE_INFORMATION_TAG, list[i]->RNTI, list[i]->CRC_INDICATION_REL8_TAG);
    }
    destroy_list();
    return 0;
}
