        // Select a subset of states based on performance-critical criteria
        if (traversal_criteria & 1) { // Traverse all states
            list[i] = pdu;
        } else if (traversal_criteria & 2) { // Traverse only high-priority states
            if (i % 2 == 0) {
                list[i] = pdu;
            }
        }

        free(pdu);
    }

    return list;
}

