typedef struct {
    int ue_id;
    long timestamp;
    int status; // 0: inactive, 1: active
} UEStatusRecord;

typedef struct {
    UEStatusRecord* records;
    int size;
    int capacity;
} UESArray;

UESArray* ue_status_array_init(int initial_capacity) {
    UESArray* array = (UESArray*)malloc(sizeof(UESArray));
    array->records = (UEStatusRecord*)malloc(initial_capacity * sizeof(UEStatusRecord));
    array->size = 0;
    array->capacity = initial_capacity;
    return array;
}

void ue_status_array_insert(UESArray* array, UEStatusRecord record) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->records = (UEStatusRecord*)realloc(array->records, array->capacity * sizeof(UEStatusRecord));
    }
    array->records[array->size++] = record;
}

void ue_status_array_update(UESArray* array, int ue_id, int status) {
    for (int i = 0; i < array->size; i++) {
        if (array->records[i].ue_id == ue_id) {
            array->records[i].status = status;
            return;
        }
    }
}

int ue_status_array_query(UESArray* array, int ue_id) {
    for (int i = 0; i < array->size; i++) {
        if (array->records[i].ue_id == ue_id) {
            return array->records[i].status;
        }
    }
    return -1; // not found
}

void ue_status_array_free(UESArray* array) {
    free(array->records);
    free(array);
}
