#include <stdatomic.h>
#include <stdlib.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    int count;
    atomic_int size;
} NFAPI_CRC_INDICATION_PDU_COLLECT;

void nfaPiCrcIndicationPduCollection_init(NFAPI_CRC_INDICATION_PDU_COLLECT* collection) {
    collection->pdus = NULL;
    collection->count = 0;
    atomic_init(&collection->size, 0);
}

void nfaPiCrcIndicationPduCollection_add(NFAPI_CRC_INDICATION_PDU_COLLECT* collection, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int new_size = atomic_exchange(&collection->size, atomic_fetch_add(&collection->size, 1)) + 1;
    if (new_size > 10000) return; // Limit size to 10,000 PDUs

    collection->pdus = realloc(collection->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_size);
    if (!collection->pdus) return; // Handle memory allocation failure

    memcpy(&collection->pdus[new_size - 1], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    collection->count = new_size;
}

void nfaPiCrcIndicationPduCollection_iterate(NFAPI_CRC_INDICATION_PDU_COLLECT* collection, void(*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    for (int i = 0; i < atomic_exchange(&collection->size, 0); i++) {
        callback(collection->pdus[i]);
    }
