class NFAPI_CRC_INDICATION_PDU_T {
public:
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

void process_messages(const std::string& key, const std::string& iv,
                       const std::vector<std::string>& messages, int N) {
    std::mutex mtx;
    std::condition_variable cv;

    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdu_array(N);

    for (const auto& message : messages) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!cv.wait_for(lock, std::chrono::milliseconds(100))) {
            // wait and retry
        }

        try {
            // decrypt the message using Triple DES with given key and IV
            // ...

            // process the decrypted message
            int RNTI_val = 0; // get RNTI value from decrypted message

            // allocate a new PDU structure if not already allocated
            auto it = pdu_array.begin();
            while (it != pdu_array.end()) {
                if (it->RNTI == RNTI_val) {
                    break;
                }
                ++it;
            }

            if (it == pdu_array.end()) {
                // allocate a new PDU structure to avoid fragmentation
                // ...

                it = pdu_array.begin();
                while (it != pdu_array.end()) {
                    if (it->RNTI == RNTI_val) {
                        break;
                    }
                    ++it;
                }

                if (it == pdu_array.end()) {
                    std::cerr << "Memory allocation failed" << std::endl;
                    return;
                }
            }

            // populate the PDU structure
            it->RX_UE_INFORMATION_TAG = ...; // get RX_UE_INFORMATION_TAG from decrypted message
            it->RNTI = RNTI_val;
            it->CRCFLAG = (rand() % 2) == 1; // set CRCFLAG randomly

            // validate RNTI value against external data source
            // ...

            // signal the waiting thread that decryption and processing are complete
            cv.notify_one();
        } catch (...) {
            std::cerr << "Error occurred during message processing" << std::endl;
        }
    }

    // wait for all threads to finish before exiting
    while (true) {
        lock.lock();
        if (!cv.wait_for(lock, std::chrono::milliseconds(100))) {
            break;
        }
        lock.unlock();
    }
}

int main() {
    const std::string key = "your_key";
    const std::string iv = "your_iv";
    const std::vector<std::string> messages = {"message1", "message2", ...};
    int N = 10;

    process_messages(key, iv, messages, N);

    return 0;
}
