#include <string.h>

// Structure to represent Network Interface Status
typedef struct {
    char IpAddress[16];
    int Port;
    int ConnectionStatus;
} NetworkInterfaceStatus;

// Function to manage a dynamic collection of NetworkInterfaceStatus structures
void* networkInterfaces = NULL; // Global storage for the collection

int numNetworkInterfaces = 0; // Number of active interfaces

// Lock for thread-safe access to the collection
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Add a new network interface to the collection
void addNetworkInterface(NetworkInterfaceStatus* interface) {
    pthread_mutex_lock(&lock);

    NetworkInterfaceStatus** interfaces = (NetworkInterfaceStatus**)realloc(networkInterfaces, (numNetworkInterfaces + 1) * sizeof(NetworkInterfaceStatus*));
    if (!interfaces) {
        // Handle memory allocation error
        return;
    }

    interfaces[numNetworkInterfaces] = interface;
    networkInterfaces = interfaces;

    numNetworkInterfaces++;

    pthread_mutex_unlock(&lock);
}

// Update an existing network interface in the collection
void updateNetworkInterface(char* IpAddress, int Port, int ConnectionStatus) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numNetworkInterfaces; i++) {
        if (!strcmp(networkInterfaces[i]->IpAddress, IpAddress)) {
            networkInterfaces[i]->Port = Port;
            networkInterfaces[i]->ConnectionStatus = ConnectionStatus;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

// Retrieve a specific network interface by its IP address
NetworkInterfaceStatus* getNetworkInterface(char* IpAddress) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numNetworkInterfaces; i++) {
        if (!strcmp(networkInterfaces[i]->IpAddress, IpAddress)) {
            NetworkInterfaceStatus* interface = networkInterfaces[i];
            pthread_mutex_unlock(&lock);
            return interface;
        }
    }

    pthread_mutex_unlock(&lock);
    // Handle missing or invalid IP address
    return NULL;
}

// Monitor and report the current number of active connections
void reportActiveConnections() {
    pthread_mutex_lock(&lock);

    int activeConnections = 0;

    for (int i = 0; i < numNetworkInterfaces; i++) {
        if (networkInterfaces[i]->ConnectionStatus) {
            activeConnections++;
        }
    }

    printf("Current number of active connections: %d\n", activeConnections);

    pthread_mutex_unlock(&lock);
}

// Serialize the collection of NetworkInterfaceStatus structures
void serializeNetworkInterfaces() {
    FILE* file = fopen("network_interfaces.bin", "wb");

    if (!file) {
        // Handle file open error
        return;
    }

    fwrite(&numNetworkInterfaces, sizeof(int), 1, file);

    for (int i = 0; i < numNetworkInterfaces; i++) {
        NetworkInterfaceStatus* interface = networkInterfaces[i];

        fwrite(interface->IpAddress, sizeof(char) * 16, 1, file);
        fwrite(&interface->Port, sizeof(int), 1, file);
        fwrite(&interface->ConnectionStatus, sizeof(int), 1, file);
    }

    fclose(file);
}

// Deserialize the collection of NetworkInterfaceStatus structures
void deserializeNetworkInterfaces() {
    FILE* file = fopen("network_interfaces.bin", "rb");

    if (!file) {
        // Handle file open error
        return;
    }

    int numInterfaces;

    fread(&numInterfaces, sizeof(int), 1, file);

    for (int i = 0; i < numInterfaces; i++) {
        NetworkInterfaceStatus* interface = malloc(sizeof(NetworkInterfaceStatus));

        fread(interface->IpAddress, sizeof(char) * 16, 1, file);
        fread(&interface->Port, sizeof(int), 1, file);
        fread(&interface->ConnectionStatus, sizeof(int), 1, file);

        addNetworkInterface(interface);
    }

    fclose(file);
}
