// Global cache to store user sessions
UserSession** sessionCache;
int cacheSize = 0;

// Function prototypes
void addUserSession(UserSession* newSession);
void updateUserSession(char* token, UserSession* updatedSession);
UserSession* getSession(char* token);

// Initialize the cache with a default size
void initSessionCache(int initialCapacity) {
    sessionCache = (UserSession**)malloc(initialCapacity * sizeof(UserSession*));
    cacheSize = initialCapacity;
}

// Add a new user session to the cache
void addUserSession(UserSession* newSession) {
    // Check if the cache is full and needs to be resized
    if (cacheSize == 0 || cacheSize >= (int)(1.5 * sizeof(UserSession*) / sizeof(*newSession))) {
        int newSize = cacheSize + cacheSize / 2;
        sessionCache = (UserSession**)realloc(sessionCache, newSize * sizeof(UserSession*));
        cacheSize = newSize;
    }

    // Add the new session to the end of the cache
    if (cacheSize > 0) {
        sessionCache[cacheSize - 1] = newSession;
    } else {
        sessionCache[0] = newSession;
    }
    cacheSize++;
}

// Update an existing user session in the cache
void updateUserSession(char* token, UserSession* updatedSession) {
    int i;
    for (i = 0; i < cacheSize; i++) {
        if (strcmp(sessionCache[i]->SessionToken, token) == 0) {
            // Found the session, update it and move it to the front of the cache
            sessionCache[0] = updatedSession;
            for (int j = 1; j <= i; j++) {
                sessionCache[j - 1] = sessionCache[i];
            }
            memmove(&sessionCache[i], &sessionCache[i + 1], sizeof(UserSession*) * (cacheSize - i));
            break;
        }
    }
}

// Retrieve a user session by its token
UserSession* getSession(char* token) {
    int i;
    for (i = 0; i < cacheSize; i++) {
        if (strcmp(sessionCache[i]->SessionToken, token) == 0) {
            return sessionCache[i];
        }
    }
    return NULL;
}

