    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a unique RNTI
uint16_t generateUniqueRNTI(uint16_t start, uint16_t end) {
    uint16_t rnti = rand() % (end - start + 1) + start;
    return rnti;
}

// Function to generate the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** generateList(int n, int* total_size) {
    NFAPI_CRC_INDICATION_PDU_T **list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    *total_size = n;

    for (int i = 0; i < n; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Generate a unique RNTI
        uint16_t rnti_start = 1;
        uint16_t rnti_end = 65535; // adjust the range as needed
        list[i]->RNTI = generateUniqueRNTI(rnti_start, rnti_end);

        // Generate a random RX_UE_INFORMATION_TAG
        list[i]->RX_UE_INFORMATION_TAG = rand() % 256;

        // Generate a random CRC_INDICATION_REL8_TAG
        list[i]->CRC_INDICATION_REL8_TAG = rand() % 256;

        // Set the CRCFLAG randomly
        list[i]->CRCFLAG = rand() & 1;
    }

    return list;
}

// Function to serialize the list of NFAPI_CRC_INDICATION_PDU_T structures
int serializeList(NFAPI_CRC_INDICATION_PDU_T **list, int total_size) {
    FILE *fp = fopen("serialized_data.bin", "wb");

    if (fp == NULL)
        return -1;

    for (int i = 0; i < total_size; i++) {
        fwrite(&list[i]->RX_UE_INFORMATION_TAG, sizeof(uint8_t), 1, fp);
        fwrite(&list[i]->RNTI, sizeof(uint16_t), 1, fp);
        fwrite(&list[i]->CRC_INDICATION_REL8_TAG, sizeof(uint8_t), 1, fp);
        fwrite(&list[i]->CRCFLAG, sizeof(uint8_t), 1, fp);
    }

    fclose(fp);

    return 0;
}

int main() {
    srand(time(NULL)); // seed the random number generator

    int n = 10000; // adjust the list size as needed
    int total_size;
    NFAPI_CRC_INDICATION_PDU_T **list = generateList(n, &total_size);

    serializeList(list, total_size);

    for (int i = 0; i < total_size; i++) {
        free(list[i]);
    }

    free(list);

    return 0;
}

