// Structure to represent NetworkEvent
typedef struct {
    int id;
    time_t timestamp;
    int status;
} NetworkEvent;

// Function to add an event to the list
void network_event_list_add(NetworkEvent **events, int *size, int new_id) {
    if (*size == 0) {
        *events = (NetworkEvent *)malloc(sizeof(NetworkEvent));
        (*events)->id = new_id;
        (*events)->timestamp = time(NULL);
        (*events)->status = 1; // Initialize with status 1
        (*size)++;
    } else {
        NetworkEvent *new_event = (NetworkEvent *)malloc(sizeof(NetworkEvent));
        new_event->id = new_id;
        new_event->timestamp = time(NULL);
        new_event->status = 1; // Initialize with status 1

        NetworkEvent **temp_events = (NetworkEvent **)realloc(*events, (*size + 1) * sizeof(NetworkEvent *));
        temp_events[*size] = new_event;
        *events = temp_events;
        (*size)++;
    }
}

// Function to remove an event from the list
void network_event_list_remove(NetworkEvent **events, int *size, int id) {
    for (int i = 0; i < *size; i++) {
        if ((*events)[i]->id == id) {
            free((*events)[i]);
            NetworkEvent **temp_events = (NetworkEvent **)realloc(*events, (*size - 1) * sizeof(NetworkEvent *));
            for (int j = i; j < *size - 1; j++) {
                temp_events[j] = temp_events[j + 1];
            }
            *events = temp_events;
            (*size)--;

            return;
        }
    }
}

// Function to update the status of an event
void network_event_list_update(NetworkEvent **events, int *size, int id, int new_status) {
    for (int i = 0; i < *size; i++) {
        if ((*events)[i]->id == id) {
            (*events)[i]->status = new_status;
            return;
        }
    }
}
