typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int tag;
    unsigned int rnti;
    int crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfaapi_crc_indication_pdu_t_list = NULL;
int nfaapi_crc_indication_pdu_t_list_size = 0;
pthread_mutex_t nfaapi_crc_indication_pdu_t_list_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = fopen("error.log", "w");

void* allocate_memory(int size) {
    void* memory = malloc(size);
    if (memory == NULL) {
        // Handle memory allocation failure
        fclose(log_file);
        exit(EXIT_FAILURE);
    }
    return memory;
}

int nfaapi_crc_indication_pdu_t_list_init(int num_elements) {
    int i;
    NFAPI_CRC_INDICATION_PDU_T *p = allocate_memory(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (p == NULL) {
        return -1;
    }
    for (i = 0; i < num_elements; i++) {
        p[i].tag = -1;
        p[i].rnti = 0;
        p[i].crc_indication = 0;
    }
    nfaapi_crc_indication_pdu_t_list = p;
    nfaapi_crc_indication_pdu_t_list_size = num_elements;
    return 0;
}

int add_nfaapi_crc_indication_pdu_t_to_list(NFAPI_CRC_INDICATION_PDU_T *new_element) {
    pthread_mutex_lock(&nfaapi_crc_indication_pdu_t_list_lock);
    if (nfaapi_crc_indication_pdu_t_list_size >= MAX_NFAPI_CRC_INDICATION_PDU_T) {
        // Handle list overflow
        fprintf(log_file, "Error: NFAPI CRC Indication PDU T List Overflow\n");
        pthread_mutex_unlock(&nfaapi_crc_indication_pdu_t_list_lock);
        return -1;
    }
    if (new_element->rnti < RNTI_MIN || new_element->rnti > RNTI_MAX) {
        // Handle invalid RNTI value
        fprintf(log_file, "Error: Invalid RNTI Value %u\n", new_element->rnti);
        pthread_mutex_unlock(&nfaapi_crc_indication_pdu_t_list_lock);
        return -1;
    }
    nfaapi_crc_indication_pdu_t_list[nfaapi_crc_indication_pdu_t_list_size++] = *new_element;
    pthread_mutex_unlock(&nfaapi_crc_indication_pdu_t_list_lock);
