    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// List structure to manage dynamic list of NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int size;
    int capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_LIST_T;

// Initialize the list with at least 'N' elements, each containing a valid RX_UE_INFORMATION_TAG, RNTI, and a CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
void* nfapi_crc_indication_pdu_list_init(int N) {
    NFAPI_CRC_INDICATION_PDU_LIST_T* list = (NFAPI_CRC_INDICATION_PDU_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST_T));

    if (!list) return NULL;  // Handle memory allocation failure

    list->size = 0;
    list->capacity = N;
    pthread_mutex_init(&list->lock, NULL);

    // Initialize the list with at least 'N' elements
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list->elements) return NULL;  // Handle memory allocation failure

    for (int i = 0; i < list->size; i++) {
        list->elements[i].RX_UE_INFORMATION_TAG = rand() % 100;
        list->elements[i].RNTI = rand() % 100;
        list->elements[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        list->elements[i].CRCFLAG = rand() % 2;
    }

    return (void*)list;
}

// Append a new NFAPI_CRC_INDICATION_PDU_T to the list, handling memory allocation failures and ensuring thread safety
int nfapi_crc_indication_pdu_list_append(NFAPI_CRC_INDICATION_PDU_LIST_T* list) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {  // Handle memory allocation failure
        list->capacity *= 2;  // Double the capacity to optimize for space and time efficiency
        NFAPI_CRC_INDICATION_PDU_T* newElements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!newElements) return -1;  // Handle memory allocation failure

        list->elements = newElements;
    }

    NFAPI_CRC_INDICATION_PDU_T* newElement = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!newElement) return -1;  // Handle memory allocation failure

    list->elements[list->size].RX_UE_INFORMATION_TAG = rand() % 100;
    list->elements[list->size].RNTI = rand() % 100;
    list->elements[list->size].CRC_INDICATION_REL8_TAG = rand() % 100;
    list->elements[list->size].CRCFLAG = rand() % 2;

    list->size++;

    pthread_mutex_unlock(&list->lock);

    return 0;  // Successful allocation and addition
}

// Get the total number of elements in the list, including statistics on successful and failed allocations
int nfapi_crc_indication_pdu_list_get_size(NFAPI_CRC_INDICATION_PDU_LIST_T* list) {
    return list->size;
}

void nfapi_crc_indication_pdu_list_free(NFAPI_CRC_INDICATION_PDU_LIST_T* list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
