    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->contexts = (UEContext*)realloc(array->contexts, sizeof(UEContext) * array->capacity);
    }
    array->contexts[array->size] = context;
    array->size++;
}

void ueContextArrayUpdate(UEContextArray* array, int ue_id, UEContext newContext) {
    for (int i = 0; i < array->size; i++) {
        if (array->contexts[i].ue_id == ue_id) {
            array->contexts[i] = newContext;
            return;
        }
    }
}

UEContext* ueContextArraySearch(UEContextArray* array, int ue_id) {
    for (int i = 0; i < array->size; i++) {
