void realloc_list(int new_size) {
    void* ptr = realloc(nfapi_crc_indication_pdu_list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (ptr != NULL) {
        nfaapi_crc_indication_pdu_list = ptr;
        max_alloc_size = new_size;

        if (list_size < new_size)
            memset((void*)&nfaapi_crc_indication_pdu_list[list_size], 0, (new_size - list_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        fprintf(stderr, "Failed to reallocate memory.\n");
    }

    printf("Reallocated %d bytes for the dynamic list.\n", new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void validate_crc_flag(int idx) {
    if (nfaapi_crc_indication_pdu_list[idx].CRCFLAG > CRCFLAG_BOUNDS) {
        // Attempt to correct CRC flag
        nfaapi_crc_indication_pdu_list[idx].CRCFLAG &= CRCFLAG_BOUNDS;

        if (nfaapi_crc_indication_pdu_list[idx].CRCFLAG == 0) {
            printf("Corrected invalid CRC flag at index %d.\n", idx);
        } else {
            printf("Invalid CRC flag at index %d. Flag value: %x\n", idx, nfaapi_crc_indication_pdu_list[idx].CRCFLAG);

            // Fallback strategy: Remove the problematic structure from the list
            for (int i = idx; i < list_size - 1; i++) {
                memcpy(&nfaapi_crc_indication_pdu_list[i], &nfaapi_crc_indication_pdu_list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }

            list_size--;
        }
    }
}

void* manage_nfa_pi_crc_indication_pdu_list(void* arg) {
    int new_size = list_size * 2;

    if (new_size > MAX_LIST_SIZE)
        new_size = MAX_LIST_SIZE;

    if (new_size > max_alloc_size) {
        pthread_mutex_lock(&lock);

        realloc_list(new_size);

        pthread_mutex_unlock(&lock);
    }

    for (int i = 0; i < list_size; i++) {
        validate_crc_flag(i);
    }
}

void init_nfa_pi_crc_indication_pdu_list() {
    nfaapi_crc_indication_pdu_list = malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (nfaapi_crc_indication_pdu_list != NULL) {
        max_alloc_size = MAX_LIST_SIZE;

