#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define a structure to hold NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    // Add your structure fields here...
} NFAPI_CRC_INDICATION_PDU_T;

// Forward declaration of the linked list node
typedef struct _ListNode {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct _ListNode* next;
    struct _ListNode* prev;
} ListNode;

// Define a circular doubly-linked list
typedef struct {
    int size;
    int max_size;
    pthread_mutex_t lock;
    ListNode* head;
    ListNode* tail;
} CircularList;

void initialize_list(CircularList* list, int max_size) {
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
}

void insert_node(CircularList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);

    ListNode* new_node = (ListNode*) malloc(sizeof(ListNode));
    new_node->data = data;

    if (list->size == 0) {
        // Handle the first node
        new_node->next = NULL;
        new_node->prev = NULL;
        list->head = new_node;
        list->tail = new_node;
    } else {
        // Add the new node to the end of the list
        new_node->prev = list->tail;
        new_node->next = NULL;
        list->tail->next = new_node;
        new_node->data->RNTI = (rand() % 1000) + 1; // Randomly assign RNTI
        new_node->data->CRCFLAG = (rand() % 2); // Randomly set CRCFLAG

        if (list->size >= list->max_size) {
            // Remove the oldest entry to accommodate new ones
            ListNode* old_head = list->head;
            list->head = list->head->next;
            free(old_head);
            list->size--;
        } else {
            list->size++;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_node(CircularList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->size > 0) {
        ListNode* old_tail = list->tail;
        list->tail = list->tail->prev;
        list->tail->next = NULL;
        free(old_tail);
        list->size--;
    }

    pthread_mutex_unlock(&list->lock);
}

void print_list(CircularList* list) {
    pthread_mutex_lock(&list->lock);

    ListNode* current = list->head;
    while (current != NULL) {
        printf("RNTI: %d, CRCFLAG: %d\n", current->data->RNTI, current->data->CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
