#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    // Add your variables here
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for the linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with random CRCFLAG and timestamp
Node* newNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        return NULL; // Error allocating memory
    }
    newNode->data = data;
    newNode->next = NULL;
    time_t now = time(NULL);
    newNode->data.timestamp = now;
    int randomCRCFlag = rand() % 2; // Randomly set CRCFLAG (0 or 1)
    newNode->data.CRCFLAG = randomCRCFlag;
    return newNode;
}

// Function to insert a new node at the beginning of the list
void insert(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = newNode(data);
    if (*head == NULL || newNode->data.RX_UE_INFORMATION_TAG < (*head)->data.RX_UE_INFORMATION_TAG) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next && current->next->data.RX_UE_INFORMATION_TAG >= data.RX_UE_INFORMATION_TAG) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to delete a node with the given RNTI
void deleteNode(Node** head, int targetRNTI) {
    if (*head == NULL)
        return; // Node not found

    if ((*head)->data.RNTI == targetRNTI) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
        return;
    }

    Node* current = *head;
    while (current->next) {
        if (current->next->data.RNTI == targetRNTI) {
            Node* temp = current->next;
            current->next = current->next->next;
            free(temp);
            return;
        }
        current = current->next;
    }
}

// Function to clear the list
void clearList(Node** head) {
    while (*head) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
