#include <stdio.h>
#include <stdlib.h>

// Define structure for Network Connection Object (NCO)
typedef struct {
    char* peerAddress;
    int connectionID;
    int packetSizeHistory[100]; // adjustable capacity
} NCO;

// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int size;
    int count;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to add new session or update existing session with recent packet size observations
void manageSession(NCO** sessions, int* numSessions) {
    // Read input data (peer address and connection ID)
    char peerAddress[20];
    int connectionID;
    scanf("%19s %d", peerAddress, &connectionID);

    // Find or create a new session based on peer address and connection ID
    for (int i = 0; i < *numSessions; i++) {
        if (strcmp(sessions[i]->peerAddress, peerAddress) == 0 && sessions[i]->connectionID == connectionID) {
            // Update existing session with recent packet size observation
            int packetSize;
            scanf("%d", &packetSize);
            for (int j = 0; j < 100; j++) {
                sessions[i]->packetSizeHistory[j] = packetSize;
            }
            return;
        }
    }

    // Create a new session
    NCO* newSession = (NCO*)malloc(sizeof(NCO));
    strcpy(newSession->peerAddress, peerAddress);
    newSession->connectionID = connectionID;
    for (int j = 0; j < 100; j++) {
        scanf("%d", &packetSize);
        newSession->packetSizeHistory[j] = packetSize;
    }
    sessions[(*numSessions)++] = newSession;
}

// Function to compute rolling average packet size for all active sessions
void computeRollingAverage(NCO** sessions, int numSessions) {
    NFAPI_CRC_INDICATION_PDU_T* nfaPiIndications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    double rollingAverage;

    // Compute rolling average packet size for each session
    for (int i = 0; i < numSessions; i++) {
        int totalPacketSize = 0;
        for (int j = 0; j < 100; j++) {
            totalPacketSize += sessions[i]->packetSizeHistory[j];
        }
        rollingAverage = (double)totalPacketSize / 100;

        // Store the computed rolling average in an NFAPI_CRC_INDICATION_PDU_T structure
        nfaPiIndications->size = (int)(rollingAverage * 1024);
        nfaPiIndications->count++;
    }

    printf("NFAPI_CRC_INDICATION_PDU_T: size = %d, count = %d\n", nfaPiIndications->size, nfaPiIndications->count);

    free(nfaPiIndications);
}

int main() {
    int numSessions = 0;
    NCO** sessions = (NCO**)malloc(10 * sizeof(NCO*)); // adjustable capacity

    while (1) {
        // Read a list of integers from standard input
        int packetSize;
        scanf("%d", &packetSize);

        if (packetSize < 0) break; // stop reading when a negative value is encountered

        // Store the packet size in the corresponding session's packet size history array
        for (int i = 0; i < numSessions; i++) {
            sessions[i]->packetSizeHistory[(*numSessions % 100)] = packetSize;
        }

        if (numSessions >= 10) { // adjustable capacity
            NCO** newSessions = (NCO**)malloc(20 * sizeof(NCO*)); // adjustable capacity
            for (int i = 0; i < numSessions; i++) {
                newSessions[i] = sessions[i];
            }
            free(sessions);
            sessions = newSessions;
        }

        numSessions++;
    }

    // Find and print the largest packet size in the array
    int maxPacketSize = 0;
    for (int i = 0; i < numSessions; i++) {
        for (int j = 0; j < 100; j++) {
            if (sessions[i]->packetSizeHistory[j] > maxPacketSize) {
                maxPacketSize = sessions[i]->packetSizeHistory[j];
            }
        }
    }
    printf("Largest packet size: %d\n", maxPacketSize);

    // Manage sessions and compute rolling average packet size
    for (int i = 0; i < numSessions; i++) {
        manageSession(sessions, &numSessions);
    }
    computeRollingAverage(sessions, numSessions);

    return 0;
}
