#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structure for LTE RRC message
typedef struct {
    enum { INIT, UPDATE } type;
    int bytes_sent;
    int bytes_received;
} LTE_RRC_Message;

// Define structure for TCP session record
typedef struct {
    int connection_id;
    char peer_ip[16];
    int log_size;
    LTE_RRC_Message* messages;
} TCP_Session_Record;

// Function to manage dynamic list of TCP session records
TCP_Session_Record* tcp_session_manager(int max_sessions) {
    // Allocate memory for the first session record
    TCP_Session_Record* sessions = (TCP_Session_Record*)malloc(sizeof(TCP_Session_Record));
    sessions->connection_id = -1;
    sessions->peer_ip[0] = '\0';
    sessions->log_size = 0;
    sessions->messages = NULL;

    // Initialize dynamic array to store session records
    int current_sessions = 1;
    TCP_Session_Record** session_array = (TCP_Session_Record**)malloc(sizeof(TCP_Session_Record*) * max_sessions);

    // Function to add a new session record
    void add_session(int connection_id, char* peer_ip) {
        // Check if the maximum number of sessions has been reached
        if (current_sessions >= max_sessions) {
            printf("Error: Maximum number of sessions exceeded.\n");
            return;
        }

        // Allocate memory for a new session record
        TCP_Session_Record* new_session = (TCP_Session_Record*)malloc(sizeof(TCP_Session_Record));
        new_session->connection_id = connection_id;
        strcpy(new_session->peer_ip, peer_ip);
        new_session->log_size = 0;
        new_session->messages = NULL;

        // Update the dynamic array
        session_array[current_sessions] = new_session;
        current_sessions++;
    }

    // Function to update an existing session record
    void update_session(int connection_id, int bytes_sent, int bytes_received) {
        for (int i = 0; i < current_sessions; i++) {
            if (session_array[i]->connection_id == connection_id) {
                // Update the log size and byte counts for the corresponding session
                session_array[i]->log_size++;
                session_array[i]->messages[session_array[i]->log_size].type = UPDATE;
                session_array[i]->messages[session_array[i]->log_size].bytes_sent += bytes_sent;
                session_array[i]->messages[session_array[i]->log_size].bytes_received += bytes_received;
                return;
            }
        }
    }

    // Function to calculate the rolling bandwidth usage for all active sessions
    void calculate_bandwidth_usage() {
        int total_bytes_sent = 0;
        int total_bytes_received = 0;

        for (int i = 0; i < current_sessions; i++) {
            total_bytes_sent += session_array[i]->messages[session_array[i]->log_size].bytes_sent;
            total_bytes_received += session_array[i]->messages[session_array[i]->log_size].bytes_received;
        }

        // Calculate the rolling bandwidth usage and update the log size
        int bandwidth_usage = (total_bytes_sent + total_bytes_received) / 1024;
        for (int i = 0; i < current_sessions; i++) {
            session_array[i]->messages[session_array[i]->log_size].type = UPDATE;
            session_array[i]->messages[session_array[i]->log_size].bytes_sent += bandwidth_usage;
            session_array[i]->messages[session_array[i]->log_size].bytes_received += bandwidth_usage;
            session_array[i]->log_size++;
        }
    }

    // Function to parse a CSV file containing session metadata
    void read_csv_file(char* filename) {
        FILE* file = fopen(filename, "r");
        if (file == NULL) {
            printf("Error: Cannot open file %s.\n", filename);
            return;
        }

        char line[1024];
        while (fgets(line, 1024, file)) {
            // Parse the CSV line and add a new session record
            int connection_id = atoi(strtok(line, ","));
            char* peer_ip = strtok(NULL, ",");
            add_session(connection_id, peer_ip);
        }

        fclose(file);
    }

    return sessions;
}

int main() {
    int max_sessions = 1000; // Define the maximum number of concurrent sessions
    TCP_Session_Record* sessions = tcp_session_manager(max_sessions);

    // Read session metadata from a CSV file
    read_csv_file("session_data.csv");

    // Update an existing session record with recent traffic statistics
    update_session(123, 1024, 512);

    // Calculate the rolling bandwidth usage for all active sessions
    calculate_bandwidth_usage();

    return 0;
}

