        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu = (NFAPI_CRC_INDATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDATION_PDU_T));
