        nfapi_crc_indication_pdu[i].RNTI = rand() % 100;
        nfapi_crc_indation_pdu[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        nfapi_crc_indation_pdu[i].CRCFLAG = (char)rand() % 2;
    }

    return nfapi_crc_indication_pdu;
}

void free_NFAPICRCINDICATIONPDU(NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu, int nptrs) {
