#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct linked_list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct linked_list_node* next;
};

void* allocate_memory(void* arg) {
    pthread_mutex_lock(arg);
    struct linked_list_node* new_node = (struct linked_list_node*)malloc(sizeof(struct linked_list_node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* data = &new_node->data;
    strcpy(data->RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
    data->RNTI = rand() % 1000; // Generate a random RNTI
    srand(time(NULL));
    data->CRCFLAG = (unsigned char)rand();
    pthread_mutex_unlock(arg);
    return new_node;
}

void check_duplicate_RNTI(struct linked_list_node** head, int RNTI) {
    struct linked_list_node* current = *head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            free(current);
            current = current->next;
            *head = current;
            return;
        }
        current = current->next;
    }
}

void print_linked_list(struct linked_list_node* head, int num_allocs, int num_duplicates) {
    struct linked_list_node* current = head;
    printf("Linked List:\n");
    while (current != NULL) {
        printf("%s RNTI: %d CRCFLAG: %x\n", current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }
    printf("Number of successful allocations: %d\n", num_allocs);
    printf("Number of rejected allocations due to duplicates: %d\n", num_duplicates);
}

int main() {
    int N; // Number of NFAPI_CRC_INDICATION_PDU_T structures
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL)); // Seed the random number generator

    printf("Enter the number of NFAPI_CRC_INDICATION_PDU_T structures: ");
    scanf("%d", &N);

    struct linked_list_node* head = NULL;
    int num_allocs = 0, num_duplicates = 0;
    clock_t start_time = clock();
    for (int i = 0; i < N; i++) {
        struct linked_list_node* new_node = allocate_memory(&lock);
        if (!new_node) break;
        if (check_duplicate_RNTI(&head, new_node->data.RNTI)) {
            free(new_node);
            continue;
        }
        head = new_node;
        num_allocs++;
    }
    clock_t end_time = clock();
    double processing_time = ((double)(end_time - start_time)) / CLOCKS_PER_SEC * 1000; // Convert time from clock ticks to milliseconds
    print_linked_list(head, num_allocs, num_duplicates);

    return 0;
}
