    if (contains_session(session_list, session_id)) {
        printf("Error: Duplicate session ID detected.\n");
        return;
    }

    SessionData* new_session = (SessionData*)malloc(sizeof(SessionData));
    new_session->session_id = strdup(session_id);
    new_session->connection_details = NULL; // Initialize with NULL for now
    new_session->throughput = 0.0;
    new_session->latency = 0.0;

    if (*list == NULL) {
        *list = new_session;
    } else {
        new_session->prev = *list;
        new_session->next = (*list)->next;
        (*list)->next->prev = new_session;
        (*list)->next = new_session;
    }

    printf("Session added successfully.\n");
}

