    if (!pduArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pduArray[i];

        // Generate unique RX_UE_INFORMATION_TAG and RNTI values
        int32_t rnti = rand() % 100;
        uint8_t tag = (uint8_t)(rand() % 256);

        while (findPduByTagAndRnti(pduArray, n, tag, rnti)) {
            // Regenerate RNTI and TAG values until no duplicates found
            rnti = rand() % 100;
            tag = (uint8_t)(rand() % 256);
        }

        pdu->tag = tag;
        pdu->rnti = rnti;
    }

    return pduArray;
}

bool findPduByTagAndRnti(NFAPI_CRC_INDICATION_PDU_T* pduArray, int32_t n, uint8_t tag, int32_t rnti) {
    for (int i = 0; i < n; i++) {
        if ((pduArray[i].tag == tag) && (pduArray[i].rnti == rnti)) {
            return true;
        }
    }

    return false;
}

void setPduCRCFlag(NFAPI_CRC_INDICATION_PDU_T* pdu, bool useTagContent, float randomProbability) {
