        // Set CRCFLAG randomly
        pdu->crcFlag = rand() % 2;
    } else {
        // Set CRCFLAG based on RX_UE_INFORMATION_TAG and RNTI values
        if ((pdu->tag & 0x01) && (pdu->rnti % 4 == 0)) {
            pdu->crcFlag = 1;
        } else {
            pdu->crcFlag = 0;
        }
    }
}

