    // Dynamically allocate memory for the array of UDP packets
    udp_packet **packets = (udp_packet **)malloc(num_packets * sizeof(udp_packet *));

    if (!packets) {
        // Handle allocation failure
        return NULL;
    }

    // Initialize each packet in the array
    for (int i = 0; i < num_packets; i++) {
        packets[i] = (udp_packet *)malloc(sizeof(udp_packet));

        if (!packets[i]) {
            // Handle allocation failure
            return NULL;
        }

        // Validate and set initial packet values
        packets[i]->source_ip = 0; // Initialize source IP address
        packets[i]->dest_ip = 0; // Initialize destination IP address
        packets[i]->port = 0; // Initialize port number
        packets[i]->protocol = 0; // Initialize protocol type
        packets[i]->payload_checksum = 0; // Initialize payload checksum

    }

    return packets;
}

// Function to free dynamically allocated array of UDP packet structures
void free_udp_packets(udp_packet **packets, int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        if (packets[i]) {
            free(packets[i]); // Free each individual packet
        }
    }

    if (packets) {
        free(packets); // Free the array of packets
    }
}

// Function to validate and process UDP packets in parallel using multiple threads
void* process_packets(void *arg) {
    int num_packets = *((int *)arg);
    udp_packet **packets = init_udp_packets(num_packets);

    if (!packets) {
        // Handle allocation failure
        return NULL;
    }

    // Process packets concurrently using threads
    pthread_t thread[num_packets];
    for (int i = 0; i < num_packets; i++) {
        pthread_create(&thread[i], NULL, process_packet, &packets[i]);
    }

    for (int i = 0; i < num_packets; i++) {
        pthread_join(thread[i], NULL);
    }

    free_udp_packets(packets, num_packets);

    return NULL;
}

