#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* crc_indications;
    int num_crc_indications;
} NFAPI_RX_FRAME;

void init_nfapi_rx_frame(int N, NFAPI_RX_FRAME** nfapi_rx_frames) {
    *nfapi_rx_frames = (NFAPI_RX_FRAME*)malloc(sizeof(NFAPI_RX_FRAME));

    (*nfapi_rx_frames)->crc_indications = 
        (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*N);

    for(int i = 0; i < N; i++) {
        // Initialize CRCFLAG randomly
        srand(time(NULL));
        (*nfapi_rx_frames)->crc_indications[i].CRCFLAG = rand() % 2;
    }

    (*nfapi_rx_frames)->num_crc_indications = N;
}

int main() {
    int N = 10000; // Set the desired number of CRC indications
    NFAPI_RX_FRAME* nfapi_rx_frame;

