#define MAX_CAPACITY 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int size = 0;

void insert(struct node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return;
    }
    new_node->data = data;
    new_node->next = *head;
    *head = new_node;
    size++;
    pthread_mutex_unlock(&lock);
}

void removeOldest(struct node** head) {
    pthread_mutex_lock(&lock);
    if (size > MAX_CAPACITY) {
        struct node* temp = *head;
        *head = (*head)->next;
        free(temp);
        size--;
    }
    pthread_mutex_unlock(&lock);
}

void destroyList(struct node** head) {
    pthread_mutex_lock(&lock);
    while (*head) {
        struct node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
    size = 0;
    pthread_mutex_unlock(&lock);
}
