    NetworkEventRecord* newRecord = (NetworkEventRecord*)malloc(sizeof(NetworkEventRecord));
    if (!newRecord) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Copy the new record into the list
    memcpy(newRecord, record, sizeof(NetworkEventRecord));

    // Check if this is the first record in the list or not
    if (!networkEventList) {
        networkEventList = newRecord; // If this is the first record, update the list pointer
    } else {
        NetworkEventRecord* currentRecord = networkEventList;
        while (currentRecord->next) {
            currentRecord = currentRecord->next;
        }
        currentRecord->next = newRecord; // Add the new record to the end of the list
    }
}

void removeRecord(int eventId) {
    if (!networkEventList) return;

    NetworkEventRecord* currentRecord = networkEventList;
    while (currentRecord && currentRecord->eventId != eventId) {
        currentRecord = currentRecord->next;
    }

    // If the record was found, update the list
    if (currentRecord) {
        if (networkEventList == currentRecord) { // Remove the first record
            networkEventList = currentRecord->next;
        } else { // Remove a middle or last record
            NetworkEventRecord* previousRecord = networkEventList;
            while (previousRecord->next != currentRecord) {
                previousRecord = previousRecord->next;
            }
            previousRecord->next = currentRecord->next;
        }

        free(currentRecord); // Free the memory allocated for the removed record
    }
}

