    char payload[1024];
} MME_MESSAGES_T;

// Function to dynamically manage a list of LTE_RRC_UECONTEXT_T structures
void ue_context_manager(LTE_RRC_UECONTEXT_T** ue_contexts, int* size) {
    // Add new structure
    void add_ue_context(LTE_RRC_UECONTEXT_T** ue_contexts, int* size) {
        *size += 1;
        LTE_RRC_UECONTEXT_T* new_ue_context = (LTE_RRC_UECONTEXT_T*)malloc(sizeof(LTE_RRC_UECONTEXT_T));
        (*ue_contexts)[*size - 1] = new_ue_context;
    }

    // Remove UE context based on UE ID
    void remove_ue_context(LTE_RRC_UECONTEXT_T** ue_contexts, int* size, uint32_t ue_id) {
        for (int i = 0; i < *size; i++) {
            if ((*ue_contexts)[i]->ue_id == ue_id) {
                free((*ue_contexts)[i]);
                memmove(&(*ue_contexts)[i], &(*ue_contexts)[i + 1], (*size - i - 1) * sizeof(LTE_RRC_UECONTEXT_T));
                *size -= 1;
                break;
            }
        }
    }

    // Update payload for a specific sequence number within a UE's message list
    void update_payload(LTE_RRC_UECONTEXT_T** ue_contexts, int* size, uint32_t ue_id, uint16_t sequence_number, char* new_payload) {
        for (int i = 0; i < *size; i++) {
            if ((*ue_contexts)[i]->ue_id == ue_id && (*ue_contexts)[i]->mme_messages != NULL) {
                for (MME_MESSAGES_T* message = (*ue_contexts)[i]->mme_messages; message; ) {
                    if (message->sequence_number == sequence_number) {
                        free(message);
                        char* new_payload_buffer = (char*)malloc(strlen(new_payload) + 1);
                        strcpy(new_payload_buffer, new_payload);
                        MME_MESSAGES_T* new_message = (MME_MESSAGES_T*)malloc(sizeof(MME_MESSAGES_T));
                        new_message->sequence_number = sequence_number;
                        strcpy(new_message->payload, new_payload_buffer);
                        free(message);
                        message = new_message;
                    }
                }
            }
        }
    }

    // Serialize and deserialize the entire list to and from a file
    void serialize_ue_contexts(LTE_RRC_UECONTEXT_T** ue_contexts, int* size) {
        FILE* file = fopen("ue_contexts.bin", "wb");
        fwrite(*ue_contexts, sizeof(LTE_RRC_UECONTEXT_T), *size, file);
