    DeviceSessionData** buckets;
    pthread_mutex_t lock;
    size_t num_collisions;
} HashTable;

HashTable* create_hash_table(size_t table_size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->table_size = table_size;
    ht->buckets = (DeviceSessionData**)calloc(table_size, sizeof(DeviceSessionData*));
    ht->num_collisions = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void hash_table_insert(HashTable* ht, DeviceSessionData* data) {
    uint64_t key = data->deviceID;
    size_t index = ht->func(key, ht->table_size);
    pthread_mutex_lock(&ht->lock);
    if (ht->buckets[index] == NULL) {
        // New entry, no collision
        ht->buckets[index] = data;
    } else {
        // Collision detected
        DeviceSessionData* collided_data = ht->buckets[index];
        // ... handle collision resolution ...
        ht->num_collisions++;
    }
    pthread_mutex_unlock(&ht->lock);
}

void hash_table_delete(HashTable* ht, uint64_t deviceID) {
    pthread_mutex_lock(&ht->lock);
    for (size_t i = 0; i < ht->table_size; i++) {
        if (ht->buckets[i] != NULL && ht->buckets[i]->deviceID == deviceID) {
