```c
#include <iostream>
#include <list>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>

class NFAPI_CRC_INDICATION_PDU_T {
public:
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
};

class NFARangeManager {
private:
    std::list<NFAPI_CRC_INDICATION_PDU_T> ranges;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<int> totalProcessingTime;

public:
    void addRange(NFAPI_CRC_INDICATION_PDU_T range) {
        // lock and check for duplicate RNTI
        std::unique_lock<std::mutex> lock(mtx);
        if (std::find_if(ranges.begin(), ranges.end(),
                         [&range](const NFAPI_CRC_INDICATION_PDU_T& existingRange) {
                             return existingRange.RNTI == range.RNTI;
                         }) != ranges.end()) {
            // reject duplicate RNTI
            std::cout << "Rejected due to duplicate RNTI: " << range.RNTI << std::endl;
        } else {
            ranges.push_back(range);
            totalProcessingTime++;
        }
    }

    void removeRange(int RNTI) {
        // lock and find the range by RNTI
        std::unique_lock<std::mutex> lock(mtx);
        auto it = std::find_if(ranges.begin(), ranges.end(),
                               [RNTI](const NFAPI_CRC_INDICATION_PDU_T& range) {
                                   return range.RNTI == RNTI;
                               });
        if (it != ranges.end()) {
            ranges.erase(it);
        }
    }

    void updateRange(int RNTI, int newMinValue, int newMaxValue) {
        // lock and find the range by RNTI
        std::unique_lock<std::mutex> lock(mtx);
        auto it = std::find_if(ranges.begin(), ranges.end(),
                               [RNTI](const NFAPI_CRC_INDICATION_PDU_T& range) {
                                   return range.RNTI == RNTI;
                               });
        if (it != ranges.end()) {
            // update the range
            it->RX_UE_INFORMATION_TAG = newMinValue;
            it->maxValue = newMaxValue;
        }
    }

    void resetRange(int RNTI) {
        // lock and find the range by RNTI
        std::unique_lock<std::mutex> lock(mtx);
        auto it = std::find_if(ranges.begin(), ranges.end(),
                               [RNTI](const NFAPI_CRC_INDICATION_PDU_T& range) {
                                   return range.RNTI == RNTI;
                               });
        if (it != ranges.end()) {
            // reset the range to default settings
            it->RX_UE_INFORMATION_TAG = 0;
            it->maxValue = 0;
        }
    }

    int getProcessingTime() const {
        return totalProcessingTime.load();
    }

    void reportProcessingTime() {
        std::cout << "Total processing time: " << totalProcessingTime.load() << " milliseconds" << std::endl;
    }

private:
    struct RangeComparator {
        bool operator()(const NFAPI_CRC_INDICATION_PDU_T& a, const NFAPI_CRC_INDICATION_PDU_T& b) {
            return a.RNTI < b.RNTI;
        }
    };
};

int main() {
    NFARangeManager rangeManager;

    // add ranges
    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T range;
        range.RX_UE_INFORMATION_TAG = i * 100 + 1;
        range.RNTI = i % 2;
        range.CRCFLAG = rand() % 256;
        rangeManager.addRange(range);
    }

    // remove ranges
    for (int i = 0; i < 5; i++) {
        rangeManager.removeRange(i % 2);
    }

    // update ranges
    for (int i = 0; i < 3; i++) {
        NFAPI_CRC_INDICATION_PDU_T range;
        range.RX_UE_INFORMATION_TAG = i * 100 + 1;
        range.RNTI = i % 2;
        range.CRCFLAG = rand() % 256;
        rangeManager.updateRange(i % 2, range.RX_UE_INFORMATION_TAG, range.maxValue);
    }

    // reset ranges
    for (int i = 0; i < 2; i++) {
        rangeManager.resetRange(i % 2);
    }

    // report processing time
    rangeManager.reportProcessingTime();

    return 0;
}
