typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
int node_count = 0;
int total_memory_footprint = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert_node(Node** head, Node* new_node) {
    if (*head == NULL) {
        *head = new_node;
        *tail = new_node;
    } else {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    }
}

void remove_node(Node** head, Node* node_to_remove) {
    if (node_to_remove == *head) {
        *head = node_to_remove->next;
    }
    if (node_to_remove == *tail) {
        *tail = node_to_remove->prev;
    }
    node_to_remove->prev->next = node_to_remove->next;
    node_to_remove->next->prev = node_to_remove->prev;
    free(node_to_remove);
}

void* thread_function(void* arg) {
    // Perform operations on the list
    pthread_mutex_lock(&lock);
    Node* current_node = head;
    while (current_node != NULL) {
        // Process the node's data
        if (current_node->data.CRCFLAG < 0x80) {
            // Remove old nodes based on time threshold
            if (time(NULL) - current_node->data.timestamp > TIME_THRESHOLD) {
                remove_node(&head, current_node);
                total_memory_footprint -= sizeof(Node);
                node_count--;
            }
        } else {
            // Insert new node
            Node* new_node = malloc(sizeof(Node));
            new_node->data = current_node->data;
            insert_node(&head, new_node);
            total_memory_footprint += sizeof(Node);
            node_count++;
        }
        current_node = current_node->next;
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

int get_active_entry_count() {
    return node_count;
}

long get_total_memory_footprint() {
    return total_memory_footprint;
}

void log_status() {
    LOG_INFO("Active entries: %d, Total memory footprint: %ld", node_count, total_memory_footprint);
}

void profiler_start() {
    PERFORMANCE_PROFILER_START();
}

void profiler_stop() {
    PERFORMANCE_PROFILER_STOP();
}
