#define MAX_LIST_SIZE 5000
#define LOGGING_FREQUENCY 10 // adjust this value based on your requirements

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t hash_mutex = PTHREAD_MUTEX_INITIALIZER;
int num_elements = 0;

// Custom hash table implementation
typedef struct {
    int RNTI;
    Node* node;
} HashEntry;

HashEntry* hash_table[1024]; // assume 2^10 (1024) is enough for your use case

void insert_node(Node* new_node) {
    pthread_mutex_lock(&list_mutex);

    if (num_elements >= MAX_LIST_SIZE) {
        printf("List full, cannot insert node.\n");
        return;
    }

    Node* current = head;
    Node* prev = NULL;

    while (current != NULL && current->data.RNTI < new_node->data.RNTI) {
        prev = current;
        current = current->next;
    }

    if (prev == NULL || prev->data.RNTI == new_node->data.RNTI) {
        // Collision detected, handle it
        int idx = new_node->data.RNTI % 1024;

        pthread_mutex_lock(&hash_mutex);
        HashEntry* entry = hash_table[idx];

        while (entry != NULL && entry->RNTI < new_node->data.RNTI) {
            entry = entry->next;
        }

        if (entry == NULL || entry->RNTI == new_node->data.RNTI) {
            // Duplicate RNTI, handle it
            printf("Duplicate RNTI detected, cannot insert node.\n");
            pthread_mutex_unlock(&hash_mutex);
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        // Insert new node into hash table and linked list
        if (entry == NULL) {
            entry = malloc(sizeof(HashEntry));
            entry->RNTI = new_node->data.RNTI;
            entry->node = new_node;
            hash_table[idx] = entry;
        } else {
            entry->next = new_node;
            prev->next = new_node;
        }

        pthread_mutex_unlock(&hash_mutex);
    } else {
        // No collision, just insert node into linked list
        if (prev == NULL) {
            head = new_node;
        } else {
            prev->next = new_node;
        }
    }

    num_elements++;
    pthread_mutex_unlock(&list_mutex);
}

void log_operation(char* message) {
    // implement your logging mechanism here
    printf("%s\n", message);
}

int search_node(int RNTI) {
    pthread_mutex_lock(&hash_mutex);

    int idx = RNTI % 1024;
    HashEntry* entry = hash_table[idx];

    while (entry != NULL && entry->RNTI < RNTI) {
        entry = entry->next;
    }

    if (entry == NULL || entry->RNTI != RNTI) {
        pthread_mutex_unlock(&hash_mutex);
        return -1; // not found
    }

    Node* node = entry->node;
    pthread_mutex_unlock(&hash_mutex);
    return node->data.RX_UE_INFORMATION_TAG; // or any other desired value
}

void* thread_function(void* arg) {
    // implement your thread function here, e.g., inserting nodes into the list
    insert_node((Node*)arg);

    if (num_elements % LOGGING_FREQUENCY == 0) {
        log_operation("Inserted node(s).");
    }

    return NULL;
}

int main() {
    pthread_t threads[MAX_LIST_SIZE];

    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        Node* new_node = malloc(sizeof(Node));
        // initialize your node structure here
        pthread_create(&threads[i], NULL, thread_function, new_node);
    }

    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
