```javascript
function copyDataChunks(chunks, numBytesToCopy) {
  const buffer = new Uint8Array(numBytesToCopy);
  let bytesRead = 0;
  for (let chunk of chunks) {
    if (!chunk || chunk.length === 0) continue;
    const bytesCopied = Math.min(chunk.length, numBytesToCopy - bytesRead);
    buffer.set(new Uint8Array(chunk.subarray(0, bytesCopied)), bytesRead);
    bytesRead += bytesCopied;
  }
  return buffer.buffer;
}
