    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG[9] = '\0'; // null-terminate the string
        int rnti = rand() % 65536;
        if (rnti < 1 || rnti > 65535) { // validate RNTI range
            printf("Invalid RNTI: %d\n", rnti);
            continue; // skip this element
        }
        list[i].RNTI = rnti;

        int tag_id = rand() % 1000;
        if (tag_id < 1 || tag_id > 999) { // validate RX_UE_INFORMATION_TAG range
            printf("Invalid RX_UE_INFORMATION_TAG: %d\n", tag_id);
            continue; // skip this element
        }
        sprintf(list[i].RX_UE_INFORMATION_TAG, "TAG_%03d", tag_id);

        list[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        list[i].CRCFLAG = rand() % 2;

        // simulate database query and potential failures
        int retries = 5;
        while (retries--) {
            int db_result = rand() % 2; // assume 50% success rate
            if (db_result) break; // got a valid result, move on
            printf("Database failure! Retrying...\n");
            if (!retries) return NULL; // timeout reached, fail
        }
    }

    // shuffle the list
    srand(time(NULL)); // reseed for shuffling
    int* indices = (int*)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        indices[i] = i;
    }
    for (int i = N - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        int temp = indices[j];
        indices[j] = indices[i];
        indices[i] = temp;
    }

    // duplicate-free shuffling
    NFAPI_CRC_INDICATION_PDU_T* shuffled_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        int j = indices[i];
        if (!shuffled_list[j].CRCFLAG) { // prevent duplicates
            shuffled_list[j] = list[indices[i]];
        } else {
            printf("Duplicate detected! Skipping...\n");
            continue;
        }
    }

    free(list);
    free(indices);

    return shuffled_list;
}

void export_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    FILE* file = fopen("output.bin", "wb"); // create binary output file
    if (!file) return; // handle file opening failure

    fwrite(&N, sizeof(int), 1, file); // write the list size
    for (int i = 0; i < N; i++) {
        fwrite(&list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);

    int checksum = 0;
    FILE* read_file = fopen("output.bin", "rb"); // open the binary output file for reading
    if (!read_file) return; // handle file opening failure

    fread(&N, sizeof(int), 1, read_file); // read the list size
    for (int i = 0; i < N; i++) {
        fread(&list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, read_file);
        checksum += list[i].CRCFLAG; // calculate the checksum
    }

    fclose(read_file);

    if (checksum != N) { // verify the checksum
        printf("Data integrity failure! Checksum mismatch.\n");
    } else {
        printf("Data verification successful!\n");
    }
}

int main() {
    int N = 100; // sample list size
    NFAPI_CRC_INDICATION_PDU_T* list = generate_list(N);
    if (!list) return 1; // handle failure

