int add_structures(NFAPI_CRC_INDICATION_PDU_T **primary_list, size_t *primary_count,
                   NFAPI_CRC_INDICATION_PDU_T **secondary_list, size_t *secondary_count,
                   int N, int M) {
    for (size_t i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_struct->RX_UE_INFORMATION_TAG = rand() % 100;
        new_struct->RNTI = rand() % 100;
        new_struct->CRC_INDICATION_REL8_TAG = rand() % 100;
        new_struct->CRCFLAG = rand() % 2;

        if (*primary_count < N) {
            for (size_t j = 0; j < *primary_count; j++) {
                if ((new_struct->RX_UE_INFORMATION_TAG == primary_list[0][j].RX_UE_INFORMATION_TAG &&
                     new_struct->RNTI == primary_list[0][j].RNTI) ||
                    (secondary_count > 0 && secondary_list[0][i % *secondary_count] != NULL &&
                     (new_struct->RX_UE_INFORMATION_TAG == secondary_list[0][i % *secondary_count]->RX_UE_INFORMATION_TAG &&
                      new_struct->RNTI == secondary_list[0][i % *secondary_count]->RNTI))) {
                    free(new_struct);
                    for (size_t k = i; k < N - 1; k++) {
                        primary_list[0][k] = primary_list[0][k + 1];
                        if (k < M - 1 && secondary_count > 0) {
                            secondary_list[0][k] = secondary_list[0][k + 1];
                        }
                    }
                    i--;
                    break;
                }
            }
        } else {
            for (size_t j = i; j >= 0; j--) {
                primary_list[0][j] = primary_list[0][j - 1];
                if (j > M && secondary_count > 0) {
                    secondary_list[0][j] = secondary_list[0][j - 1];
                }
            }
            i--;
        }

        if (*primary_count < N) {
            *primary_list = realloc(*primary_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 2));
            primary_list[0][i] = new_struct;
            (*primary_count)++;
            if (*secondary_count < M) {
                *secondary_list = realloc(*secondary_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (M + 1));
                secondary_list[0][*secondary_count] = new_struct;
                (*secondary_count)++;
            }
        }

    }
    return *primary_count;
}
