int generateList(int n, size_t maxThreshold, struct NFAPI_CRC_INDICATION_PDU_T** list) {
    if (n <= 0 || !list) return -1; // invalid number of items or null pointer
    size_t totalBytes = n * sizeof(struct NFAPI_CRC_INDICATION_PDU_T);

    if (totalBytes > maxThreshold) return -2; // exceeds maximum threshold

