    for (int i = 0; i < n; ++i) {
        tempList[i].RX_UE_INFORMATION_TAG = rand() % 256;
        int rnti = rand();
        while (rnti > 0x7FFF) rnti -= 0x8000; // ensure uniqueness
        tempList[i].RNTI = rnti;
        tempList[i].CRCFLAG = rand() % 2 ? CRCFLAG_ON : CRCFLAG_OFF;
