NFAPI_CRC_INDICATION_PDU_T* generateList(int N) {
    // Initialize the list
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the external data source for RX_UE_INFORMATION_TAG values
    FILE* file = fopen("data.txt", "r");
    char* buffer = (char*)malloc(32);
    int idx = 0;

    // Dynamically generate a list of NFAPI_CRC_INDICATION_PDU_T structures
    for(int i = 0; i < N; i++) {
        // Generate RX_UE_INFORMATION_TAG value from the external data source
        fread(buffer, 1, 32, file);
        strcpy(list[i].RX_UE_INFORMATION_TAG, buffer);

        // Generate RNTI and CRC_INDICATION_REL8_TAG values
        list[i].RNTI = rand() % 1000;
        srand(time(NULL));
        sprintf(list[i].CRC_INDICATION_REL8_TAG, "%02X", (uint16_t)rand());

        // Check for duplicate RX_UE_INFORMATION_TAG values
        if(idx > 0 && !strcmp(buffer, list[idx-1].RX_UE_INFORMATION_TAG)) {
            i--; // Roll back and regenerate the value
            continue;
        }

        idx++;
    }

    // Close the file and free memory
    fclose(file);
    free(buffer);

    return list;
}

