#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[5];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create a new node with random CRCFLAG
NFAPI_CRC_INDICATION_PDU_T* create_node(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    // Initialize random CRCFLAG
    node->CRCFLAG = rand() % 2;

    // Assign valid RX_UE_INFORMATION_TAG and RNTI
    node->RX_UE_INFORMATION_TAG = (int)(rand() % 1000);
    node->RNTI = RNTI;
    sprintf(node->CRC_INDICATION_REL8_TAG, "%04x", rand());

    return node;
}

// Function to insert a new node at the end of the linked list
void insert_node(NFAPI_CRC_INDICATION_PDU_T** head, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* node = create_node(RNTI);
    if (!node || *head == NULL) return;

    // Check for duplicate RNTI
    for (NFAPI_CRC_INDICATION_PDU_T* temp = *head; temp != NULL; temp = temp->next) {
        if (temp->RNTI == node->RNTI) {
            free(node);
            return;
        }
    }

    // Check if the list exceeds maximum threshold
    size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) + (*head ? *head->next : 0);
    if (total_size > 1024*1024*10) { // 10MB threshold
        free(node);
        return;
    }

    node->next = *head;
    *head = node;
}

// Function to delete a node from the linked list
void delete_node(NFAPI_CRC_INDICATION_PDU_T** head, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    NFAPI_CRC_INDICATION_PDU_T* previous = NULL;

    while (current != NULL && current->RNTI != RNTI) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (previous) previous->next = current->next;
    else *head = current->next;

    free(current);
}

// Function to monitor memory usage and performance
void monitor_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) + (head ? head->next : 0);
    printf("Total list size: %zu bytes\n", total_size);

    if (total_size > 1024*1024*10) { // 10MB threshold
        printf("Memory usage exceeds threshold, alerting system...\n");
    }
}
