} NFAPI_CRC_INDICATION_PDU_T;

void initialize_and_configure_mac_entities(int num_entities) {
    MAC_CONTEXT_T* mac_entities = (MAC_CONTEXT_T*)malloc(num_entities * sizeof(MAC_CONTEXT_T));
    L1_CONTEXT_T** l1_contexts = (L1_CONTEXT_T**)malloc(num_entities * sizeof(L1_CONTEXT_T*));

    for (int i = 0; i < num_entities; i++) {
        mac_entities[i].validity_flag = rand() % 2;

        l1_contexts[i] = (L1_CONTEXT_T*)malloc(sizeof(L1_CONTEXT_T));
        l1_contexts[i]->tx_power = rand() % 10 + 1;
    }

    // Initialize linked list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_entities * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_entities; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % 100;
        crc_indications[i].RNTI = (rand() % (MAX_RNTI - MIN_RNTI + 1)) + MIN_RNTI;

        if (crc_indications[i].RNTI < MIN_RNTI || crc_indications[i].RNTI > MAX_RNTI) {
            printf("Invalid RNTI value: %d\n", crc_indications[i].RNTI);
            return;
        }

        crc_indications[i].CRCFLAG = CRCFLAG_DEFAULT;
    }

    // Validate CRCFLAG consistency across the linked list
    for (int i = 0; i < num_entities; i++) {
        if (crc_indications[i].CRCFLAG != CRCFLAG_DEFAULT) {
            printf("Invalid CRCFLAG value: %d\n", crc_indications[i].CRCFLAG);
            return;
        }
    }

    // Populate the linked list with data
