    rewind(file);

    NFAPI_CRC_INDICATION_PDU_T* rx_info_list = (NFAPI_CRC_INDATION_PDU_T*)calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    if (!rx_info_list) return -2; // error allocating memory

    fread(&rx_info_list->rx_ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file);
    fread(&rx_info_list->rnti, sizeof(RNTI), 1, file);
    fread(&rx_info_list->crc_indication_rel8_tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);

    for (int i = 0; i < count; i++) {
        rx_info_list[i].CRCFLAG = rand() % 2;
    }

    fclose(file);
    return count;
