NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indications = NULL;
size_t nfapi_crc_indications_size = 0;
size_t nfapi_crc_indications_capacity = 0;
atomic_flag nfapi_crc_indications_lock = ATOMIC_FLAG_INIT;

void nfapi_crc_indication_init(size_t initial_capacity) {
    nfapi_crc_indications_capacity = initial_capacity;
    nfapi_crc_indications = aligned_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), nfapi_crc_indications_capacity);
}

void nfapi_crc_indication_insert(NFAPI_CRC_INDICATION_PDU_T* new_pdu) {
    if (atomic_compare_exchange_strong(&nfapi_crc_indications_lock, 0, 1)) {
        size_t i = 0;
        while (i < nfapi_crc_indications_size && nfapi_crc_indications[i].ue_info != new_pdu->ue_info) {
            i++;
        }
        if (i == nfapi_crc_indications_size || memcmp(&nfapi_crc_indications[i], &new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            // Insertion not necessary
        } else if (nfapi_crc_indications_size >= nfapi_crc_indications_capacity) {
            // Resize array and copy existing PDUs
            size_t new_capacity = nfapi_crc_indications_capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T* new_array = aligned_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), new_capacity);
            memcpy(new_array, nfapi_crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * nfapi_crc_indications_size);
            free(nfapi_crc_indications);
            nfapi_crc_indications = new_array;
            nfapi_crc_indications_capacity = new_capacity;
        } else {
            // Insertion is necessary
            memmove(&nfapi_crc_indications[i + 1], &nfapi_crc_indications[i], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfapi_crc_indications_size - i));
            memcpy(&nfapi_crc_indications[i], new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
        nfapi_crc_indications_size++;
    } else {
        // Wait for the lock to be released
        while (atomic_load(&nfapi_crc_indications_lock) == 1);
    }
}

void nfapi_crc_indication_delete(RNTI rnti) {
    size_t i = 0;
    atomic_flag lock Acquisition = ATOMIC_FLAG_INIT;
    if (!atomic_compare_exchange_strong(&lock, 0, 1)) {
        // Wait for the lock to be released
        while (atomic_load(&lock) == 1);
    }
    for (i = 0; i < nfapi_crc_indications_size; i++) {
        if (nfapi_crc_indications[i].rnti == rnti) {
            break;
        }
    }
    if (i < nfapi_crc_indications_size) {
        memmove(&nfapi_crc_indications[i], &nfapi_crc_indications[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfapi_crc_indications_size - i - 1));
        nfapi_crc_indications_size--;
    }
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_get(RNTI rnti) {
    size_t i = 0;
    atomic_flag lock Acquisition = ATOMIC_FLAG_INIT;
    if (!atomic_compare_exchange_strong(&lock, 0, 1)) {
        // Wait for the lock to be released
        while (atomic_load(&lock) == 1);
    }
    for (i = 0; i < nfapi_crc_indications_size; i++) {
        if (nfapi_crc_indications[i].rnti == rnti) {
