void addNode(NFAPI_CRC_INDATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *newNode) {
    if (*head == NULL || (*head)->timestamp < newNode->timestamp) {
        newNode->next = *head;
        *head = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = *head;
        while (current->next != NULL && current->next->timestamp >= newNode->timestamp)
            current = current->next;
        newNode->next = current->next;
        current->next = newNode;
    }
}

void removeNode(NFAPI_CRC_INDATION_PDU_T **head, time_t timestamp) {
    if (*head == NULL || (*head)->timestamp != timestamp)
        return;

    NFAPI_CRC_INDICATION_PDU_T *current = *head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current != NULL && current->timestamp != timestamp) {
        prev = current;
        current = current->next;
    }

    if (current == NULL)
        return;

    if (prev == NULL)
        *head = current->next;
    else
        prev->next = current->next;

    free(current);
}

NFAPI_CRC_INDICATION_PDU_T* createNode() {
    NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
