int pdu_array_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* init_pdu_array(int initial_size) {
    int i;
    TX_PDU** new_array = (TX_PDU**)malloc(initial_size * sizeof(TX_PDU*));
    if (!new_array) {
        return NULL;
    }
    for (i = 0; i < initial_size; i++) {
        new_array[i] = malloc(sizeof(TX_PDU));
        if (!new_array[i]) {
            free(new_array);
            return NULL;
        }
    }
    free(pdu_array);
    pdu_array = new_array;
    pdu_array_size = initial_size;
    return NULL;
}

void add_pdu(int tx_id, int modulation_scheme, SCHEDULING_PRIORITY priority, QoS_SETTING qos) {
    pthread_mutex_lock(&lock);
    if (pdu_array_size == 0) {
        init_pdu_array(1);
    }
    TX_PDU* new_pdu = (TX_PDU*)malloc(sizeof(TX_PDU));
    if (!new_pdu) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return;
    }
    new_pdu->TX_ID = tx_id;
    new_pdu->modulation_scheme = modulation_scheme;
    int i;
    for (i = 0; i < pdu_array_size; i++) {
        if (!pdu_array[i]) {
            break;
        }
    }
    if (i == pdu_array_size) {
        TX_PDU** new_array = realloc(pdu_array, (pdu_array_size + 1) * sizeof(TX_PDU*));
        if (!new_array) {
            free(new_pdu);
            perror("Memory reallocation failed");
            pthread_mutex_unlock(&lock);
            return;
        }
        pdu_array = new_array;
        pdu_array_size++;
    }
    pdu_array[i] = new_pdu;
    pthread_mutex_unlock(&lock);
}

