        if (pdu_array[i]->TX_ID == tx_id) {
            free(pdu_array[i]);
            for (int j = i + 1; j < pdu_array_size; j++) {
                pdu_array[j - 1] = pdu_array[j];
            }
            pdu_array_size--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void free_pdu_array() {
    int i;
    for (i = 0; i < pdu_array_size; i++) {
        free(pdu_array[i]);
    }
    free(pdu_array);
}
