DataPacket* init_data_packet_array(size_t capacity) {
    if (capacity == 0) {
        return NULL;
    }

    DataPacket* array = (DataPacket*)calloc(capacity, sizeof(DataPacket));
    if (!array) {
        return NULL; // Handle allocation failure
    }

    for (size_t i = 0; i < capacity; i++) {
        array[i].timestamp = time(NULL); // Update timestamp with current system time
        array[i].packetSize = rand() % 1024 + 1; // Random packet size between 1-1023 bytes
        array[i].payload = malloc(array[i].packetSize);
        if (!array[i].payload) {
            // Handle allocation failure for payload
        }
        for (size_t j = 0; j < array[i].packetSize; j++) {
            ((unsigned char*)array[i].payload)[j] = rand() % 256; // Random bytes for payload
        }
    }

    return array;
}

void free_data_packet_array(DataPacket* array, size_t capacity) {
    if (!array || capacity == 0) {
        return;
    }

    for (size_t i = 0; i < capacity; i++) {
        if (array[i].payload) {
            free(array[i].payload); // Free payload memory
        }
    }

    free(array); // Free array memory
}

int main() {
    size_t capacity = 10000;
    DataPacket* array = init_data_packet_array(capacity);

    if (!array) {
        printf("Error initializing data packet array.\n");
        return 1; // Handle error
    }

    // Use the data packet array...

    free_data_packet_array(array, capacity);
    return 0;
}
