void initializeQciRecords(LTE_EVM_QCI_RECORD_T **qciRecords, size_t *recordsCapacity) {
    // Initialize the first record
    *qciRecords = (LTE_EVM_QCI_RECORD_T *)malloc(1 * sizeof(LTE_EVM_QCI_RECORD_T));
    (*qciRecords)[0].EVM_DATA_TAG[0] = '\0';
    (*qciRecords)[0].QCI_TAG = -1;
    (*qciRecords)[0].EVM_RSRP_TAG = 0.0f;

    *recordsCapacity = 1;
}

void addRecord(LTE_EVM_QCI_RECORD_T **qciRecords, size_t *recordsCapacity, LTE_EVM_QCI_RECORD_T record) {
    if (*recordsCapacity == 0) {
        // Dynamically resize the array
        *qciRecords = (LTE_EVM_QCI_RECORD_T *)realloc(*qciRecords, (*recordsCapacity + 1) * sizeof(LTE_EVM_QCI_RECORD_T));
        (*recordsCapacity)++;
    }

    strcpy((*qciRecords)[*recordsCapacity - 1].EVM_DATA_TAG, record.EVM_DATA_TAG);
    (*qciRecords)[*recordsCapacity - 1].QCI_TAG = record.QCI_TAG;
    (*qciRecords)[*recordsCapacity - 1].EVM_RSRP_TAG = record.EVM_RSRP_TAG;
}

int validateRecord(LTE_EVM_QCI_RECORD_T record) {
    if (record.EVM_DATA_TAG[0] == '\0' || record.QCI_TAG < 0) {
        return 0; // Invalid record
    }
    return 1; // Valid record
}

void calculateRSRP(LTE_EVM_QCI_RECORD_T *qciRecords, size_t recordsCount, float *rsrpSum, int *numValidRecords) {
    for (size_t i = 0; i < recordsCount; i++) {
        if (validateRecord(qciRecords[i])) {
            (*rsrpSum) += qciRecords[i].EVM_RSRP_TAG;
            (*numValidRecords)++;
        }
    }
}

void logValidationIssues(LTE_EVM_QCI_RECORD_T *qciRecords, size_t recordsCount, int invalidRecordsCount) {
    printf("Validation issues: %d invalid records\n", invalidRecordsCount);
}
