    NETWORK_METRIC_RECORD_T* records = (NETWORK_METRIC_RECORD_T*)arg;

    int record_count = 0;

    // Initialize the lock for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    while(1) {
        // Lock the critical section to prevent concurrent modifications
        pthread_mutex_lock(&lock);

        // Process and validate records
        for(int i = 0; i < record_count; i++) {
            if(records[i].timestamp + 30000 > time(NULL)) { // Validate timestamp (30 minutes)
                continue;
            }
            if(isnan(records[i].latency_value) || records[i].latency_value > 1000) { // Validate latency value
                memmove(&records[i], &records[i+1], (record_count - i - 1) * sizeof(NETWORK_METRIC_RECORD_T));
                record_count--;
                i--; 
            }
        }

        // Resize the array if necessary
        int new_size = record_count + 1000; // dynamic resizing with a buffer of 1000 records
        NETWORK_METRIC_RECORD_T* new_records = (NETWORK_METRIC_RECORD_T*)malloc(new_size * sizeof(NETWORK_METRIC_RECORD_T));
        memcpy(new_records, records, record_count * sizeof(NETWORK_METRIC_RECORD_T));
        free(records);
        records = new_records;

        // Unlock the critical section to allow other threads
        pthread_mutex_unlock(&lock);

