#include <pthread.h>

#define MAX_CAPACITY 10000
#define THREAD_SAFE_LOCK_MUTEX_INITIALIZER pthread_mutex_t = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    char RX_UE_INFORMATION_TAG[10];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[20];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfaPiList;
int listSize = 0;
pthread_mutex_t lockMutex = THREAD_SAFE_LOCK_MUTEX_INITIALIZER;

void initNFAPILIST() {
    nfaPiList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_CAPACITY);
}

void insertNFAPIStructure(NFAPI_CRC_INDICATION_PDU_T* newStruct) {
    pthread_mutex_lock(&lockMutex);

    if (listSize >= MAX_CAPACITY) {
        // Resize the list
        NFAPI_CRC_INDICATION_PDU_T* newMemory = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfaPiList, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (MAX_CAPACITY * 2));
        if (!newMemory) {
            printf("Failed to allocate memory.\n");
            pthread_mutex_unlock(&lockMutex);
            return;
        }
        nfaPiList = newMemory;
    }

    // Check for duplicate RNTI
    int found = 0;
    for (int i = 0; i < listSize; i++) {
        if (newStruct->RNTI == nfaPiList[i].RNTI) {
            found = 1;
            break;
        }
    }

    if (!found) {
        memcpy(nfaPiList + listSize, newStruct, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        listSize++;
    } else {
        printf("Duplicate RNTI detected.\n");
    }

    pthread_mutex_unlock(&lockMutex);
}

void printNFAPILIST() {
    pthread_mutex_lock(&lockMutex);

    for (int i = 0; i < listSize; i++) {
        printf("%s, RNTI: %d, CRC_INDICATION_REL8_TAG: %s\n", nfaPiList[i].RX_UE_INFORMATION_TAG, nfaPiList[i].RNTI, nfaPiList[i].CRC_INDICATION_REL8_TAG);
    }

    pthread_mutex_unlock(&lockMutex);
}

