typedef struct list_node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct list_node* next;
} list_node;

void init_list(list_node** head_ref) {
    *head_ref = NULL;
}

int add_to_list(list_node** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    list_node* new_node = (list_node*)malloc(sizeof(list_node));
    if (!new_node) return 0;

    new_node->data = new_data;
    new_node->next = *head_ref;
    *head_ref = new_node;
    return 1;
}

int remove_from_list(list_node** head_ref, int RNTI_to_remove) {
    list_node* current = *head_ref;
    list_node* previous = NULL;

    while (current != NULL && current->data.RNTI != RNTI_to_remove) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return 0;

    if (previous == NULL)
        *head_ref = current->next;
    else
        previous->next = current->next;

    free(current);
    return 1;
}

int serialize_list(list_node* head, FILE* file) {
    list_node* current = head;
    int count = 0;

    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
        count++;
    }

    return count;
}

