```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structures
typedef struct {
    uint32_t ue_id;
    time_t timestamp;
    NFAPI_RX_CHANNEL_INFO* channels; // variable-length array of channel info
} NFAPI_RX_FRAME_INFO;

typedef struct {
    int rssi;
    char qos_class[3]; // QoS class identifier (e.g., "GSM", "LTE", etc.)
    uint8_t freq_band; // frequency band identifier (e.g., 0 for GSM, 1 for LTE, etc.)
} NFAPI_RX_CHANNEL_INFO;

// Define the data structure
typedef struct {
    NFAPI_RX_FRAME_INFO* frames;
    int capacity;
    int size;
    pthread_mutex_t lock; // concurrency management
    pthread_cond_t cond; // conditional variable for dynamic resizing
} NFAPI_RX_FRAME_POOL;

NFAPI_RX_FRAME_POOL* nfapi_rx_frame_pool_create(int initial_capacity) {
    NFAPI_RX_FRAME_POOL* pool = (NFAPI_RX_FRAME_POOL*)malloc(sizeof(NFAPI_RX_FRAME_POOL));
    pool->frames = (NFAPI_RX_FRAME_INFO*)calloc(initial_capacity, sizeof(NFAPI_RX_FRAME_INFO));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

void nfapi_rx_frame_pool_free(NFAPI_RX_FRAME_POOL* pool) {
    free(pool->frames);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}

int nfapi_rx_frame_pool_push(NFAPI_RX_FRAME_POOL* pool, NFAPI_RX_FRAME_INFO* frame) {
    if (pthread_mutex_lock(&pool->lock)) {
        return -1; // error
    }
    if (pool->size >= pool->capacity) { // dynamic resizing needed
        int new_capacity = pool->capacity * 2;
        NFAPI_RX_FRAME_POOL* new_pool = nfapi_rx_frame_pool_create(new_capacity);
        memcpy(new_pool->frames, pool->frames, sizeof(NFAPI_RX_FRAME_INFO) * pool->size);
        free(pool->frames);
        pool = new_pool;
    }
    pool->frames[pool->size] = frame;
    pool->size++;
    pthread_cond_signal(&pool->cond); // notify other threads of the update
    pthread_mutex_unlock(&pool->lock);
    return 0; // success
}

NFAPI_RX_FRAME_INFO* nfapi_rx_frame_pool_pop(NFAPI_RX_FRAME_POOL* pool) {
    if (pthread_mutex_lock(&pool->lock)) {
        return NULL; // error
    }
    NFAPI_RX_FRAME_INFO* frame = &pool->frames[pool->size - 1];
    pool->size--;
    pthread_cond_signal(&pool->cond); // notify other threads of the update
    pthread_mutex_unlock(&pool->lock);
    return frame;
}

void nfapi_rx_frame_pool_statistics(NFAPI_RX_FRAME_POOL* pool) {
    printf("Frame Pool Statistics:\n");
    printf("  Capacity: %d\n", pool->capacity);
    printf("  Size: %d\n", pool->size);
}
```
