void free_srbs() {
    int i;
    pthread_mutex_lock(&mutex);
    for (i = 0; i < srbs_size; i++) {
        free(srbs[i]);
    }
    free(srbs);
    pthread_mutex_unlock(&mutex);
}

NFAPI_SRB_MESSAGE_T *get_srbs(int m) {
    pthread_mutex_lock(&mutex);

    if (m > srbs_size) {
        int new_m = m;
        while (new_m > MAX_SIZE) {
            new_m /= 2;
        }
        allocate_srbs(new_m);
    }

    NFAPI_SRB_MESSAGE_T *srb;
    pthread_mutex_unlock(&mutex);
    return srb;
}

void print_srbs(NFAPI_SRB_MESSAGE_T **srbs, int size) {
    int i;
    for (i = 0; i < size; i++) {
        printf("Type: %d, ID: %d, Status: %d\n", srbs[i]->type, srbs[i]->id, srbs[i]->status);
    }
}

int main() {
    NFAPI_SRB_MESSAGE_T **srbs;
    int m = 5; // initial size

    pthread_create(NULL, NULL, allocate_srbs, (void *)m);

    // Example usage
    print_srbs(srbs, srbs_size);

    free_srbs();

    return 0;
}

