void manageNFAPI_CRC_INDICATION_PDU_T_array(int N, int M) {
    NFAPI_CRC_INDICATION_PDU_T** users = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < N; i++) {
        users[i] = (NFAPI_CRC_INDICATION_PDU_T*)calloc(M, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Initialize the array with some default values
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            users[i][j].field1 = 0;
            users[i][j].field2 = 0;
        }
    }

    // Allocate memory for each user's session
    for (int i = 0; i < N; i++) {
        if (!users[i]) {
            printf("Memory allocation failed for user %d\n", i);
            return;
        }
    }

    // Handle reallocation when the initial capacity is exceeded
    int reallocCount = 0;
    while (reallocCount < M) {
        for (int i = 0; i < N; i++) {
            if (!users[i]) continue;
            if (users[i][M - 1].field1 > users[i][M - 2].field1 + 1) { // Check condition
                users[i] = realloc(users[i], (M * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
                M++;
            }
        }
    }

    // Free the dynamically allocated memory
    for (int i = 0; i < N; i++) {
        free(users[i]);
    }
    free(users);
}
