#include <string.h>
#include <pthread.h>

#define MAX_UE_INFO 10000
#define LOG_FILE "nfa_log.txt"
#define LOG_THRESHOLD 1000
#define UPDATE_INTERVAL 3600 // 1 hour

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* ue_info_array = NULL;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

int rnti_pool_size = 1000; // Initial pool size
int used_rntis[MAX_UE_INFO];
int rnti_index = 0;

void* generate_ue_info(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* ue_info;
    int idx, rnti_idx, found = 0;

    while (rnti_index < MAX_UE_INFO) {
        rnti_idx = rand() % rnti_pool_size;

        pthread_mutex_lock(&log_mutex);
        for (idx = 0; idx < rnti_index; idx++) {
            if (used_rntis[idx] == rnti_idx) {
                found = 1;
                break;
            }
        }
        pthread_mutex_unlock(&log_mutex);

        if (!found) {
            used_rntis[rnti_index++] = rnti_idx;
            ue_info = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            ue_info->RX_UE_INFORMATION_TAG = rand();
            ue_info->RNTI = rnti_idx;
            ue_info->CRC_INDICATION_REL8_TAG = rand();
            ue_info->CRCFLAG = (rand() % 2) ? 1 : 0;

            // Log the used RNTI
            pthread_mutex_lock(&log_mutex);
            FILE* log_file = fopen(LOG_FILE, "a");
            if (log_file) {
                fprintf(log_file, "%d\n", rnti_idx);
                fclose(log_file);
            }
            pthread_mutex_unlock(&log_mutex);

            if (!ue_info_array) {
                ue_info_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_UE_INFO);
            }

            // Update the array
            if (rnti_index < MAX_UE_INFO) {
                ue_info_array[rnti_index - 1] = *ue_info;
            }

            free(ue_info);

            // Periodically flush the log and update the available pool size
            rnti_idx++;
        }
    }

    return NULL;
}

int main() {
    pthread_t threads[MAX_UE_INFO / 10];
    int i, thread_count;

    srand(time(NULL)); // Seed random number generator

    for (thread_count = 0; thread_count < MAX_UE_INFO / 10; thread_count++) {
        pthread_create(&threads[thread_count], NULL, generate_ue_info, NULL);
    }

    for (i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
