#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_BUFFER 5000
#define MIN_FREE_ID 1
#define MAX_FREE_ID 65535
#define BUFFER_TAG_SIZE sizeof(LTE_PHY_TX_BUFFER_T)

typedef struct {
    LTE_PHY_TX_BUFFER_T* buffers;
    pthread_mutex_t mutex;
    int free_id;
    int size;
} buffer_pool;

buffer_pool* create_buffer_pool() {
    buffer_pool* pool = (buffer_pool*)malloc(sizeof(buffer_pool));
    if (!pool) return NULL;

    pool->buffers = (LTE_PHY_TX_BUFFER_T*)calloc(MAX_BUFFER, BUFFER_TAG_SIZE);
    if (!pool->buffers) {
        free(pool);
        return NULL;
    }

    pool->free_id = MIN_FREE_ID;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

void destroy_buffer_pool(buffer_pool* pool) {
    if (pool) {
        for (int i = 0; i < MAX_BUFFER; i++) {
            free((char*)pool->buffers + i * BUFFER_TAG_SIZE);
        }
        free(pool->buffers);
        free(pool);
    }
}

LTE_PHY_TX_BUFFER_T* allocate_buffer(buffer_pool* pool) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->size >= MAX_BUFFER) {
        printf("Buffer pool exhausted.\n");
        return NULL;
    }

    LTE_PHY_TX_BUFFER_T* buffer = &pool->buffers[pool->free_id];
    buffer->TX_STREAM_ID = pool->free_id;
    buffer->MODULATION_TYPE = rand() % 2;

    pool->size++;
    pool->free_id++;

    pthread_mutex_unlock(&pool->mutex);
    return buffer;
}

void deallocate_buffer(buffer_pool* pool, LTE_PHY_TX_BUFFER_T* buffer) {
    pthread_mutex_lock(&pool->mutex);

    if (buffer->TX_STREAM_ID < MIN_FREE_ID || buffer->TX_STREAM_ID > MAX_FREE_ID) {
        printf("Invalid buffer ID.\n");
        return;
    }

    for (int i = 0; i < MAX_BUFFER; i++) {
        if (&pool->buffers[i] == buffer) {
            pool->free_id = i + 1;
            break;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
}

void monitor_pool_usage(buffer_pool* pool) {
    printf("Pool usage: %d buffers allocated, %d free.\n", pool->size, pool->free_id - pool->size);
}
