#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char IMSI[20];
    char PLMN_ID[20];
    int LTE_RRC_CU_UE_CONTEXT;
} CellularConnectionInfo;

struct CellList {
    CellularConnectionInfo* data;
    unsigned int count;
    pthread_mutex_t mutex;
};

CellularConnectionInfo* cellListCreate() {
    struct CellList* list = (struct CellList*)malloc(sizeof(struct CellList));
    list->data = NULL;
    list->count = 0;
    if(pthread_mutex_init(&list->mutex, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

void cellListDestroy(struct CellList* list) {
    if(list == NULL) return;
    pthread_mutex_destroy(&list->mutex);
    free(list->data);
    free(list);
}

int cellListAdd(struct CellList* list, CellularConnectionInfo* info) {
    pthread_mutex_lock(&list->mutex);

    // Check for invalid inputs
    if(info == NULL || strlen(info->IMSI) > 19 || strlen(info->PLMN_ID) > 19) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    info = (CellularConnectionInfo*)malloc(sizeof(CellularConnectionInfo));
    strcpy(info->IMSI, info->IMSI); // Validate IMSI format
    strcpy(info->PLMN_ID, info->PLMN_ID); // Validate PLMN_ID format

    if(list->data == NULL) {
        list->data = (CellularConnectionInfo*)malloc(sizeof(CellularConnectionInfo));
        *list->data = *info;
        list->count++;
    } else {
        CellularConnectionInfo* node = list->data;
        while(node != NULL && node->LTE_RRC_CU_UE_CONTEXT > 0) { // Check for valid LTE_RRC_CU_UE_CONTEXT
            if(strcmp(node->IMSI, info->IMSI) == 0 && strcmp(node->PLMN_ID, info->PLMN_ID) == 0) {
                free(info);
                pthread_mutex_unlock(&list->mutex);
                return -1;
            }
            node = node->next;
        }

        // Add new connection
        node = (CellularConnectionInfo*)malloc(sizeof(CellularConnectionInfo));
        *node = *info;
        if(list->count == 0) {
            list->data = node;
        } else {
            while(node->prev != NULL && node->LTE_RRC_CU_UE_CONTEXT > 0) { // Check for valid LTE_RRC_CU_UE_CONTEXT
                node = node->prev;
            }
            node->next = (list->data)->next;
            if((list->data)->next != NULL) {
                ((list->data)->next)->prev = node;
            } else {
                list->count--;
            }
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int main() {
    struct CellList* cell_list = cellListCreate();

    // Example usage
    CellularConnectionInfo info1 = {"123456789012345", "PLMN_ID_1", 5};
    CellularConnectionInfo info2 = {"234567890123456", "PLMN_ID_2", 10};
    int status1 = cellListAdd(cell_list, &info1);
    int status2 = cellListAdd(cell_list, &info2);

    // Add more connections...

    cellListDestroy(cell_list);
    return 0;
}
