#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONCURRENT_USERS 1000
#define RNTI_MAX 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocateList(int n) {
    return calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void freeList(void* list) {
    free(list);
}

void populateList(int n, void* list) {
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* ptr = (NFAPI_CRC_INDICATION_PDU_T*)list;
        ptr[i].RX_UE_INFORMATION_TAG = i % RNTI_MAX;
        ptr[i].RNTI = rand() % RNTI_MAX + 1;
        ptr[i].CRC_INDICATION_REL8_TAG = rand() % RNTI_MAX;
        ptr[i].CRCFLAG = rand() & 1; // Randomly set CRCFLAG
    }
}

void validateList(int n, void* list) {
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* ptr = (NFAPI_CRC_INDICATION_PDU_T*)list;
        if (ptr[i].RNTI > RNTI_MAX) {
            // Log error message
            printf("Invalid RNTI detected: %d\n", ptr[i].RNTI);
        }
    }
}

void manageList(int n, int maxConcurrentUsers, pthread_mutex_t* mutex) {
    void* list = allocateList(n);
    populateList(n, list);
    validateList(n, list);

    int count = 0;
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* ptr = (NFAPI_CRC_INDICATION_PDU_T*)list;
        if (ptr[i].RNTI <= RNTI_MAX) {
            count++;
        }
    }

    while (count > maxConcurrentUsers && pthread_mutex_lock(mutex)) {
        // Backpressure mechanism: delay or queue new requests
        printf("Backpressure engaged. Limiting concurrent users to %d.\n", maxConcurrentUsers);
        sleep(1); // Simulate delay or queuing
    }

    pthread_mutex_unlock(mutex);

    freeList(list);
}

int main() {
    int n = 1000;
    int maxConcurrentUsers = MAX_CONCURRENT_USERS;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    manageList(n, maxConcurrentUsers, &mutex);

    return 0;
}
