// Forward and backward traversal structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* p;
    int pos;
} NFAPI_CRC_ITERATOR;

// Hashing mechanism
unsigned long hash_func(NFAPI_CRC_INDICATION_PDU_T* p) {
