}

// List management functions
NFAPI_CRC_INDICATION_PDU_T** nfapi_crc_list_new(int size) {
    NFAPI_CRC_INDICATION_PDU_T** list = malloc((size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) return NULL;
