typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node structure
typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct Node* next;
} Node;

// Hash table for unique RNTI detection
typedef struct HashTable {
    unsigned long long size;
    Node** buckets;
} HashTable;

// Function to create a hash table of the given size
HashTable* create_hash_table(int size) {
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    hash_table->size = size;
    hash_table->buckets = (Node**)calloc(size, sizeof(Node*));
    return hash_table;
}

// Function to insert a node into the linked list and hash table
void insert_node(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = (*head_ref);
    (*head_ref) = new_node;
}

// Function to check if a RNTI is already present in the hash table
int is_rnti_present(HashTable* hash_table, int rnti) {
    unsigned long long index = (unsigned long long)rnti % hash_table->size;
    Node** bucket = &hash_table->buckets[index];
    while (*bucket != NULL && (*bucket)->data.RNTI != rnti)
        bucket = &((*bucket)->next);
    return *bucket != NULL;
}

// Function to create and populate the linked list of NFAPI_CRC_INDICATION_PDU_T structures
int create_crc_indication_pdu_list(int M, int* status_code) {
    Node* head = NULL;
    HashTable* hash_table = create_hash_table(M);

    for (int i = 0; i < M; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;

        // Set random CRCFLAG
        data.CRCFLAG = rand();

        // Ensure unique RNTI
        int rnti;
        do {
            rnti = rand();
        } while (is_rnti_present(hash_table, rnti));

        data.RX_UE_INFORMATION_TAG = i;
        data.RNTI = rnti;
        data.CRC_INDICATION_REL8_TAG = i + 1;

        // Insert node into linked list and hash table
        insert_node(&head, data);
    }

    // Log memory allocation/deallocation status
    if (status_code != NULL)
        *status_code = 0; // successful allocation

    return head;
}

// Function to periodically clean up unused resources
void cleanup_resources(Node* head) {
    Node* current = head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}
