// File system entry structure
typedef struct {
    char path[256];
    mode_t permissions;
    uid_t owner;
    struct timespec last_modified;
} FileEntry;

// Thread-safe list of file system entries
void* fs_entry_list = NULL;
thrd_t list_lock = thrd_create_flags(0, NULL);

// Function to initialize the file system entry list
int init_fs_entry_list() {
    if (fs_entry_list) {
        free(fs_entry_list);
    }
    fs_entry_list = malloc(sizeof(FileEntry));
    if (!fs_entry_list) {
        return -1; // Memory allocation failed
    }
    *fs_entry_list = (FileEntry){0};
    return 0;
}

// Function to add a file system entry to the list
int add_fs_entry(const char* path, mode_t permissions, uid_t owner, struct timespec last_modified) {
    FileEntry* current = fs_entry_list;
    while (current) {
        if (!strcmp(current->path, path)) {
            return -1; // Entry already exists in the list
        }
        current = (FileEntry*) ((char*)current + sizeof(FileEntry));
    }

    FileEntry* new_entry = malloc(sizeof(FileEntry));
    if (!new_entry) {
        return -1; // Memory allocation failed
    }
    strcpy(new_entry->path, path);
    new_entry->permissions = permissions;
    new_entry->owner = owner;
    new_entry->last_modified = last_modified;

    current = fs_entry_list;
    while (current && current != (FileEntry*) ((char*)current + sizeof(FileEntry))) {
        current = (FileEntry*) ((char*)current + sizeof(FileEntry));
    }
    if (!current) {
        fs_entry_list = new_entry;
    } else {
        FileEntry* prev = fs_entry_list;
        while (prev && prev != current) {
            prev = (FileEntry*) ((char*)prev + sizeof(FileEntry));
        }
        prev->next = new_entry;
    }

    return 0;
}

// Function to iterate over the file system entry list
void iterate_fs_entries(void (*callback)(const char*, mode_t, uid_t, struct timespec)) {
    FileEntry* current = fs_entry_list;
    while (current) {
        callback(current->path, current->permissions, current->owner, current->last_modified);
        current = (FileEntry*) ((char*)current + sizeof(FileEntry));
    }
}

// Function to free the file system entry list
void free_fs_entry_list() {
    if (!fs_entry_list) {
        return;
    }

    FileEntry* current = fs_entry_list;
    while (current) {
        FileEntry* next = (FileEntry*) ((char*)current + sizeof(FileEntry));
        free(current);
        current = next;
    }
    fs_entry_list = NULL;
}
