#define MAX_STRUCTURES 1000

typedef struct {
    char RX_UE_INFORMATION_TAG[10];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[20];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* generate_list(int num_structures) {
    // Initialize the list
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Set valid CRCFLAG to 1 and set RX_UE_INFORMATION_TAG to random values
    srand(time(NULL));
    for(int i = 0; i < num_structures; i++) {
        structures[i].RX_UE_INFORMATION_TAG[0] = 'A' + rand() % 26;
        structures[i].RX_UE_INFORMATION_TAG[1] = 'B' + rand() % 26;
        structures[i].RX_UE_INFORMATION_TAG[2] = '\0';
        structures[i].RNTI = i; // Each structure has a unique RNTI
        structures[i].CRC_INDICATION_REL8_TAG[0] = 'C' + rand() % 26;
        structures[i].CRC_INDICATION_REL8_TAG[1] = 'D' + rand() % 26;
        structures[i].CRC_INDICATION_REL8_TAG[2] = '\0';
        structures[i].CRCFLAG = (uint8_t)(rand() % 256);
    }

    // Check for consecutive RNTI values and re-generate the list if necessary
    int prev_RNTI = -1;
    for(int i = 0; i < num_structures; i++) {
        if(structures[i].RNTI == prev_RNTI) {
            // Regenerate the structures until no consecutive RNTI values are found
            while(true) {
                for(int j = 0; j < MAX_STRUCTURES; j++) {
                    structures[j].RX_UE_INFORMATION_TAG[0] = 'A' + rand() % 26;
                    structures[j].RX_UE_INFORMATION_TAG[1] = 'B' + rand() % 26;
                    structures[j].RX_UE_INFORMATION_TAG[2] = '\0';
                    structures[j].RNTI = j; // Each structure has a unique RNTI
                    structures[j].CRC_INDICATION_REL8_TAG[0] = 'C' + rand() % 26;
                    structures[j].CRC_INDICATION_REL8_TAG[1] = 'D' + rand() % 26;
                    structures[j].CRC_INDICATION_REL8_TAG[2] = '\0';
                    structures[j].CRCFLAG = (uint8_t)(rand() % 256);
                }
                // Check for consecutive RNTI values
                prev_RNTI = -1;
                for(int j = 0; j < num_structures; j++) {
                    if(structures[j].RNTI == prev_RNTI) {
                        break;
                    } else {
                        prev_RNTI = structures[j].RNTI;
                    }
                }
                if(prev_RNTI != -1) {
                    // Still consecutive RNTI values, need to re-generate
                } else {
                    // No consecutive RNTI values found, stop regenerating
                    break;
                }
            }
        }
        prev_RNTI = structures[i].RNTI;
    }

    return (void*)structures;
}

int main() {
    int num_structures = 10; // Set the number of structures you want to generate

    void* generated_list = generate_list(num_structures);

    printf("Generated list:\n");
    for(int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)generated_list;
        printf("RX_UE_INFORMATION_TAG: %s, RNTI: %d, CRC_INDICATION_REL8_TAG: %s, CRCFLAG: %u\n", structure[i].RX_UE_INFORMATION_TAG, structure[i].RNTI, structure[i].CRC_INDICATION_REL8_TAG, structure[i].CRCFLAG);
    }

    free(generated_list);

    return 0;
}
