#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define a structure for LTE PHY layer configuration
typedef struct {
    int param1;
    int param2;
    // Add more parameters as needed
} PhyConfig;

// Define the dynamic array of PhyConfig structures
typedef struct {
    PhyConfig* configs;
    size_t capacity;
    pthread_mutex_t mutex;  // Synchronization lock
    pthread_cond_t cond;     // Condition variable for notifications
    size_t count;            // Number of allocated configurations
} PhyConfigArray;

// Function to initialize and manage the dynamic array
PhyConfigArray* phy_config_array_init(size_t initial_capacity) {
    PhyConfigArray* arr = (PhyConfigArray*)malloc(sizeof(PhyConfigArray));
    if (!arr) return NULL;

    arr->configs = (PhyConfig*)malloc(initial_capacity * sizeof(PhyConfig));
    if (!arr->configs) {
        free(arr);
        return NULL;
    }

    arr->capacity = initial_capacity;
    pthread_mutex_init(&arr->mutex, NULL);
    pthread_cond_init(&arr->cond, NULL);
    arr->count = 0;

    return arr;
}

// Function to add a configuration to the dynamic array
int phy_config_array_add(PhyConfigArray* arr, PhyConfig config) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->count >= arr->capacity) {
        // Reallocate memory with increased capacity
        size_t new_capacity = arr->capacity * 2;
        PhyConfig* new_configs = (PhyConfig*)realloc(arr->configs, new_capacity * sizeof(PhyConfig));
        if (!new_configs) {
            pthread_mutex_unlock(&arr->mutex);
            return -1;  // Allocation failed
        }

        arr->configs = new_configs;
        arr->capacity = new_capacity;
    }

    arr->configs[arr->count++] = config;

    pthread_cond_signal(&arr->cond);  // Notify waiting threads
    pthread_mutex_unlock(&arr->mutex);

    return 0;  // Operation successful
}

// Function to remove a configuration from the dynamic array
int phy_config_array_remove(PhyConfigArray* arr, PhyConfig config) {
    pthread_mutex_lock(&arr->mutex);

    for (size_t i = 0; i < arr->count; i++) {
        if (memcmp(&arr->configs[i], &config, sizeof(PhyConfig)) == 0) {
            // Shift remaining configurations and update count
            memmove(&arr->configs[i], &arr->configs[i + 1], (arr->count - i - 1) * sizeof(PhyConfig));
            arr->count--;
            break;
        }
    }

    pthread_mutex_unlock(&arr->mutex);

    return 0;  // Operation successful
}

// Function to retrieve a configuration from the dynamic array
int phy_config_array_get(PhyConfigArray* arr, size_t index, PhyConfig* config) {
    pthread_mutex_lock(&arr->mutex);

    if (index >= arr->count) {
        pthread_mutex_unlock(&arr->mutex);
        return -1;  // Index out of bounds
    }

    *config = arr->configs[index];

    pthread_mutex_unlock(&arr->mutex);

    return 0;  // Operation successful
}

// Example logging function for debugging and performance monitoring
void phy_config_array_log(const char* message) {
    printf("%s\n", message);
}
