#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CAPACITY 1000
#define LOG_MAX_SIZE 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    int capacity;
    int size;
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    FILE* log_file;
} List;

List* init_list() {
    List* list = (List*)malloc(sizeof(List));
    list->capacity = MAX_CAPACITY;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->log_file = fopen("nfa_pi_list.log", "w");
    return list;
}

void add_element(List* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = new_data;
    if (list->size == 0) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = NULL;
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void remove_element(List* list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL && current->data.rnti != rnti) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }
    if (current == list->tail) {
        list->tail = previous;
    }
    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T get_element(List* list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL && current->data.rnti != rnti) {
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0};
    }
    NFAPI_CRC_INDICATION_PDU_T data = current->data;
    pthread_mutex_unlock(&list->lock);
    return data;
}

void resize_list(List* list) {
    if (list->size > 0.7 * list->capacity) {
        list->capacity *= 2;
        Node** new_nodes = (Node**)malloc(sizeof(Node*) * list->capacity);
        int i = 0;
        for (Node* current = list->head; current != NULL; current = current->next) {
            new_nodes[i++] = current;
        }
        free(list->head);
        list->head = new_nodes[0];
        for (int j = 1; j < i; j++) {
            new_nodes[j-1]->next = new_nodes[j];
        }
        list->tail = new_nodes[i-1];
    }
}

void log_action(List* list, char* action) {
    pthread_mutex_lock(&list->lock);
    fprintf(list->log_file, "%s\n", action);
    if (ferror(list->log_file)) {
        // handle log file error
    }
    pthread_mutex_unlock(&list->lock);
}

void clean_up_logs(List* list) {
    fclose(list->log_file);
    list->log_file = fopen("nfa_pi_list.log", "w");
}
