        // Handle memory allocation failure
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        array[i].CRC_INDICATION_REL8_TAG = rand();
    }

    return array;
}

void freeArray(NFAPI_CRC_INDICATION_PDU_T *array, int n) {
