#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STRUCTURES 1000
#define MAX_UCT_CONTEXTS 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int UE_ID;
    char* servingPLMNs[MAX_UCT_CONTEXTS];
    int activeSessions[MAX_UCT_CONTEXTS][3]; // QoS parameters
} LTE_UE_Context_Information;

NFAPI_CRC_INDICATION_PDU_T* nfaPiCRCList = NULL;
int nfaPiCRCListCount = 0;
pthread_mutex_t nfaPiCRCListMutex = PTHREAD_MUTEX_INITIALIZER;

LTE_UE_Context_Information* ueContextArray = NULL;
int ueContextArrayLength = 0;
pthread_mutex_t ueContextArrayMutex = PTHREAD_MUTEX_INITIALIZER;

void initNFAPI_CRC_List() {
    pthread_mutex_lock(&nfaPiCRCListMutex);
    if (!nfaPiCRCList) {
        nfaPiCRCList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memset(nfaPiCRCList, 0, MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pthread_mutex_unlock(&nfaPiCRCListMutex);
}

void initUE_Context_Array() {
    pthread_mutex_lock(&ueContextArrayMutex);
    if (!ueContextArray) {
        ueContextArray = (LTE_UE_Context_Information*)malloc(MAX_UCT_CONTEXTS * sizeof(LTE_UE_Context_Information));
        memset(ueContextArray, 0, MAX_UCT_CONTEXTS * sizeof(LTE_UE_Context_Information));
    }
    pthread_mutex_unlock(&ueContextArrayMutex);
}

int getAvailableRNTI(int RNTI) {
    // Generate random numbers to check uniqueness
    int i;
    for (i = 0; i < nfaPiCRCListCount; i++) {
        if (nfaPiCRCList[i].RNTI == RNTI)
            return -1; // Already exists in the list
    }
    return 1; // Available RNTI
}

void addNFAPI_CRC_ListEntry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&nfaPiCRCListMutex);
    if (nfaPiCRCListCount < MAX_STRUCTURES) {
        NFAPI_CRC_INDICATION_PDU_T newStruct;
        newStruct.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        newStruct.RNTI = RNTI;
        newStruct.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        // Generate random CRCFLAG
        newStruct.CRCFLAG = rand() % 2;
        nfaPiCRCList[nfaPiCRCListCount] = newStruct;
        nfaPiCRCListCount++;
    }
    pthread_mutex_unlock(&nfaPiCRCListMutex);
}

void removeNFAPI_CRC_ListEntry(int RNTI) {
    pthread_mutex_lock(&nfaPiCRCListMutex);
    int i, j;
    for (i = 0; i < nfaPiCRCListCount; i++) {
        if (nfaPiCRCList[i].RNTI == RNTI) {
            // Shift all subsequent entries down
            for (j = i + 1; j < nfaPiCRCListCount; j++)
                nfaPiCRCList[j - 1] = nfaPiCRCList[j];
            nfaPiCRCListCount--;
            break;
        }
    }
    pthread_mutex_unlock(&nfaPiCRCListMutex);
}

void updateUE_Context(QoS_Parameters* qosParams) {
    pthread_mutex_lock(&ueContextArrayMutex);
    int i;
    for (i = 0; i < ueContextArrayLength; i++) {
        if (ueContextArray[i].activeSessions[0][2] == qosParams->QoSParam1 &&
            ueContextArray[i].activeSessions[1][2] == qosParams->QoSParam2) {
            // Update UE Context
            break;
        }
    }
    pthread_mutex_unlock(&ueContextArrayMutex);
}

void freeNFAPI_CRC_List() {
    pthread_mutex_lock(&nfaPiCRCListMutex);
    if (nfaPiCRCList) {
        free(nfaPiCRCList);
        nfaPiCRCList = NULL;
    }
    pthread_mutex_unlock(&nfaPiCRCListMutex);
}

void freeUE_Context_Array() {
    pthread_mutex_lock(&ueContextArrayMutex);
    if (ueContextArray) {
        free(ueContextArray);
        ueContextArray = NULL;
    }
    pthread_mutex_unlock(&ueContextArrayMutex);
}
