typedef struct {
    long timestamp;
    int eventType;
    char cellId[16];
} CellularEventLogEntry;

typedef struct {
    int capacity;
    int size;
    CellularEventLogEntry* entries;
    pthread_mutex_t mutex;
} LogArray;

void log_array_init(LogArray* log) {
    log->capacity = 4; // initial capacity
    log->size = 0;
    log->entries = (CellularEventLogEntry*)malloc(log->capacity * sizeof(CellularEventLogEntry));
    pthread_mutex_init(&log->mutex, NULL);
}

void log_array_resize(LogArray* log) {
    int newCapacity = log->capacity * 2; // grow capacity by a factor of 2
    CellularEventLogEntry* newEntries = (CellularEventLogEntry*)realloc(log->entries, newCapacity * sizeof(CellularEventLogEntry));
    if (!newEntries) {
        printf("Error: unable to resize log array\n");
        return;
    }
    log->capacity = newCapacity;
    log->entries = newEntries;
}

void log_array_add_entry(LogArray* log, CellularEventLogEntry entry) {
    pthread_mutex_lock(&log->mutex);
    if (log->size == log->capacity) {
        log_array_resize(log); // resize if full
    }
    log->entries[log->size] = entry;
    log->size++;
    pthread_mutex_unlock(&log->mutex);
}

void log_to_external_service(LogArray* log) {
    // implement your logging service logic here
    printf("Logging entries to external service...\n");
}

void log_array_close(LogArray* log) {
    free(log->entries);
    pthread_mutex_destroy(&log->mutex);
}
