        pItem->CRCFLAG = 'A' + rand() % 26;
        if((pItem->RX_UE_INFORMATION_TAG >= capacity) || (pItem->RNTI > 1000000)) {
            free(pItem);
            return -1;  // RNTI or UE tag exceeds limit
