#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_N 1000
#define LOG_FILE "allocation.log"
#define DEBUG_LOG_FILE "debug_allocation.log"

typedef struct {
    // Your structure definition goes here
} NFAPI_CRC_INDICATION_PDU_T;

void log_validation_error(const char* file, int line, const char* error_message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(log_file, "%s:%d - %s\n", file, line, error_message);
    fclose(log_file);
}

void log_allocation_report(const char* message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}

int main(int argc, char** argv) {
    int N = 0; // Number of structures to allocate
    int max_memory_threshold = MAX_N * sizeof(NFAPI_CRC_INDICATION_PDU_T); // Default memory threshold

    if (argc > 1) {
        N = atoi(argv[1]);
    }

    if (N > MAX_N) {
        fprintf(stderr, "Error: Number of structures exceeds maximum limit.\n");
        return -1;
    }

    int allocated_count = 0; // Total number of allocated structures
    NFAPI_CRC_INDICATION_PDU_T* puds = NULL;

    for (int i = 0; i < N; i++) {
        if (puds == NULL || allocated_count >= max_memory_threshold) {
            // Check memory usage and report to system logs
            printf("Memory usage: %.2f%%\n", (double)i / N * 100);
            log_allocation_report("Memory usage exceeded threshold. Refusing further allocations.");

            if (puds != NULL) {
                free(puds); // Free previously allocated memory
            }
            break;
        }

        puds = realloc(puds, (allocated_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (puds == NULL) {
            log_validation_error(__FILE__, __LINE__, "Memory allocation failed.");
            free(puds); // Free previously allocated memory
            return -1;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu = {0};
        // Validate and set RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG fields
        if (!validate_pdu(&pdu)) {
            log_validation_error(__FILE__, __LINE__, "PDU validation failed.");
            free(puds); // Free previously allocated memory
            return -1;
        }

        puds[allocated_count] = pdu; // Insert validated structure into the array
        allocated_count++;

        if (debug_mode) {
            FILE* debug_log_file = fopen(DEBUG_LOG_FILE, "a");
            if (debug_log_file == NULL) {
                perror("Error opening debug log file");
                return;
            }
            fprintf(debug_log_file, "%d: Validated structure inserted.\n", allocated_count);
            fclose(debug_log_file);
        }
    }

    free(puds); // Free all allocated memory
    return 0;
}
