#include <stdlib.h>
#include <stdio.h>

typedef struct Connection {
    char *ip;
    int port;
    int state;
} Connection;

typedef struct ConnectionList {
    Connection **connections;
    int count;
} ConnectionList;

ConnectionList* init_connection_list() {
    ConnectionList* list = (ConnectionList*)malloc(sizeof(ConnectionList));
    if (!list) {
        return NULL; // memory allocation failed
    }
    list->connections = NULL;
    list->count = 0;
    return list;
}

int add_connection(ConnectionList* list, const char* ip, int port) {
    Connection* connection = (Connection*)malloc(sizeof(Connection));
    if (!connection) {
        printf("Memory allocation failure\n");
        return -1; // error
    }
    connection->ip = strdup(ip);
    if (!connection->ip) {
        free(connection);
        printf("String duplication failure\n");
        return -2; // error
    }
    connection->port = port;
    connection->state = 0;

    int i;
    for (i = 0; i < list->count; i++) {
        if (!strcmp(list->connections[i]->ip, ip) && list->connections[i]->port == port) {
            free(connection);
            printf("IP:Port pair already exists\n");
            return -3; // error
        }
    }

    Connection** new_connections = (Connection**)realloc(list->connections, sizeof(Connection*) * (list->count + 1));
    if (!new_connections) {
        free(connection->ip);
        free(connection);
        printf("Memory reallocation failure\n");
        return -4; // error
    }
    list->connections = new_connections;
    list->connections[list->count] = connection;
    list->count++;

    return 0; // success
}

void destroy_connection_list(ConnectionList* list) {
    int i;
    for (i = 0; i < list->count; i++) {
        free(list->connections[i]->ip);
        free(list->connections[i]);
    }
    free(list->connections);
    free(list);
}
