int nfa_api_list_reserve(nfa_api_list* list, int new_size) {
    if (new_size > list->capacity * 2) {
        // Realloc the array when it's half full to avoid frequent reallocations
        void* temp = realloc(list->list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) return -1;
        list->list = temp;
        list->capacity = new_size;
    }
    return 0;
}

void nfa_api_list_insert(nfa_api_list* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        if (nfa_api_list_reserve(list, list->size * 2) < 0) {
            printf("Failed to reserve memory!\n");
            exit(-1);
        }
    }
    int rnti = pdu->RX_UE_INFORMATION_TAG & RNTI_MASK;
    for (int i = list->size - 1; i >= 0; --i) {
        if ((list->list[i]->RX_UE_INFORMATION_TAG & RNTI_MASK) == rnti) {
            // Find the first element with a different RNTI and insert there
            int pos = i;
            while (pos > 0 && (list->list[pos-1]->RX_UE_INFORMATION_TAG & RNTI_MASK) == rnti);
            memmove(&list->list[i+1], &list->list[i], (list->size - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->list[pos] = pdu;
            break;
        }
    } else {
        // Insert at the end
        list->list[list->size++] = pdu;
    }
    pthread_mutex_unlock(&list->mutex);
}

void nfa_api_list_free(nfa_api_list* list) {
    free(list->list);
    pthread_mutex_destroy(&list->mutex);
}
