#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1000
#define RETENTION_POLICY 300 // in seconds

typedef struct {
    RX_UE_INFO ue_info;
    RNTI rnti;
    CRC_INDICATION crc_indication;
    time_t age;
} MAC_RX_TASK_T;

// Function to initialize and manage the dynamic array
void *mac_rx_task_array_init(void) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int size = 0;
    MAC_RX_TASK_T **array = (MAC_RX_TASK_T **)malloc(sizeof(MAC_RX_TASK_T *) * MAX_ARRAY_SIZE);
    time_t now;

    // Initialize the array
    for(int i = 0; i < MAX_ARRAY_SIZE; i++) {
        array[i] = NULL;
    }

    // Function to append new entries
    void mac_rx_task_array_append(RX_UE_INFO ue_info, RNTI rnti) {
        pthread_mutex_lock(&mutex);
        now = time(NULL);

        // Check if the array is full
        if(size >= MAX_ARRAY_SIZE) {
            printf("Array full! Cannot append new entry.\n");
            return;
        }

        MAC_RX_TASK_T *task = (MAC_RX_TASK_T *)malloc(sizeof(MAC_RX_TASK_T));
        task->ue_info = ue_info;
        task->rnti = rnti;
        task->crc_indication = generate_crc_indication(ue_info, rnti);
        task->age = now;

        array[size] = task;
        size++;

        pthread_mutex_unlock(&mutex);
    }

    // Function to remove outdated entries based on retention policy
    void mac_rx_task_array_gc(void) {
        pthread_mutex_lock(&mutex);

        for(int i = 0; i < size; i++) {
            now = time(NULL);
            if((now - array[i]->age) > RETENTION_POLICY) {
                free(array[i]);
                array[i] = NULL;
                size--;
            }
        }

        pthread_mutex_unlock(&mutex);
    }

    return (void *)array;
}

// Function to free the dynamic array
void mac_rx_task_array_free(void *ptr) {
    MAC_RX_TASK_T **array = (MAC_RX_TASK_T **)ptr;

    for(int i = 0; i < size; i++) {
        if(array[i] != NULL) {
            free(array[i]);
        }
    }

    free(array);
}
