void pdu_manager(Pdu** pdus, int* num_pds, int capacity) {
    if (*num_pds >= capacity) {
        printf("Array full. Please increase the capacity.\n");
        return;
    }

    // Add new PDU
    pdus[*num_pds] = (Pdu*)malloc(sizeof(Pdu));
    (*num_pds)++;

    // Remove PDU by frame number
    for (int i = 0; i < *num_pds; i++) {
        if (pdus[i]->frame_number == target_frame_number) {
            free(pdus[i]);
            memmove(&pdus[i], &pdus[i+1], (*num_pds - i - 1)*sizeof(Pdu));
            (*num_pds)--;
            break;
        }
    }

    // Update PRB occupancy indicators
    for (int i = 0; i < *num_pds; i++) {
        pdus[i]->prb_occupancy_indicators[0] = new_prb_indicator;
    }
}

// Function to synchronize frame numbers and timestamps from external data source
void sync_data(Pdu** pdus, int* num_pds) {
    // Read updated frame numbers and timestamps from the external data source
    // Update PDUs accordingly
    for (int i = 0; i < *num_pds; i++) {
        pdus[i]->frame_number = new_frame_number;
        pdus[i]->timestamp = new_timestamp;
    }
}

