// Define the structure for LTE_EPC_GTPV2_MESSAGE
typedef struct {
    uint32_t pduSessionId;
    char sgwAddress[20];
    uint16_t sequenceNumber;
} LTE_EPC_GTPV2_MESSAGE;

// Define the linked list node structure
typedef struct LinkedListNode {
    LTE_EPC_GTPV2_MESSAGE message;
    struct LinkedListNode* next;
} LinkedListNode;

// Define the hash table structure
typedef struct {
    size_t size;
    LinkedListNode** buckets;
} HashTable;

// Function to initialize the hash table
HashTable* initHashTable(size_t size) {
    HashTable* hashTable = (HashTable*)malloc(sizeof(HashTable));
    hashTable->size = size;
    hashTable->buckets = (LinkedListNode**)malloc(sizeof(LinkedListNode*) * size);
    for (int i = 0; i < size; i++) {
        hashTable->buckets[i] = NULL;
    }
    return hashTable;
}

// Function to insert a message into the hash table
void insertMessage(HashTable* hashTable, LTE_EPC_GTPV2_MESSAGE message) {
    uint32_t key = message.pduSessionId % hashTable->size;
    LinkedListNode* node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    node->message = message;
    node->next = hashTable->buckets[key];
    hashTable->buckets[key] = node;
}

// Function to remove a message from the hash table
void removeMessage(HashTable* hashTable, LTE_EPC_GTPV2_MESSAGE message) {
    uint32_t key = message.pduSessionId % hashTable->size;
    LinkedListNode* current = hashTable->buckets[key];
    LinkedListNode* previous = NULL;
    while (current != NULL) {
        if (current->message.pduSessionId == message.pduSessionId) {
            if (previous == NULL) {
                hashTable->buckets[key] = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to iterate over the hash table
void iterateMessages(HashTable* hashTable, void (*callback)(LTE_EPC_GTPV2_MESSAGE)) {
    for (int i = 0; i < hashTable->size; i++) {
        LinkedListNode* current = hashTable->buckets[i];
        while (current != NULL) {
            callback(current->message);
            current = current->next;
        }
    }
}

// Function to initialize the linked list
LinkedListNode* initLinkedList() {
    return NULL;
}

// Function to add a message to the linked list
void addMessage(LinkedListNode** head, LTE_EPC_GTPV2_MESSAGE message) {
    LinkedListNode* newNode = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    newNode->message = message;
    newNode->next = *head;
    *head = newNode;
}

// Function to remove a message from the linked list
void removeMessageFromList(LinkedListNode** head, LTE_EPC_GTPV2_MESSAGE message) {
    LinkedListNode* current = *head;
    LinkedListNode* previous = NULL;
    while (current != NULL) {
        if (current->message.pduSessionId == message.pduSessionId) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to iterate over the linked list
void iterateMessagesList(LinkedListNode* head, void (*callback)(LTE_EPC_GTPV2_MESSAGE)) {
    while (head != NULL) {
        callback(head->message);
        head = head->next;
    }
}
