    long Timestamp;
    char SourceAddress[20];
    int PayloadLength;
} DataPacket;

// Define the list node structure
typedef struct Node {
    DataPacket* packet;
    struct Node* next;
} Node;

// Function to create a new Node with a given DataPacket
Node* createNode(DataPacket* packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    newNode->packet = packet;
    newNode->next = NULL;
    return newNode;
}

// Function to add a DataPacket to the list
void addPacket(Node** headRef, DataPacket* packet) {
    Node* newHead = (Node*)malloc(sizeof(Node));
    if (!newHead) {
        printf("Memory allocation failed.\n");
        return;
    }
    newHead->packet = packet;
    newHead->next = *headRef;
    *headRef = newHead;
}

// Function to find a DataPacket by Timestamp and SourceAddress
DataPacket* findPacket(Node* head, long timestamp, char sourceAddress[20]) {
    Node* current = head;
    while (current) {
        if (current->packet->Timestamp == timestamp && strcmp(current->packet->SourceAddress, sourceAddress) == 0) {
            return current->packet;
        }
        current = current->next;
    }
    return NULL;
}

// Function to remove a DataPacket by Timestamp and SourceAddress
void removePacket(Node** headRef, long timestamp, char sourceAddress[20]) {
    if (*headRef == NULL) {
        printf("List is empty.\n");
        return;
    }

    Node* current = *headRef;
    Node* previous = NULL;

    while (current && (current->packet->Timestamp != timestamp || strcmp(current->packet->SourceAddress, sourceAddress) != 0)) {
        previous = current;
        current = current->next;
    }

    if (current) {
        if (previous) {
            previous->next = current->next;
        } else {
            *headRef = current->next;
        }
        free(current);
    }
}

// Function to print the list
void printList(Node* head) {
    Node* current = head;
    while (current) {
        printf("Timestamp: %ld, SourceAddress: %s, PayloadLength: %d\n", current->packet->Timestamp, current->packet->SourceAddress, current->packet->PayloadLength);
        current = current->next;
    }
}

// Function to free the list
void freeList(Node** headRef) {
    Node* current = *headRef;
    Node* nextNode;

    while (current) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }

    *headRef = NULL;
}
