        measurements[i]->PHY_MEASUREMENTS_TAG = i + 1;
        measurements[i]->MEASUREMENT_TYPE = rand() % 3;
        measurements[i]->TIMESTAMP = time(NULL);

        // Logging mechanism
        printf("Measurement %d added: MEASUREMENT_FLAG = %d, MEASUREMENT_TYPE = %d\n", i, measurements[i]->MEASUREMENT_FLAG, measurements[i]->MEASUREMENT_TYPE);
    }

    // Error checking for memory allocation
    if (*measurements == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }
}

void add_measurement(LTE_PHY_MEASUREMENTS_T **measurements, int *size) {
    LTE_PHY_MEASUREMENTS_T *new_measurement = (LTE_PHY_MEASUREMENTS_T *)malloc(sizeof(LTE_PHY_MEASUREMENTS_T));

    if(new_measurement == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    new_measurement->MEASUREMENT_FLAG = (*size) % 2 == 0 ? 0 : 1;
    new_measurement->PHY_MEASUREMENTS_TAG = *size + 1;
    new_measurement->MEASUREMENT_TYPE = rand() % 3;
    new_measurement->TIMESTAMP = time(NULL);

    // Add to the list
    measurements[*size] = new_measurement;
    (*size)++;
}

void remove_measurement(LTE_PHY_MEASUREMENTS_T **measurements, int *size) {
    if(*size > 0) {
        free(measurements[(*size) - 1]);
        for(int i = (*size) - 1; i > 0; i--) {
            measurements[i] = measurements[i - 1];
        }

        // Decrement size
        (*size]--;
    }
}

void iterate_measurements(LTE_PHY_MEASUREMENTS_T **measurements, int *size) {
    for(int i = 0; i < *size; i++) {
        printf("Measurement %d: MEASUREMENT_FLAG = %d, MEASUREMENT_TYPE = %d\n", i, measurements[i]->MEASUREMENT_FLAG, measurements[i]->MEASUREMENT_TYPE);
    }
}

int main() {
