    LTE_PHY_MEASUREMENTS_T *measurements = NULL;

    manage_lte_phy_measurements_list(&measurements, &size);

    add_measurement(&measurements, &size);
    add_measurement(&measurements, &size);

    iterate_measurements(&measurements, &size);

    remove_measurement(&measurements, &size);

    return 0;
}

