#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <pthread.h>

// Define the structure for MAC transaction
typedef struct {
    uint64_t mac_transaction_id;
    char mac_pdu[16];  // Randomly generated MAC PDU
} MAC_TRANSACTION_T;

// Function to manage a dynamically allocated array of MAC TRANSACTION T structures
void* mac_transactions = NULL;
int num_transactions = 0;
pthread_mutex_t transaction_lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function to allocate memory for the array and initialize transactions
void* initialize_transactions(int capacity) {
    mac_transactions = malloc(capacity * sizeof(MAC_TRANSACTION_T));
    if (mac_transactions == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    for (int i = 0; i < capacity; i++) {
        MAC_TRANSACTION_T* transaction = &((MAC_TRANSACTION_T*)mac_transactions)[i];
        transaction->mac_transaction_id = i;
        // Randomly generate MAC PDU
        char* pdu = (char*)malloc(16);
        int random_length = rand() % 15 + 1;
        for (int j = 0; j < random_length; j++) {
            pdu[j] = (char)(rand() % 256);
        }
        transaction->mac_pdu[0] = '\0';
        strcat(transaction->mac_pdu, pdu);
        free(pdu);
    }
    return mac_transactions;
}

// Add a new transaction to the array
int add_transaction(MAC_TRANSACTION_T* transaction) {
    pthread_mutex_lock(&transaction_lock);
    if (num_transactions >= sizeof(mac_transactions) / sizeof(MAC_TRANSACTION_T)) {
        // Handle overflow condition
        printf("Transaction array is full. Cannot add more transactions.\n");
        pthread_mutex_unlock(&transaction_lock);
        return -1;
    }
    MAC_TRANSACTION_T* current_transactions = (MAC_TRANSACTION_T*)mac_transactions;
    memcpy(&current_transactions[num_transactions], transaction, sizeof(MAC_TRANSACTION_T));
    num_transactions++;
    pthread_mutex_unlock(&transaction_lock);
    return 0;
}

// Remove a transaction from the array
int remove_transaction(uint64_t mac_transaction_id) {
    pthread_mutex_lock(&transaction_lock);
    for (int i = 0; i < num_transactions; i++) {
        if (((MAC_TRANSACTION_T*)mac_transactions)[i].mac_transaction_id == mac_transaction_id) {
            // Shift remaining transactions to fill the gap
            memmove((void*)&((MAC_TRANSACTION_T*)mac_transactions)[i], (void*)&((MAC_TRANSACTION_T*)mac_transactions)[i + 1],
                    (num_transactions - i - 1) * sizeof(MAC_TRANSACTION_T));
            num_transactions--;
            pthread_mutex_unlock(&transaction_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&transaction_lock);
    return -1;  // Transaction not found
}

// Query a transaction by ID
int query_transaction(uint64_t mac_transaction_id) {
    pthread_mutex_lock(&transaction_lock);
    for (int i = 0; i < num_transactions; i++) {
        if (((MAC_TRANSACTION_T*)mac_transactions)[i].mac_transaction_id == mac_transaction_id) {
            // Return the transaction details
            pthread_mutex_unlock(&transaction_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&transaction_lock);
    return -1;  // Transaction not found
}

// Destructor to release memory when the program terminates
void destroy_transactions() {
    free(mac_transactions);
}
