pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void create_crc_indication_pdu_list(int n) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            printf("Memory allocation failed!\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        pdu->RX_UE_INFORMATION_TAG = i % 256;
        pdu->RNTI = (i / 256) % 256;
        pdu->CRC_INDICATION_REL8_TAG = i & 0xFF;

        if (!validate_pdu(pdu)) {
            free(pdu);
            continue;
        }

        list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list_size + 1));
        if (!list) {
            printf("Memory reallocation failed!\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        list[list_size] = pdu;
        list_size++;
    }

    pthread_mutex_unlock(&mutex);
}

int validate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Add your validation logic here
    if (pdu->RX_UE_INFORMATION_TAG > 255 || pdu->RNTI > 255) {
        return 0;
    }
    return 1;
}
