#include <pthread.h>

// Define the LTE UE Context Information structure
typedef struct {
    int ue_id;
    float *pdcp_snr_reports;
    size_t report_count;
    size_t buffer_size;
} lte_ue_context_info;

// Initialize and manage a list of LTE UE Context Information structures
void* init_ue_list(size_t initial_buffer_size) {
    void **ue_list = (void**)malloc(sizeof(void*) * initial_buffer_size);
    pthread_mutex_init(&mutex, NULL);

    return ue_list;
}

// Add a new LTE UE Context Information structure to the list
int add_ue(lte_ue_context_info* ue_info, size_t buffer_size, void** ue_list) {
    lte_ue_context_info* new_ue = (lte_ue_context_info*)malloc(sizeof(lte_ue_context_info));
    new_ue->ue_id = ue_info->ue_id;
    new_ue->pdcp_snr_reports = (float*)malloc(buffer_size * sizeof(float));
    new_ue->report_count = 0;
    new_ue->buffer_size = buffer_size;

    pthread_mutex_lock(&mutex);
    // Add the new UE to the list and update the report count
    for (size_t i = 0; i < ue_list.size; i++) {
        if (!ue_list[i]) {
            ue_list[i] = &new_ue;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    return 1;
}

// Remove a LTE UE Context Information structure from the list
int remove_ue(int ue_id, void** ue_list) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < ue_list.size; i++) {
        if (((lte_ue_context_info*)ue_list[i])->ue_id == ue_id) {
            free(ue_list[i]->pdcp_snr_reports);
            free(ue_list[i]);
            memmove(ue_list + i, ue_list + i + 1, sizeof(void*) * (ue_list.size - i));
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Update the PDCP SNR reports for a specific UE
int update_ue_reports(int ue_id, float* new_reports, size_t report_count, void** ue_list) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < ue_list.size; i++) {
        if (((lte_ue_context_info*)ue_list[i])->ue_id == ue_id) {
            // Update the reports and report count
            free(((lte_ue_context_info*)ue_list[i])->pdcp_snr_reports);
            ((lte_ue_context_info*)ue_list[i])->pdcp_snr_reports = (float*)malloc(report_count * sizeof(float));
            memcpy(((lte_ue_context_info*)ue_list[i])->pdcp_snr_reports, new_reports, report_count * sizeof(float));
            ((lte_ue_context_info*)ue_list[i])->report_count = report_count;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Flush old reports and update the UE list
void flush_old_reports(void** ue_list) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < ue_list.size; i++) {
        if (((lte_ue_context_info*)ue_list[i])->report_count > 0) {
            // Flush old reports and update the report count
            free(((lte_ue_context_info*)ue_list[i])->pdcp_snr_reports);
            ((lte_ue_context_info*)ue_list[i])->pdcp_snr_reports = (float*)malloc(((lte_ue_context_info*)ue_list[i])->buffer_size * sizeof(float));
            ((lte_ue_context_info*)ue_list[i])->report_count = 0;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Monitor and log context information
void monitor_ue_list(void** ue_list) {
    // Log UE list statistics and report counts
    for (size_t i = 0; i < ue_list.size; i++) {
        printf("UE %d: Report count = %zu, Buffer size = %zu\n", ((lte_ue_context_info*)ue_list[i])->ue_id, ((lte_ue_context_info*)ue_list[i])->report_count, ((lte_ue_context_info*)ue_list[i])->buffer_size);
    }
}

int main() {
    void* ue_list = init_ue_list(10);
    // Add UEs to the list
    add_ue(&ue1, 5, ue_list);
    add_ue(&ue2, 3, ue_list);
    // Update UE reports
    update_ue_reports(ue1.id, new_report1, report_count1, ue_list);
    update_ue_reports(ue2.id, new_report2, report_count2, ue_list);
    // Flush old reports and update the UE list
    flush_old_reports(ue_list);
    // Monitor and log context information
    monitor_ue_list(ue_list);

    return 0;
}
