NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int n) {
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        int rx_ue_info_tag = i;
        unsigned long rnti = rand() % 4294967295 + 1;
        int crc_indication_rel8_tag = (rand() % 2) ? 1 : 0;
