            crc_indication_rel8_tag |= 2;
        crc_indications[i].rx_ue_info_tag = rx_ue_info_tag;
        crc_indications[i].rnti = rnti;
        crc_indications[i].crc_indication_rel8_tag = crc_indication_rel8_tag;
    }
    return crc_indications;
}

void store_crc_indications(const char* config_dir, NFAPI_CRC_INDICATION_PDU_T** crc_indications, int n) {
    DIR* dir = opendir(config_dir);
    if (dir == NULL && errno != ENOENT) {
        // Retry logic for transient failures
        sleep(1);
        dir = opendir(config_dir);
        if (dir == NULL)
            exit(EXIT_FAILURE);
    }
    if (mkdir(config_dir, S_IRWXU | S_IRGRP | S_IROTH) && errno != EEXIST)
        exit(EXIT_FAILURE);
    for (int i = 0; i < n; i++) {
        char file_name[16];
        sprintf(file_name, "crc_indication_%d.bin", i);
        FILE* file = fopen(strcat(config_dir, "/"), file_name, "wb");
        if (file == NULL)
            exit(EXIT_FAILURE);
        fwrite(&((*crc_indications)[i]), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        fclose(file);
    }
    closedir(dir);
}
