#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_N 1000
#define MAX_TAG_LENGTH 32
#define MAX_RNTI 255
#define CRCFLAG 1

typedef struct {
    char RX_UE_INFORMATION_TAG[MAX_TAG_LENGTH];
    int RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *list = NULL;
int list_size = 0;
int max_list_size = MAX_N;
int log_index = 0;
FILE *log_file = fopen("CRC_indications.log", "a+");
pthread_mutex_t lock_log = PTHREAD_MUTEX_INITIALIZER;

void add_CRC_indication(int N) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < N; i++) {
        if (list_size >= max_list_size) {
            list = realloc(list, (max_list_size + MAX_N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!list) {
                perror("Memory allocation failed");
                pthread_mutex_unlock(&lock);
                return;
            }
            max_list_size += MAX_N;
        }
        NFAPI_CRC_INDICATION_PDU_T* new_indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_indication) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&lock);
            return;
        }
        strcpy(new_indication->RX_UE_INFORMATION_TAG, "tag");
        new_indication->RNTI = rand() % MAX_RNTI;
        new_indication->CRC_INDICATION_REL8_TAG = rand();
        time_t timestamp = time(NULL);
        new_indication->timestamp = timestamp;
        pthread_mutex_lock(&lock_log);
        fprintf(log_file, "%s: %s, RNTI: %d, Timestamp: %ld\n", "NEW_CRC_INDICATION", new_indication->RX_UE_INFORMATION_TAG, new_indication->RNTI, timestamp);
        pthread_mutex_unlock(&lock_log);
        free(list[list_size]);
        list[list_size] = new_indication;
        list_size++;
    }
    pthread_mutex_unlock(&lock);
}

void remove_CRC_indication(int N) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < N; i++) {
        if (list_size >= N) {
            for (int j = 0; j < N; j++) {
                free(list[j]);
            }
            free(list);
            list = NULL;
            list_size = 0;
            max_list_size = MAX_N;
        } else {
            for (int j = i; j < list_size; j++) {
                list[j] = list[j + 1];
            }
            list_size -= N;
        }
    }
    pthread_mutex_unlock(&lock);
}

void print_CRC_indications() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < list_size; i++) {
        printf("%s: %s, RNTI: %d, Timestamp: %ld\n", "CRC_INDICATION", list[i]->RX_UE_INFORMATION_TAG, list[i]->RNTI, list[i]->timestamp);
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    int N = 10;
    add_CRC_indication(N);
    print_CRC_indications();
    remove_CRC_indication(N);
    return 0;
}
