#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

typedef struct {
    char mac[18];
    struct sockaddr_in ip;
} InterfaceConfig;

typedef struct {
    int config_id;
    InterfaceConfig *configs;
    int config_count;
} NetworkConfigDB;

NetworkConfigDB* init_network_config_db() {
    return (NetworkConfigDB*)malloc(sizeof(NetworkConfigDB));
}

int add_interface_config(NetworkConfigDB* db, const char* mac, const char* ip_str, const char* subnet_mask_str) {
    // Convert IP and subnet mask to struct sockaddr_in
    InterfaceConfig* config = (InterfaceConfig*)malloc(sizeof(InterfaceConfig));
    strcpy(config->mac, mac);
    inet_pton(AF_INET, ip_str, &config->ip.sin_addr);
    config->ip.sin_family = AF_INET;
    inet_pton(AF_INET, subnet_mask_str, &config->ip.sin_mask);

    // Check for IP overlap
    for (int i = 0; i < db->config_count; i++) {
        if ((db->configs[i].ip.sin_addr.s_addr & config->ip.sin_mask.s_addr) == (db->configs[i].ip.sin_addr.s_addr & config->ip.sin_addr.s_addr)) {
            free(config);
            return -1;
        }
    }

    // Add new configuration
    db->config_count++;
    if (db->configs == NULL) {
        db->configs = (InterfaceConfig*)malloc(sizeof(InterfaceConfig));
        db->configs[0] = *config;
    } else {
        InterfaceConfig* temp = (InterfaceConfig*)realloc(db->configs, sizeof(InterfaceConfig) * (db->config_count + 1));
        temp[db->config_count - 1] = *config;
        free(config);
        db->configs = temp;
    }
    return 0;
}

int remove_interface_config(NetworkConfigDB* db, const char* mac) {
    for (int i = 0; i < db->config_count; i++) {
        if (!strcmp(db->configs[i].mac, mac)) {
            // Move last configuration to the current position
            memmove(&db->configs[i], &db->configs[i + 1], sizeof(InterfaceConfig) * (db->config_count - i - 1));
            db->config_count--;
            return 0;
        }
    }
    return -1; // Configuration not found
}

int free_network_config_db(NetworkConfigDB* db) {
    for (int i = 0; i < db->config_count; i++) {
        free(db->configs[i].mac);
        free((void*)(&db->configs[i]));
    }
    free(db->configs);
    free(db);
}
