        structures[i].RNTI = rand();
        structures[i].CRC_INDICATION_REL8_TAG = rand();
        structures[i].CRCFLAG = (rand() % 2);
    }

    free(structures);

    return NULL;
}

int main(int argc, char** argv) {
    int N = atoi(argv[1]);

    pthread_t threads[N];
    int* args = (int*)malloc(N * sizeof(int));

    for(int i = 0; i < N; i++) {
        args[i] = i + 1;
        pthread_create(&threads[i], NULL, thread_function, &args[i]);
    }

    for(int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    free(args);

    return 0;
}
