void insert_LTEPHY_RRC_INTERFACE_MESSAGE(int rrc_connection_id, NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_t) {
    LTEPHY_RRC_INTERFACE_MESSAGE* new_element = (LTEPHY_RRC_INTERFACE_MESSAGE*)malloc(sizeof(LTEPHY_RRC_INTERFACE_MESSAGE));
