            uniqueRnti = rand();
            i = -1;
        }
    }
    return uniqueRnti;
}

void populateNFApiStructures() {
    for (int i = 0; i < arraySize; i++) {
        nfaPiArray[i]->RX_UE_INFORMATION_TAG = rand();
        nfaPiArray[i]->CRCFLAG = rand() % 2;
        nfaPiArray[i]->RNTI = getUniqueRnti();
    }
}

void* processNFApiStructures(void* arg) {
    int iterations = 0;
    while (1) {
        // Perform operations on NFAPI array
        cleanUpUnusedStructures();
        populateNFApiStructures();
        sleep(1); // Simulate processing time

        if (iterations >= CRCFLAG_MAX_ITERATIONS) {
            break;
        }
        iterations++;
    }
    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, processNFApiStructures, NULL);
    pthread_join(thread, NULL);

    return 0;
}
