            (*tail)->next = newNode;
        } else {
            head = newNode;
        }

        *tail = newNode;
    }

    return head;
}

void freeList(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
