#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

#define MAX_STRUCTURES 1024
#define THRESHOLD 5 // packet loss percentage

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *structures[MAX_STRUCTURES];
int active_structures = 0;
int inactive_structures = 0;

void* initialize_array(int size) {
    for (int i = 0; i < size; i++) {
        structures[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structures[i]) {
            printf("Memory allocation failed\n");
            return NULL;
        }
    }
    return NULL;
}

void add_structure(NFAPI_CRC_INDICATION_PDU_T* new_struct) {
    pthread_mutex_lock(&mutex);
    structures[active_structures] = new_struct;
    active_structures++;
    pthread_mutex_unlock(&mutex);
}

void remove_structure(int index) {
    pthread_mutex_lock(&mutex);
    if (index < active_structures) {
        free(structures[index]);
        memmove(&structures[index], &structures[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (active_structures - index - 1));
        active_structures--;
    }
    pthread_mutex_unlock(&mutex);
}

void iterate_array(void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < active_structures; i++) {
        callback(structures[i]);
    }
    pthread_mutex_unlock(&mutex);
}

void cleanup_unused_structures() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (!structures[i]) continue;
        free(structures[i]);
        structures[i] = NULL;
    }
    pthread_mutex_unlock(&mutex);
}

int get_active_structures() {
    return active_structures;
}

int get_inactive_structures() {
    return inactive_structures;
}

void log_performance() {
    printf("Active structures: %d, Inactive structures: %d\n", active_structures, inactive_structures);
}
