typedef struct {
    char ip[16];
    char subnet_mask[16];
    char gateway_address[16];
    int port_number;
} NetConfigSetting;

// A dynamic array of NetConfigSettings
typedef struct {
    size_t capacity;
    size_t size;
    NetConfigSetting* settings;
} NetConfigCollection;

NetConfigCollection* net_config_collection_create(size_t initial_capacity) {
    NetConfigCollection* collection = malloc(sizeof(NetConfigCollection));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->settings = calloc(initial_capacity, sizeof(NetConfigSetting));
    return collection;
}

void net_config_collection_destroy(NetConfigCollection* collection) {
    free(collection->settings);
    free(collection);
}

int net_config_collection_add_setting(NetConfigCollection* collection, NetConfigSetting setting) {
    if (collection->size >= collection->capacity) {
        // Double the capacity when it's full
        collection->capacity *= 2;
        collection->settings = realloc(collection->settings, collection->capacity * sizeof(NetConfigSetting));
    }

    size_t i;
    for (i = 0; i < collection->size; i++) {
        if (!strcmp(setting.ip, collection->settings[i].ip) &&
            !strcmp(setting.subnet_mask, collection->settings[i].subnet_mask)) {
            printf("Error: Duplicate IP and subnet mask combination\n");
            return -1;
        }
    }

    collection->settings[collection->size] = setting;
    collection->size++;
    return 0;
}

int net_config_collection_get_setting(NetConfigCollection* collection, size_t index, NetConfigSetting* setting) {
    if (index >= collection->size) {
        printf("Error: Index out of bounds\n");
        return -1;
    }

    *setting = collection->settings[index];
    return 0;
}

int main() {
    // Example usage
    NetConfigCollection* collection = net_config_collection_create(2);
    NetConfigSetting setting1 = {"192.168.1.100", "255.255.255.0", "192.168.1.254", 22};
    NetConfigSetting setting2 = {"10.0.0.100", "255.255.255.0", "10.0.0.254", 80};

    net_config_collection_add_setting(collection, setting1);
    net_config_collection_add_setting(collection, setting2);

    NetConfigSetting retrieved;
    net_config_collection_get_setting(collection, 0, &retrieved);
    printf("Retrieved IP: %s\n", retrieved.ip);

    return 0;
}
