    NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_pi_crc_indication_pdu) return NULL;

    nfa_pi_crc_indication_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    nfa_pi_crc_indication_pdu->RNTI = RNTI;
    nfa_pi_crc_indication_pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    return nfa_pi_crc_indication_pdu;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T to the linked list
void add_nfa_pi_crc_indication_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T** head, int RX_UE_INFORMATION_TAG, int RNTI) {
    // Check if an NFAPI_CRC_INDICATION_PDU_T with same RX_UE_INFORMATION_TAG and RNTI already exists in the list
    for (NFAPI_CRC_INDICATION_PDU_T* current = *head; current != NULL; current = current->next) {
        if ((current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) && (current->RNTI == RNTI)) return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_pdu = create_nfa_pi_crc_indication_pdu(RX_UE_INFORMATION_TAG, RNTI);
    if (!new_pdu) return;

    // Add the new pdu to the end of the list
    if (*head == NULL) {
        *head = new_pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* last = *head;
        while (last->next != NULL) last = last->next;
        last->next = new_pdu;
    }
}

// Function to create a new LTE PHY layer PDU
LTE_PHY_layer_PDU* create_lte_phy_layer_pdu(int frame_number, long timestamp, int num_PRB_occupancy_indicators) {
    LTE_PHY_layer_PDU* lte_phy_layer_pdu = (LTE_PHY_layer_PDU*)malloc(sizeof(LTE_PHY_layer_PDU) + sizeof(int) * num_PRB_occupancy_indicators);
    if (!lte_phy_layer_pdu) return NULL;

    lte_phy_layer_pdu->frame_number = frame_number;
    lte_phy_layer_pdu->timestamp = timestamp;

    return lte_phy_layer_pdu;
}

// Function to add a new LTE PHY layer PDU to the dynamic array
void add_lte_phy_layer_pdu_to_array(LTE_PHY_layer_PDU** arr, int* size, int frame_number, long timestamp, int num_PRB_occupancy_indicators) {
    // Resize the array if necessary
    if (*size == 0) *arr = (LTE_PHY_layer_PDU*)malloc(sizeof(LTE_PHY_layer_PDU));
    else if (*size <= (int)((*size - 1) * 1.5)) {
        int new_size = (int)(2 * *size);
        *arr = (LTE_PHY_layer_PDU*)realloc(*arr, sizeof(LTE_PHY_layer_PDU) * new_size);
    }

    // Add the new pdu to the array
    if (*size > 0) {
        for (int i = *size - 1; i >= 0; --i) {
            arr[i + 1] = arr[i];
        }
    }
    arr[0] = create_lte_phy_layer_pdu(frame_number, timestamp, num_PRB_occupancy_indicators);

    (*size)++;
}

// Function to remove a PDU from the dynamic array by frame number
void remove_pdu_from_array(LTE_PHY_layer_PDU** arr, int* size, int frame_number) {
    for (int i = 0; i < *size; ++i) {
        if ((arr[i]->frame_number == frame_number)) {
            // Shift all PDUs to the left after removing
            for (int j = i + 1; j < *size; ++j) arr[j - 1] = arr[j];
            --*size;
            free(arr[*size]);
            return;
        }
    }
}

