NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int n, int seed) {
    // Initialize variables for dynamic memory allocation
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;
    int max_elements = 100000;
    int threshold_mb = 5;
    int concurrency_level = 4;
    int retry_limit = 3;

    // Initialize random seed
    srand(seed);

    // Loop to create and populate linked list
