    NFAPI_CRC_INDICATION_PDU_T* temp;

    while (current && current->next) {
        temp = current->next;
        free(current);
        current = temp;
    }

    if (current) {
        free(current);
    }
}

// Function to map RNTI and validate the integrity of the linked list
int validate_linked_list(NFAPI_CRC_INDICATION_PDU_T* head, int rnti_map_fd) {
