#define MAX_LIST_SIZE 10000
#define MIN_BACKOFF 100
#define MAX_BACKOFF 5000

typedef struct {
    char tag[32];
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void init_and_populate_list(int seed, int max_size, int *num_allocated, int **list) {
    srand(seed);
    *num_allocated = 0;
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < max_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* p = &(*list)[i];
        strcpy(p->tag, "RX_UE_INFORMATION_TAG");
        p->RNTI = rand() % 100000;
        p->CRCFLAG = rand() % 2;

        if (p->RNTI < 0 || p->RNTI > 99999) {
            printf("Error: RNTI out of range\n");
            continue;
        }

        // Check for duplicates
        int found_duplicate = 0;
        for (int j = 0; j < *num_allocated; j++) {
            if (*list[j].RNTI == p->RNTI) {
                found_duplicate = 1;
                break;
            }
        }

        if (found_duplicate) {
            // Handle duplicate RNTI
            printf("Duplicate RNTI detected\n");
            if (p->CRCFLAG > *list[(*num_allocated - 1)].CRCFLAG) {
                free(*list);
                *num_allocated = 0;
                *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(2 * max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            } else {
                // Discard current structure
                continue;
            }
        }

        (*num_allocated)++;
    }
}

void log_structure_init(NFAPI_CRC_INDICATION_PDU_T* p) {
    time_t now = time(NULL);
    printf("Timestamp: %lu, RNTI: %d, CRC Indication Status: %s\n", (long unsigned)now, p->RNTI, p->CRCFLAG ? "Indicated" : "Not Indicated");
}

void periodically_compact_memory(int *num_allocated, int **list) {
    for (int i = 0; i < *num_allocated; i++) {
        // Compact memory every 10th element
        if ((i + 1) % 10 == 0 && i > 0) {
            NFAPI_CRC_INDICATION_PDU_T* p = &(*list)[i];
            memmove(p, (*list) + (i - 1), sizeof(NFAPI_CRC_INDICATION_PDU_T));
            free(&(*list)[i - 1]);
        }
    }
}

void handle_transient_failure(int *num_allocated, int **list) {
    // Retry mechanism with configurable backoff
    int backoff = MIN_BACKOFF;
    while (backoff <= MAX_BACKOFF) {
        // Simulate transient failure
        printf("Transient failure detected. Retrying in %d milliseconds...\n", backoff);
        sleep(backoff / 1000);

        // If successful, reset backoff and continue
        if (*num_allocated > 0) {
            backoff *= 2;
            break;
        }

        // Increase backoff if still failing
        backoff *= 2;
    }
}

int main() {
    int seed = time(NULL);
    int max_size = MAX_LIST_SIZE;
    int num_allocated = 0;
    int *list;

    init_and_populate_list(seed, max_size, &num_allocated, &list);

    // Periodic memory compaction
    while (1) {
        periodically_compact_memory(&num_allocated, &list);
        sleep(10000); // every 10 seconds
    }

    return 0;
}
