// Define the maximum number of elements
#define MAX_ELEMENTS 1000

// Define the upper limit for N
#define UPPER_LIMIT 50000

// Define a struct to store RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage the dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
void* initialize_array(int N, uint32_t seed, void** output) {
    // Validate input parameters
    if (N <= 0 || N > UPPER_LIMIT) {
        printf("Invalid number of elements: %d\n", N);
        return NULL;
    }

    // Initialize the DHT for unique RX_UE_INFORMATION_TAG and RNTI values
    pthread_mutex_t dht_lock = PTHREAD_MUTEX_INITIALIZER;
    uint32_t* dht = (uint32_t*)malloc((N + 1) * sizeof(uint32_t));
    srand(seed);

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!arr || !dht) {
        printf("Memory allocation failed\n");
        free(arr);
        free(dht);
        return NULL;
    }

    // Initialize each structure with unique RX_UE_INFORMATION_TAG and RNTI values
    for (int i = 0; i < N; i++) {
        uint32_t tag = rand() % ((1 << 16) - 1);
        uint16_t rnti = rand() % ((1 << 14) - 1);

        arr[i].RX_UE_INFORMATION_TAG = tag;
        arr[i].RNTI = rnti;
        arr[i].CRCFLAG = rand() & 0x01;

        pthread_mutex_lock(&dht_lock);
        dht[tag] = i;
        pthread_mutex_unlock(&dht_lock);
    }

    *output = arr;
    return NULL;
}

// Function to release allocated resources
void cleanup(void** output) {
    if (!*output) {
        return;
    }

    free(*output);
    *output = NULL;
}

// Function to dynamically resize the array based on system resource availability and usage patterns
void* resize_array(int N, void** output) {
    // Resize the array using realloc()
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*output, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!arr) {
        printf("Memory reallocation failed\n");
        return NULL;
    }

    *output = arr;

    // Update the DHT for unique RX_UE_INFORMATION_TAG and RNTI values
    pthread_mutex_lock(&dht_lock);
    for (int i = 0; i < N; i++) {
        uint32_t tag = rand() % ((1 << 16) - 1);
        uint16_t rnti = rand() % ((1 << 14) - 1);

        arr[i].RX_UE_INFORMATION_TAG = tag;
        arr[i].RNTI = rnti;
        arr[i].CRCFLAG = rand() & 0x01;

        dht[tag] = i;
    }
    pthread_mutex_unlock(&dht_lock);
}

// Function to log initialization attempts and errors
void log_init_attempt(int N, uint32_t seed) {
    FILE* log_file = fopen("log.txt", "a");
    if (!log_file) {
        printf("Error opening log file\n");
        return;
    }

    fprintf(log_file, "Initialization attempt with %d elements and seed %u\n", N, seed);
    fclose(log_file);
}
