#include <stdlib.h>
#include <string.h>

typedef struct {
    char ue_id[32];
    int ip_addr;
    int port;
    struct connection* connections;
} session_context;

typedef struct connection {
    int protocol;
    char remote_ip[16];
    int remote_port;
    struct connection* next;
} connection;

session_context* sessions = NULL;
int num_sessions = 0;

void add_session(char* ue_id, int ip_addr, int port) {
    session_context* new_session = malloc(sizeof(session_context));
    strcpy(new_session->ue_id, ue_id);
    new_session->ip_addr = ip_addr;
    new_session->port = port;
    new_session->connections = NULL;

    if (sessions == NULL) {
        sessions = &new_session;
    } else {
        session_context* current = sessions;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = &new_session;
    }

    num_sessions++;
}

void remove_session(char* ue_id) {
    if (num_sessions == 0) return;

    session_context* current = sessions;
    for (int i = 0; i < num_sessions - 1; i++) {
        if (strcmp(current->ue_id, ue_id) == 0) {
            // Remove this session
            session_context* next_session = current->next;
            free(current);
            current = next_session;
            num_sessions--;
            return;
        }
        current = current->next;
    }
}

void update_ip(char* ue_id, int new_ip_addr) {
    session_context* current = sessions;
    for (int i = 0; i < num_sessions; i++) {
        if (strcmp(current->ue_id, ue_id) == 0) {
            current->ip_addr = new_ip_addr;
            return;
        }
        current = current->next;
    }
}

void print_sessions() {
    session_context* current = sessions;
    for (int i = 0; i < num_sessions; i++) {
        printf("UE ID: %s, IP: %d, Port: %d\n", current->ue_id, current->ip_addr, current->port);
        connection* c = current->connections;
        while (c != NULL) {
            printf("  Protocol: %d, Remote IP: %s, Remote Port: %d\n", c->protocol, c->remote_ip, c->remote_port);
            c = c->next;
        }
        current = current->next;
    }
}
