    int seed;
    int current_entry;
} ArrayStruct;

ArrayStruct arrays[10]; // Define maximum number of arrays

void init_array(int index, int n, int max_entries) {
    arrays[index].N = n;
    arrays[index].MAX_ENTRIES = max_entries;
    arrays[index].seed = time(NULL); // Use current time as seed
    arrays[index].arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_entries * sizeof(NFAPI_CRC_INDATION_PDU_T));
    arrays[index].current_entry = 0;
}

void switch_array(int old_index, int new_index) {
    // Copy elements from old array to the current entry of the new array
    for (int i = 0; i < arrays[old_index].current_entry; i++) {
        arrays[new_index].arr[i] = arrays[old_index].arr[i];
    }
    arrays[old_index].current_entry = 0;
}

void insert_element(int index) {
    if (arrays[index].current_entry >= arrays[index].MAX_ENTRIES) {
        printf("Array full. Cannot insert new element.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* elem = &arrays[index].arr[arrays[index].current_entry];
    // Generate random CRCFLAG using the seed
    srand(arrays[index].seed);
    *elem = (NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = rand() % 100, .RNTI = rand() % 256, .CRC_INDICATION_REL8_TAG = rand() % 255};
    arrays[index].current_entry++;
}

void retrieve_element(int index) {
    if (index >= arrays[0].N || arrays[index].current_entry <= 0) {
        printf("Array empty or out of bounds. Cannot retrieve element.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* elem = &arrays[index].arr[arrays[index].current_entry - 1];
    printf("Retrieved element at index %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n", index, elem->RX_UE_INFORMATION_TAG, elem->RNTI, elem->CRC_INDICATION_REL8_TAG);
}

void log_operation(int operation_type) {
    time_t now = time(NULL);
    char* timestamp_str = ctime(&now);

    // Implement circular buffer for logging
    static char log_buffer[100];
    sprintf(log_buffer, "%s: %s\n", timestamp_str, (operation_type == 0 ? "Insertion" : operation_type == 1 ? "Retrieval" : "Array Switch"));
    printf("%s", log_buffer);
}

int main() {
    init_array(0, 5, 10); // Initialize array 0 with 5 entries and max entries of 10
    init_array(1, 3, 8); // Initialize array 1 with 3 entries and max entries of 8

    insert_element(0); // Insert element in array 0
    retrieve_element(0); // Retrieve element from array 0
    switch_array(0, 1); // Switch to array 1
    insert_element(1); // Insert element in array 1
    retrieve_element(1); // Retrieve element from array 1

    return 0;
}
