NFAPI_CRC_INDICATION_PDU_T* createList(int n) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            printf("Memory allocation failed\n");
            return head;
        }

        // Generate random RNTI
        srand(time(NULL));
        int rnti = rand() % 1000 + 1;

        // Set CRCFLAG randomly
        int crcflag = (rand() % 2);

        strcpy(new_node->RX_UE_INFORMATION_TAG, "Information_Tag");
        new_node->RNTI = rnti;
        strcpy(new_node->CRC_INDICATION_REL8_TAG, "Tag");
        new_node->CRCFLAG = crcflag;

        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }
    return head;
}
