#include <string.h>

#define MAX_Ueid 16
#define MAX_Stmsi 32
#define MAX_Guti 64
#define LIST_SIZE_THRESHOLD 1000

typedef struct {
    char ueid[MAX_Ueid];
    char stmsi[MAX_Stmsi];
    char guti[MAX_Guti];
} LTEUEContext;

typedef struct {
    LTEUEContext* records;
    int size;
    int capacity;
} LTEUEContextList;

LTEUEContextList* lteue_context_list_init(int initial_capacity) {
    LTEUEContextList* list = (LTEUEContextList*)malloc(sizeof(LTEUEContextList));
    list->records = (LTEUEContext*)calloc(initial_capacity, sizeof(LTEUEContext));
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void lteue_context_list_free(LTEUEContextList* list) {
    if (!list) return;
    free(list->records);
    free(list);
}

int lteue_context_list_add(LTEUEContextList* list, LTEUEContext record) {
    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2;
        LTEUEContext* new_records = (LTEUEContext*)realloc(list->records, new_capacity * sizeof(LTEUEContext));
        list->records = new_records;
        list->capacity = new_capacity;
    }
    strcpy(record.ueid, "your_ue_id_here");
    strcpy(record.stmsi, "your_stmsi_here");
    strcpy(record.guti, "your_guti_here");
    list->records[list->size] = record;
    list->size++;
}

void lteue_context_list_prune(LTEUEContextList* list) {
    if (list->size > LIST_SIZE_THRESHOLD) {
        int new_size = LIST_SIZE_THRESHOLD / 2;
        LTEUEContext* new_records = (LTEUEContext*)malloc(new_size * sizeof(LTEUEContext));
        memcpy(new_records, list->records, new_size * sizeof(LTEUEContext));
        free(list->records);
        list->records = new_records;
        list->size = new_size;
    }
}

int main() {
    LTEUEContextList* list = lteue_context_list_init(10);

    // add some records
    LTEUEContext record1 = {"your_ue_id_here", "your_stmsi_here", "your_guti_here"};
    LTEUEContext record2 = {"another_ue_id_here", "another_stmsi_here", "another_guti_here"};

    lteue_context_list_add(list, record1);
    lteue_context_list_add(list, record2);

    // prune the list
    lteue_context_list_prune(list);

    return 0;
}
