typedef struct {
    int context_id;
    int ue_id;
    char serving_plmn[20];
    int rnti;
    int qos_param1;
    int qos_param2;
    // Add more fields as needed
} LTE_UE_CONTEXT_INFORMATION_T;

// Dynamic array of LTE UE Context Information structures
LTE_UE_CONTEXT_INFORMATION_T *ue_context_array = NULL;
int ue_context_array_size = 0;
int ue_context_array_max_size = 10; // Initial maximum size

void add_ue_context(LTE_UE_CONTEXT_INFORMATION_T *new_context) {
    if (ue_context_array_size >= ue_context_array_max_size) {
        // Reallocate memory with double the previous size
        LTE_UE_CONTEXT_INFORMATION_T *temp_array = realloc(ue_context_array, sizeof(LTE_UE_CONTEXT_INFORMATION_T) * ue_context_array_max_size * 2);
        if (!temp_array) {
            perror("Memory allocation failed");
            return;
        }
        ue_context_array = temp_array;
        ue_context_array_max_size *= 2;
    }
    // Add the new context to the array
    ue_context_array[ue_context_array_size++] = *new_context;
}

void remove_ue_context(int context_id) {
    for (int i = 0; i < ue_context_array_size; i++) {
        if (ue_context_array[i].context_id == context_id) {
            // Shift the remaining contexts down to fill the gap
            memmove(&ue_context_array[i], &ue_context_array[i + 1], sizeof(LTE_UE_CONTEXT_INFORMATION_T) * (ue_context_array_size - i - 1));
            ue_context_array_size--;
            return;
        }
    }
}

void update_qos(int context_id, int qos_param1, int qos_param2) {
    for (int i = 0; i < ue_context_array_size; i++) {
        if (ue_context_array[i].context_id == context_id) {
            // Update the QoS settings
            ue_context_array[i].qos_param1 = qos_param1;
            ue_context_array[i].qos_param2 = qos_param2;
            return;
        }
    }
}

void iterate_ue_contexts() {
    for (int i = 0; i < ue_context_array_size; i++) {
        // Process the UE context information
        printf("Context ID: %d, UE ID: %d, Serving PLMN: %s, RNTI: %d\n", 
               ue_context_array[i].context_id, ue_context_array[i].ue_id, ue_context_array[i].serving_plmn, ue_context_array[i].rnti);
    }
}
