#define MAX_PACKETS 1000
#define TIMESTAMP_MIN 0
#define TIMESTAMP_MAX 3600 // seconds in an hour

typedef struct {
    int packetID;
    time_t timestamp;
    size_t payloadSize;
} PacketHeader;

PacketHeader** initializePacketArray(int initialCapacity) {
    if (initialCapacity > MAX_PACKETS) {
        printf("Initial capacity exceeds maximum allowed.\n");
        return NULL;
    }

    PacketHeader** packets = (PacketHeader**)malloc(initialCapacity * sizeof(PacketHeader*));
    for (int i = 0; i < initialCapacity; i++) {
        packets[i] = (PacketHeader*)malloc(sizeof(PacketHeader));
        if (!packets[i]) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        packets[i]->packetID = -1; // Initialize packet ID
    }

    return packets;
}

void addPacket(PacketHeader** packets, int capacity, PacketHeader* newPacket) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < capacity; i++) {
        if (packets[i]->packetID == -1) { // Find an uninitialized packet
            packets[i] = newPacket;
            return;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void validatePacket(PacketHeader* packet) {
    if (packet->timestamp < TIMESTAMP_MIN || packet->timestamp > TIMESTAMP_MAX) {
        printf("Timestamp out of range.\n");
        return 1; // Error
    }
    if (packet->payloadSize == 0) {
        printf("Payload size cannot be zero.\n");
        return 1; // Error
    }
    return 0; // No error
}

void freePacketArray(PacketHeader** packets, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (packets[i]) {
            free(packets[i]);
        }
    }
    free(packets);
}
