int nicConfigCount = 0;

// Function to initialize and populate NIC configuration array
void initNicConfigs() {
    nicConfigs = (NicConfig*) malloc(sizeof(NicConfig) * 1000);
}

// Helper function to generate a unique MAC address
char* generateMacAddress() {
    static char macAddress[18];
    for(int i = 0; i < 17; i++) {
        macAddress[i] = 'a' + (rand() % 26);
    }
    macAddress[17] = '\0';
    return macAddress;
}

