    NicConfig* config = &nicConfigs[nicConfigCount];
    strcpy(config->macAddress, macAddress);
    config->vlanId = vlanId;
    config->status = 1; // Initialize as up

    if(nicConfigCount < 1000) {
        nicConfigCount++;
        return 0; // Success
    } else {
        printf("NIC configuration limit reached. Cannot add more configurations.\n");
        return -1; // Failure
    }
}

// Function to update an existing NIC configuration
