    if(index < nicConfigCount) {
        NicConfig* config = &nicConfigs[index];
        strcpy(config->macAddress, macAddress);
        config->vlanId = vlanId;
        return 0; // Success
    } else {
        printf("Invalid NIC configuration index. Cannot update.\n");
        return -1; // Failure
    }
}

