#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int SessionID;
    time_t ConnectionTimestamp;
    time_t LastActivityTime;
    char *DataField;
} NetworkSession;

// Function to dynamically allocate memory for a new network session
NetworkSession* createNewSession() {
    NetworkSession* newSession = (NetworkSession*)malloc(sizeof(NetworkSession));
    if (!newSession) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    newSession->DataField = NULL;
    return newSession;
}

// Function to append a new session to the dynamic list
void appendSession(NetworkSession** sessions, int* size) {
    NetworkSession* newSession = createNewSession();
    if (!newSession) return; // Memory allocation failed

    if (*size == 0) {
        *sessions = (NetworkSession**)malloc(sizeof(NetworkSession*));
        (*sessions)[0] = newSession;
        *size = 1;
    } else {
        NetworkSession** newSessions = (NetworkSession**)realloc(*sessions, (*size + 1) * sizeof(NetworkSession*));
        if (!newSessions) {
            free(newSession);
            return; // Memory reallocation failed
        }
        (*newSessions)[*size] = newSession;
        *sessions = newSessions;
        (*size)++;
    }
}

// Function to query a session by its ID from the dynamic list
NetworkSession* getSession(NetworkSession** sessions, int size, int targetID) {
    for (int i = 0; i < size; i++) {
        if (sessions[i]->SessionID == targetID) return sessions[i];
    }
    return NULL;
}

// Function to free memory allocated for a session
void freeSession(NetworkSession* session) {
    if (session->DataField) free(session->DataField);
    free(session);
}
