#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_UETAGS 1000

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T nfacrc_list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void add_ue_tag(NFAPI_CRC_INDICATION_PDU_T *tag) {
    pthread_mutex_lock(&nfacrc_list.lock);

    // Add the new tag to the list
    NFAPI_CRC_INDICATION_PDU_T **new_list = (NFAPI_CRC_INDICATION_PDU_T **)realloc(nfacrc_list.data, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (nfacrc_list.size + 1));
    if (!new_list) {
        printf("Memory allocation error\n");
        return;
    }
    new_list[nfacrc_list.size] = tag;
    nfacrc_list.data = new_list;

    // Sort the list by RNTI
    int i, j;
    for (i = 0; i < nfacrc_list.size - 1; i++) {
        for (j = 0; j < nfacrc_list.size - i - 1; j++) {
            if (nfacrc_list.data[j]->RNTI > nfacrc_list.data[j+1]->RNTI) {
                NFAPI_CRC_INDICATION_PDU_T *temp = nfacrc_list.data[j];
                nfacrc_list.data[j] = nfacrc_list.data[j+1];
                nfacrc_list.data[j+1] = temp;
            }
        }
    }

    nfacrc_list.size++;

    pthread_mutex_unlock(&nfacrc_list.lock);
}

void remove_ue_tag(int rnti) {
    pthread_mutex_lock(&nfacrc_list.lock);

    // Find and remove the UE tag with the given RNTI
    int i;
    for (i = 0; i < nfacrc_list.size; i++) {
        if (nfacrc_list.data[i]->RNTI == rnti) {
            // Shift all subsequent elements down by one position
            memmove(&nfacrc_list.data[i], &nfacrc_list.data[i+1], sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (nfacrc_list.size - i - 1));

            nfacrc_list.size--;
            break;
        }
    }

    // Re-allocate the memory to match the new size
    if (i < nfacrc_list.size) {
        NFAPI_CRC_INDICATION_PDU_T **new_list = (NFAPI_CRC_INDICATION_PDU_T **)realloc(nfacrc_list.data, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * nfacrc_list.size);
        if (!new_list) {
            printf("Memory allocation error\n");
            return;
        }
        nfacrc_list.data = new_list;
    }

    pthread_mutex_unlock(&nfacrc_list.lock);
}

void update_ue_tag(int rnti, uint8_t crcflag) {
    pthread_mutex_lock(&nfacrc_list.lock);

    // Find the UE tag with the given RNTI and update its CRCFLAG
    int i;
    for (i = 0; i < nfacrc_list.size; i++) {
        if (nfacrc_list.data[i]->RNTI == rnti) {
            nfacrc_list.data[i]->CRCFLAG = crcflag;
            break;
        }
    }

    pthread_mutex_unlock(&nfacrc_list.lock);
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T ue_tag1 = {"RX_UE_INFO_TAG_1", 123, "CRC_IND_REL8_TAG_1", 0};
    NFAPI_CRC_INDICATION_PDU_T ue_tag2 = {"RX_UE_INFO_TAG_2", 456, "CRC_IND_REL8_TAG_2", 1};

    add_ue_tag(&ue_tag1);
    add_ue_tag(&ue_tag2);

    remove_ue_tag(123);

    update_ue_tag(456, 2);

    return 0;
}
