    int i;

    pthread_mutex_lock(&nfa_list.lock);
    for (i = 0; i < nfa_list.size; i++) {
        if (nfa_list.nfapis[i]->rnti == rnti) {
            free(nfa_list.nfapis[i]);
            for (; i < nfa_list.size - 1; i++) {
                nfa_list.nfapis[i] = nfa_list.nfapis[i + 1];
            }
            nfa_list.size--;
            break;
        }
    }

    pthread_mutex_unlock(&nfa_list.lock);
}

// Function to update the CRCFLAG value of an NFAPI CRC indication PDU
void update_crc(int rnti, unsigned short new_crc_flag) {
    int i;

    pthread_mutex_lock(&nfa_list.lock);
    for (i = 0; i < nfa_list.size; i++) {
        if (nfa_list.nfapis[i]->rnti == rnti) {
            nfa_list.nfapis[i]->crc_ind_rel8_tag = new_crc_flag;
            break;
        }
    }

    pthread_mutex_unlock(&nfa_list.lock);
}

void print_nfas() {
