    pthread_mutex_lock(&nfa_list.lock);
    for (i = 0; i < nfa_list.size; i++) {
        printf("RX_UE_INFO_TAG: %s, RNTI: %d, CRCFLAG: 0x%04X\n",
               nfa_list.nfapis[i]->rx_ue_info_tag,
               nfa_list.nfapis[i]->rnti,
               nfa_list.nfapis[i]->crc_ind_rel8_tag);
    }

    pthread_mutex_unlock(&nfa_list.lock);
}

int main() {
    add_nfa("UE1", 12345);
    add_nfa("UE2", 67890);
    add_nfa("UE3", 11111);

