typedef enum {
    LOG_LEVEL_ERROR,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG
} log_level;

typedef struct {
    log_level level;
    const char *format;
    char path[256];
} config_settings;

config_settings parse_config(const char *filename) {
    config_settings settings = {LOG_LEVEL_ERROR, "", ""};
    FILE *file = fopen(filename, "r");
    yaml_parser_t parser;
    yaml_event_t event;
    if (!file) return settings;

    yaml_parser_init(&parser);
    for (;;) {
        int token = yaml_parser_parse(file, &parser, &event);
        if (token == YAML_NO_EVENT) break;
        switch (event.type) {
            case YAML_STREAM_START_EVENT:
                continue;
            case YAML_MAPPING_START_EVENT:
                char key[256];
                yaml_event_get_mapping_key(&event, key, sizeof(key));
                if (!strcmp(key, "log_level")) {
                    settings.level = (log_level)atoi(yaml_event_get_scalar_value(&event).vscalar);
                } else if (!strcmp(key, "format")) {
                    settings.format = yaml_event_get_scalar_value(&event).vscalar;
                } else if (!strcmp(key, "path")) {
                    strncpy(settings.path, yaml_event_get_scalar_value(&event).vscalar, sizeof(settings.path));
                }
                break;
            default:
                continue;
        }
    }

    yaml_parser_delete(&parser);
    fclose(file);

    return settings;
}

