    // Submitting logs to external service or storing locally
    // ...

    return NULL;
}

int main() {
    config_settings settings = parse_config("config.yaml");

    pthread_t thread;
    pthread_create(&thread, NULL, init_logging, &settings);
    pthread_join(thread, NULL);

    return 0;
}
