// Function to create and manage linked list
void* nfaPI_crc_indication_pdu_t_list_create(int num_elements) {
    // Initialize head and tail pointers
    Node *head = NULL, *tail = NULL;

    // Create a mutex for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the linked list
    for (int i = 0; i < num_elements; i++) {
        Node* node = malloc(sizeof(Node));

        if (!node) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        // Initialize data fields with random CRCFLAG values
        node->data.RX_UE_INFORMATION_TAG = /* initialize */;
        node->data.RNTI = /* initialize */;
        node->data.crc_indication_rel8 = /* initialize */;
        node->data.CRCFLAG = rand() % 2;

        // Link the new node to the list
        if (!head) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    return head;
}

// Function to verify CRCFLAG consistency across adjacent elements
void nfaPI_crc_indication_pdu_t_list_verify_consistency(Node* head) {
    Node* current = head;
    while (current && current->next) {
        if (current->data.CRCFLAG != current->next->data.CRCFLAG) {
            // Log error and terminate gracefully
            printf("CRCFLAG inconsistency detected.\n");
            exit(1);
        }
        current = current->next;
    }
}

// Function to free the linked list
void nfaPI_crc_indication_pdu_t_list_free(Node* head) {
    Node* current = head;

    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
