typedef struct {
    LTE_PHY_FRAME_T *frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} lte_phy_frame_list_t;

void lte_phy_frame_list_init(lte_phy_frame_list_t *list) {
    list->capacity = 16; // initial capacity
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int lte_phy_frame_list_add(lte_phy_frame_list_t *list, LTE_PHY_FRAME_T frame) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2; // dynamic resizing
        LTE_PHY_FRAME_T *new_frames = realloc(list->frames, sizeof(LTE_PHY_FRAME_T) * new_capacity);
        if (!new_frames) return -1;
        list->frames = new_frames;
        list->capacity = new_capacity;
    }
    list->frames[list->size++] = frame;
    return 0;
}

int lte_phy_frame_list_remove(lte_phy_frame_list_t *list, size_t index) {
    if (index >= list->size) return -1;
    memmove(&list->frames[index], &list->frames[index + 1], sizeof(LTE_PHY_FRAME_T) * (list->size - index - 1));
    list->size--;
    return 0;
}

LTE_PHY_FRAME_T* lte_phy_frame_list_get(lte_phy_frame_list_t *list, size_t index) {
    if (index >= list->size) return NULL;
    pthread_mutex_lock(&list->mutex);
    LTE_PHY_FRAME_T* frame = &list->frames[index];
    pthread_mutex_unlock(&list->mutex);
    return frame;
}

void lte_phy_frame_list_free(lte_phy_frame_list_t *list) {
    free(list->frames);
    pthread_mutex_destroy(&list->mutex);
}
