#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_UES 1000
#define PACKETS_PER_UE 10
#define THRESHOLD -50

typedef struct {
    int id;
    int signal_strength;
    char packets[PACKETS_PER_UE][1024];
} User_Equipment;

User_Equipment ue_array[MAX_UES];
int ue_count = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_ue_array() {
    for (int i = 0; i < MAX_UES; i++) {
        ue_array[i].id = -1;
        strcpy(ue_array[i].packets, "");
    }
}

void add_ue(int id, int signal_strength) {
    pthread_mutex_lock(&mutex);
    if (ue_count < MAX_UES) {
        ue_array[ue_count].id = id;
        ue_array[ue_count].signal_strength = signal_strength;
        ue_count++;
    }
    pthread_mutex_unlock(&mutex);
}

void update_ue_signal(int id, int signal_strength) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < ue_count; i++) {
        if (ue_array[i].id == id) {
            ue_array[i].signal_strength = signal_strength;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void remove_ue(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < ue_count; i++) {
        if (ue_array[i].id == id) {
            memmove(&ue_array[i], &ue_array[i + 1], (ue_count - i - 1) * sizeof(ue_array[0]));
            ue_count--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void serialize_ue_array() {
    int file_descriptor = open("ue_data.txt", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (file_descriptor >= 0) {
        for (int i = 0; i < ue_count; i++) {
            write(file_descriptor, &ue_array[i], sizeof(ue_array[0]));
        }
        close(file_descriptor);
    }
}

void deserialize_ue_array() {
    int file_descriptor = open("ue_data.txt", O_RDONLY);
    if (file_descriptor >= 0) {
        for (int i = 0; i < MAX_UES; i++) {
            read(file_descriptor, &ue_array[i], sizeof(ue_array[0]));
        }
        close(file_descriptor);
    }
}

void* signal_strength_update_thread(void* arg) {
    while (1) {
        // Read signal strength updates from external data source
        // ...
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < ue_count; i++) {
            if (ue_array[i].signal_strength < THRESHOLD) {
                remove_ue(ue_array[i].id);
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}

void start_signal_strength_update_thread() {
    pthread_t thread;
    pthread_create(&thread, NULL, signal_strength_update_thread, NULL);
}

int main() {
    initialize_ue_array();
    // Add UEs
    add_ue(1, 20);
    add_ue(2, -30);
    add_ue(3, 10);
    // Update UE signals
    update_ue_signal(1, 25);
    update_ue_signal(2, -40);
    // Remove UEs below threshold
    remove_ue(2);
    serialize_ue_array();
    start_signal_strength_update_thread();
    return 0;
}

