import java.io.*;
import java.net.URI;
import java.util.*;
import java.util.concurrent.*;

public class APIExecutor {
    private static final Logger logger = LoggerFactory.getLogger(APIExecutor.class);
    private static final int MAX_RETRIES = 5; // configurable maximum retries
    private static final long BACKOFF_DELAY_MILLIS = 1000; // initial delay

    public static List<NFAPI_CRC_INDICATION_PDU_T> executeCommand(String url, String command) throws Exception {
        List<NFAPI_CRC_INDICATION_PDU_T> result = new ArrayList<>();

        // check if local file exists and delete it
        File fileToDelete = new File("local_file.txt");
        if (fileToDelete.exists()) {
            fileToDelete.delete();
        }

        ExecutorService executor = Executors.newSingleThreadExecutor();

        Future<String> commandFuture = executor.submit(() -> executeCommandAsync(url, command));

        // read output and error streams asynchronously
        ExecutorService streamExecutor = Executors.newCachedThreadPool();
        Future<String> outputStreamFuture = streamExecutor.submit(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(commandFuture.get()))) {
                return reader.lines().collect(Collectors.join());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        });

        Future<String> errorStreamFuture = streamExecutor.submit(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(commandFuture.get(), "ISO-8859-1"))) {
                return reader.lines().collect(Collectors.join());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        });

        executor.shutdown();

        // process the results efficiently
        String output = outputStreamFuture.get();
        String errorStream = errorStreamFuture.get();

        for (String line : output.split("\n")) {
            NFAPI_CRC_INDICATION_PDU_T pdu = populatePDU(line);
            result.add(pdu);
        }

        logger.info("Command executed successfully: {}", output);
        logger.info("Error stream: {}", errorStream);

        return result;
    }

    private static String executeCommandAsync(String url, String command) throws Exception {
        int retryCount = 0;
        long backoffDelayMillis = BACKOFF_DELAY_MILLIS;

        while (retryCount <= MAX_RETRIES) {
            try {
                // execute the command using the external API service
                URL apiUrl = new URL(url);
                HttpURLConnection connection = (HttpURLConnection) apiUrl.openConnection();
                connection.setRequestMethod("POST");
                connection.setDoOutput(true);

                // set headers and payload as needed

                InputStream in = new ByteArrayInputStream(command.getBytes());
                byte[] bytes = new byte[1024];
                int bytesRead;
                while ((bytesRead = in.read(bytes)) != -1) {
                    connection.getOutputStream().write(bytes, 0, bytesRead);
                }

                connection.connect();
                int responseCode = connection.getResponseCode();

                if (responseCode >= 200 && responseCode < 300) {
                    // process the API response
                    return readResponse(connection);

                } else if (responseCode == 503) {
                    // service unavailable; wait and retry
                    logger.info("Service unavailable; will retry in {} milliseconds", backoffDelayMillis);
                    Thread.sleep(backoffDelayMillis);
                    backoffDelayMillis *= 2;
                    retryCount++;
                } else {
                    throw new IOException("API returned unexpected response code: " + responseCode);
                }
            } catch (IOException | InterruptedException e) {
                logger.error("Error executing command", e);
                if (retryCount < MAX_RETRIES) {
                    Thread.sleep(backoffDelayMillis);
                    backoffDelayMillis *= 2;
                    retryCount++;
                } else {
                    throw new RuntimeException("Maximum retries exceeded");
                }
            }
        }

        return null;
    }

    private static NFAPI_CRC_INDICATION_PDU_T populatePDU(String line) {
        // populate the NFAPI_CRC_INDICATION_PDU_T structure
        // ...
    }

    private static String readResponse(HttpURLConnection connection) throws IOException {
        InputStream in = connection.getInputStream();
        return new BufferedReader(new InputStreamReader(in)).lines().collect(Collectors.join());
    }
}
