TrafficEvent** manage_traffic_events(int initial_capacity) {
    int capacity = initial_capacity;
    int size = 0;
    TrafficEvent** events = (TrafficEvent**)malloc(sizeof(TrafficEvent*) * capacity);
    for (int i = 0; i < capacity; i++) {
        events[i] = NULL;
    }

    for (int i = 0; i < 10; i++) { // populate the array with simulated traffic events
        TrafficEvent* event = (TrafficEvent*)malloc(sizeof(TrafficEvent));
        event->timestamp = i;
        strcpy(event->type, "Type");
        strcpy(event->metadata, "Metadata");
        int index = size % capacity;
        if (events[index] != NULL) {
            // dynamically resize the array as new events are added
            capacity *= 2;
            TrafficEvent** new_events = (TrafficEvent**)realloc(events, sizeof(TrafficEvent*) * capacity);
            for (int j = index; j < size; j++) {
                new_events[j] = events[(j + 1) % capacity];
            }
            events = new_events;
        }
        events[index] = event;
        size++;
    }

    return events;
}
