typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *prev;
    struct list_node *next;
} list_node;

list_node* create_list_node() {
    list_node* node = (list_node*)malloc(sizeof(list_node));
    if (!node) {
        return NULL;
    }

    node->data.RX_UE_INFORMATION_TAG = (uint32_t)rand();
    node->data.CRCFLAG = (uint8_t)rand() % 2;

    // Ensure no two consecutive nodes share the same RNTI
    uint16_t rnti = (uint16_t)rand();
    while (get_hash_table_value(rnti)) {
        rnti = (uint16_t)rand();
    }
    node->data.RNTI = rnti;

    // Initialize CRC_INDICATION_REL8_TAG randomly
    node->data.CRC_INDICATION_REL8_TAG = (uint8_t)rand() % 256;

    return node;
}

void free_list_node(list_node* node) {
    if (!node) {
        return;
    }

    free(node);
}

int insert_list_node(list_node** head, list_node* node) {
    // Handle memory allocation errors
    if (!(*head)) {
        *head = node;
    } else {
        node->next = (*head);
        (*head)->prev = node;
        (*head) = node;
    }

    return 0;
}

void verify_list(list_node* head) {
    int count = 1;
    list_node* current = head;
    while (current && current->next) {
        if (!get_hash_table_value(current->data.RNTI)) {
            // Log error and handle
            logging_framework_log_error("Duplicate RNTI found");
            free_list_node(current);
            return;
        }

        count++;
        current = current->next;
    }
}

void dynamic_list_init() {
    hash_table_init();
}

void dynamic_list_cleanup() {
    list_node* head = NULL;
    list_node* temp = NULL;

    while (head) {
        temp = head;
        head = head->next;
        free_list_node(temp);
    }

    hash_table_cleanup();
}

int main() {
    // Initialize the list
    dynamic_list_init();

    // Create nodes and insert them into the list
    for (int i = 0; i < 100000; i++) {
        list_node* node = create_list_node();
        if (!node) {
            logging_framework_log_error("Memory allocation error");
            return -1;
        }

        // Insert node into the list
        insert_list_node(&head, node);
    }

    // Verify the list for duplicate RNTI values
    verify_list(head);

    // Cleanup the list
    dynamic_list_cleanup();

    return 0;
}
