void generate_and_store_NFAPICRCINDICATIONPDUs(int n, char* config_dir_path) {
    srand(time(NULL));

    char *config_dir = getenv("NFAPI_CRC_INDICATION_PDU_STORAGE_DIR");
    if (config_dir == NULL || strlen(config_dir) == 0) {
        config_dir = config_dir_path;
    }

    struct stat sb;
    if (stat(config_dir, &sb) != 0) {
        if (mkdir(config_dir, S_IRWXU | S_IRGRP | S_IWGRP | S_IROTH | S_IWOTH) == -1) {
            printf("Error creating directory %s\n", config_dir);
            return;
        }
    } else if (!S_ISDIR(sb.st_mode)) {
        printf("%s is not a directory\n", config_dir);
        return;
    }

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            printf("Memory allocation failed\n");
            return;
