        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 1000;
        int crcflag = rand() % 2;
        pdu->CRC_INDICATION_REL8_TAG = crcflag ? 1 : 0;

        char filename[256];
        sprintf(filename, "%s/NFAPI_CRC_INDICATION_PDU_%d", config_dir, i);
        FILE *fp = fopen(filename, "wb");
        if (fp == NULL) {
            printf("Error opening file %s\n", filename);
            free(pdu);
            return;
        }

        fwrite(&pdu->RX_UE_INFORMATION_TAG, sizeof(int), 1, fp);
        fwrite(&pdu->RNTI, sizeof(int), 1, fp);
        fwrite(&pdu->CRC_INDICATION_REL8_TAG, sizeof(int), 1, fp);

        fclose(fp);
        free(pdu);
    }
}

int main() {
    int n = 100;
    char *config_dir_path = "/path/to/config/directory";
    generate_and_store_NFAPICRCINDICATIONPDUs(n, config_dir_path);
    return 0;
}
