#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_RNTIS 1000
#define CRCFLAG_MAX 0xFF

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[CRCFLAG_MAX];
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* prev;
    struct node* next;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int rnti_count = 0;

void insert_node(struct node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    // Handle edge case: empty list
    if (*head == NULL) {
        *head = (struct node*)malloc(sizeof(struct node));
        (*head)->prev = (*head)->next = NULL;
    } else {
        struct node* temp = *head;
        while (temp->next != NULL)
            temp = temp->next;

        // Insert new node
        struct node* new_node = (struct node*)malloc(sizeof(struct node));
        new_node->data = data;
        new_node->prev = temp;
        new_node->next = NULL;
        temp->next = new_node;
    }

    // Ensure no two consecutive structures share the same RNTI value
    while (rnti_count < MAX_RNTIS) {
        data.RNTI = rand() % (MAX_RNTIS + 1);
        if (data.RNTI == temp->next->data.RNTI)
            break;
        rnti_count++;
    }

    pthread_mutex_unlock(&lock);
}

void remove_node(struct node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    // Find and remove the node
    struct node* temp = *head;
    while (temp != NULL && temp->data.RNTI != data.RNTI)
        temp = temp->next;

    if (temp == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    // Update previous and next nodes
    if (temp->prev != NULL)
        temp->prev->next = temp->next;
    else
        *head = temp->next;

    if (temp->next != NULL)
        temp->next->prev = temp->prev;

    free(temp);

    pthread_mutex_unlock(&lock);
}

int is_cyclic(struct node* head) {
    pthread_mutex_lock(&lock);

    // Detect cycle using Floyd's algorithm
    struct node* slow = head, *fast = head;
    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;

        if (slow == fast)
            break;
    }

    pthread_mutex_unlock(&lock);

    return slow == fast; // Returns 1 if cyclic, 0 otherwise
}

int get_rnti_count() {
    return rnti_count;
}
