typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[32];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfaPiCrcIndicationPduArray;
int nfaPiCrcIndicationPduArrayLength = 0;

// Function to populate the array with 'N' elements
void populateArray(int N) {
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            printf("Memory allocation failed.\n");
            exit(-1);
        }
        // Initialize the structure members
        sprintf(pdu->RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG_%d", i);
        pdu->RNTI = rand() % 100;
        sprintf(pdu->CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG_%d", i);
        pdu->CRCFLAG = (i % 2) ? 1 : 0;

        // Add the structure to the array
        nfaPiCrcIndicationPduArray = realloc(nfaPiCrcIndicationPduArray, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfaPiCrcIndicationPduArrayLength + 1));
        if (!nfaPiCrcIndicationPduArray) {
            printf("Memory allocation failed.\n");
            exit(-1);
        }
        nfaPiCrcIndicationPduArray[nfaPiCrcIndicationPduArrayLength] = *pdu;
        free(pdu);
        nfaPiCrcIndicationPduArrayLength++;
    }
}

// Function to filter the array based on 'RNTI' and time range
void filterArray(int RNTI, struct tm *start_time, struct tm *end_time) {
    for (int i = 0; i < nfaPiCrcIndicationPduArrayLength; i++) {
