// Function to initialize and populate linked list of TrafficFlow structures
TrafficFlow* init_and_populate_linked_list(int num_flows, int bandwidth_limit) {
    TrafficFlow* head = NULL;
    TrafficFlow** tail = &head;

    // Initialize buffer for dynamic resizing
    void** buffer = NULL;
    size_t buffer_size = 0;
    size_t allocated_size = 0;

    int flow_id = 1;
    char* flow_type = "Unknown";
    float traffic_volume = 0.0f;

    // Fetch flow data from external API with retry mechanism
    for (int i = 0; i < num_flows; i++) {
        while (1) {
            // Fetch flow data from API
            // ...

            if (/* API call successful */) {
                break;
            }

            // Handle transient failure with exponential backoff
            // ...
        }

        // Validate traffic volume and FlowID
        if (traffic_volume > bandwidth_limit || flow_id < 1) {
            printf("Error: Traffic flow volume exceeds limit or invalid ID\n");
            return NULL;
        }

        // Initialize new node in linked list
        void* temp = realloc(buffer, allocated_size + sizeof(TrafficFlow));
        if (!temp) {
            printf("Error: Memory allocation failed\n");
            free(buffer);
            return NULL;
        }
        buffer = (void**)temp;
        allocated_size += sizeof(TrafficFlow);

        // Set node values
        TrafficFlow* new_node = (TrafficFlow*)buffer + (allocated_size / sizeof(TrafficFlow)) - 1;
        new_node->FlowID = flow_id++;
        strcpy(new_node->FlowType, flow_type);
        new_node->TrafficVolume = traffic_volume;

        // Update linked list tail
        *tail = new_node;
        tail = &(new_node)->next;

        // Reset buffer and allocated size for next node
        buffer_size = 0;
        allocated_size = sizeof(TrafficFlow);

        // Update tail pointer
        *tail = NULL;
    }

    return head;
}

// Function to serialize linked list into binary format
int serialize_linked_list(TrafficFlow* head, FILE* file) {
    fwrite(&head->FlowID, sizeof(head->FlowID), 1, file);
    fwrite(head->FlowType, strlen(head->FlowType) + 1, 1, file);
    fwrite(&head->TrafficVolume, sizeof(head->TrafficVolume), 1, file);

    // Serialize rest of linked list
    for (TrafficFlow* current = head; current; current = current->next) {
        fwrite(&current->FlowID, sizeof(current->FlowID), 1, file);
        fwrite(current->FlowType, strlen(current->FlowType) + 1, 1, file);
        fwrite(&current->TrafficVolume, sizeof(current->TrafficVolume), 1, file);
    }

    return 0;
}

// Function to parse serialized data back into original structure layout
int parse_serialized_data(TrafficFlow** head, FILE* file) {
    // Read flow ID and type from file
    TrafficFlow* new_node = (TrafficFlow*)malloc(sizeof(TrafficFlow));
    fread(&new_node->FlowID, sizeof(new_node->FlowID), 1, file);
    fread(new_node->FlowType, strlen(new_node->FlowType) + 1, 1, file);
    fread(&new_node->TrafficVolume, sizeof(new_node->TrafficVolume), 1, file);

    // Add new node to linked list
    if (*head == NULL) {
        *head = new_node;
    } else {
        TrafficFlow* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    return 0;
}
