// Global variables for thread-safe access
pthread_mutex_t report_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_RRC_MEASUREMENT_REPORT** measurement_reports = NULL;
int report_count = 0;
int max_reports = 100000;
time_t age_threshold = 300; // 5 minutes in seconds

// Function to manage dynamic array of measurement reports
void* manage_measurement_reports(void* arg) {
    int i, j;
    NFAPI_RRC_MEASUREMENT_REPORT** new_reports = NULL;

    // Check if the global lock is already held
    if (pthread_mutex_lock(&report_lock)) {
        printf("Error acquiring report lock.\n");
        return NULL;
    }

    // Allocate memory for a new array of reports
    new_reports = realloc(measurement_reports, (max_reports + 1) * sizeof(NFAPI_RRC_MEASUREMENT_REPORT*));

    if (!new_reports) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&report_lock);
        return NULL;
    }

    measurement_reports = new_reports;

    // Insert new reports into the array
    for (i = 0; i < report_count; i++) {
        if ((measurement_reports[i]->timestamp + age_threshold) <= time(NULL)) {
            // Remove outdated reports
            free(measurement_reports[i]);
        } else {
            measurement_reports[i] = NULL;
        }
    }

    // Add new reports to the end of the array
    for (i = report_count; i > 0; i--) {
        if (!measurement_reports[i - 1]) {
            for (j = i - 1; j > 0 && !measurement_reports[j - 1]; j--) {
                measurement_reports[j] = measurement_reports[j - 1];
            }
            measurement_reports[0] = NULL;
        } else {
            break;
        }
    }

    // Shift reports to the beginning of the array
    for (i = 0; i < report_count; i++) {
        if (measurement_reports[i]) {
            measurement_reports[i]->timestamp = time(NULL);
        }
    }

    pthread_mutex_unlock(&report_lock);

    return NULL;
}

// Function to retrieve the highest RSRP value within a specified time window
float get_highest_rsrp_value(int start_time, int end_time) {
    float max_rsrp = -1.0;
    int i;

    pthread_mutex_lock(&report_lock);

    for (i = 0; i < report_count; i++) {
        if ((measurement_reports[i]->timestamp >= start_time && measurement_reports[i]->timestamp <= end_time) &&
            (measurement_reports[i]->rsrp_value > max_rsrp)) {
            max_rsrp = measurement_reports[i]->rsrp_value;
        }
    }

    pthread_mutex_unlock(&report_lock);

    return max_rsrp;
}

// Function to insert a new measurement report
void insert_measurement_report(NFAPI_RRC_MEASUREMENT_REPORT* report) {
    pthread_mutex_lock(&report_lock);

    // Add the new report to the array
    if (report_count < max_reports) {
        measurement_reports[report_count] = report;
        report_count++;
    } else {
        printf("Measurement report insertion failed due to capacity limitations.\n");
    }

    pthread_mutex_unlock(&report_lock);
}

// Function to remove a measurement report by its ID
void remove_measurement_report(int measurement_id) {
    int i;

    pthread_mutex_lock(&report_lock);

    for (i = 0; i < report_count; i++) {
        if (measurement_reports[i]->measurement_id == measurement_id) {
            free(measurement_reports[i]);
            break;
        }
    }

    // Shift reports to fill the gap
    for (i = i + 1; i < report_count; i++) {
        measurement_reports[i - 1] = measurement_reports[i];
    }

    report_count--;

    pthread_mutex_unlock(&report_lock);
}

int main() {
    // Initialize the dynamic array of measurement reports
    measurement_reports = malloc(max_reports * sizeof(NFAPI_RRC_MEASUREMENT_REPORT*));
    if (!measurement_reports) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Create a new thread to manage the measurement reports
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, manage_measurement_reports, NULL);

    // Simulate inserting and removing measurement reports
    for (int i = 0; i < 10000; i++) {
        NFAPI_RRC_MEASUREMENT_REPORT* report = malloc(sizeof(NFAPI_RRC_MEASUREMENT_REPORT));
        report->measurement_id = i;
        report->cell_id = rand() % 100;
        report->rsrp_value = (float)rand() / RAND_MAX;
        report->timestamp = time(NULL);
        insert_measurement_report(report);

        // Sleep for a short period to simulate reporting rate
        sleep(1);
    }

    // Retrieve the highest RSRP value within a specified time window
    int start_time = time(NULL) - 300; // 5 minutes ago
    int end_time = time(NULL);
    float max_rsrp = get_highest_rsrp_value(start_time, end_time);

    printf("Highest RSRP value: %f\n", max_rsrp);

    return 0;
}
