int nfapi_crc_allocation(int num_structures, int *num_allocated) {
    static NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;
    static int allocated = 0;

    if (*num_allocated > MAX_SIZE)
        return -1; // allocation limit exceeded

    if (allocated >= *num_allocated) {
        for (int i = 0; i < allocated; i++) {
            free((void *)(&pdu_array[i]));
        }
        free(pdu_array);
    }

    pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pdu_array, STRUCT_SIZE * (*num_allocated));
    if (!pdu_array) {
        return -1; // allocation failed
    }

    allocated = *num_allocated;

    for (int i = 0; i < allocated; i++) {
        pdu_array[i].crcflag = rand() % 2;
    }

    *num_allocated = allocated;
    return 0;
}

void nfapi_crc_deallocation(int num_structures, int *num_allocated) {
    if (*num_allocated > MAX_SIZE)
        return; // nothing to deallocate

    for (int i = 0; i < *num_allocated; i++) {
        free((void *)(&pdu_array[i]));
    }
    free(pdu_array);
    *num_allocated = 0;
}

int main() {
    int num_structures, allocated = 0;

    while (1) {
        printf("Enter number of structures to allocate (or -1 to exit): ");
        scanf("%d", &num_structures);

        if (num_structures == -1)
            break;

        nfapi_crc_allocation(num_structures, &allocated);
    }

    nfapi_crc_deallocation(allocated, &allocated);

    return 0;
}
