use std::fs::create_dir_all;
use std::path::PathBuf;
use std::env;
use std::thread;

fn create_persistent_storage(directory_name: &str) {
    let dir_path = PathBuf::from(directory_name);
    if !dir_path.exists() {
        create_dir_all(dir_path.as_path()).unwrap();
    } else {
        let mut timestamp = String::new();
        thread::sleep(std::time::Duration::from_millis(1)); // add a small delay to avoid conflicts
        timestamp.push_str(&directory_name);
        timestamp.push_str("_");
        timestamp.push_str(&std::time::SystemTime::now().format("'%Y-%m-%d_%H-%M-%S'").to_string());

        let new_dir_path = dir_path.parent().unwrap().join(timestamp.as_str()).unwrap();
        create_dir_all(new_dir_path).unwrap();
    }

    let path_var = format!("USER_CONTENT_DIR={}", dir_path.to_str().unwrap());
    if env::var("USER_CONTENT_DIR").is_err() {
        env::set_var(&path_var);
    } else {
        let mut existing_path = env::var("USER_CONTENT_DIR").unwrap();
        if !existing_path.contains(&directory_name) {
            existing_path.push_str(",");
            existing_path.push_str(directory_name);

            env::set_var(existing_path.as_str());
        }
    }
}
