#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#define MAX_STRUCTURES 50000
#define LOGGING_ENABLED 1

typedef struct {
    // FRAME_HEADER
    int header_field1;
    int header_field2;

    // DATA_PAYLOAD
    char data_payload[1024];

    // CRC_CHECK_TAG
    int crc_flag;
} MAC_FRAME_BUFFER_T;

static MAC_FRAME_BUFFER_T* frame_buffer = NULL;
static int num_frames = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int init_frame_buffer() {
    if (frame_buffer != NULL) {
        return -1; // Already initialized
    }

    frame_buffer = (MAC_FRAME_BUFFER_T*)malloc(MAX_STRUCTURES * sizeof(MAC_FRAME_BUFFER_T));
    if (!frame_buffer) {
        return -2; // Allocation failure
    }

    num_frames = 0;
    pthread_mutex_init(&mutex, NULL);

    return 0;
}

int destroy_frame_buffer() {
    if (frame_buffer == NULL) {
        return -1; // Not initialized
    }

    for (int i = 0; i < num_frames; i++) {
        free(frame_buffer + i);
    }
    free(frame_buffer);
    frame_buffer = NULL;
    pthread_mutex_destroy(&mutex);

    return 0;
}

int allocate_frame() {
    if (num_frames >= MAX_STRUCTURES) {
        return -1; // Out of memory
    }

    MAC_FRAME_BUFFER_T* new_frame = frame_buffer + num_frames++;
    new_frame->header_field1 = rand();
    new_frame->header_field2 = rand();
    strcpy(new_frame->data_payload, "Random data...");
    new_frame->crc_flag = rand();

    if (LOGGING_ENABLED) {
        printf("Frame %d allocated.\n", num_frames - 1);
    }

    return 0;
}

int free_frame(int frame_index) {
    if (frame_index < 0 || frame_index >= num_frames) {
        return -1; // Invalid index
    }

    MAC_FRAME_BUFFER_T* old_frame = frame_buffer + frame_index;
    memcpy(old_frame, frame_buffer + (num_frames - 1), sizeof(MAC_FRAME_BUFFER_T));
    for (int i = 0; i < num_frames - 1; i++) {
        free(frame_buffer + i);
    }
    free(frame_buffer);

    frame_buffer = (MAC_FRAME_BUFFER_T*)malloc(MAX_STRUCTURES * sizeof(MAC_FRAME_BUFFER_T));
    pthread_mutex_init(&mutex, NULL);
    num_frames--;
    pthread_mutex_destroy(&mutex);

    return 0;
}

int verify_frame(int frame_index) {
    if (frame_index < 0 || frame_index >= num_frames) {
        return -1; // Invalid index
    }

    MAC_FRAME_BUFFER_T* frame = frame_buffer + frame_index;
    int crc_result = frame->header_field1 ^ frame->header_field2 ^ strlen(frame->data_payload);
    printf("Frame %d CRC: %x\n", frame_index, crc_result);

    return 0;
}
