}

void deallocate_list(void* list, int n) {
    free(list);
}

int serialize_list_to_cache(void* list, int n) {
    FILE* cache = fopen("cache.txt", "wb");
    if (!cache) {
        return -1;
    }

    fwrite(&n, sizeof(int), 1, cache);
    for (int i = 0; i < n; i++) {
        fwrite((void*)&((NFAPI_CRC_INDICATION_PDU_T*)list)[i], 
               sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, cache);
    }

    fclose(cache);
    return 0;
}

int deserialize_list_from_cache(void** list) {
    FILE* cache = fopen("cache.txt", "rb");
    if (!cache) {
        return -1;
    }

    int n;
    fread(&n, sizeof(int), 1, cache);
    *list = allocate_list(n);
    for (int i = 0; i < n; i++) {
        fread((void*)&((NFAPI_CRC_INDICATION_PDU_T*)*list)[i], 
              sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, cache);
    }

    fclose(cache);
    return 0;
}

void manage_list(void** list, int n) {
    // dynamic allocation and deallocation of memory
    for (int i = 0; i < n; i++) {
        ((NFAPI_CRC_INDICATION_PDU_T*)*list)[i].CRCFLAG = /* dynamically set CRCFLAG */;
    }

    // serialize the list into a disk-based cache
    if (serialize_list_to_cache(*list, n) == -1) {
        printf("Error serializing list to cache!\n");
        deallocate_list(*list, n);
        *list = NULL;
    } else {
        printf("List serialized successfully.\n");
    }
}

