// Function to add a new entry to the dynamic array
void addEntry(int RNTI, int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
    // Allocate memory for the new structure
    NFAPI_CRC_INDICATION_PDU_T* newEntry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newEntry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newEntry->RNTI = RNTI;
    newEntry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Reallocate the dynamic array to accommodate the new entry
    int newSize = sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (dynamicArray ? strlen(dynamicArray) + 2 : 1);
    NFAPI_CRC_INDICATION_PDU_T** newArray = (NFAPI_CRC_INDICATION_PDU_T**)realloc(dynamicArray, newSize);

    // Add the new entry to the dynamic array
    if (!newArray) {
        free(newEntry);
        return;
    }

    *newArray = newEntry;

    // Update the dynamicArray pointer
    dynamicArray = newArray;
}

// Function to update an existing entry in the dynamic array
void updateEntry(int RNTI, int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
    // Iterate through the dynamic array to find the matching RNTI
    for (int i = 0; i < strlen(dynamicArray); i++) {
        if (dynamicArray[i]->RNTI == RNTI) {
            // Update the existing entry
            dynamicArray[i]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            dynamicArray[i]->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            return;
