// Function to remove an entry by RNTI from the dynamic array
void removeEntry(int RNTI) {
    // Iterate through the dynamic array to find the matching RNTI
    int i = 0;
    while (i < strlen(dynamicArray)) {
        if (dynamicArray[i]->RNTI == RNTI) {
            // Remove the entry and re-allocate the dynamic array
            NFAPI_CRC_INDICATION_PDU_T** newArray = (NFAPI_CRC_INDICATION_PDU_T**)realloc(dynamicArray, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * strlen(dynamicArray) - 1);
            if (!newArray) {
                return;
            }

            // Shift the remaining entries to fill the gap
            for (int j = i; j < strlen(newArray); j++) {
                newArray[j] = newArray[j + 1];
            }

            // Update the dynamicArray pointer
            dynamicArray = newArray;

            // Return after successful removal
            return;
        }
        i++;
    }
}

// Function to validate the integrity of the data structure
void validateDataStructure() {
    // Iterate through the dynamic array and check for any inconsistencies
