void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed. Aborting.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int is_duplicate_rnti(const NFAPI_CRC_INDICATION_PDU_T *pdu, int rnti) {
    for (int i = 0; i < pdu->length; i++) {
        if (pdu[i].rnti == rnti)
            return 1;
    }
    return 0;
}

void verify_integrity(NFAPI_CRC_INDICATION_PDU_T *list, int length) {
    for (int i = 0; i < length; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = list[i];
        if (is_duplicate_rnti(list, pdu.rnti)) {
            printf("Error: Duplicate RNTI found.\n");
            exit(EXIT_FAILURE);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu_t_list(int length) {
    NFAPI_CRC_INDICATION_PDU_T *list = safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * length);
    if (list == NULL)
        return NULL;

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s.\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    int total_memory_usage = 0;
    for (int i = 0; i < length; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Initialize fields with random values
        srand(time(NULL) * i); // Seed the random number generator
        sprintf(pdu.rx_ue_information_tag, "RX_UE_INFORMATION_TAG_%d", i);
        pdu.rnti = rand() % 1000; // Random RNTI value between 0 and 999
        sprintf(pdu.crc_indication_rel8_tag, "CRC_INDICATION_REL8_TAG_%d", i);
        pdu.crcflag = rand() % 2; // Random CRCFLAG value (0 or 1)

        if (total_memory_usage + sizeof(NFAPI_CRC_INDICATION_PDU_T) > sysconf(_SC_PAGESIZE) * MEMORY_THRESHOLD) {
            fprintf(log_file, "Memory allocation threshold exceeded at index %d.\n", i);
        }

        list[i] = pdu;
        total_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    fclose(log_file);

    // Verify the integrity of the generated list
    verify_integrity(list, length);

    return list;
}

