// Function to initialize and manage a dynamic array of UE configurations
void initAndManageUes() {
    // Initialize an empty array to store UE configurations
    UEConfig** ueConfigs = (UEConfig**)malloc(sizeof(UEConfig*) * 10);

    // Initialize the number of UEs
    int numUes = 0;

    // Function to add a new UE configuration
    void addUE(int id, char* frequencyBand, float bandwidth, int* channelsToMonitor) {
        // Check for duplicate UE IDs and overlapping frequency bands
        if (id <= 0 || strstr(frequencyBand, "2.4") != NULL && numUes > 0) {
            printf("Error: Duplicate UE ID or overlapping frequency band\n");
            return;
        }

        // Dynamically allocate memory for the new UE configuration
        UEConfig* newUE = (UEConfig*)malloc(sizeof(UEConfig));
        newUE->id = id;
        strcpy(newUE->frequencyBand, frequencyBand);
        newUE->bandwidth = bandwidth;
        newUE->channelsToMonitor = channelsToMonitor;

        // Add the new UE configuration to the array
        ueConfigs[numUes++] = newUE;
    }

    // Function to remove a UE configuration
    void removeUE(int id) {
        for (int i = 0; i < numUes; i++) {
            if (ueConfigs[i]->id == id) {
                free(ueConfigs[i]);
                memmove(&ueConfigs[i], &ueConfigs[i + 1], sizeof(UEConfig*) * (numUes - i));
                numUes--;
                return;
            }
        }
    }

    // Function to update a UE configuration
    void updateUE(int id, char* frequencyBand, float bandwidth) {
        for (int i = 0; i < numUes; i++) {
            if (ueConfigs[i]->id == id) {
                strcpy(ueConfigs[i]->frequencyBand, frequencyBand);
                ueConfigs[i]->bandwidth = bandwidth;
                return;
            }
        }
    }

