    unsigned int RNTI;
    unsigned char CRCFLAG;
    time_t timestamp;
    int counter;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* list = NULL;
int list_size = 0;

void addCRCIndicator(int RNTI, int CRCFLAG) {
    if (list_size >= MAX_LIST_SIZE) {
        // Remove oldest entry in the list
        time_t oldest_timestamp = list[0].timestamp;
        for (int i = 1; i < list_size; i++) {
            if (list[i].timestamp < oldest_timestamp) {
                oldest_timestamp = list[i].timestamp;
                break;
            }
        }
        // Shift elements to fill the gap
        memmove(&list[0], &list[1], (list_size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(list + list_size);
        list_size--;
    }

    if (RNTI > 65535 || RNTI < 0) {
        printf("Invalid RNTI: %d\n", RNTI);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_entry->RNTI = RNTI;
    new_entry->CRCFLAG = CRCFLAG;
    new_entry->timestamp = time(NULL);
    new_entry->counter = 1;

    list = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list, (list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    list[list_size] = new_entry;
    list_size++;
}

void printList() {
    for (int i = 0; i < list_size; i++) {
        printf("RNTI: %d, CRCFLAG: %u, timestamp: %lu, counter: %d\n", list[i]->RNTI, list[i]->CRCFLAG, (long unsigned)list[i]->timestamp, list[i]->counter);
    }
}

int main() {
    // Initialize the list
    addCRCIndicator(12345, 0);

    // Add some more entries
    for (int i = 0; i < 10; i++) {
        addCRCIndicator(i % 65536, rand() % 2);
    }

    printList();

    return 0;
}

