#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ipaddr.h>

// Define a structure to represent a Network Interface Configuration (NIC)
typedef struct {
    char* ip_address;
    char* subnet_mask;
    char* gateway_ip;
    int num_channels;
    char** channels;
} NIC;

// Function to initialize and manage the dynamic array of NICs
void* nic_manager(int max_nics) {
    // Allocate memory for the dynamic array of NICs
    void** nics = (void**)malloc(max_nics * sizeof(void*));

    // Initialize the dynamic array with null pointers
    memset(nics, 0, max_nics * sizeof(void*));

    return nics;
}

// Function to add a new NIC dynamically while ensuring efficient memory management
void add_nic(void** nics, int num_nics, char* ip_address, char* subnet_mask, char* gateway_ip, int num_channels, char** channels) {
    // Validate the input parameters for each struct to ensure they conform to standard IP address formats
    if (!validate_ip(ip_address) || !validate_ip(subnet_mask)) {
        printf("Invalid IP address format\n");
        return;
    }

    // Calculate the network address based on the provided subnet mask
    char* network_addr = calculate_network_addr(subnet_mask);

    // Allocate memory for the new NIC struct and initialize its fields
    NIC* new_nic = (NIC*)malloc(sizeof(NIC));
    new_nic->ip_address = ip_address;
    new_nic->subnet_mask = subnet_mask;
    new_nic->gateway_ip = gateway_ip;
    new_nic->num_channels = num_channels;
    new_nic->channels = channels;

    // Add the new NIC to the dynamic array and update the count
    if (num_nics < max_nics) {
        nics[num_nics] = new_nic;
        num_nics++;
    } else {
        printf("Maximum number of NICS reached\n");
    }
}

// Function to remove a NIC from the dynamic array while ensuring efficient memory management
void remove_nic(void** nics, int* num_nics, int index) {
    // Check if the specified index is within bounds and not null
    if (index < 0 || index >= *num_nics || !nics[index]) {
        printf("Invalid NIC index\n");
        return;
    }

    // Free the memory allocated for the removed NIC struct
    free(((NIC*)nics[index])->ip_address);
    free(((NIC*)nics[index])->subnet_mask);
    free(((NIC*)nics[index])->gateway_ip);
    free(nics[index]);

    // Update the count of NICS and shift the remaining structs to fill the gap
    for (int i = index; i < *num_nics - 1; i++) {
        nics[i] = nics[i + 1];
    }
    (*num_nics)--;
