#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct NASMessage {
    int type;
    int mme_ue_index;
} NASMessage;

typedef struct RadioBearer {
    int bearerId;
    int qosProfile;
} RadioBearer;

typedef struct UEContext {
    int ueId;
    NASMessage nasMessage;
    RadioBearer radioBearer;
} UEContext;

void initUEContextArray(UEContext** ueContexts, int numUEContexts) {
    // Initialize array with null pointers
    for (int i = 0; i < numUEContexts; i++) {
        ueContexts[i] = NULL;
    }
}

int createUEContext(UEContext** ueContexts, int numUEContexts) {
    // Allocate memory for UEContext structures
    UEContext* contexts = (UEContext*)malloc(numUEContexts * sizeof(UEContext));

    if (contexts == NULL) {
        return -1;  // Memory allocation failed
    }

    for (int i = 0; i < numUEContexts; i++) {
        UEContext* ueContext = &contexts[i];

        // Generate random UE ID
        srand(time(NULL));
        int ueId = rand() % 10000;

        // Initialize NASMessage and RadioBearer structures
        NASMessage nasMessage = { rand() % 10, rand() % 256 };
        RadioBearer radioBearer = { rand() % 1000, rand() % 16 };

        // Initialize UEContext structure
        ueContext->ueId = ueId;
        ueContext->nasMessage = nasMessage;
        ueContext->radioBearer = radioBearer;

        *ueContexts[i] = ueContext;  // Store pointer in the array
    }

    return 0;  // Successful allocation and initialization
}

int serializeUEContextArray(UEContext** ueContexts, int numUEContexts, char* buffer) {
    // Serialize UEContext data into binary format
    for (int i = 0; i < numUEContexts; i++) {
        UEContext* ueContext = *ueContexts[i];

        // Write UE ID, NAS message type, and MME UE index to the buffer
        buffer[4*i] = (char)(ueContext->ueId & 0xFF);
        buffer[4*i+1] = (char)((ueContext->ueId >> 8) & 0xFF);
        buffer[4*i+2] = (char)(ueContext->nasMessage.type & 0xFF);
        buffer[4*i+3] = (char)(ueContext->nasMessage.mme_ue_index & 0xFF);

        // Write bearer ID and QoS profile to the buffer
        buffer[4*i+4] = (char)(ueContext->radioBearer.bearerId & 0xFF);
        buffer[4*i+5] = (char)((ueContext->radioBearer.bearerId >> 8) & 0xFF);
        buffer[4*i+6] = (char)(ueContext->radioBearer.qosProfile & 0xFF);
    }

    return numUEContexts * sizeof(UEContext);  // Number of bytes written
}

int main() {
    int numUEContexts = 10;
    UEContext** ueContexts = (UEContext**)malloc(numUEContexts * sizeof(UEContext*));

    if (createUEContextArray(ueContexts, numUEContexts) != 0 || createUEContext(ueContexts, numUEContexts) != 0) {
        // Handle memory allocation errors
        return -1;
    }

    char buffer[4 * numUEContexts];

    if (serializeUEContextArray(ueContexts, numUEContexts, buffer) == -1) {
        // Handle serialization errors
        return -1;
    }

    return 0;  // Successful initialization and serialization
}

