#define MAX_SIZE 1000
#define LOCK_KEY "NFAPI_CRC_INDICATION_PDU_T"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int array_size = 0;
NFAPI_CRC_INDICATION_PDU_T* array[MAX_SIZE];

void* create_pdu(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = rand();
    pdu->CRCFLAG = rand() % 2;

    return pdu;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&lock);

    if (array_size >= MAX_SIZE) {
        pthread_mutex_unlock(&lock);
        free(pdu);
        return;
    }

    array[array_size++] = pdu;
    pthread_mutex_unlock(&lock);
}

void free_all() {
    for (int i = 0; i < array_size; i++) {
        if (array[i]) free(array[i]);
    }

    array_size = 0;
}

void* handle_pdu(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;

    // Validate RX_UE_INFORMATION_TAG for integrity
    if (!validate_integrity(pdu->RX_UE_INFORMATION_TAG)) {
        free(pdu);
        return NULL;
    }

    add_pdu(pdu);

    return NULL;
}

void pdu_manager(int N) {
    pthread_mutex_lock(&lock);

    while (array_size < N) {
        int RX_UE_INFORMATION_TAG = rand();
        int RNTI = rand();

        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(RX_UE_INFORMATION_TAG, RNTI);

        if (!pdu) break;

        pthread_create(NULL, NULL, &handle_pdu, pdu);
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    int N = 100;
    pdu_manager(N);

    free_all();

    return 0;
}
