#include <pthread.h>
#include "logging_library.h"

// Define the struct to be managed in the list
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage a dynamically resizable list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** nfapi_crc_list_init(size_t initial_capacity) {
    if(initial_capacity < 1) {
        LOG_ERROR("Invalid initial capacity");
        return NULL;
    }

    // Initialize the list with a default capacity of 1024 elements
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc((initial_capacity + 1)*sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if(list == NULL) {
        LOG_ERROR("Memory allocation failure");
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL); // Initialize the mutex for thread safety
    list->size = initial_capacity;
    list->capacity = initial_capacity;

    return list;
}

void nfapi_crc_list_add(NFAPI_CRC_INDICATION_PDU_T** list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->mutex); // Lock the mutex for thread safety

    if(list->size == list->capacity) { // Resize the list if it's full
        size_t new_capacity = list->capacity * 2; // Double the capacity
        NFAPI_CRC_INDICATION_PDU_T** new_list = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list, (new_capacity + 1)*sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if(new_list == NULL) {
            LOG_ERROR("Memory allocation failure");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list = new_list;
    }

    // Add the element to the list
    size_t i;
    for(i = 0; i < list->size; i++) {
        if(list[i] == NULL) {
            list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if(list[i] == NULL) {
                LOG_ERROR("Memory allocation failure");
                pthread_mutex_unlock(&list->mutex);
                return;
            }
            *list[i] = *element; // Validate and copy the element
            if(*list[i].rx_ue_info.tag != 0 || *list[i].rnti.rnti_value < 0) {
                LOG_ERROR("Invalid RX_UE_INFORMATION_TAG or RNTI");
                free(list[i]);
                list[i] = NULL;
                pthread_mutex_unlock(&list->mutex);
                return;
            }
            break; // The element is added
        }
    }

    if(i == list->size) { // If the list is still empty, add the element
        list[list->size++] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if(list[list->size - 1] == NULL) {
            LOG_ERROR("Memory allocation failure");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        *list[list->size - 1] = *element; // Validate and copy the element
    }

    pthread_mutex_unlock(&list->mutex); // Unlock the mutex
}

void nfapi_crc_list_deinit(NFAPI_CRC_INDICATION_PDU_T** list) {
    for(size_t i = 0; i < list->size; i++) {
        free(list[i]);
    }
    free(list);
    pthread_mutex_destroy(&list->mutex);
}
