#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FRAMES 1000
#define AVERAGE_WINDOW 100

typedef struct {
    int timestamp;
    int packet_count;
    int byte_count;
} FrameStatistics;

FrameStatistics* frames = NULL;
int frame_count = 0;
double average_byte_count = 0.0;

void add_frame(FrameStatistics* new_frame) {
    if (frame_count >= MAX_FRAMES) {
        // If the array is full, realloc and move existing data
        int* old_frames = frames;
        frames = (FrameStatistics*)realloc(frames, sizeof(FrameStatistics) * (MAX_FRAMES * 2));
        memcpy(&frames[MAX_FRAMES], old_frames, sizeof(FrameStatistics) * MAX_FRAMES);
        free(old_frames);
        MAX_FRAMES *= 2;
    }

    // Add the new frame to the array
    frames[frame_count] = *new_frame;

    if (++frame_count > AVERAGE_WINDOW) {
        // If we have more than AVERAGE_WINDOW frames, remove the oldest one
        FrameStatistics* oldest_frame = &frames[0];
        memmove(&frames[0], &frames[1], sizeof(FrameStatistics) * (frame_count - 1));
        free(oldest_frame);
        frame_count--;
    }
}

double calculate_average_byte_count() {
    int sum = 0;
    for (int i = 0; i < frame_count && i < AVERAGE_WINDOW; i++) {
        sum += frames[i].byte_count;
    }
    return (double)sum / AVERAGE_WINDOW;
}

void update_average_byte_count() {
    average_byte_count = calculate_average_byte_count();
}
