#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T **nfapi_crc_list;
int nfapi_crc_list_len = 0;
pthread_mutex_t nfapi_crc_list_lock = PTHREAD_MUTEX_INITIALIZER;

void* create_nfa_pi_crc(struct timespec *spec, int num_elements) {
    NFAPI_CRC_INDICATION_PDU_T **temp_array;
    temp_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for(int i = 0; i < num_elements; i++) {
        temp_array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Randomly set CRCFLAG
        temp_array[i]->CRCFLAG = rand() % 2;

        // Set valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values
        temp_array[i]->RX_UE_INFORMATION_TAG = i + 1;
        temp_array[i]->RNTI = i * i;
        temp_array[i]->CRC_INDICATION_REL8_TAG = i % 10;
    }

    free(temp_array);
    return NULL;
}

void nfa_pi_crc_list_init(int num_elements) {
    pthread_mutex_lock(&nfapi_crc_list_lock);

    if (nfaapi_crc_list != NULL) {
        for(int i = 0; i < nfaapi_crc_list_len; i++) {
            free(nfaapi_crc_list[i]);
        }
        free(nfaapi_crc_list);
    }

    nfaapi_crc_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    nfaapi_crc_list_len = num_elements;

    pthread_mutex_unlock(&nfapi_crc_list_lock);
}

int nfa_pi_crc_list_insert(int idx, NFAPI_CRC_INDICATION_PDU_T* new_element) {
    pthread_mutex_lock(&nfapi_crc_list_lock);

    if (idx < 0 || idx >= nfaapi_crc_list_len) {
        return -1;
    }

    nfaapi_crc_list[idx] = new_element;

    pthread_mutex_unlock(&nfapi_crc_list_lock);
    return 0;
}

void nfa_pi_crc_list_free() {
    pthread_mutex_lock(&nfapi_crc_list_lock);

    for(int i = 0; i < nfaapi_crc_list_len; i++) {
        free(nfaapi_crc_list[i]);
    }

    free(nfaapi_crc_list);

    nfaapi_crc_list = NULL;
    nfaapi_crc_list_len = 0;

    pthread_mutex_unlock(&nfapi_crc_list_lock);
}
