void* serialize_structures(LTE_PHY_RX_PROC_T** structures, size_t n, const char* filename) {
    int fd = open(filename, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        return NULL;
    }

    for (size_t i = 0; i < n; i++) {
        LTE_PHY_RX_PROC_T* structure = structures[i];
        // serialize the structure to file
        int len = sizeof(LTE_PHY_RX_PROC_T);
        write(fd, &structure, len);
    }

    close(fd);

    return NULL;
}

void deserialize_structures(LTE_PHY_RX_PROC_T** deserialized_structures, size_t n, const char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        return;
    }

    for (size_t i = 0; i < n; i++) {
        LTE_PHY_RX_PROC_T* structure = &deserialized_structures[i][0];
        // deserialize the structure from file
        int len = sizeof(LTE PHY RX PROC T);
        read(fd, structure, len);
    }

    close(fd);
}

int main() {
    size_t n = 10;
    LTE_PHY_RX_PROC_T** structures = (LTE_PHY_RX_PROC_T**)malloc(n * sizeof(LTE_PHY_RX_PROC_T*));
