typedef struct {
    time_t timestamp;
    char src_ip[16];
    char dst_ip[16];
    int payload_len;
    char* payload;
} Report;

// Define the dynamic array of reports
typedef struct {
    Report** reports;
    int size;
    int capacity;
} ReportsArray;

// Function to initialize the reports array with a given initial capacity
ReportsArray* init_reports_array(int initial_capacity) {
    ReportsArray* arr = (ReportsArray*)malloc(sizeof(ReportsArray));
    arr->reports = (Report**)calloc(initial_capacity, sizeof(Report*));
    arr->size = 0;
    arr->capacity = initial_capacity;
    return arr;
}

// Function to add a new report to the array
void add_report(ReportsArray* reports_array, Report* new_report) {
    if (reports_array->size >= reports_array->capacity) {
        // Double the capacity and reallocate memory
        reports_array->capacity *= 2;
        reports_array->reports = (Report**)realloc(reports_array->reports,
                reports_array->capacity * sizeof(Report*));
    }
    reports_array->reports[reports_array->size++] = new_report;
}

// Function to free the reports array and its contents
void free_reports_array(ReportsArray* reports_array) {
    for (int i = 0; i < reports_array->size; i++) {
        free(reports_array->reports[i]->payload);
        free(reports_array->reports[i]);
    }
    free(reports_array->reports);
    free(reports_array);
}

