            free(element);
        }
    }

    // Define a function to allocate a new MAC frame element
    void* alloc_new_mac_frame_element(void) {
        MAC_FRAME_T* new_element = (MAC_FRAME_T*)malloc(sizeof(MAC_FRAME_T));
        if (!new_element) {
            return NULL;
