        // Set the TX_POWER_LEVEL and MCS_INDEX to random values
        new_element->TX_POWER_LEVEL = rand();
        new_element->MCS_INDEX = rand();
        return new_element;
    }

    // Define a function to free a MAC frame element
    void free_mac_frame_element(MAC_FRAME_T* element) {
        if (element) {
            free(element);
        }
    }

    while (1) {
        // Lock the mutexes for both lists
        pthread_mutex_lock(&nfaapi_crc_indication_pdu_mac_frame_list->crc_indication_pdu_lock);
        pthread_mutex_lock(&nfaapi_crc_indication_pdu_mac_frame_list->mac_frame_lock);

        // Check if either list is full
        if (nfaapi_crc_indication_pdu_mac_frame_list->crc_indication_pdu_size >= 500 || nfaapi_crc_indication_pdu_mac_frame_list->mac_frame_size >= 500) {
