        if (new_crc_indication_pdu_element) {
            nfaapi_crc_indication_pdu_mac_frame_list->crc_indication_pdu_list[nfaapi_crc_indication_pdu_mac_frame_list->crc_indication_pdu_size] = *new_crc_indication_pdu_element;
