            nfaapi_crc_indication_pdu_mac_frame_list->mac_frame_list[nfaapi_crc_indication_pdu_mac_frame_list->mac_frame_size] = *new_mac_frame_element;
            nfaapi_crc_indication_pdu_mac_frame_list->mac_frame_size++;
