            break;
        }

        // Unlock the mutexes for both lists
        pthread_mutex_unlock(&nfaapi_crc_indication_pdu_mac_frame_list->crc_indication_pdu_lock);
        pthread_mutex_unlock(&nfaapi_crc_indication_pdu_mac_frame_list->mac_frame_lock);
    }

    // Free all elements in both lists and then free the lists themselves
    for (int i = 0; i < nfaapi_crc_indication_pdu_mac_frame_list->crc_indication_pdu_size; i++) {
        free_crc_indication_pdu_element(nfaapi_crc_indication_pdu_mac_frame_list->crc_indication_pdu_list + i);
