    for (int i = 0; i < nfaapi_crc_indication_pdu_mac_frame_list->mac_frame_size; i++) {
        free_mac_frame_element(nfaapi_crc_indication_pdu_mac_frame_list->mac_frame_list + i);
    }
    free(nfaapi_crc_indication_pdu_mac_frame_list->crc_indication_pdu_list);
    free(nfaapi_crc_indication_pdu_mac_frame_list->mac_frame_list);

    // Free the shared memory structure
    free(nfaapi_crc_indication_pdu_mac_frame_list);

    return NULL;
}
