#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>

class Session {
public:
    int userId;
    long startTime;
    long lastActivityTime;
    std::string payload;

    Session(int _userId, const std::string& _payload) : 
        userId(_userId), 
        startTime(std::time(nullptr)), 
        lastActivityTime(startTime), 
        payload(_payload) {}

    void updateLastActivityTime() {
        lastActivityTime = std::time(nullptr);
    }
};

class SessionManager {
public:
    static const int DEFAULT_CAPACITY = 1000;
    std::vector<Session> sessions;
    mutable std::mutex mutex;

    SessionManager(int capacity = DEFAULT_CAPACITY) : 
        sessions(capacity) {}

    void addSession(Session session) {
        std::lock_guard<std::mutex> lock(mutex);
        sessions.push_back(session);
    }

    void updateLastActivityTime(int userId) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& session : sessions) {
            if (session.userId == userId) {
                session.updateLastActivityTime();
                break;
            }
        }
    }

    void removeSession(int userId) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = std::remove_if(sessions.begin(), sessions.end(), 
                                  [userId](const Session& session) { return session.userId == userId; });
        sessions.erase(it, sessions.end());
    }
};

int main() {
    SessionManager manager;

    for (int i = 0; i < 1000; i++) {
        manager.addSession(Session(i, "Initial Payload"));
    }

    std::thread t1([&manager]() {
        for (int i = 0; i < 500; i++) {
            manager.updateLastActivityTime(i);
        }
    });

    std::thread t2([&manager]() {
        for (int i = 0; i < 500; i++) {
            manager.removeSession(i);
        }
    });

    t1.join();
    t2.join();

    return 0;
}
