int nfa_pi_crc_array_capacity = 0;

NFAPI_CRC_INDICATION_PDU_T *nfa_pi_crc_get_entry_by_rnti(RNTI rnti) {
    // Thread-safe lookup
    pthread_rwlock_rdlock(&rw_lock);
    for (int i = 0; i < nfa_pi_crc_array_size; i++) {
        if (nfa_pi_crc_array[i]->rnti == rnti) {
            pthread_rwlock_unlock(&rw_lock);
            return &nfa_pi_crc_array[i];
        }
    }
    pthread_rwlock_unlock(&rw_lock);
    return NULL;
}

void nfa_pi_crc_add_entry(NFAPI_CRC_INDICATION_PDU_T *entry) {
    // Thread-safe add
    pthread_rwlock_wrlock(&rw_lock);
    if (nfa_pi_crc_array_size >= nfa_pi_crc_array_capacity) {
        // Resize the array if it's full
        int new_capacity = nfa_pi_crc_array_capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_array = (NFAPI_CRC_INDICATION_PDU_T **)realloc(nfa_pi_crc_array, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * new_capacity);
        if (!new_array) {
            // Handle memory allocation failure
            pthread_rwlock_unlock(&rw_lock);
            return;
        }
        nfa_pi_crc_array = new_array;
        nfa_pi_crc_array_capacity = new_capacity;
    }
    nfa_pi_crc_array[nfa_pi_crc_array_size++] = entry;
    pthread_rwlock_unlock(&rw_lock);
}

void nfa_pi_crc_update_entry_by_rnti(RNTI rnti, NFAPI_CRC_INDICATION_PDU_T *entry) {
    // Thread-safe update
    pthread_rwlock_wrlock(&rw_lock);
    for (int i = 0; i < nfa_pi_crc_array_size; i++) {
        if (nfa_pi_crc_array[i]->rnti == rnti) {
            memcpy(nfa_pi_crc_array[i], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_rwlock_unlock(&rw_lock);
            return;
        }
    }
    pthread_rwlock_unlock(&rw_lock);
}

int main() {
    // Initialize the array and lock
    nfa_pi_crc_array = (NFAPI_CRC_INDICATION_PDU_T **)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * 10);
    if (!nfa_pi_crc_array) {
        return -1;
    }
    nfa_pi_crc_array_size = 0;
    nfa_pi_crc_array_capacity = 10;
    pthread_rwlock_init(&rw_lock, NULL);

    // Add entries
    for (int i = 0; i < 10000; i++) {
        NFAPI_CRC_INDICATION_PDU_T *entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        entry->rx_ue_info = ...; // Initialize RX_UE_INFORMATION_TAG
        entry->rnti = i;
        entry->crc_indication_rel8 = ...; // Initialize CRC_INDICATION_REL8_TAG
        nfa_pi_crc_add_entry(entry);
    }

    // Update and retrieve entries
    NFAPI_CRC_INDICATION_PDU_T *entry = nfa_pi_crc_get_entry_by_rnti(5);
    if (entry) {
        // Update the entry
        entry->rx_ue_info = ...; // Update RX_UE_INFORMATION_TAG
        nfa_pi_crc_update_entry_by_rnti(entry->rnti, entry);
    }

    // Clean up
    for (int i = 0; i < nfa_pi_crc_array_size; i++) {
        free(nfa_pi_crc_array[i]);
    }
    free(nfa_pi_crc_array);
    pthread_rwlock_destroy(&rw_lock);

