#define MAX_NFAPI_CRC_INDICATION_PDU_T 1000
#define CRCFLAG_MAX_VALUE 0xFF

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T nfaPiCrcIndicationPduTs[MAX_NFAPI_CRC_INDICATION_PDU_T];

pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
int crcFlagThreshold = 0; // configurable threshold

void* processNfaPiData(void* ptr) {
    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)ptr;

    pthread_mutex_lock(&mtx);
    int i = 0;
    while (i < MAX_NFAPI_CRC_INDICATION_PDU_T) {
        if (data[i].RX_UE_INFORMATION_TAG > 0 && 
            data[i].RNTI > 0 && 
            data[i].CRC_INDICATION_REL8_TAG > 0) {
            int crcFlag = rand() % CRCFLAG_MAX_VALUE;
            data[i].CRCFLAG = crcFlag;
        }
        i++;
    }
    pthread_mutex_unlock(&mtx);

    return NULL;
}

int populateNfaPiCrcIndicationPduTs(int n, int threshold) {
    crcFlagThreshold = threshold;

    pthread_t threads[MAX_NFAPI_CRC_INDICATION_PDU_T];
    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    int i = 0;
    while (i < n) {
        data[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        data[i].RNTI = rand() % 500 + 1;
        data[i].CRC_INDICATION_REL8_TAG = rand() % 1000 + 1;

        pthread_create(&threads[i], NULL, processNfaPiData, &data[i]);
        i++;
    }

    for (i = 0; i < n; i++) {
        pthread_join(threads[i], NULL);
    }

    free(data);

    return 0;
}

int logFunctionPerformance(int eventCount, int memoryConsumption) {
    // implement logging mechanism
    printf("Event count: %d, Memory consumption: %d MB\n", eventCount, memoryConsumption / (1024 * 1024));
    return 0;
}
