} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically construct and manage a doubly linked list of NFAPI_CRC_INDICATION_PDU_T structures
int construct_and_manage_doubly_linked_list(int n) {
    // Initialize the head and tail pointers for the doubly linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* tail = NULL;

    // Dynamically allocate memory for the structures
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            printf("Memory allocation failed.\n");
            return -1;
        }

        // Initialize the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
        new_node->rx_ue_info_tag.rnti = rand() % 1000; // Randomly generated RNTI
        strcpy(new_node->rx_ue_info_tag.tag, "Random Tag"); // Initialize with a default tag

        int crcflag = rand() % 2; // Randomly generate CRCFLAG (0 or 1)
        if (crcflag) {
            new_node->crc_ind_rel8_tag = CRCFLAG_UP;
        } else {
            new_node->crc_ind_rel8_tag = CRCFLAG_DOWN;
        }

        // Add the new node to the doubly linked list
        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }

    return 0;
}

int main() {
    int n = 5; // Number of structures to construct
    if (construct_and_manage_doubly_linked_list(n) != 0) {
        printf("Error constructing and managing the doubly linked list.\n");
    } else {
        printf("Doubly linked list constructed successfully.\n");
    }
    return 0;
}
