// Function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void* manage_NFAPI_CRC_INDICATION_PDU_T_list(int num_elements) {
    // Initialize the list and its size
    void** list = NULL;
    int list_size = 0;

    // Function to resize the list
    void* resize_list(void** list, int old_size, int new_size) {
        // Allocate memory for the new list
        list = (void**)realloc(list, new_size * sizeof(void*));
        if (!list) {
            printf("Error: Unable to reallocate memory.\n");
            return NULL;
        }

        // Copy existing elements to the new list
        for (int i = 0; i < old_size; i++) {
            list[i] = i < new_size ? list[i] : NULL;
        }

        // Return the resized list
        return list;
    }

    // Function to serialize the list to a binary format
    int serialize_list_to_binary(void** list, FILE* file) {
        // Write the list size to the file
        fwrite(&list_size, sizeof(int), 1, file);

        // Write each element in the list
        for (int i = 0; i < list_size; i++) {
            NFAPI_CRC_INDICATION_PDU_T* element = list[i];
            fwrite(&element->RX_UE_INFORMATION_TAG, sizeof(char) * 256, 1, file);
            fwrite(&element->RNTI, sizeof(int), 1, file);
            fwrite(&element->CRC_INDICATION_REL8_TAG, sizeof(int), 1, file);
            fwrite(&element->CRCFLAG, sizeof(int), 1, file);
        }

        // Return the number of elements written
        return list_size;
    }

    // Function to serialize the list to a JSON format
    int serialize_list_to_json(void** list, FILE* file) {
        // Write the list size to the file
        fprintf(file, "{\"size\": %d, \"elements\": [", list_size);

        // Write each element in the list as JSON
        for (int i = 0; i < list_size; i++) {
            NFAPI_CRC_INDICATION_PDU_T* element = list[i];
            fprintf(file, "{\"RX_UE_INFORMATION_TAG\": \"%s\", \"RNTI\": %d, \"CRC_INDICATION_REL8_TAG\": %d, \"CRCFLAG\": %d},",
                    element->RX_UE_INFORMATION_TAG, element->RNTI, element->CRC_INDICATION_REL8_TAG, element->CRCFLAG);
        }

        // Close the JSON array
        fprintf(file, "]}\n");

        // Return the number of elements written
        return list_size;
    }

    // Main function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
    int main() {
        srand(time(NULL));  // Seed random number generator

        // Initialize the list and its size
        list = NULL;
        list_size = 0;

        // Create a new element with a unique RX_UE_INFORMATION_TAG and non-zero RNTI
        NFAPI_CRC_INDICATION_PDU_T* new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        strcpy(new_element->RX_UE_INFORMATION_TAG, "unique_tag");
        new_element->RNTI = 1;
        new_element->CRC_INDICATION_REL8_TAG = 0;
        new_element->CRCFLAG = 0;

        // Add the element to the list
        if (!list) {
            list = (void**)malloc(sizeof(void*));
            *list = new_element;
            list_size = 1;
        } else {
            int new_list_size = list_size + 1;
            list = resize_list(list, list_size, new_list_size);
            *(list + list_size - 1) = new_element;
            list_size = new_list_size;
        }

        // Serialize the list to a binary format
        FILE* binary_file = fopen("nfaapi_crc_indication_pdu_t_list_binary", "wb");
        int num_elements_written_binary = serialize_list_to_binary(list, binary_file);
        fclose(binary_file);

        // Serialize the list to a JSON format
        FILE* json_file = fopen("nfaapi_crc_indication_pdu_t_list_json", "w");
        int num_elements_written_json = serialize_list_to_json(list, json_file);
        fclose(json_file);

        return 0;
    }
