void* memory_pool_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed!\n");
        exit(-1);
    }
    return ptr;
}

void* memory_pool_calloc(size_t nmemb, size_t size) {
    void* ptr = calloc(nmemb, size);
    if (ptr == NULL) {
        printf("Memory allocation failed!\n");
        exit(-1);
    }
    return ptr;
