// Structure to represent a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with random CRCFLAG
Node* create_node() {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;  // Handle allocation failure

    NFAPI_CRC_INDICATION_PDU_T data;
    // Set random CRCFLAG
    srand(time(NULL));
    int crc_flag = rand() % 2;
    data.crc_indication_rel8_tag.crcflag = crc_flag;

    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a new node at the end of the linked list
void insert_node(Node** head, Node* new_node) {
    if (!*head) *head = new_node;  // If the list is empty, set the new node as the head
    else {
        Node* current = *head;
        while (current->next) current = current->next;
        current->next = new_node;
    }
}

// Function to print the linked list
void print_list(Node* head) {
    Node* current = head;
    while (current) {
        printf("%p: %x\n", &current->data, current->data.crc_indication_rel8_tag.crcflag);
        current = current->next;
    }
}

// Function to serialize the linked list to a file
void serialize_list(Node* head, FILE* file) {
    Node* current = head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
}

// Function to deserialize the linked list from a file
Node* deserialize_list(FILE* file) {
    Node* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;

    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        Node* node = create_node();
        if (!node) return NULL;  // Handle allocation failure

        node->data = data;
        insert_node(&head, node);
    }

    return head;
}

// Function to handle concurrent access and modification
pthread_mutex_t lock;

void *thread_function(void *arg) {
    pthread_mutex_lock(&lock);

    // Perform some operations on the linked list here

    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    Node* head = NULL;

    pthread_mutex_init(&lock, NULL);  // Initialize the lock

    for (int i = 0; i < 10; i++) {
        Node* node = create_node();
        if (!node) break;  // Handle allocation failure
        insert_node(&head, node);
    }

    print_list(head);

    FILE* file = fopen("linked_list.bin", "wb");
    serialize_list(head, file);
    fclose(file);

    head = deserialize_list(fopen("linked_list.bin", "rb"));
    print_list(head);

    pthread_mutex_destroy(&lock);  // Destroy the lock

    return 0;
}
