        // Initialize each structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        // with a randomly set CRCFLAG
        arr[i]->RX_UE_INFORMATION_TAG = i;
        arr[i]->RNTI = i % 100; // Ensure unique RNTI values for the initial N structures
        arr[i]->CRC_INDICATION_REL8_TAG = i + 1;
        arr[i]->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        // Track the number of unique RNTI values
        int num_unique_RNTIs = 1; // Start with one unique RNTI value for the first structure

        // Check for duplicate RNTI values and resize the array if necessary
        for (int j = i + 1; j < N; j++) {
            arr[j] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

            do {
                arr[j]->RX_UE_INFORMATION_TAG = j;
                arr[j]->RNTI = (num_unique_RNTIs * 100) + rand() % 10; // Ensure unique RNTI values
                arr[j]->CRC_INDICATION_REL8_TAG = j + 1;
                arr[j]->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

                // Check for duplicate RNTI values
                int found_duplicate = 0;
                for (int k = 0; k < i; k++) {
                    if (arr[k]->RNTI == arr[j]->RNTI) {
                        found_duplicate = 1;
                        break;
                    }
                }

                // Resize the array if a duplicate RNTI value is found
                if (found_duplicate) {
                    free(arr[i]);
                    N -= i - k; // Adjust the number of structures to be created
                    arr = (NFAPI_CRC_INDICATION_PDU_T**)realloc(arr, N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
                    i = k; // Reset the loop counter

                } else {
                    num_unique_RNTIs++;
                }
            } while (found_duplicate);
        }
    }

    return arr;
}

