            uniqueRNTICount++;
            int* tempArray = (int*)realloc(uniqueRNTIs, sizeof(int)*(uniqueRNTICount+2));
            tempArray[uniqueRNTICount]=RNTIs[i];
            free(uniqueRNTIs);
            uniqueRNTIs=tempArray;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*)*N);
    for(int i=0; i<N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
