void* allocate_memory(size_t size) {
    void* memory = malloc(size);
    if (memory == NULL) {
        // Retry mechanism for failed memory allocations
        int retries = 0;
        while (retries < 3 && memory == NULL) {
            memory = malloc(size);
            if (memory != NULL)
                break;
            retries++;
        }
        if (memory == NULL) {
            // Log critical failure
            printf("Memory allocation failed after %d retries\n", retries);
        }
    }
    return memory;
}

void deallocate_memory(void* memory, size_t size) {
