    for(int i = 0; i < 5; i++) {
        if(rx_chains[i].rf_band == 1 && rx_chains[i].rf_channel > 2) {
            // Adjust antenna gain settings to avoid overlap
            rx_chains[i].antennas[0].gain_setting += 5;
            rx_chains[i].antennas[1].gain_setting -= 3;
