#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with random CRCFLAG value
Node* createNode() {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) {
        return NULL;
    }
    newNode->data.RX_UE_INFORMATION_TAG = rand();
    newNode->data.RNTI = 'A' + rand() % 26;
    newNode->data.CRC_INDICATION_REL8_TAG = rand();
    srand(time(NULL));
    newNode->data.CRCFLAG = (rand() % 2);
    return newNode;
}

// Function to insert a new node at the end of the linked list
int addNode(Node** head, Node* newNode) {
    if (*head == NULL || newNode == NULL) {
        *head = newNode;
        return 0; // success
    }
    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = newNode;
    return 0; // success
}

// Function to toggle CRCFLAG for all nodes in the linked list
int toggleCRCFLAG(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        current->data.CRCFLAG ^= 1;
        current = current->next;
    }
    return 0; // success
}

// Function to validate the integrity of the linked list
int validateList(Node* head) {
    Node* current = head;
    int count = 0;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG < 0 || current->data.RNTI < 'A' || current->data.RNTI > 'Z') {
            return -1; // validation failed
        }
        if (current->data.CRC_INDICATION_REL8_TAG < 0) {
            return -1; // validation failed
        }
        count++;
        current = current->next;
    }
    printf("List validated successfully, %d entries found.\n", count);
    return 0; // success
}

// Function to iterate over the linked list and perform an operation on each node
int iterateList(Node* head, void (*operation)(Node*)) {
    Node* current = head;
    while (current != NULL) {
        operation(current);
        current = current->next;
    }
    return 0; // success
}

// Example usage:
int main() {
    srand(time(NULL));
    Node* head = NULL;

    for (int i = 0; i < 10; i++) {
        Node* newNode = createNode();
        if (addNode(&head, newNode) != 0) {
            printf("Error adding node.\n");
            return -1;
        }
    }

    toggleCRCFLAG(&head);

    validateList(head);

    iterateList(head, &toggleCRCFLAG);

    // Clean up
    Node* current = head;
    while (current != NULL) {
        Node* temp = current->next;
        free(current);
        current = temp;
    }
    return 0;
}

