#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1000
#define COMPACT_THRESHOLD 1.5
#define LOG_FILE "nfa_log.txt"
#define CRC_VALIDATION 0x1234

typedef struct NFAPI_L2_RX_MSG_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    L2_RX_INDICATION_REL8_TAG indication;
} NFAPI_L2_RX_MSG_PDU_T;

pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_L2_RX_MSG_PDU_T* nfa_array = NULL;
int nfa_array_size = 0;
FILE* log_file = fopen(LOG_FILE, "a");

void compactArray() {
    pthread_mutex_lock(&array_lock);
    NFAPI_L2_RX_MSG_PDU_T* temp = (NFAPI_L2_RX_MSG_PDU_T*) realloc(nfa_array, sizeof(NFAPI_L2_RX_MSG_PDU_T) * nfa_array_size / COMPACT_THRESHOLD);
    if (!temp) {
        printf("Memory allocation failed during compaction.\n");
        pthread_mutex_unlock(&array_lock);
        return;
    }
    nfa_array = temp;
    for (int i = 0; i < nfa_array_size; i++) {
        if (i >= nfa_array_size / COMPACT_THRESHOLD) {
            memset(&nfa_array[i], 0, sizeof(NFAPI_L2_RX_MSG_PDU_T));
        }
    }
    pthread_mutex_unlock(&array_lock);
}

void addElement(NFAPI_L2_RX_MSG_PDU_T* element) {
    pthread_mutex_lock(&array_lock);
    if (nfa_array_size >= MAX_ARRAY_SIZE) {
        printf("Array is full. Cannot add new elements.\n");
        pthread_mutex_unlock(&array_lock);
        return;
    }
    NFAPI_L2_RX_MSG_PDU_T* temp = (NFAPI_L2_RX_MSG_PDU_T*) realloc(nfa_array, sizeof(NFAPI_L2_RX_MSG_PDU_T) * (nfa_array_size + 1));
    if (!temp) {
        printf("Memory allocation failed during addition.\n");
        pthread_mutex_unlock(&array_lock);
        return;
    }
    nfa_array = temp;
    nfa_array[nfa_array_size++] = *element;
    pthread_mutex_unlock(&array_lock);

    // Log the operation
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(log_file, "%ld.%06ld: Added new element.\n", tv.tv_sec, tv.tv_usec);
}

void validateCRC(NFAPI_L2_RX_MSG_PDU_T* element) {
    if (element->crc != CRC_VALIDATION) {
        printf("Invalid CRC flag detected.\n");
    }
}

int main() {
    // Initialize the array
    nfa_array = (NFAPI_L2_RX_MSG_PDU_T*) malloc(sizeof(NFAPI_L2_RX_MSG_PDU_T));
    nfa_array_size = 1;

    // Create threads for concurrent access
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, threadFunc, NULL);
    }

    // Wait for threads to finish
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void* threadFunc(void* arg) {
    NFAPI_L2_RX_MSG_PDU_T element;
    // Initialize the structure...
    addElement(&element);
    validateCRC(&element);

    return NULL;
}
