void generate_list(int num_entries, const char* seed) {
    srand((unsigned int)atoi(seed));

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        printf("Memory allocation failed.\n");
        return;
    }

    time_t start_time = clock();
    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* entry = &list[i];

        // Generate valid RX_UE_INFORMATION_TAG
        entry->RX_UE_INFORMATION_TAG = rand() % 256;

        // Generate RNTI
        entry->RNTI = rand() % 1000;

        // Generate CRC_INDICATION_REL8_TAG and CRCFLAG
        char tag[20];
        sprintf(tag, "TAG_%d", i);
        strcpy(entry->CRC_INDICATION_REL8_TAG, tag);
        entry->CRCFLAG = rand() % 2; // Ensure CRCFLAG adheres to system-defined integrity constraints

        printf("Generated entry %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=\"%s\", CRCFLAG=%d\n", i, entry->RX_UE_INFORMATION_TAG, entry->RNTI, entry->CRC_INDICATION_REL8_TAG, entry->CRCFLAG);
    }

    time_t end_time = clock();

    printf("List generation completed in %f seconds.\n", (double)(end_time - start_time) / CLOCKS_PER_SEC);

    // Log successful operation
    printf("Operation successful. List size: %d entries.\n", num_entries);

    // Release memory
    free(list);
}

