NFAPI_CRC_INDICATION_PDU_T* create_array(int N) {
    if (N <= 0 || N > 1000)
        return NULL; // Invalid input

    srand(time(NULL)); // Seed random number generator

    int* rnti_values = malloc(N * sizeof(int));
    for (int i = 0; i < N; i++)
        rnti_values[i] = i; // Unique RNTI values

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array)
        return NULL; // Memory allocation failed for array

    int crcflag_prev = -1;
    for (int i = 0; i < N; i++) {
        int crcflag = rand() & 1; // Randomly set CRCFLAG
        while (crcflag == crcflag_prev) // Ensure no two consecutive structures have the same CRCFLAG
            crcflag = rand() & 1;
        crcflag_prev = crcflag;

        array[i].RX_UE_INFORMATION_TAG = i; // Unique RX_UE_INFORMATION_TAG values
        array[i].RNTI = rnti_values[i]; // Assign RNTI values from the previous step
        array[i].CRC_INDICATION_REL8_TAG.crcflag = crcflag;
    }

    free(rnti_values); // Release memory allocated for RNTI values

    return array;
}
