#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000
#define MEMORY_POOL_SIZE (MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T))

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int16_t crcflag;
    uint64_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

void *memory_pool = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *structures[MAX_STRUCTURES] = {0};
int num_structures = 0;
int oldest_index = -1;

void init_crc_indication_list(int max_size) {
    if (max_size > MAX_STRUCTURES) {
        max_size = MAX_STRUCTURES;
    }
    memory_pool = malloc(MEMORY_POOL_SIZE);
    memset(memory_pool, 0, MEMORY_POOL_SIZE);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_structure() {
    NFAPI_CRC_INDICATION_PDU_T *new_structure;
    if (num_structures < MAX_STRUCTURES) {
        new_structure = structures[num_structures];
        num_structures++;
    } else {
        // Remove the oldest structure if the list is full
        int oldest_index_to_remove = 0;
        for (int i = 1; i < num_structures; i++) {
            if (structures[i]->timestamp < structures[oldest_index_to_remove]->timestamp) {
                oldest_index_to_remove = i;
            }
        }
        new_structure = structures[oldest_index];
        free(structures[oldest_index]);
        structures[oldest_index] = NULL;
        num_structures--;
        oldest_index++;
    }
    return new_structure;
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    int i;
    for (i = 0; i < num_structures; i++) {
        if (structures[i] == structure) {
            break;
        }
    }
    free(structure);
    structures[i] = NULL;
    num_structures--;
}

void iterate_reverse() {
    for (int i = num_structures - 1; i >= 0; i--) {
        // Process the most recent data first
        printf("Timestamp: %llu, RNTI: %u, CRCFLAG: %d\n", structures[i]->timestamp, structures[i]->rnti, structures[i]->crcflag);
    }
}

void crc_indication_list_thread_safe_init() {
    pthread_mutex_init(&lock, NULL);
}
