#include <time.h>

#define M 10
#define MAX_NFAPI_PDUS 1000
#define N 8

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    unsigned long timestamp;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfaapi_crc_indication_pdu_list[M];

void nfaapi_crc_indication_pdu_manager(int num_entries) {
    int i, j;
    time_t current_time;
    srand(time(NULL));

    for (i = 0; i < M; i++) {
        nfaapi_crc_indication_pdu_list[i] = NULL;
    }

    for (i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (pdu != NULL) {
            current_time = time(NULL);
            pdu->timestamp = current_time;

            strcpy(pdu->RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
            pdu->RNTI = rand() % 1000;
            strcpy(pdu->CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG");
            pdu->CRCFLAG = (rand() % 2) ? 1 : 0;

            int found = 0;
            for (j = 0; j < M; j++) {
                if (nfaapi_crc_indication_pdu_list[j] != NULL && nfaapi_crc_indication_pdu_list[j]->RNTI == pdu->RNTI) {
                    free(pdu);
                    found = 1;
                    break;
                }
            }

            if (!found) {
                int k;
                for (k = M - 1; k > 0; k--) {
                    if (nfaapi_crc_indication_pdu_list[k] == NULL) {
                        nfaapi_crc_indication_pdu_list[k] = pdu;
                        break;
                    }
                }

                if (k == 0 && i >= M) {
                    printf("Warning: Maximum number of NFAPI PDUs exceeded.\n");
                }
            } else {
                free(pdu);
            }
        }
    }
}
