#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createArray(int N) {
    if (N < 1 || N > 1000) {
        printf("Invalid input: N must be between 1 and 1000.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int uniqueTags[N];
    for (int i = 0; i < N; i++) {
        int tag = rand() % 65536;
        while (tag <= 0 || findTag(uniqueTags, i, tag)) {
            tag = rand() % 65536;
        }
        uniqueTags[i] = tag;
    }

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = uniqueTags[i];
        array[i].RNTI = rand() % 65535 + 1;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000000;
        if (i % 2 == 0) {
            array[i].CRCFLAG = 0;
        } else {
            array[i].CRCFLAG = 1;
        }
    }

    return array;
}

int findTag(int* uniqueTags, int index, int tag) {
    for (int i = 0; i <= index; i++) {
        if (uniqueTags[i] == tag) {
            return 1;
        }
    }
    return 0;
}
